(257, 1, 10, 'lat', 'latitude', 'The WGS84 latitude of a SpatialThing (decimal degrees).'),
(258, 1, 10, 'location', 'location', 'The relation between something and the point, \n or other geometrical thing in space, where it is.  For example, the realtionship between\n a radio tower and a Point with a given lat and long.\n Or a relationship between a park and its outline as a closed arc of points, or a road and\n its location as a arc (a sequence of points).\n Clearly in practice there will be limit to the accuracy of any such statement, but one would expect\n an accuracy appropriate for the size of the object and uses such as mapping .\n '),
(259, 1, 10, 'long', 'longitude', 'The WGS84 longitude of a SpatialThing (decimal degrees).'),
(260, 1, 10, 'alt', 'altitude', 'The WGS84 altitude of a SpatialThing (decimal meters \nabove the local reference ellipsoid).'),
(261, 1, 10, 'lat_long', 'lat/long', 'A comma-separated representation of a latitude, longitude coordinate.'),
(262, 1, 11, 'text', 'text that may be displayed', 'This property provides a summary of the descriptorset that it annotates, suitable for display to end users.'),
(263, 1, 11, 'issuedby', 'issued by', 'This property denotes the author of a POWDER document.'),
(264, 1, 11, 'matchesregex', 'matches regular expression', 'This is the key \'include\' property for IRI set definitions in POWDER-S. It is necessary to take account of the POWDER Semantic Extension to process this fully. The value is a regular expression that is matched against an IRI.'),
(265, 1, 11, 'notmatchesregex', 'matches regular expression', 'This is the key \'exclude\' property for IRI set definitions in POWDER-S. It is necessary to take account of the POWDER Semantic Extension to process this fully. The value is a regular expression that is matched against an IRI.'),
(266, 1, 11, 'hasIRI', 'has IRI', 'This property is meant to be used in OWL2 instead of wdrs:matchesregex. It denotes the string data range corresponding to a set of IRIs.'),
(267, 1, 11, 'tag', 'tag', 'Property linking to a free-text tag which may include spaces.'),
(268, 1, 11, 'notknownto', 'not known to', 'Property used in results returned from a POWDER Processor that has no data about the candidate resource. The value is the IRI of the processor.'),
(269, 1, 11, 'describedby', 'described by', 'An RDF property to exactly match the describedby relationship type introduced in http://www.w3.org/TR/powder-dr/#assoc-linking and formally defined in appendix D of the same document, i.e. the relationship A \'describedby\' B asserts that resource B provides a description of resource A. There are no constraints on the format or representation of either A or B, neither are there any further constraints on either resource.'),
(270, 1, 11, 'authenticate', 'authenticate', 'A pointer to a document that describes how Description Resources created by a FOAF Agent or a DC Terms Agent may be authenticated'),
(271, 1, 11, 'validfrom', 'valid from', 'Provides a timestamp that a POWDER Processor may use when assessing trustworthiness of a POWDER document. Informally, a POWDER Processor should normally ignore data in the document before the given date.'),
(272, 1, 11, 'validuntil', 'valid until', 'Provides a timestamp that a POWDER Processor may use when assessing trustworthiness of a POWDER document. Informally, a POWDER Processor should normally ignore data in the document after the given date.'),
(273, 1, 11, 'logo', 'logo', 'Points to a graphic summary for the resources in a given class. Typically, it is a logo denoting conformance of a given (set of) resource(s) to a given set of criteria.'),
(274, 1, 11, 'sha1sum', 'SHA-1 sum', 'Links to a Base64-encoded binary SHA-1 hash of the described resource. May be used by POWDER Processors when assessing trustworthiness of a DR.'),
(275, 1, 11, 'certified', 'certified', 'A property that takes a Boolean value to declare whether the author of the data certifies the described resource.'),
(276, 1, 11, 'certifiedby', 'certified by', 'A property that links a resource to a POWDER document that certifies it.'),
(277, 1, 11, 'supportedby', 'supported by', 'A property that links a POWDER document to some other data source that supports the descriptions provided.'),
(278, 1, 11, 'data_error', 'data error', 'A property denoting a description of the specific error found in a given POWDER document.'),
(279, 1, 11, 'proc_error', 'processing error', 'A property denoting a description of the specific software error.'),
(280, 1, 11, 'error_code', 'error code', 'A property denoting the code of any error encountered by the POWDER processor.'),
(281, 1, 12, 'AP1_produced', 'produced', 'This property identifies the S11 Amount of Matter, e.g. a basket, that is preserved (part or total of) from an instance of A1 Excavation Processing Unit for further examination or evidence keeping.'),
(282, 1, 12, 'AP1i_was_produced_by', 'was produced by', NULL),
(283, 1, 12, 'AP2_discarded', 'discarded', 'This property identifies an instance of S11 Amount of Matter discarded (e.g. onto a heap) by an instance of A1 Excavation Processing Unit.'),
(284, 1, 12, 'AP2i_was_discarded_by', 'was discarded by', NULL),
(285, 1, 12, 'AP3_investigated', 'investigated', 'This property identifies the 3D excavated volume instance of E27 Site, i.e., a three- dimensional volume, that was actually investigated during an A9 Archaeological Excavation.'),
(286, 1, 12, 'AP3i_was_investigated_by', 'was investigated by', NULL),
(287, 1, 12, 'AP4_produced_surface', 'produced surface', 'This property identifies the instance of A10 Excavation Interface that constitutes the new surface produced during an instance of A1 Excavation Processing Unit in the excavated area. Frequently this surface or parts of it are documented through drawing and/or measured by technical means such as photography, tachymetry or laser scanning.'),
(288, 1, 12, 'AP4i_was_surface_produced_by', 'was surface produced by', NULL),
(289, 1, 12, 'AP5_removed_part_or_all_of', 'removed part or all of', 'This property identifies the instance of A8 Stratigraphic Unit that was cut during an A1 Excavation Processing Unit.'),
(290, 1, 12, 'AP5i_was_partially_or_totally_removed_by', 'was partially or totally removed by', NULL),
(291, 1, 12, 'AP6_intended_to_approximate', 'intended to approximate', 'This property identifies the A3 Stratigraphic Interface that was intended to approximate during an A1 Excavation Processing Unit. This property should be assigned when a stratigraphic excavation methodology is used. It enables the linkage of the surface produced by an A1 Excavation Processing Unit and an A3 Stratigraphic Interface.'),
(292, 1, 12, 'AP6i_was_approximated_by', 'was approximated by', NULL),
(293, 1, 12, 'AP7_produced', 'produced', 'This property identifies the instance of A8 Stratigraphic Unit that was produced during an instance of A4 Stratigraphic Genesis Event.'),
(294, 1, 12, 'AP7i_was_produced_by', 'was produced by', NULL),
(295, 1, 12, 'AP8_disturbed', 'disturbed', 'This property identifies an A8 Stratigraphic Unit that was disturbed through an A5 Stratigraphic Modification. One A5 Stratigraphic Modification may disturb several A8 Stratigraphic Units.'),
(296, 1, 12, 'AP8i_was_disturbed_by', 'was disturbed by', NULL),
(297, 1, 12, 'AP9_took_matter_from', 'took matter from', 'This property associates an instance of A4 Stratigraphic Genesis with an instance of S10 Material Substantial, from which matter was incorporated in the instance of A8 Stratigraphic Unit produced by this genesis. The instance of A8 Stratigraphic Unit produced by an instance of A4 Stratigraphic Genesis can be documented by using the property AP7 produced (was produced by) and should be distinct from the instance of S10 Material Substantial from which matter was taken. The latter instance will be modified or cease to exist due to this genesis process.'),
(298, 1, 12, 'AP9i_provided_matter_to', 'provided matter to', NULL),
(299, 1, 12, 'AP10_destroyed', 'destroyed', 'This property identifies the S22 Segment of Matter that was destroyed through an A1 Excavation Processing Unit. The spatial extent of the instance of S22 Segment of Matter is defined by the extent of the spatial 3-dimensional projection of the A1 Excavation Processing Unit. Depending on the granularity of the documented instance of A1 Excavation Processing Unit, different instances of S22 Segment of Matter may be identified by the A10 property.'),
(300, 1, 12, 'AP10i_was_destroyed_by', 'was destroyed by', NULL),
(301, 1, 12, 'AP11_has_physical_relation_to', 'has physical relation to', 'This property identifies the physical relationship between two A8 Stratigraphic Units. The described relationship may be between two adjacent instances of A2 Stratigraphic Volume Unit sharing a common interface (instance of A3 Stratigraphic Interface), between an instance of A2 Stratigraphic Volume Unit and one of its adjacent interfaces, such as human-made cuts or earthquake induced faults, or even between two intersecting interfaces. The type of physical relationships found between stratigraphic units in archaeological or geological documentation is documented through the property AP11.1 has type. The type applies to the direction from the domain to the range of the property AP11 has physical relation to (is physically related from). The type of physical relationship typically constitutes strong evidence for the sequence of genesis of the related stratigraphic units, which can be documented by the property AP13 has stratigraphic relation to (is stratigraphically related by). The type may either pertain to a relative topology, such as the one being “under” the other, or to the fine-structure of the interface between them, such as a layer of concrete having filled out earlier micro-cavities in various directions in the interface before solidifying.'),
(302, 1, 12, 'AP11i_is_physical_relation_from', 'is physical relation from', NULL),
(303, 1, 12, 'AP12_confines', 'confines', 'This property identifies partly or completely the surface (A3 Stratigraphic Interface) of an A2 Stratigraphic Volume Unit. One A3 Stratigraphic Interface may confine two or more A2 Stratigraphic Volume Units.'),
(304, 1, 12, 'AP12i_is_confined_by', 'is confined by', NULL),
(305, 1, 12, 'AP13_has_stratigraphic_relation_to', 'has stratigraphic relation to', 'This property identifies the stratigraphic relation between two A5 Stratigraphic Modification events. This relation may be inferred from the kind of physical relation that exists between the two AP 8 Stratigraphic Units that have been created or modified during the corresponding A5 Stratigraphic Modification events. The type of stratigraphic relationships in archaeological documentation assigned to two A5 Stratigraphic Modification events is documented through the property AP 13.1 has type.'),
(306, 1, 12, 'AP13i_is_stratigraphic_relation_of', 'is stratigraphic relation of', NULL),
(307, 1, 12, 'AP15_is_or_contains_remains_of', 'is or contains remains of', 'This property indicates that an instance of A2 Stratigraphic Volume Unit can be the remains of or contain the remains of an instance of S10 Material Substantial.'),
(308, 1, 12, 'AP15i_is_or_has_remains_contained_in', 'is or has remains contained in', NULL),
(309, 1, 12, 'AP16_assigned_attribute_to', 'assigned attribute to', 'This property indicates an instance of E18 Physical Thing that was assigned by an instance of A6 Group Declaration Event as remains of the target of this instance of A6 Group Declaration Event.'),
(310, 1, 12, 'AP16i_was_attributed_by', 'was attributed by', NULL),
(311, 1, 12, 'AP17_is_found_by', 'is found by', 'This property associates an instance of S19 Encounter Event with an instance of A7 Embedding that has been found during this event.'),
(312, 1, 12, 'AP17i_found', 'found', NULL),
(313, 1, 12, 'AP18_is_embedding_of', 'is embedding of', 'This property identifies the E18 Physical Thing that is contained in an A7 Embedding.'),
(314, 1, 12, 'AP18i_is_embedded', 'is embedded', NULL),
(315, 1, 12, 'AP19_is_embedding_in', 'is embedding in', 'This property identifies the instance of A2 Stratigraphic Volume Unit that contains the A7 Embedding. An Embedding may not extend over more than one instance of A2 Stratigraphic Volume Unit.'),
(316, 1, 12, 'AP19i_contains_embedding', 'contains embedding', NULL),
(317, 1, 12, 'AP21_contains', 'contains', 'This property associates an E18 Physical Thing that is found within an A2 Stratigraphic Volume Unit with the stratigraphic volume unit. AP21 contains (is contained in) is a shortcut for the more detailed path from E18 Physical Thing through AP18i is embedded, A7 Embedding, AP19 is embedding in, A2 Stratigraphic Volume Unit.'),
(318, 1, 12, 'AP21i_is_contained_in', 'is contained in', NULL),
(319, 1, 12, 'AP22_is_equal_in_time_to', 'is equal in time to', 'This property symmetrically identifies a situation in which the starting point and the ending point for an instance of E2 Temporal Entity is equal to the starting point and the ending point of another instance of E2 Temporal Entity, respectively. This property is only necessary if the time span is unknown (otherwise the equivalence can be calculated). This property is the same as the \"equal\" relationship of Allen’s temporal logic (Allen, 1983, pp. 832-843). This property is transitive.'),
(320, 1, 12, 'AP23_finishes', 'finishes', 'This property identifies a situation in which the ending point of an instance of E2 Temporal Entity is equal to the ending point of another temporal entity of longer duration. There is no causal relationship implied by this property. This property is only necessary if the time span is unknown (otherwise the relationship can be calculated). This property is the same as the \"finishes / finished-by\" relationships of Allen’s temporal logic (Allen, 1983, pp. 832-843). This property is transitive.'),
(321, 1, 12, 'AP23i_is_finished_by', 'is finished by', NULL),
(322, 1, 12, 'AP24_starts', 'starts', 'This property identifies a situation in which the starting point for an instance of E2 Temporal Entity is equal to the starting point of another instance of E2 Temporal Entity of longer duration. This property is only necessary if the time span is unknown (otherwise the relationship can be calculated). This property is the same as the \"starts / started-by\" relationships of Allen’s temporal logic (Allen, 1983, pp. 832-843). This property is transitive.'),
(323, 1, 12, 'AP24i_is_started_by', 'is started by', NULL),
(324, 1, 12, 'AP25_occurs_during', 'occurs during', 'This property identifies the situation in which the entire temporal extent of an instance of E2 Temporal Entity is within the temporal extent of another instance of E2 Temporal Entity that starts before and ends after the included temporal entity. This property is only necessary if the time span is unknown (otherwise the relationship can be calculated). This property is the same as the \"during / includes\" relationships of Allen’s temporal logic (Allen, 1983, pp. 832-843). This property is transitive.'),
(325, 1, 12, 'AP25i_includes', 'includes', NULL),
(326, 1, 12, 'AP26_overlaps_in_time_with', 'overlaps in time with', 'This property identifies a situation in which there is an overlap between the temporal extents of two instances of E2 Temporal Entity. It implies a temporal order between the two entities: if A overlaps in time B, then A must start before B, and B must end after A. This property is only necessary if the relevant time spans are unknown (otherwise the relationship can be calculated). This property is the same as the \"overlaps / overlapped-by\" relationships of Allen’s temporal logic (Allen, 1983, pp. 832-843).'),
(327, 1, 12, 'AP26i_is_overlapped_in_time_by', 'is overlapped in time by', NULL),
(328, 1, 12, 'AP27_meets_in_time_with', 'meets in time with', 'This property identifies a situation in which one instance of E2 Temporal Entity immediately follows another instance of E2 Temporal Entity. It implies a particular order between the two entities: if A meets in time with B, then A must precede B. This property is only necessary if the relevant time spans are unknown (otherwise the relationship can be calculated). This property is the same as the \"meets / met-by\" relationships of Allen’s temporal logic (Allen, 1983, pp. 832-843).'),
(329, 1, 12, 'AP27i_is_met_in_time_by', 'is met in time by', NULL),
(330, 1, 12, 'AP28_occurs_before', 'occurs before', 'This property identifies the relative chronological sequence of two temporal entities. It implies that a temporal gap exists between the end of A and the start of B. This property is only necessary if the relevant time spans are unknown (otherwise the relationship can be calculated). This property is the same as the \"before / after\" relationships of Allen’s temporal logic(Allen, 1983). This property is transitive.'),
(331, 1, 12, 'AP28i_occurs_after', 'occurs after', NULL),
(332, 1, 12, 'AP29_appears_in', 'appears in', 'This property associates a kind of object (documented as an instance of E55 Type) with an instance of E4 Period indicating that objects of this kind have been brought into existence during this period. The genesis of such objects may be the result of human, biological, geological or other processes. This property makes a weak statement about the distribution of the associated object kind in the archaeological record: that is, if the genesis of an object of the type can plausibly be assumed to fall within the genesis of the context within which it was found, then this property supports reasoning, ceteris paribus, that the genesis period of the context forms part of, or overlaps with, one of the instances of E4 Period in which the respective object type has appeared. Such weak statements may also be useful in the context of geological or paleontological observations. Stronger claims can be made using the properties AP30 restricted to and AP31 typical for .'),
(333, 1, 12, 'AP29i_has_appearing_type', 'has appearing type', NULL),
(334, 1, 12, 'AP30_restricted_to', 'restricted to', 'This property associates a kind of object (documented as an instance of E55 Type) with an instance of E4 Period indicating that objects of this kind have been generated exclusively in this period. This property makes a strong statement concerning the distribution of the associated object kind in the observed record: If the genesis of an object of this type can plausibly be assumed to fall within the genesis of the context in which it was found, then the statement made with this property would support reasoning, ceteris paribus , that the genesis period of the find context actually forms part of the related instance of E4 Period, or at least overlaps with it. In contrast, objects from previous periods may appear in a context because they are still in use, and objects from later periods may have been displaced into an older context. Weaker claims can be made using the properties AP29 appears in (gas appearing type) and AP31 typical for (has typical type) .'),
(335, 1, 12, 'AP30i_restricts_appearance_of', 'restricts appearance of', NULL),
(336, 1, 12, 'AP31_typical_for', 'typical for', 'This property associates a kind of object (documented as an instance of E55 Type) with an instance of E4 Period indicating that objects of this kind have been generated in this period in significantly greater numbers and in wider distributions, than in other periods. This property makes a moderate statement concerning the distribution of the associated object kind in the observed record: If a \"sufficient number\" of objects of this type are found in a context, and their genesis can plausibly be assumed to fall within the genesis of the find context, then the statement made with this property would support reasoning, ceteris paribus , that the genesis period of the find context is likely to form part of the related instance of E4 Period, or at least overlap with it. “Sufficient number” means that the density of objects of this kind in the find context is compatible with the general density that this kind of object had during the associated period in contexts of a comparable nature and deposition history. A stronger claim can be made using AP30 restricted to (restricts appearance of) while a weaker claim would use AP29 appears in (has appearing type) .'),
(337, 1, 12, 'AP31i_has_typical_type', 'has typical type', NULL),
(338, 1, 12, 'AP32_discarded_into', 'discarded into', 'This property identifies the S11 Amount of Matter (e.g. a heap) into which material from an A1 Excavation Processing Unit is discarded. The same instance of A1 Excavation Processing Unit may discard matter into multiple heaps, but also simply throw away the excavated matter without any order or exported to be deposited elsewhere, thereby breaking any close correspondence between the excavation and the deposit.'),
(339, 1, 12, 'AP32i_was_discarded_by', 'was discarded by', NULL),
(340, 1, 13, 'O1_diminished', 'diminished', 'This property associates an instance of S1 Matter Removal with the instance of S10 Material Substantial that this activity diminished. Although an instance of S1 Matter Removal activity normally concerns only one item of S10 Material Substantial, it is possible to imagine circumstances under which more than one item might be diminished by a single Matter Removal activity. An instance S1 Matter Removal activity requires to diminish at least one item of S10 Material Substantial. This may be realized by any of the subproperties of O1 diminished . Therefore the instantiation of a particular subproperty of O1 diminished is not necessary.'),
(341, 1, 13, 'O1i_was_diminished_by', 'was diminished by', NULL),
(342, 1, 13, 'O2_removed', 'removed', 'This property associates an instance of S1 Matter Removal with the instance of S11 Amount of Matter that it has removed.'),
(343, 1, 13, 'O2i_was_removed_by', 'was removed by', NULL),
(344, 1, 13, 'O3_sampled_from', 'sampled from', 'This property associates an instance of S2 Sample Taking with the instance S10 Material Substantial from which a sample was taken. In particular, it may be a feature or a fluid body from which a sample was removed.'),
(345, 1, 13, 'O3i_was_sample_by', 'was sample by', NULL),
(346, 1, 13, 'O4_sampled_at', 'sampled at', 'This property associates an instance of S2 Sample Taking with the instance of E53 Place (\"spot\") at which this activity sampled. It identifies the narrowest relevant area on the material substantial from which the sample was taken. This may be known or given in absolute terms or relative to an instance of the material substantial from which it was taken. If samples are taken from more than one spot, the sample taking activity must be documented by separate instances for each spot. The property P7 took place at, inherited from E4 Period, describes the position of the area in which the sampling activity occurred; this latter comprises the space within which operators and instruments were contained during the activity, and the sample taking spot.'),
(347, 1, 13, 'O4i_was_sampling_location_of', 'was sampling location of', NULL),
(348, 1, 13, 'O5_removed', 'removed', 'This property associates an instance of S2 Sample Taking with the instance of S13 Sample that was taken during the activity.'),
(349, 1, 13, 'O5i_was_removed_by', 'was removed by', NULL),
(350, 1, 13, 'O6_is_former_or_current_part_of', 'is former or current part of', 'This property associates an instance of S12 Amount of Fluid with an instance of S14 Fluid Body which formed or forms part of it. It allows instances of S14 Fluid Body to be analyzed into elements of S12 Amount of Fluid.'),
(351, 1, 13, 'O6i_has_former_or_current_part', 'has former or current part', NULL),
(352, 1, 13, 'O7_confines', 'confines', 'This property associates an instance of S20 Rigid Physical Feature with an instance of S10 Material Substantial that it partially or completely confines. It describes cases in which rigid features such as stratigraphic layers, walls, dams, riverbeds, etc. form the boundaries of some item such as another stratigraphic layer or the waters of a river.'),
(353, 1, 13, 'O7i_is_confined_by', 'is confined by', NULL),
(354, 1, 13, 'O8_observed', 'observed', 'This property associates an instance of S4 Observation with an instance of S15 Observable Entity that was observed. Specifically it describes that a thing, a feature, a phenomenon or its reaction is observed by an activity of Observation.'),
(355, 1, 13, 'O8i_was_observed_by', 'was observed by', NULL),
(356, 1, 13, 'O9_observed_property_type', 'observed property type', 'This property associates an instance of S4 Observation with the instance of S9 Property Type for which the observation provides a value or evidence, such as “concentration of nitrate” observed in the water from a particular borehole. Encoding the observed property by type, observed entity and value (properties O9, O10, O16) is a method to circumscribe the reification of the observed property by the respective instance of S4 Observation. In an RDFS encoding, this circumscription can be transformed into an explicit representation of the observed property in terms of a formal ontology either by use of a reification construct or by the use of a Named Graph containing the observed property. The latter representation allows for more formal reasoning with the model, the former is more flexible about the kinds of observations.'),
(357, 1, 13, 'O9i_property_type_was_observed_by', 'property type was observed by', NULL),
(358, 1, 13, 'O10_assigned_dimension', 'assigned dimension', 'This property associates an instance of S6 Data Evaluation with an instance of E54 Dimension that a data evaluation activity has assigned. In that case, dimensions may be determined by making evaluations on observational data based on mathematical inference rules and calculations.'),
(359, 1, 13, 'O10i_dimension_was_assigned_by', 'dimension was assigned by', NULL),
(360, 1, 13, 'O11_described', 'described', 'This property associates an instance of S6 Data Evaluation with an instance of S15 Observable Entity for which a data evaluation activity provides a description. This description of any Observable Entity is based on data evaluations.'),
(361, 1, 13, 'O11i_was_described_by', 'was described by', NULL),
(362, 1, 13, 'O12_has_dimension', 'has dimension', 'This property associates an instance of S15 Observable Entity with an instance of E54 Dimension that the observable entity has. It offers no information about how and when an E54 Dimension was established. In case the instance of S15 Observable Entity is more specifically an instance of E18 Physical Thing, using the property O12 has dimension (is dimension of) is equivalent to using the property P43 has dimension (is dimension of). In other words, using the one implies the other.'),
(363, 1, 13, 'O12i_is_dimension_of', 'is dimension of', NULL),
(364, 1, 13, 'O13_triggered', 'triggered', 'This property associates an instance of E5 Event that triggered another instance of E5 Event with the latter. It identifies the interaction between events: an event can activate (trigger) other events in a target system that is in a situation of sustained tension, such as a trap or an unstable mountain slope giving way to a land slide after a rain or earthquake. In that sense the triggering event is interpreted as a cause. However, the association of the two events is based on their temporal proximity, with the triggering event ending when the triggered event starts.'),
(365, 1, 13, 'O13i_was_triggered_by', 'was triggered by', NULL),
(366, 1, 13, 'O15_occupied', 'occupied', 'This property associates an instance of S10 Material Substantial with the instance of E53 Place that this substance occupied. It describes the space filled (occupied) by a physical matter. This property is the development of the shortcut expressed in the proposition of classification: “S20 Physical Feature” isA “E53 Place”. This property is equivalent to P156 occupies (is occupied by) with domain E18 Physical Thing and range E53 Place.'),
(367, 1, 13, 'O15i_was_occupied_by', 'was occupied by', NULL),
(368, 1, 13, 'O16_observed_value', 'observed value', 'This property associates a value assigned to an entity observed by S4 Observation.'),
(369, 1, 13, 'O16i_value_was_observed_by', 'value was observed by', NULL),
(370, 1, 13, 'O17_generated', 'generated', 'This property associates an instance of S17 Physical Genesis event with an instance of E18 Physical Thing that the event generated.'),
(371, 1, 13, 'O17i_was_generated_by', 'was generated by', NULL),
(372, 1, 13, 'O18_altered', 'altered', 'This property associates an instance of S18 Alteration process with an instance of E18 Physical Thing which was altered by this activity.'),
(373, 1, 13, 'O18i_was_altered_by', 'was altered by', NULL),
(374, 1, 13, 'O19_encountered_object', 'encountered object', 'This property associates an instance of S19 Encounter Event with an instance of E18 Physical Thing that was encountered or observed as present during the event.'),
(375, 1, 13, 'O19i_was_object_encountered_through', 'was object encountered through', NULL),
(376, 1, 13, 'O20_sampled_from_type_of_part', 'sampled from type of part', 'This property associates the activity of a Sample Taking with the type of the location part from which a sample was taken. It is a shortcut of the property O4 sampled at, and it is used as an alternative property, identifying features and material substantial as types of parts of sampling positions.'),
(377, 1, 13, 'O20i_type_of_part_was_sampled_by', 'type of part was sampled by', NULL),
(378, 1, 13, 'O21_encountered_at', 'encountered at', 'This property associates an instance of S19 Encounter Event with an instance of E53 Place at which the things, which were encountered, were observed to be present. This may be given in absolute terms or in terms relative to the observed thing. The associated place must be within the boundaries of the E53 Place at which the S19 Encounter Event took place, if that has been given. Note, that the encountered object may be larger and extend beyond the place of encounter, such as a corner of a building being excavated.'),
(379, 1, 13, 'O21i_witnessed_encounter', 'witnessed encounter', NULL),
(380, 1, 13, 'O23_is_defined_by', 'is defined by', 'This property identifies the E92 Spacetime Volume that defines a S22 Segment of Matter. The spatial boundaries of the E92 Spacetime Volume are defined through S4 Observation or declaration while the temporal boundaries are confined by S18 Alteration events.'),
(381, 1, 13, 'O23i_defines', 'defines', NULL),
(382, 1, 13, 'O24_measured', 'measured', 'This property associates an instance of S21 Measurement with the instance of S15 Observable Entity to which it applied. An instance of S15 Observable Entity may be measured more than once. Material and immaterial things and processes may be measured, e.g. the number of words in a text, or the duration of an event.'),
(383, 1, 13, 'O24i_was_measured_by', 'was measured by', NULL);
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(384, 1, 13, 'O25_contains', 'contains', 'This property describes that an instance of S10 Material Substantial was or is contained in another instance of S10 Material Substantial regardless of whether the identity of the involved instances is based on the persistence of the form of material or on material substance that may change form.'),
(385, 1, 13, 'O25i_is_contained_in', 'is contained in', NULL),
(386, 1, 13, 'O27_split', 'split', 'This property associates an instance of S24 Sample Splitting with the instance of S13 Sample which is the original sample being split.'),
(387, 1, 13, 'O27i_was_source_for', 'was source for', NULL),
(388, 1, 13, 'O28_is_conceptually_greater_than', 'is conceptually greater than', 'This property allows an instance of E55 Type from a particular concept scheme or vocabulary to be declared as having an order relative to other instances of E55 Type in the same or other concept schemes, without necessarily having a specific value associated with either instance. This allows, for example, for an E55 Type instance representing the concept of \"good\" in a conservation report vocabulary to be greater than the E55 Type instance representing the concept of \"average\" in the same vocabulary. This property is transitive, and thus if \"average\" is greater than \"poor\", then \"good\" is also greater than \"poor\". In the domain of statistics, types that participate in this kind of relationship are called \"Ordinal Variables\"; as opposed to those without order which are called \"Nominal Variables\". This property allows for queries that select based on the relative position of participating E55 Types.'),
(389, 1, 13, 'O28i_is_conceptually_less_than', 'is conceptually less than', NULL),
(390, 1, 13, 'O29_removed_sub-sample', 'removed sub-sample', 'This property associates an instance of S24 Sample Splitting with the resulting instance of S13 Sample that has been removed from the original sample. The new sample (i.e. the sub-sample) maintains the characteristic qualities of the original.'),
(391, 1, 13, 'O29i_was_sub-sample_removed_by', 'was sub-sample removed by', NULL),
(392, 1, 13, 'O30_determined_position', 'determined position', 'This property associates an instance of S23 Position Determination with the instance of E94 Space Primitive which is the result of that determination. The instance of E94 Space Primitive approximates the place occupied by the entity whose position is being determined.'),
(393, 1, 13, 'O31_has_validity_time-span', 'has validity time-span', 'This property associates an instance of S23 Position Determination with the instance of E52 Time-Span for which the determination is valid according to the observer at the time of the observation. No inferences can be made in relation to the validity of the determination outside this time-span despite the fact that some entities are relatively stable and their positions may remain the same after the determination. The time-span of validity should fall within the overall time-span of the process of determination.'),
(394, 1, 13, 'O31i_is_time-span_validity_for', 'is time-span validity for', NULL),
(395, 1, 13, 'O32_determined_position_of', 'determined position of', 'This property connects an instance of S23 Position Determination with the instance of S15 Observable Entity whose position is being determined.'),
(396, 1, 13, 'O32i_was_located_by', 'was located by', NULL),
(397, 1, 14, 'P1_is_identified_by', 'is identified by', 'This property describes the naming or identification of any real-world item by a name or any other identifier.\nThis property is intended for identifiers in general use, which form part of the world the model intends to describe, and not merely for internal database identifiers which are specific to a technical system, unless these latter also have a more general use outside the technical context. This property includes in particular identification by mathematical expressions such as coordinate systems used for the identification of instances of E53 Place. The property does not reveal anything about when, where and by whom this identifier was used. A more detailed representation can be made using the fully developed (i.e. indirect) path through E15 Identifier Assignment.\nThis property is a shortcut for the path from E1 CRM Entity through P140i was attributed by, E15 Identifier Assignment, P37 assigned to E42 Identifier.\nIt is also a shortcut for the path from E1 CRM Entity through P1 is identified by, E41 Appellation, P139 has alternative form to E41 Appellation.'),
(398, 1, 14, 'P1i_identifies', 'identifies', NULL),
(399, 1, 14, 'P2_has_type', 'has type', 'This property allows sub-typing of CIDOC CRM entities –a form of specialisation – through the use of a terminological hierarchy, or thesaurus.\nThe CIDOC CRM is intended to focus on the high-level entities and relationships needed to describe data structures. Consequently, it does not specialise entities any further than is required for this immediate purpose. However, entities in the isA hierarchy of the CIDOC CRM may by specialised into any number of sub-entities, which can be defined in the E55 Type hierarchy. E41 Appellation, for example, may be specialised into “e-mail address”, “telephone number”, “post office box”, “URL”, etc., none of which figures explicitly in the CIDOC CRM class hierarchy. A comprehensive explanation about refining CIDOC CRM concepts by E55 Type is given in the section “About Types” in the section on “Specific Modelling Constructs” of this document.\nThis property is a shortcut for the path from E1 CRM Entity through P41i was classified by, E17 Type Assignment, P42 assigned to E55 Type.'),
(400, 1, 14, 'P2i_is_type_of', 'is type of', NULL),
(401, 1, 14, 'P3_has_note', 'has note', 'This property is a container for all informal descriptions about an object that have not been expressed in terms of CIDOC CRM constructs.\nIn particular, it captures the characterisation of the item itself, its internal structures, appearance, etc.\nLike property P2 has type (is type of), this property is a consequence of the restricted focus of the CIDOC CRM. The aim is not to capture, in a structured form, everything that can be said about an item; indeed, the CIDOC CRM formalism is not regarded as sufficient to express everything that can be said. Good practice requires use of distinct note fields for different aspects of a characterisation. The P3.1 has type property of P3 has note allows differentiation of specific notes, e.g. “construction”, “decoration”, etc.\nAn item may have many notes, but a note is attached to a specific item.'),
(402, 1, 14, 'P4_has_time-span', 'has time-span', 'This property associates an instance of E2 Temporal Entity with the instance of E52 Time-Span during which it was on-going. The associated instance of E52 Time-Span is understood as the real time-span during which the phenomena making up the temporal entity instance were active. More than one instance of E2 Temporal Entity may share a common instance of E52 Time-Span only if they come into being and end being due to identical declarations or events.'),
(403, 1, 14, 'P4i_is_time-span_of', 'is time-span of', NULL),
(404, 1, 14, 'P5_consists_of', 'consists of', 'This property describes the decomposition of an instance of E3 Condition State into discrete, subsidiary states.\nIt is assumed that the sub-states into which the condition state is analysed form a logical whole, although the entire story may not be completely known, and that the sub-states are in fact constitutive of the general condition state. For example, a general condition state of “in ruins” may be decomposed into the individual stages of decay.\nThis property is transitive and asymmetric.'),
(405, 1, 14, 'P5i_forms_part_of', 'forms part of', NULL),
(406, 1, 14, 'P7_took_place_at', 'took place at', 'This property describes the spatial location of an instance of E4 Period.\nThe related instance of E53 Place should be seen as a wider approximation of the geometric area within which the phenomena that characterise the period in question occurred, see below. P7 took place at (witnessed) does not convey any meaning other than spatial positioning (frequently on the surface of the earth). For example, the period “Révolution française” can be said to have taken place in “France in 1789”; the “Victorian” period may be said to have taken place in “Britain from 1837-1901” and its colonies, as well as other parts of Europe and North America. An instance of E4 Period can take place at multiple non-contiguous, non-overlapping locations.\nAny place where something happened includes the spatial projection of the happening given in the same geometric reference system. For instance, HMS Victory, as place of Lord Nelson\'s dying, includes the location of his body relative to the hull of HMS Victory at his time of death as the most precise location of his death. By the definition of P161 has spatial projection, an instance of E4 Period takes place on all its spatial projections to respective reference systems, that is, instances of E53 Place. Therefore, this property implies the more fully developed path from E4 Period through P161 has spatial projection, E53 Place, P89 falls within to E53 Place, where both places are defined in the same geometric reference system. The relation between an instance of E53 Place and its reference system can conveniently be documented via the property P157 is at rest relative to (provides reference space for).\nSomething that has happened at a given place can also be considered to have happened at a smaller place within it: for example, it is reasonable to say Caesar’s murder took place in Rome, but also on the Forum Romanum, and more precisely in the Curia. It is characteristic for different historical sources to use varying precision in such statements, without being in contradiction with each other. This may be due to lack of knowledge or to the relevance of the precision for the purpose of the statement. In information integration, the more precise statement improves the overall knowledge.'),
(407, 1, 14, 'P7i_witnessed', 'witnessed', NULL),
(408, 1, 14, 'P8_took_place_on_or_within', 'took place on or within', 'This property describes the location of an instance of E4 Period with respect to an instance of E18 Physical Thing.\nThis property is a shortcut of the more fully developed path from E4 Period through P7 took place at, E53 Place, P156i is occupied by to E18 Physical Thing.\nIt describes a period that can be located with respect to the space defined by an E19 Physical Object such as a ship or a building. The precise geographical location of the object during the period in question may be unknown or unimportant.\nFor example, the French and German armistice of 22-nd June 1940 was signed in the same railway carriage as the armistice of 11-th November 1918.'),
(409, 1, 14, 'P8i_witnessed', 'witnessed', NULL),
(410, 1, 14, 'P9_consists_of', 'consists of', 'This property associates an instance of E4 Period with another instance of E4 Period that is defined by a subset of the phenomena that define the former. Therefore, the spacetime volume of the latter must fall within the spacetime volume of the former.\nThis property is transitive and asymmetric.'),
(411, 1, 14, 'P9i_forms_part_of', 'forms part of', NULL),
(412, 1, 14, 'P10_falls_within', 'falls within', 'This property associates an instance of E92 Spacetime Volume with another instance of E92 Spacetime Volume that falls within the latter. In other words, all points in the former are also points in the latter.\nThis property is transitive and reflexive.'),
(413, 1, 14, 'P10i_contains', 'contains', NULL),
(414, 1, 14, 'P11_had_participant', 'had participant', 'This property describes the active or passive participation of instances of E39 Actors in an instance of E5 Event.\nIt documents known events in which an instance of E39 Actor has participated during the course of that actor’s life or history. The instances of E53 Place and E52 Time-Span where and when these events happened provide constraints about the presence of the related instances of E39 Actor in the past. Collective actors, i.e. instances of E74 Group, may physically participate in events via their representing instances of E21 Persons only. The participation of multiple actors in an event is most likely an indication of their acquaintance and interaction.\nThe property implies that the actor was involved in the event but does not imply any causal relationship. For instance, someone having been portrayed can be said to have participated in the creation of the portrait.'),
(415, 1, 14, 'P11i_participated_in', 'participated in', NULL),
(416, 1, 14, 'P12_occurred_in_the_presence_of', 'occurred in the presence of', 'This property describes the active or passive presence of an E77 Persistent Item in an instance of E5 Event without implying any specific role.\nIt documents known events in which an instance of E77 Persistent Item was present during the course of its life or history. For example, an object may be the desk, now in a museum, on which a treaty was signed. The instance of E53 Place and the instance of E52 Time-Span where and when these events happened provide constraints about the presence of the related instance E77 Persistent Item in the past. Instances of E90 Symbolic Object, in particular information objects, are physically present in events via at least one of the instances of E18 Physical Thing carrying them. Note, that the human mind can be such a carrier. A precondition for a transfer of information to a person or another new physical carrier is the presence of the respective information object and this person or physical thing in one event.'),
(417, 1, 14, 'P12i_was_present_at', 'was present at', NULL),
(418, 1, 14, 'P13_destroyed', 'destroyed', 'This property links an instance of E6 Destruction to an instance of E18 Physical Thing that has been destroyed by it.\nDestruction implies the end of an item’s life as a subject of cultural documentation – the physical matter of which the item was composed may in fact continue to exist. An instance of E6 Destruction may be contiguous with an instance of E12 Production that brings into existence a derived object composed partly of matter from the destroyed object.'),
(419, 1, 14, 'P13i_was_destroyed_by', 'was destroyed by', NULL),
(420, 1, 14, 'P14_carried_out_by', 'carried out by', 'This property describes the active participation of an instance of E39 Actor in an instance of E7 Activity.\nIt implies causal or legal responsibility. The P14.1 in the role of property of the property specifies the nature of an Actor’s participation.'),
(421, 1, 14, 'P14i_performed', 'performed', NULL),
(422, 1, 14, 'P15_was_influenced_by', 'was influenced by', 'This is a high-level property, which captures the relationship between an instance of E7 Activity and anything, that is, an instance of E1 CRM Entity, that may have had some bearing upon it.\nThe property has more specific subproperties.'),
(423, 1, 14, 'P15i_influenced', 'influenced', NULL),
(424, 1, 14, 'P16_used_specific_object', 'used specific object', 'This property describes the use of material or immaterial things in a way essential to the performance or the outcome of an instance of E7 Activity.\nThis property typically applies to tools, instruments, moulds, raw materials and items embedded in a product. It implies that the presence of the object in question was a necessary condition for the action. For example, the activity of writing this text required the use of a computer. An immaterial thing can be used if at least one of its carriers is present. For example, the software tools on a computer.\nAnother example is the use of a particular name by a particular group of people over some span to identify a thing, such as a settlement. In this case, the physical carriers of this name are at least the people understanding its use.'),
(425, 1, 14, 'P16i_was_used_for', 'was used for', NULL),
(426, 1, 14, 'P17_was_motivated_by', 'was motivated by', 'This property describes an item or items that are regarded as a reason for carrying out the instance of E7 Activity.\nFor example, the discovery of a large hoard of treasure may call for a celebration, an order from headquarters can start a military manoeuvre.'),
(427, 1, 14, 'P17i_motivated', 'motivated', NULL),
(428, 1, 14, 'P19_was_intended_use_of', 'was intended use of', 'This property relates an instance of E7 Activity with instances of E71 Human-Made Thing, created specifically for use in the activity.\nThis is distinct from the intended use of an item in some general type of activity such as the book of common prayer which was intended for use in Church of England services (see P101 had as general use (was use of)).'),
(429, 1, 14, 'P19i_was_made_for', 'was made for', NULL),
(430, 1, 14, 'P20_had_specific_purpose', 'had specific purpose', 'This property describes the relationship between a preparatory activity, an instance of E7 Activity and the instance of E5 Event that it is intended as a preparation for.\nThis includes activities, orders and other organisational actions, taken in preparation for other activities or events.\nP20 had specific purpose (was purpose of) implies that the activity succeeded in achieving its aim. If it does not succeed, such as the setting of a trap that did not catch anything, the unrealized intention should be documented using P21 had general purpose (was purpose of): E55 Type and/or P33 used specific technique (was used by): E29 Design or Procedure.'),
(431, 1, 14, 'P20i_was_purpose_of', 'was purpose of', NULL),
(432, 1, 14, 'P21_had_general_purpose', 'had general purpose', 'This property describes an intentional relationship between an instance of E7 Activity and some general goal or purpose, described as an instance of E55 Type.\nThis may involve activities intended as preparation for some type of activity or event. P21 had general purpose (was purpose of) differs from P20 had specific purpose (was purpose of in that no specific event is implied as the purpose.'),
(433, 1, 14, 'P21i_was_purpose_of', 'was purpose of', NULL),
(434, 1, 14, 'P22_transferred_title_to', 'transferred title to', 'This property identifies the instance of E39 Actor that acquires the legal ownership of an object as a result of an instance of E8 Acquisition.\nThe property will typically describe an Actor purchasing or otherwise acquiring an object from another Actor. However, title may also be acquired without any corresponding loss of title by another Actor, through legal fieldwork such as hunting, shooting, or fishing.\nIn reality, the title is either transferred to or from someone, or both.'),
(435, 1, 14, 'P22i_acquired_title_through', 'acquired title through', NULL),
(436, 1, 14, 'P23_transferred_title_from', 'transferred title from', 'This property identifies the instance(s) of E39 Actor who relinquish legal ownership as the result of an instance of E8 Acquisition.\nThe property will typically be used to describe a person donating or selling an object to a museum. In reality, the title is either transferred to or from someone, or both.'),
(437, 1, 14, 'P23i_surrendered_title_through', 'surrendered title through', NULL),
(438, 1, 14, 'P24_transferred_title_of', 'transferred title of', 'This property identifies the instance(s) of E18 Physical Thing involved in an instance of E8 Acquisition.\nIn reality, an acquisition must refer to at least one transferred item.'),
(439, 1, 14, 'P24i_changed_ownership_through', 'changed ownership through', NULL),
(440, 1, 14, 'P25_moved', 'moved', 'This property identifies an instance of E19 Physical Object that was moved by an instance of E9 Move. A move must concern at least one object.\nThe property implies the object’s passive participation. For example, Monet’s painting “Impression sunrise” was moved for the first Impressionist exhibition in 1874.'),
(441, 1, 14, 'P25i_moved_by', 'moved by', NULL),
(442, 1, 14, 'P26_moved_to', 'moved to', 'This property identifies a destination, an instance of E53 Place, of an instance of E9 Move.\nA move will be linked to a destination, such as the move of an artifact from storage to display. A move may be linked to many terminal instances of E53 Place by multiple instances of this property. In this case the move describes a distribution of a set of objects. The area of the move includes the origin(s), route and destination(s).\nTherefore, the described destination is an instance of E53 Place which P89 falls within (contains) the instance of E53 Place the move P7 took place at.'),
(443, 1, 14, 'P26i_was_destination_of', 'was destination of', NULL),
(444, 1, 14, 'P27_moved_from', 'moved from', 'This property identifies an origin, an instance of E53 Place, of an instance of E9 Move.\nA move will be linked to an origin, such as the move of an artifact from storage to display. A move may be linked to many starting instances of E53 Place by multiple instances of this property. In this case the move describes the picking up of a set of objects. The area of the move includes the origin(s), route and destination(s).\nTherefore, the described origin is an instance of E53 Place which P89 falls within (contains) the instance of E53 Place the move P7 took place at.'),
(445, 1, 14, 'P27i_was_origin_of', 'was origin of', NULL),
(446, 1, 14, 'P28_custody_surrendered_by', 'custody surrendered by', 'This property identifies the instance(s) of E39 Actor who surrender custody of an instance of E18 Physical Thing in an instance of E10 Transfer of Custody.\nThe property will typically describe an Actor surrendering custody of an object when it is handed over to someone else’s care. On occasion, physical custody may be surrendered involuntarily, e.g. through accident, loss, or theft.\nIn reality, custody is either transferred to someone or from someone, or both.'),
(447, 1, 14, 'P28i_surrendered_custody_through', 'surrendered custody through', NULL),
(448, 1, 14, 'P29_custody_received_by', 'custody received by', 'This property identifies the instance(s) of E39 Actor who receive custody of an instance of E18 Physical Thing in an instance of E10 Transfer of Custody.\nThe property will typically describe Actors receiving custody of an object when it is handed over from another Actor’s care. On occasion, physical custody may be received involuntarily or illegally, e.g. through accident, unsolicited donation, or theft.\nIn reality, custody is either transferred to someone or from someone, or both.'),
(449, 1, 14, 'P29i_received_custody_through', 'received custody through', NULL),
(450, 1, 14, 'P30_transferred_custody_of', 'transferred custody of', 'This property identifies the instance(s) of E18 Physical Thing concerned in an instance of E10 Transfer of Custody.\nThe property will typically describe the object that is handed over by an instance of E39 Actor to the custody of another instance of E39 Actor. On occasion, physical custody may be transferred involuntarily or illegally, e.g. through accident, unsolicited donation, or theft.'),
(451, 1, 14, 'P30i_custody_transferred_through', 'custody transferred through', NULL),
(452, 1, 14, 'P31_has_modified', 'has modified', 'This property identifies the instance of E18 Physical Thing modified in an instance of E11 Modification.'),
(453, 1, 14, 'P31i_was_modified_by', 'was modified by', NULL),
(454, 1, 14, 'P32_used_general_technique', 'used general technique', 'This property identifies the technique or method, modelled as an instance of E55 Type, that was employed in an instance of E7 Activity.\nThese techniques should be drawn from an external E55 Type hierarchy of consistent terminology of general techniques or methods such as embroidery, oil-painting, carbon dating, etc. Specific documented techniques should be described as instances of E29 Design or Procedure.'),
(455, 1, 14, 'P32i_was_technique_of', 'was technique of', NULL),
(456, 1, 14, 'P33_used_specific_technique', 'used specific technique', 'This property identifies a specific instance of E29 Design or Procedure in order to carry out an instance of E7 Activity or parts of it.\nThe property differs from P32 used general technique (was technique of) in that P33 refers to an instance of E29 Design or Procedure, which is a concrete information object in its own right rather than simply being a term or a method known by tradition.\nTypical examples would include intervention plans for conservation or the construction plans of a building.'),
(457, 1, 14, 'P33i_was_used_by', 'was used by', NULL),
(458, 1, 14, 'P34_concerned', 'concerned', 'This property identifies the instance of E18 Physical Thing that was assessed during an instance of E14 Condition Assessment.\nConditions may be assessed either by direct observation or using recorded evidence. In the latter case the instance of E18 Physical Thing does not need to be present or extant at the time of assessment.'),
(459, 1, 14, 'P34i_was_assessed_by', 'was assessed by', NULL),
(460, 1, 14, 'P35_has_identified', 'has identified', 'This property identifies the instance of E3 Condition State that was observed in an instance of E14 Condition Assessment activity.'),
(461, 1, 14, 'P35i_was_identified_by', 'was identified by', NULL),
(462, 1, 14, 'P37_assigned', 'assigned', 'This property records the identifier that was assigned to an item in an instance of E15 Identifier Assignment.\nThe same identifier may be assigned on more than one occasion.\nAn identifier might be created prior to an assignment.'),
(463, 1, 14, 'P37i_was_assigned_by', 'was assigned by', NULL),
(464, 1, 14, 'P38_deassigned', 'deassigned', 'This property records the identifier that was deassigned from an instance of E1 CRM Entity.\nDe-assignment of an identifier may be necessary when an item is taken out of an inventory, a new numbering system is introduced or items are merged or split up.\nThe same identifier may be deassigned on more than one occasion.'),
(465, 1, 14, 'P38i_was_deassigned_by', 'was deassigned by', NULL),
(466, 1, 14, 'P39_measured', 'measured', 'This property associates an instance of E16 Measurement with the instance of E18 Physical Thing upon which it acted. The instance of E16 Measurement is specific to the measured object. An instance of E18 Physical Thing may be measured more than once with different results, constituting different instances of E16 Measurement.'),
(467, 1, 14, 'P39i_was_measured_by', 'was measured by', NULL),
(468, 1, 14, 'P40_observed_dimension', 'observed dimension', 'This property records the dimension that was observed in an E16 Measurement Event.\nE54 Dimension can be any quantifiable aspect of E70 Thing. Weight, image colour depth and monetary value are dimensions in this sense. One measurement activity may determine more than one dimension of one object.\nDimensions may be determined either by direct observation or using recorded evidence. In the latter case the measured Thing does not need to be present or extant.\nEven though knowledge of the value of a dimension requires measurement, the dimension may be an object of discourse prior to, or even without, any measurement being made.'),
(469, 1, 14, 'P40i_was_observed_in', 'was observed in', NULL),
(470, 1, 14, 'P41_classified', 'classified', 'This property records the item to which a type was assigned in an E17 Type Assignment activity.\nAny instance of a CIDOC CRM entity may be assigned a type through type assignment. Type assignment events allow a more detailed path from E1 CRM Entity through P41i was classified by, E17 Type Assignment, P42 assigned, to E55 Type for assigning types to objects compared to the shortcut offered by P2 has type (is type of).'),
(471, 1, 14, 'P41i_was_classified_by', 'was classified by', NULL),
(472, 1, 14, 'P42_assigned', 'assigned', 'This property records the type that was assigned to an entity by an E17 Type Assignment activity.\nType assignment events allow a more detailed path from E1 CRM Entity through P41i was classified by, E17 Type Assignment, P42 assigned, to E55 Type for assigning types to objects compared to the shortcut offered by P2 has type (is type of).\nFor example, a fragment of an antique vessel could be assigned the type “attic red figured belly handled amphora” by expert A. The same fragment could be assigned the type “shoulder handled amphora” by expert B.\nA Type may be intellectually constructed independent from assigning an instance of it.'),
(473, 1, 14, 'P42i_was_assigned_by', 'was assigned by', NULL),
(474, 1, 14, 'P43_has_dimension', 'has dimension', 'This property records an instance of E54 Dimension of some instance of E70 Thing.\nIn the case that the recorded property is a result of a measurement of an instance of E18 Physical Thing, this property is a shortcut of the more fully developed path from E18 Physical Thing through P39i was measured by, E16 Measurement, P40 observed dimension to E54 Dimension.\nIt offers no information about how and when an E54 Dimension was established, nor by whom. Knowledge about an instance of E54 Dimension need not be the result of a measurement; it may be the result of evaluating data or other information, which should be documented as an instance of E13 Attribute Assignment.\nAn instance of E54 Dimension is specific to an instance of E70 Thing.'),
(475, 1, 14, 'P43i_is_dimension_of', 'is dimension of', NULL),
(476, 1, 14, 'P44_has_condition', 'has condition', 'This property records an E3 Condition State for some E18 Physical Thing.\nThis property is a shortcut of the more fully developed path from E18 Physical Thing through P34i was assessed by, E14 Condition Assessment, P35 has identified to E3 Condition State. It offers no information about how and when the E3 Condition State was established, nor by whom.\nAn instance of E3 Condition State is specific to an instance of E18 Physical Thing.'),
(477, 1, 14, 'P44i_is_condition_of', 'is condition of', NULL),
(478, 1, 14, 'P45_consists_of', 'consists of', 'This property identifies the instances of E57 Materials of which an instance of E18 Physical Thing is composed.\nAll physical things consist of physical materials. P45 consists of (is incorporated in) allows the different materials to be recorded. P45 consists of (is incorporated in) refers here to observed material as opposed to the consumed raw material.\nA material, such as a theoretical alloy, may not have any physical instances.'),
(479, 1, 14, 'P45i_is_incorporated_in', 'is incorporated in', NULL),
(480, 1, 14, 'P46_is_composed_of', 'is composed of', 'This property associates an instance of E18 Physical Thing with another instance of Physical Thing that forms part of it. The spatial extent of the composing part is included in the spatial extent of the whole.\nComponent elements, since they are themselves instances of E18 Physical Thing, may be further analysed into sub-components, thereby creating a hierarchy of part decomposition. An instance of E18 Physical Thing may be shared between multiple wholes, for example two buildings may share a common wall. This property does not specify when and for how long a component element resided in the respective whole. If a component is not part of a whole from the beginning of existence or until the end of existence of the whole, the classes E79 Part Addition and E90 Part Removal can be used to document when a component became part of a particular whole and/or when it stopped being a part of it. For the time-span of being part of the respective whole, the component is completely contained in the place the whole occupies.\nThis property is intended to describe specific components that are individually documented, rather than general aspects. Overall descriptions of the structure of an instance of E18 Physical Thing are captured by the P3 has note property.\nThe instances of E57 Material of which an instance of E18 Physical Thing is composed should be documented using P45 consists of (is incorporated in).\nThis property is transitive and asymmetric.'),
(481, 1, 14, 'P46i_forms_part_of', 'forms part of', NULL),
(482, 1, 14, 'P48_has_preferred_identifier', 'has preferred identifier', 'This property records the preferred instance of E42 Identifier that was used to identify an instance of E1 CRM Entity at the time this property was recorded.\nMore than one preferred identifier may have been assigned to an item over time.\nUse of this property requires an external mechanism for assigning temporal validity to the respective CIDOC CRM instance.\nThe fact that an identifier is a preferred one for an organisation can be better expressed in a context independent form by assigning a suitable instance of E55 Type to the respective instance of E15 Identifier Assignment using the P2 has type property.'),
(483, 1, 14, 'P48i_is_preferred_identifier_of', 'is preferred identifier of', NULL),
(484, 1, 14, 'P49_has_former_or_current_keeper', 'has former or current keeper', 'This property identifies the instance of E39 Actor who has or has had custody of an instance of E18 Physical Thing at some time. This property leaves open the question if parts of this physical thing have been added or removed during the time-spans it has been under the custody of this actor, but it is required that at least a part which can unambiguously be identified as representing the whole has been under this custody for its whole time. The way, in which a representative part is defined, should ensure that it is unambiguous who keeps a part and who the whole and should be consistent with the identity criteria of the kept instance of E18 Physical Thing.\nThe distinction with P50 has current keeper (is current keeper of) is that P49 has former or current keeper (is former or current keeper of) leaves open the question as to whether the specified keepers are current.\nThis property is a shortcut for the more detailed path from E18 Physical Thing through P30i custody transferred through, E10 Transfer of Custody, P28 custody surrendered by or P29 custody received by to E39 Actor.'),
(485, 1, 14, 'P49i_is_former_or_current_keeper_of', 'is former or current keeper of', NULL),
(486, 1, 14, 'P50_has_current_keeper', 'has current keeper', 'This property identifies the instance of E39 Actor that had custody of an instance of E18 Physical Thing at the time of validity of the record or database containing the statement that uses this property.\nThis property is a shortcut for the more detailed path from E18 Physical Thing through, P30i custody transferred through, E10 Transfer of Custody, P29 custody received by to E39 Actor, if and only if the custody has not been surrendered by the receiving actor at any later time'),
(487, 1, 14, 'P50i_is_current_keeper_of', 'is current keeper of', NULL),
(488, 1, 14, 'P51_has_former_or_current_owner', 'has former or current owner', 'This property identifies an instance of E39 Actor that is or had been the legal owner (i.e. title holder) of an instance of E18 Physical Thing at some time.\nThe distinction with P52 has current owner (is current owner of) is that P51 has former or current owner (is former or current owner of) does not indicate whether the specified owners are current.\nThis property is a shortcut for the more detailed path from E18 Physical Thing through P24i changed ownership through, E8 Acquisition, P23 transferred title from, or P22 transferred title to to E39 Actor.'),
(489, 1, 14, 'P51i_is_former_or_current_owner_of', 'is former or current owner of', NULL),
(490, 1, 14, 'P52_has_current_owner', 'has current owner', 'This property identifies the instance of E21 Person or E74 Group that was the owner of an instance of E18 Physical Thing at the time of validity of the record or database containing the statement that uses this property.\nThis property is a shortcut for the more detailed path from E18 Physical Thing through, P24i changed ownership through, E8 Acquisition, P22 transferred title to to E39 Actor, if and only if this acquisition event is the most recent.'),
(491, 1, 14, 'P52i_is_current_owner_of', 'is current owner of', NULL),
(492, 1, 14, 'P53_has_former_or_current_location', 'has former or current location', 'This property identifies an instance of E53 Place as the former or current location of an instance of E18 Physical Thing.\nIn the case of instances of E19 Physical Object, the property does not allow any indication of the Time-Span during which the instance of E19 Physical Object was located at this instance of E53 Place, nor if this is the current location.\nIn the case of immobile objects, the Place would normally correspond to the Place of creation.\nThis property is a shortcut. A more detailed representation can make use of the fully developed (i.e. indirect) path from E19 Physical Object, though, P25i moved by, E9 Move, P26 moved to or P27 moved from to E53 Place.'),
(493, 1, 14, 'P53i_is_former_or_current_location_of', 'is former or current location of', NULL),
(494, 1, 14, 'P54_has_current_permanent_location', 'has current permanent location', 'This property records the foreseen permanent location of an instance of E19 Physical Object at the time of validity of the record or database containing the statement that uses this property.\nP54 has current permanent location (is current permanent location of) is similar to P55 has current location (currently holds). However, it indicates the E53 Place currently reserved for an object, such as the permanent storage location or a permanent exhibit location. The object may be temporarily removed from the permanent location, for example when used in temporary exhibitions or loaned to another institution. The object may never actually be located at its permanent location.'),
(495, 1, 14, 'P54i_is_current_permanent_location_of', 'is current permanent location of', NULL),
(496, 1, 14, 'P55_has_current_location', 'has current location', 'This property records the location of an instance of E19 Physical Object at the time of validity of the record or database containing the statement that uses this property.\nThis property is a specialisation of P53 has former or current location (is former or current location of). It indicates that the instance of E53 Place associated with the instance of E19 Physical Object is the current location of the object. The property does not allow any indication of how long the object has been at the current location.\nThis property is a shortcut. A more detailed representation can make use of the fully developed (i.e., indirect) path from E19 Physical Object, through, P25i moved by, E9 Move, P26 moved to to E53 Place if and only if this Move is the most recent.'),
(497, 1, 14, 'P55i_currently_holds', 'currently holds', NULL),
(498, 1, 14, 'P56_bears_feature', 'bears feature', 'This property links an instance of E19 Physical Object to an instance of E26 Physical Feature that it bears.\nAn instance of E26 Physical Feature can only exist on one object. One object may bear more than one E26 Physical Feature. An instance of E27 Site should be considered as an instance of E26 Physical Feature on the surface of the Earth.\nAn instance B of E26 Physical Feature being a detail of the structure of another instance A of E26 Physical Feature can be linked to B by use of the property P46 is composed of (forms part of). This implies that the subfeature B is P56i is found on the same E19 Physical Object as A.\nThis property is a shortcut. A more detailed representation can make use of the fully developed (i.e. indirect) path E19 Physical Object, through, P59 has section, E53 Place, P53i is former or current location of to E26 Physical Feature.'),
(499, 1, 14, 'P56i_is_found_on', 'is found on', NULL),
(500, 1, 14, 'P57_has_number_of_parts', 'has number of parts', 'This property documents the number of parts, an instance of E60 Number, of which an instance of E19 Physical Object is composed.\nThis may be used as a method of checking inventory counts with regard to aggregate or collective objects. What constitutes a part or component depends on the context and requirements of the documentation. Normally, the parts documented in this way would not be considered as worthy of individual attention.\nFor a more complete description, objects may be decomposed into their components and constituents using P46 is composed of (forms parts of) and P45 consists of (is incorporated in). This allows each element to be described individually.'),
(501, 1, 14, 'P59_has_section', 'has section', 'This property links an area, i.e., an instance of E53 Place to the instance of E18 Physical Thing upon which it is found. This area may either be identified by a name, or by a geometry in terms of a coordinate system adapted to the shape of the respective instance of E18 Physical Thing. Typically, names identifying sections of physical objects are composed of the name of a kind of part and the name of the object itself, such as “The poop deck of H.M.S. Victory”, which is composed of “poop deck” and “H.M.S. Victory”.'),
(502, 1, 14, 'P59i_is_located_on_or_within', 'is located on or within', NULL),
(503, 1, 14, 'P62_depicts', 'depicts', 'This property identifies something that is depicted by an instance of E24 Physical Human-Made Thing. Depicting is meant in the sense that an instance of E24 Physical Human-Made Thing intentionally shows, through its optical qualities or form, a representation of the entity depicted. Photographs are by default regarded as being intentional in this sense. Anything that is designed to change the properties of the depiction, such as an e-book reader, is specifically excluded. The property does not pertain to inscriptions or any other information encoding.\nThis property is a shortcut of the more fully developed path from E24 Physical Human-Made Thing through P65 shows visual item, E36 Visual Item, P138 represents to E1 CRM Entity. P62.1 mode of depiction allows the nature of the depiction to be refined.'),
(504, 1, 14, 'P62i_is_depicted_by', 'is depicted by', NULL),
(505, 1, 14, 'P65_shows_visual_item', 'shows visual item', 'This property documents an instance of E36 Visual Item shown by an instance of E24 Physical Human-Made Thing.\nThis property is similar to P62 depicts (is depicted by) in that it associates an instance of E24 Physical Human-Made Thing with a visual representation. However, P65 shows visual item (is shown by) differs from the P62 depicts (is depicted by) property in that it makes no claims about what the instance of E36 Visual Item is deemed to represent. An instance of E36 Visual Item identifies a recognisable image or visual symbol, regardless of what this image may or may not represent.\nFor example, all recent British coins bear a portrait of Queen Elizabeth II, a fact that is correctly documented using P62 depicts (is depicted by). Different portraits have been used at different periods, however. P65 shows visual item (is shown by) can be used to refer to a particular portrait.\nP65 shows visual item (is shown by) may also be used for Visual Items such as signs, marks and symbols, for example the \'Maltese Cross\' or the \'copyright symbol’ that have no particular representational content.\nThis property is part of the fully developed path E24 Physical Human-Made Thing, P65 shows visual item, E36 Visual Item, P138 represents to E1 CRM Entity which is shortcut by, P62 depicts (is depicted by).'),
(506, 1, 14, 'P65i_is_shown_by', 'is shown by', NULL),
(507, 1, 14, 'P67_refers_to', 'refers to', 'This property documents that an instance of E89 Propositional Object makes a statement about an instance of E1 CRM Entity. P67 refers to (is referred to by) has the P67.1 has type link to an instance of E55 Type. This is intended to allow a more detailed description of the type of reference. This differs from P129 is about (is subject of), which describes the primary subject or subjects of the instance of E89 Propositional Object.'),
(508, 1, 14, 'P67i_is_referred_to_by', 'is referred to by', NULL),
(509, 1, 14, 'P68_foresees_use_of', 'foresees use of', 'This property identifies an instance of E57 Material foreseen to be used by an instance of E29 Design or Procedure.\nE29 Designs and procedures commonly foresee the use of particular instances of E57 Material. The fabrication of adobe bricks, for example, requires straw, clay and water. This property enables this to be documented.\nThis property is not intended for the documentation of instances of E57 Materials that were used on a particular occasion when an instance of E29 Design or Procedure was executed.'),
(510, 1, 14, 'P68i_use_foreseen_by', 'use foreseen by', NULL),
(511, 1, 14, 'P69_has_association_with', 'has association with', 'This property generalises relationships like whole-part, sequence, prerequisite or inspired by between instances of E29 Design or Procedure. Any instance of E29 Design or Procedure may be associated with other designs or procedures. The property is considered to be symmetrical unless otherwise indicated by P69.1 has type. The property is not transitive.\nThis property is a directed relationship. The P69.1 has type property of P69 has association with allows the nature of the association to be specified reading from domain to range; examples of types of association between instances of E29 Design or Procedure include: has part, follows, requires, etc.\nInstances of this property are considered to be symmetric, in case no directed sense is provided for them by the property P69.1 has type.\nThe property can typically be used to model the decomposition of the description of a complete workflow into a series of separate procedures.'),
(512, 1, 14, 'P69i_is_associated_with', 'is associated with', NULL),
(513, 1, 14, 'P70_documents', 'documents', 'This property describes the CRM Entities documented as instances of E31 Document.\nDocuments may describe any conceivable entity, hence the link to the highest-level entity in the CIDOC CRM class hierarchy. This property is intended for cases where a reference is regarded as making a proposition about reality. This may be of a documentary character, in the scholarly or scientific sense, or a more general statement.'),
(514, 1, 14, 'P70i_is_documented_in', 'is documented in', NULL),
(515, 1, 14, 'P71_lists', 'lists', 'This property associates an instance of E32 Authority Document with an instance of E1 CRM Entity which it lists for reference purposes.'),
(516, 1, 14, 'P71i_is_listed_in', 'is listed in', NULL),
(517, 1, 14, 'P72_has_language', 'has language', 'This property associates an instance(s) of E33 Linguistic Object with an instance of E56 Language in which it is, at least partially, expressed.\nLinguistic Objects are composed in one or more human languages. This property allows these languages to be documented.'),
(518, 1, 14, 'P72i_is_language_of', 'is language of', NULL),
(519, 1, 14, 'P73_has_translation', 'has translation', 'This property links an instance of E33 Linguistic Object (A), to another instance of E33 Linguistic Object (B) which is the translation of A.\nWhen an instance of E33 Linguistic Object is translated into a new language a new instance of E33 Linguistic Object is created, despite the translation being conceptually similar to the source.\nThis property is asymmetric.'),
(520, 1, 14, 'P73i_is_translation_of', 'is translation of', NULL),
(521, 1, 14, 'P74_has_current_or_former_residence', 'has current or former residence', 'This property describes the current or former place of residence (an instance of E53 Place) of an instance of E39 Actor.\nThe residence may be either the place where the actor resides, or a legally registered address of any kind.'),
(522, 1, 14, 'P74i_is_current_or_former_residence_of', 'is current or former residence of', NULL),
(523, 1, 14, 'P75_possesses', 'possesses', 'This property associates an instance of E39 Actor to an instance of E30 Right over which the actor holds or has held a legal claim.'),
(524, 1, 14, 'P75i_is_possessed_by', 'is possessed by', NULL),
(525, 1, 14, 'P76_has_contact_point', 'has contact point', 'This property associates an instance of E39 Actor to an instance of E41 Appellation which a communication service uses to direct communications to this actor, such as an e-mail address, fax number, or postal address.'),
(526, 1, 14, 'P76i_provides_access_to', 'provides access to', NULL),
(527, 1, 14, 'P79_beginning_is_qualified_by', 'beginning is qualified by', 'This property associates an instance of E52 Time-Span with a note detailing the scholarly or scientific opinions and justifications about the certainty, precision, sources etc. of its beginning. Such notes may also be used to elaborate arguments about constraints or to give explanations of alternatives.'),
(528, 1, 14, 'P80_end_is_qualified_by', 'end is qualified by', 'This property associates an instance of E52 Time-Span with a note detailing the scholarly or scientific opinions and justifications about the end of this time-span concerning certainty, precision, sources etc. This property may also be used to describe arguments constraining possible dates and to distinguish reasons for alternative dates.'),
(529, 1, 14, 'P81_ongoing_throughout', 'ongoing throughout', 'This property associates an instance of E52 Time-Span with an instance of E61 Time Primitive specifying a minimum period of time covered by it. Since Time-Spans may not have precisely known temporal extents, the CIDOC CRM supports statements about the minimum and maximum temporal extents of Time-Spans. This property allows a Time-Span’s minimum temporal extent (i.e., its inner boundary) to be assigned an E61 Time Primitive value. Time Primitives are treated by the CIDOC CRM as application or system specific date intervals, and are not further analysed. If different sources of evidence justify different minimum extents without contradicting each other, the smallest interval including all these extents will be the best estimate. This should be taken into account for information integration.'),
(530, 1, 14, 'P81a_end_of_the_begin', 'end of the begin', NULL),
(531, 1, 14, 'P81b_begin_of_the_end', 'begin of the end', NULL);
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(532, 1, 14, 'P82_at_some_time_within', 'at some time within', 'This property describes the maximum period of time within which an E52 Time-Span falls. Since Time-Spans may not have precisely known temporal extents, the CIDOC CRM supports statements about the minimum and maximum temporal extents of Time-Spans. This property allows a Time-Span’s maximum temporal extent (i.e. its outer boundary) to be assigned an E61 Time Primitive value. Time Primitives are treated by the CIDOC CRM as application or system specific date intervals, and are not further analysed. If different sources of evidence justify different maximum extents without contradicting each other, the resulting intersection of all these extents will be the best estimate. This should be taken into account for information integration.'),
(533, 1, 14, 'P82a_begin_of_the_begin', 'begin of the begin', NULL),
(534, 1, 14, 'P82b_end_of_the_end', 'end of the end', NULL),
(535, 1, 14, 'P86_falls_within', 'falls within', 'This property describes the inclusion relationship between two instances of E52 Time-Span.\nThis property supports the notion that the temporal extent of an instance of E52 Time-Span falls within the temporal extent of another instance of E52 Time-Span. It addresses temporal containment only, and no contextual link between the two instances of E52 Time-Span is implied. This property is transitive and reflexive.'),
(536, 1, 14, 'P86i_contains', 'contains', NULL),
(537, 1, 14, 'P89_falls_within', 'falls within', 'This property identifies an instance of E53 Place that falls wholly within the extent of another instance of E53 Place.\nIt addresses spatial containment only and does not imply any relationship between things or phenomena occupying these places.\nThis property is transitive and reflexive.'),
(538, 1, 14, 'P89i_contains', 'contains', NULL),
(539, 1, 14, 'P90_has_value', 'has value', 'This property allows an instance of E54 Dimension to be approximated by an instance of E60 Number primitive.'),
(540, 1, 14, 'P90a_has_lower_value_limit', 'has lower value limit', NULL),
(541, 1, 14, 'P90b_has_upper_value_limit', 'has upper value limit', NULL),
(542, 1, 14, 'P91_has_unit', 'has unit', 'This property shows the type of unit an instance of E54 Dimension was expressed in.'),
(543, 1, 14, 'P91i_is_unit_of', 'is unit of', NULL),
(544, 1, 14, 'P92_brought_into_existence', 'brought into existence', 'This property links an instance of E63 Beginning of Existence to the instance of E77 Persistent Item brought into existence by it.\nIt allows a “start” to be attached to any instance of E77 Persistent Item being documented, i.e., as instances of E70 Thing, E72 Legal Object, E39 Actor, E41 Appellation and E55 Type.'),
(545, 1, 14, 'P92i_was_brought_into_existence_by', 'was brought into existence by', NULL),
(546, 1, 14, 'P93_took_out_of_existence', 'took out of existence', 'This property links an instance of E64 End of Existence to the instance of E77 Persistent Item taken out of existence by it.\nIn the case of immaterial things, the instance of E64 End of Existence is considered to take place with the destruction of the last physical carrier.\nThis allows an “end” to be attached to any instance of E77 Persistent Item being documented i.e. instances of E70 Thing, E72 Legal Object, E39 Actor, E41 Appellation, and E55 Type. For many instances of E77 Persistent Item we know the maximum life-span and can infer that they must have ended to exist. We assume in that case an instance of E64 End of Existence, which may be as unnoticeable as forgetting the secret knowledge by the last representative of some indigenous nation.'),
(547, 1, 14, 'P93i_was_taken_out_of_existence_by', 'was taken out of existence by', NULL),
(548, 1, 14, 'P94_has_created', 'has created', 'This property links an instance of E65 Creation to the instance of E28 Conceptual Object created by it.\nIt represents the act of conceiving the intellectual content of the instance of E28 Conceptual Object. It does not represent the act of creating the first physical carrier of the instance of E28 Conceptual Object. As an example, this is the composition of a poem, not its commitment to paper.'),
(549, 1, 14, 'P94i_was_created_by', 'was created by', NULL),
(550, 1, 14, 'P95_has_formed', 'has formed', 'This property associates the instance of E66 Formation with the instance of E74 Group that it founded.'),
(551, 1, 14, 'P95i_was_formed_by', 'was formed by', NULL),
(552, 1, 14, 'P96_by_mother', 'by mother', 'This property links an instance of E67 Birth to an instance of E21 Person in the role of birth-giving mother.\nNote that biological fathers are not necessarily participants in the Birth (see P97 from father (was father for)). The instance of E21 Person being born is linked to the instance of E67 Birth with the property P98 brought into life (was born). This is not intended for use with general natural history material, only people. There is no explicit method for modelling conception and gestation except by using extensions.'),
(553, 1, 14, 'P96i_gave_birth', 'gave birth', NULL),
(554, 1, 14, 'P97_from_father', 'from father', 'This property links an instance of E67 Birth to an instance of E21 Person in the role of biological father.\nNote that biological fathers are not seen as necessary participants in the birth, whereas birth-giving mothers are (see P96 by mother (gave birth)). The Person being born is linked to the Birth with the property P98 brought into life (was born).\nThis is not intended for use with general natural history material, only people. There is no explicit method for modelling conception and gestation except by using extensions.\nAn instance of E67 Birth is normally (but not always) associated with one biological father.'),
(555, 1, 14, 'P97i_was_father_for', 'was father for', NULL),
(556, 1, 14, 'P98_brought_into_life', 'brought into life', 'This property links an instance of E67 Birth event to an instance of E21 Person in the role of offspring.\nTwins, triplets etc. are brought into life by the same instance of E67 Birth. This is not intended for use with general Natural History material, only people. There is no explicit method for modelling conception and gestation except by using extensions.'),
(557, 1, 14, 'P98i_was_born', 'was born', NULL),
(558, 1, 14, 'P99_dissolved', 'dissolved', 'This property associates the instance of E68 Dissolution with the instance of E74 Group that it disbanded.'),
(559, 1, 14, 'P99i_was_dissolved_by', 'was dissolved by', NULL),
(560, 1, 14, 'P100_was_death_of', 'was death of', 'This property links an instance of E69 Death to the instance of E21 Person that died.\nAn instance of E69 Death may involve multiple people, for example in the case of a battle or disaster.\nThis is not intended for use with general natural history material, only people.'),
(561, 1, 14, 'P100i_died_in', 'died in', NULL),
(562, 1, 14, 'P101_had_as_general_use', 'had as general use', 'This property associates an instance of E70 Thing with an instance of E55 Type that describes the type of use that it was actually employed for.\nIt allows the relationship between particular things, both physical and immaterial, and the general methods and techniques of real use to be documented. This may well be different from the intended functional purpose of the instance of E70 Thing (which can be documented with P103 was intended for (was intention of)). For example, it could be recorded that a particular wooden crate had a general use as a shelf support on a market stall even though it had been originally intended for carrying vegetables.\nThe use of this property is intended to allow the documentation of usage patterns attested in historical records or through scientific investigation (for instance ceramic residue analysis). It should not be used to document the intended, and thus assumed, use of an object.'),
(563, 1, 14, 'P101i_was_use_of', 'was use of', NULL),
(564, 1, 14, 'P102_has_title', 'has title', 'This property associates an instance of E35 Title that has been applied to an instance of E71 Human-Made Thing.\nThe P102.1 has type property of the P102 has title (is title of) property enables the relationship between the title and the thing to be further clarified, for example, if the title was a given title, a supplied title etc.\nIt allows any human-made material or immaterial thing to be given a title. It is possible to imagine a title being created without a specific object in mind.'),
(565, 1, 14, 'P102i_is_title_of', 'is title of', NULL),
(566, 1, 14, 'P103_was_intended_for', 'was intended for', 'This property links an instance of E71 Human-Made Thing to an instance of E55 Type of usage or audience. It creates a relation between specific human-made things, both physical and immaterial, to E55 Types. This property can be used to specify intended methods and techniques of use or to characterise the intended audience by indicating a type of personal characteristic that everyone falling into the target audience has.\nNote: A link between specific human-made things and a specific use activity should be expressed using P19 was intended use of (was made for).'),
(567, 1, 14, 'P103i_was_intention_of', 'was intention of', NULL),
(568, 1, 14, 'P104_is_subject_to', 'is subject to', 'This property links a particular instance of E72 Legal Object to the instances of E30 Right to which it is subject.\nThe Right is held by an instance of E39 Actor as described by P75 possesses (is possessed by).'),
(569, 1, 14, 'P104i_applies_to', 'applies to', NULL),
(570, 1, 14, 'P105_right_held_by', 'right held by', 'This property identifies the instance of E39 Actor who holds the instances of E30 Right to an instance of E72 Legal Object.\nIt is a superproperty of P52 has current owner (is current owner of) because ownership is a right that is held on the owned object.\nThis property is a shortcut of the fully developed path from E72 Legal Object, P104 is subject to, E30 Right, P75i is possessed by to E39 Actor.'),
(571, 1, 14, 'P105i_has_right_on', 'has right on', NULL),
(572, 1, 14, 'P106_is_composed_of', 'is composed of', 'This property associates an instance of E90 Symbolic Object with a part of it that is by itself an instance of E90 Symbolic Object, such as fragments of texts or clippings from an image.\nThis property is transitive asymmetric.'),
(573, 1, 14, 'P106i_forms_part_of', 'forms part of', NULL),
(574, 1, 14, 'P107_has_current_or_former_member', 'has current or former member', 'This property associates an instance of E74 Group with an instance of E39 Actor that is or has been a member thereof.\nInstances of E74 Group and E21 Person may all be members of instances of E74 Group. An instance of E74 Group may be founded initially without any member.\nThis property is a shortcut of the more fully developed path from E74 Group, P144i gained member by, E85 Joining, P143 joined to E39 Actor.\nThe property P107.1 kind of member can be used to specify the type of membership or the role the member has in the group.'),
(575, 1, 14, 'P107i_is_current_or_former_member_of', 'is current or former member of', NULL),
(576, 1, 14, 'P108_has_produced', 'has produced', 'This property identifies the instance of E24 Physical Human-Made Thing that came into existence as a result of the instance of E12 Production.\nThe identity of an instance of E24 Physical Human-Made Thing is not defined by its matter, but by its existence as a subject of documentation. An E12 Production can result in the creation of multiple instances of E24 Physical Human-Made Thing.'),
(577, 1, 14, 'P108i_was_produced_by', 'was produced by', NULL),
(578, 1, 14, 'P109_has_current_or_former_curator', 'has current or former curator', 'This property identifies the instance of E39 Actor who assumed or has assumed overall curatorial responsibility for an instance of E78 Curated Holding.\nIt does not allow a history of curation to be recorded. This would require use of an event initiating a curator being responsible for a collection.'),
(579, 1, 14, 'P109i_is_current_or_former_curator_of', 'is current or former curator of', NULL),
(580, 1, 14, 'P110_augmented', 'augmented', 'This property identifies the instance of E18 Physical Thing that is added to (augmented) in an instance of E79 Part Addition.\nAlthough an instance of E79 Part Addition event normally concerns only one instance of E18 Physical Thing, it is possible to imagine circumstances under which more than one item might be added to (augmented). For example, the artist Jackson Pollock trailing paint onto multiple canvasses.'),
(581, 1, 14, 'P110i_was_augmented_by', 'was augmented by', NULL),
(582, 1, 14, 'P111_added', 'added', 'This property identifies the instance of E18 Physical Thing that is added during an instance of E79 Part Addition activity.'),
(583, 1, 14, 'P111i_was_added_by', 'was added by', NULL),
(584, 1, 14, 'P112_diminished', 'diminished', 'This property identifies the instance of E18 Physical Thing that was diminished by an instance of E80 Part Removal.\nAlthough an instance of E80 Part removal activity normally concerns only one instance of E18 Physical Thing, it is possible to imagine circumstances under which more than one item might be diminished by a single instance of E80 Part Removal activity.'),
(585, 1, 14, 'P112i_was_diminished_by', 'was diminished by', NULL),
(586, 1, 14, 'P113_removed', 'removed', 'This property identifies the instance of E18 Physical Thing that is removed during an instance of E80 Part Removal activity.'),
(587, 1, 14, 'P113i_was_removed_by', 'was removed by', NULL),
(588, 1, 14, 'P121_overlaps_with', 'overlaps with', 'This symmetric property associates an instance of E53 Place with another instance of E53 Place geometrically overlapping it.\nIt does not specify anything about the shared area. This property is purely spatial. It does not imply that phenomena that define, by their extent, places related by P121 overlaps with have ever covered a common area at the same time or even coexisted. In contrast, spatiotemporal overlaps described by P132 spatiotemporally overlaps are the total of areas simultaneously covered by the related spacetime volumes.\nThis property is symmetric. This property is reflexive.'),
(589, 1, 14, 'P122_borders_with', 'borders with', 'This symmetric property associates an instance of E53 Place with another instance of E53 Place which shares a part of its border.\nThis property is purely spatial. It does not imply that the phenomena that define, by their extent, places related by P122 borders with have ever shared a respective border at the same time or even coexisted. In particular, this may be the case when the respective common border is formed by a natural feature.\nThis property is not transitive. This property is symmetric.'),
(590, 1, 14, 'P123_resulted_in', 'resulted in', 'This property identifies the instance or instances of E18 Physical Thing that are the result of an instance of E81 Transformation. New items replace the transformed item or items, which cease to exist as units of documentation. The physical continuity between the old and the new is expressed by the links to the common instance of E81 Transformation.'),
(591, 1, 14, 'P123i_resulted_from', 'resulted from', NULL),
(592, 1, 14, 'P124_transformed', 'transformed', 'This property identifies the instance or instances E18 Physical Thing that have ceased to exist due to an instance of E81 Transformation.\nThe item that has ceased to exist and was replaced by the result of the Transformation. The continuity between both items, the new and the old, is expressed by the links to the common instance of E81 Transformation.'),
(593, 1, 14, 'P124i_was_transformed_by', 'was transformed by', NULL),
(594, 1, 14, 'P125_used_object_of_type', 'used object of type', 'This property associates an instance of E7 Activity to an instance of E55 Type, which classifies an instance of E70 Thing used in an instance of E7 Activity, when the specific instance is either unknown or not of interest, such as use of “a hammer”.\nThis property is a shortcut of the more fully developed path from E7 Activity through P16 used specific object, E70 Thing, P2 has type, to E55 Type.'),
(595, 1, 14, 'P125i_was_type_of_object_used_in', 'was type of object used in', NULL),
(596, 1, 14, 'P126_employed', 'employed', 'This property identifies the instance of E57 Material employed in an instance of E11 Modification.\nThe instance of E57 Material used during the instance of E11 Modification does not necessarily become incorporated into the instance of E24 Physical Human-Made Thing that forms the subject of the instance of E11 Modification.'),
(597, 1, 14, 'P126i_was_employed_in', 'was employed in', NULL),
(598, 1, 14, 'P127_has_broader_term', 'has broader term', 'This property associates an instance of E55 Type with another instance of E55 Type that has a broader meaning.\nIt allows instances of E55 Types to be organised into hierarchies. This is the sense of “broader term generic (BTG)” as defined in ISO 25964-2:2013 (International Organization for Standardization 2013).\nThis property is transitive. This property is asymmetric.'),
(599, 1, 14, 'P127i_has_narrower_term', 'has narrower term', NULL),
(600, 1, 14, 'P128_carries', 'carries', 'This property identifies an instance E90 Symbolic Object carried by an instance of E18 Physical Thing. Since an instance of E90 Symbolic Object is defined as an immaterial idealization over potentially multiple carriers, any individual realization on a particular physical carrier may be defective, due to deterioration or shortcomings in the process of creating the realization compared to the intended ideal. As long as such defects do not substantially affect the complete recognition of the respective symbolic object, it is still regarded as carrying an instance of this E90 Symbolic Object. If these defects are of scholarly interest, the particular realization can be modelled as an instance of E25 Human-Made Feature. Note, that any instance of E90 Symbolic Object incorporated (P165) in the carried symbolic object is also carried by the same instance of E18 Physical Thing.'),
(601, 1, 14, 'P128i_is_carried_by', 'is carried by', NULL),
(602, 1, 14, 'P129_is_about', 'is about', 'This property documents that an instance of E89 Propositional Object has as subject an instance of E1 CRM Entity.\nThis differs from P67 refers to (is referred to by), which refers to an instance of E1 CRM Entity, in that it describes the primary subject or subjects of an instance of E89 Propositional Object.'),
(603, 1, 14, 'P129i_is_subject_of', 'is subject of', NULL),
(604, 1, 14, 'P130_shows_features_of', 'shows features of', 'This property generalises the notions of “copy of” and “similar to” into a directed relationship, where the domain expresses the derivative or influenced item and the range the source or influencing item, if such a direction can be established. The property can also be used to express similarity in cases that can be stated between two objects only, without historical knowledge about its reasons. The property expresses a symmetric relationship in case no direction of influence can be established either from evidence on the item itself or from historical knowledge. This holds in particular for siblings of a derivation process from a common source or non-causal cultural parallels, such as some weaving patterns.\nThe P130.1 kind of similarity property of the P130 shows features of (features are also found on) property enables the relationship between the domain and the range to be further clarified, in the sense from domain to range, if applicable. For example, it may be expressed if both items are product “of the same mould”, or if two texts “contain identical paragraphs”.\nIf the reason for similarity is a sort of derivation process, i.e. that the creator has used or had in mind the form of a particular thing during the creation or production, this process should be explicitly modelled. In these cases, P130 shows features of can be regarded as a shortcut of such a process. However, the current model does not contain any path specific enough to infer this property. Specializations of the CIDOC CRM may however be more explicit, for instance describing the use of moulds etc.\nThis property is not transitive. This property is irreflexive.'),
(605, 1, 14, 'P130i_features_are_also_found_on', 'features are also found on', NULL),
(606, 1, 14, 'P132_spatiotemporally_overlaps_with', 'spatiotemporally overlaps with', 'This symmetric property associates two instances of E92 Spacetime Volume that have some of their extents in common. If only the fuzzy boundaries of the instances of E92 Spacetime Volume overlap, this property cannot be determined from observation alone and therefore should not be applied. However, there may be other forms of justification that the two instances of E92 Spacetime Volume must have some of their extents in common regardless of where and when precisely.\nIf this property holds for two instances of E92 Spacetime Volume then it cannot be the case that P133 is spatiotemporally separated from also holds for the same two instances. Furthermore, there are cases where neither P132 spatiotemporally overlaps with nor P133 is spatiotemporally separated from holds between two instances of E92 Spacetime Volume. This would occur where only an overlap of the fuzzy boundaries of the two instances of E92 Spacetime Volume occurs and no other evidence is available.\nThis property is not transitive. This property is symmetric. This property is reflexive.'),
(607, 1, 14, 'P133_is_spatiotemporally_separated_from', 'is spatiotemporally separated from', 'This symmetric property associates two instances of E92 Spacetime Volume that have no extents in common. If only the fuzzy boundaries of the instances of E92 Spacetime Volume overlap, this property cannot be determined from observation alone and therefore should not be applied. However, there may be other forms of justification that the two instances of E92 Spacetime Volume must not have any of their extents in common regardless of where and when precisely.\nIf this property holds for two instances of E92 Spacetime Volume then it cannot be the case that P132 spatiotemporally overlaps with also holds for the same two instances. Furthermore, there are cases where neither P132 spatiotemporally overlaps with nor P133 is spatiotemporally separated from holds between two instances of E92 Spacetime Volume. This would occur where only an overlap of the fuzzy boundaries of the two instances of E92 Spacetime Volume occurs and no other evidence is available.\nThis property is not transitive. This property is symmetric. This property is irreflexive.'),
(608, 1, 14, 'P134_continued', 'continued', 'This property associates two instances of E7 Activity, where the domain is considered as an intentional continuation of the range. A continuation of an activity may happen when the continued activity is still ongoing or after the continued activity has completely ended. The continuing activity may have started already before it decided to continue the other one. Continuation implies a coherence of intentions and outcomes of the involved activities.\nThis property is not transitive. This property is asymmetric.'),
(609, 1, 14, 'P134i_was_continued_by', 'was continued by', NULL),
(610, 1, 14, 'P135_created_type', 'created type', 'This property identifies the instance of E55 Type, which is created in an instance of E83 Type Creation activity.'),
(611, 1, 14, 'P135i_was_created_by', 'was created by', NULL),
(612, 1, 14, 'P136_was_based_on', 'was based on', 'This property identifies one or more instances of E1 CRM Entity that were used as evidence to declare a new instance of E55 Type.\nThe examination of these items is often the only objective way to understand the precise characteristics of a new type. Such items should be deposited in a museum or similar institution for that reason. The taxonomic role renders the specific relationship of each item to the type, such as “holotype” or “original element”.'),
(613, 1, 14, 'P136i_supported_type_creation', 'supported type creation', NULL),
(614, 1, 14, 'P137_exemplifies', 'exemplifies', 'This property associates an instance of E1 CRM Entity with an instance of E55 Type for which it has been declared to be a particularly characteristic example.\nThe P137.1 in the taxonomic role property of P137 exemplifies (is exemplified by) allows differentiation of taxonomic roles. The taxonomic role renders the specific relationship of this example to the type, such as “prototypical”, “archetypical”, “lectotype”, etc. The taxonomic role “lectotype” is not associated with the instance of E83 Type Creation itself but is selected in a later phase.'),
(615, 1, 14, 'P137i_is_exemplified_by', 'is exemplified by', NULL),
(616, 1, 14, 'P138_represents', 'represents', 'This property establishes the relationship between an instance of E36 Visual Item and the instance of E1 CRM Entity that it visually represents.\nAny entity may be represented visually. This property is part of the fully developed path from E24 Physical Human-Made Thing through P65 shows visual item (is shown by), E36 Visual Item, P138 represents (has representation) to E1 CRM Entity, which is shortcut by P62 depicts (is depicted by). P138.1 mode of representation allows the nature of the representation to be refined.\nThis property is also used for the relationship between an original and a digitisation of the original by the use of techniques such as digital photography, flatbed or infrared scanning. Digitisation is here seen as a process with a mechanical, causal component rendering the spatial distribution of structural and optical properties of the original and does not necessarily include any visual similarity identifiable by human observation.'),
(617, 1, 14, 'P138i_has_representation', 'has representation', NULL),
(618, 1, 14, 'P139_has_alternative_form', 'has alternative form', 'This property associates an instance of E41 Appellation with another instance of E41 Appellation that constitutes a derivative or variant of the former and that may also be used for identifying items identified by the former, in suitable contexts, independent from the particular item to be identified. This property should not be confused with additional variants of names used characteristically for a single, particular item, such as individual nicknames. It is a directed relationship, where the range expresses the derivative or variant and the domain the source of derivation or original form of variation, if such a direction can be established. Otherwise, the relationship is symmetric.\nMultiple names assigned to an object, which do not apply to all things identified with the specific instance of E41 Appellation, should be modelled as repeated values of P1 is identified by (identifies) of this object.\nP139.1 has type allows the type of derivation to be refined, for instance “transliteration from Latin 1 to ASCII”.'),
(619, 1, 14, 'P139i_is_alternative_form_of', 'is alternative form of', NULL),
(620, 1, 14, 'P140_assigned_attribute_to', 'assigned attribute to', 'This property associates an instance of E13 Attribute Assignment with the instance of E1 CRM Entity about which it made an attribution. The instance of E1 CRM Entity plays the role of the domain of the attribution.\nThe kind of attribution made should be documented using P177 assigned property of type (is type of property assigned).'),
(621, 1, 14, 'P140i_was_attributed_by', 'was attributed by', NULL),
(622, 1, 14, 'P141_assigned', 'assigned', 'This property associates an instance of E13 Attribute Assignment with the instance of E1 CRM Entity used in the attribution. The instance of E1 CRM Entity here plays the role of the range of the attribution.\nThe kind of attribution made should be documented using P177 assigned property of type (is type of property assigned).'),
(623, 1, 14, 'P141i_was_assigned_by', 'was assigned by', NULL),
(624, 1, 14, 'P142_used_constituent', 'used constituent', 'This property associates an instance of E15 Identifier Assignment with the instance of E90 Symbolic Object used as constituent of an instance of E42 Identifier in this act of assignment.'),
(625, 1, 14, 'P142i_was_used_in', 'was used in', NULL),
(626, 1, 14, 'P143_joined', 'joined', 'This property identifies the instance of E39 Actor that becomes member of an instance of E74 Group in an instance of E85 Joining.\nJoining events allow for describing actors becoming members of a group with the more detailed path E74 Group, P144i gained member by, E85 Joining, P143 joined, E39 Actor, compared to the shortcut offered by P107 has current or former member (is current or former member of).'),
(627, 1, 14, 'P143i_was_joined_by', 'was joined by', NULL),
(628, 1, 14, 'P144_joined_with', 'joined with', 'This property identifies the instance of E74 Group of which an instance of E39 Actor becomes a member through an instance of E85 Joining.\nAlthough a joining activity normally concerns only one instance of E74 Group, it is possible to imagine circumstances under which becoming member of one Group implies becoming member of another Group as well.\nJoining events allow for describing people becoming members of a group with a more detailed path from E74 Group through, P144i gained member by, E85 Joining, P143 joined, E39 Actor, compared to the shortcut offered by P107 has current or former member (is current or former member of).\nThe property P144.1 kind of member can be used to specify the type of membership or the role the member has in the group.'),
(629, 1, 14, 'P144i_gained_member_by', 'gained member by', NULL),
(630, 1, 14, 'P145_separated', 'separated', 'This property identifies the instance of E39 Actor that leaves an instance of E74 Group through an instance of E86 Leaving.'),
(631, 1, 14, 'P145i_left_by', 'left by', NULL),
(632, 1, 14, 'P146_separated_from', 'separated from', 'This property identifies the instance of E74 Group an instance of E39 Actor leaves through an instance of E86 Leaving.\nAlthough a leaving activity normally concerns only one instance of E74 Group, it is possible to imagine circumstances under which leaving one E74 Group implies leaving another E74 Group as well.'),
(633, 1, 14, 'P146i_lost_member_by', 'lost member by', NULL),
(634, 1, 14, 'P147_curated', 'curated', 'This property associates an instance of E87 Curation Activity with the instance of E78 Curated Holding with that is subject of that curation activity following some implicit or explicit curation plan.'),
(635, 1, 14, 'P147i_was_curated_by', 'was curated by', NULL),
(636, 1, 14, 'P148_has_component', 'has component', 'This property associates an instance of E89 Propositional Object with a structural part of it that is by itself an instance of E89 Propositional Object.\nThis property is transitive. This property is asymmetric.'),
(637, 1, 14, 'P148i_is_component_of', 'is component of', NULL),
(638, 1, 14, 'P150_defines_typical_parts_of', 'defines typical parts of', 'This property associates an instance of E55 Type “A” with an instance of E55 Type “B”, when items of type “A” typically form part of items of type “B”, such as “car motors” and “cars”.\nIt allows types to be organised into hierarchies based on one type describing a typical part of another. This property is equivalent to “broader term partitive (BTP)” as defined in ISO 2788 and “broaderPartitive” in SKOS.\nThis property is not transitive. This property is asymmetric.'),
(639, 1, 14, 'P150i_defines_typical_wholes_for', 'defines typical wholes for', NULL),
(640, 1, 14, 'P151_was_formed_from', 'was formed from', 'This property associates an instance of E66 Formation with an instance of E74 Group from which the new group was formed preserving a sense of continuity such as in mission, membership or tradition.'),
(641, 1, 14, 'P151i_participated_in', 'participated in', NULL),
(642, 1, 14, 'P152_has_parent', 'has parent', 'This property associates an instance of E21 Person with another instance of E21 Person who plays the role of the first instance’s parent, regardless of whether the relationship is biological parenthood, assumed or pretended biological parenthood or an equivalent legal status of rights and obligations obtained by a social or legal act.\nThis property is, among others, a shortcut of the fully developed paths from E21 Person through P98i was born, E67 Birth, P96 by mother to E21 Person, and from E21 Person through P98i was born, E67 Birth, P97 from father to E21 Person.\nThis property is not transitive. This property is irreflexive.'),
(643, 1, 14, 'P152i_is_parent_of', 'is parent of', NULL),
(644, 1, 14, 'P156_occupies', 'occupies', 'This property describes the largest volume in space, an instance of E53 Place, that an instance of E18 Physical Thing has occupied at any time during its existence, with respect to the reference space relative to the physical thing itself. This allows for describing the thing itself as a place that may contain other things, such as a box that may contain coins. In other words, it is the volume that contains all the points which the thing has covered at some time during its existence. The reference space for the associated place must be the one that is permanently at rest (P157 is at rest relative to) relative to the physical thing. For instances of E19 Physical Objects it is the one which is at rest relative to the object itself, i.e., which moves together with the object. For instances of E26 Physical Feature it is one which is at rest relative to the physical feature itself and the surrounding matter immediately connected to it. Therefore, there is a 1:1 relation between the instance E18 Physical Thing and the instance of E53 Place it occupies. We include in the occupied space the space filled by the matter of the physical thing and all its inner spaces.\nThis property implies the fully developed path from E18 Physical Thing through P196 defines, E92 Spacetime Volume, P161 has spatial projection to E53 Place. However, in contrast to P156 occupies, the property P161 has spatial projection does not constrain the reference space of the referred instance of E53 Place.\nIn contrast to P156 occupies, for the property P53 has former or current location the following holds:\nIt does not constrain the reference space of the referred instance of E53 Place.\nIt identifies a possibly wider instance of E53 Place at which a thing is or has been for some unspecified time-span.\nIf the reference space of the referred instance of E53 Place is not at rest with respect to the physical thing found there, the physical thing may move away after some time to another place and/or may have been at some other place before. The same holds for the fully developed path from E18 Physical Thing through P196 defines, E92 Spacetime Volume, P161 has spatial projection to E53 Place.'),
(645, 1, 14, 'P156i_is_occupied_by', 'is occupied by', NULL),
(646, 1, 14, 'P157_is_at_rest_relative_to', 'is at rest relative to', 'This property associates an instance of E53 Place with the instance of E18 Physical Thing that determines a reference space for this instance of E53 Place by being at rest with respect to this reference space. The relative stability of form of an instance of E18 Physical Thing defines its default reference space. The reference space is not spatially limited to the referred thing. For example, a ship determines a reference space in terms of which other ships in its neighbourhood may be described. Larger constellations of matter, such as continental plates, may comprise many physical features that are at rest with them and define the same reference space.'),
(647, 1, 14, 'P157i_provides_reference_space_for', 'provides reference space for', NULL),
(648, 1, 14, 'P160_has_temporal_projection', 'has temporal projection', 'This property describes the temporal projection of an instance of E92 Spacetime Volume. The property P4 has time-span is the same as P160 has temporal projection if it is used to document an instance of E4 Period or any subclass of it.'),
(649, 1, 14, 'P160i_is_temporal_projection_of', 'is temporal projection of', NULL),
(650, 1, 14, 'P161_has_spatial_projection', 'has spatial projection', 'This property associates an instance of E92 Spacetime Volume with an instance of E53 Place that is the result of the spatial projection of the instance of the E92 Spacetime Volume on a reference space.\nIn general, there can be more than one useful reference space (for reference space see P156 occupies and P157 is at rest relative to) to describe the spatial projection of a spacetime volume, for example, in describing a sea battle, the difference between the battle ship and the seafloor as reference spaces. Thus, it can be seen that the projection is not unique.\nThe spatial projection is the actual spatial coverage of a spacetime volume, which normally has fuzzy boundaries except for instances of E92 Spacetime Volume which are geometrically defined in the same reference system as the range of this property and are an exception to this and do not have fuzzy boundaries. Modelling explicitly fuzzy spatial projections serves therefore as a common topological reference of different spatial approximations rather than absolute geometric determination, for instance for relating outer or inner spatial boundaries for the respective spacetime volumes.\nThe spatial projection is unique with respect to the reference system. For instance, there is exactly one spatial projection of Lord Nelson’s dying relative to the ship HMS Victory, i.e. the location of his body relative to the ship HMS Victory at the time of his death.\nIn case the domain of an instance of P161 has spatial projection is an instance of E4 Period, the spatial projection describes all areas that period was ever present at, for instance, the Roman Empire.\nThis property is part of the fully developed path from E18 Physical Thing through P196 defines, E92 Spacetime Volume, P161 has spatial projection to E53 Place, which in turn is implied by P156 occupies (is occupied by).'),
(651, 1, 14, 'P161i_is_spatial_projection_of', 'is spatial projection of', NULL),
(652, 1, 14, 'P164_is_temporally_specified_by', 'is temporally specified by', 'This property relates an instance of E93 Presence with the instance of E52 Time-Span that defines the time-slice of the spacetime volume that this instance of E93 Presence is related to via the property P166 was a presence of (had presence).\nThere are two typical cases for the determination of the related instance of E52 Time-Span. In the first, it is the temporal extent of an instance of E2 Temporal Entity (documented with P4 has time-span (is time-span of)): this then documents the simultaneity of the instance of E93 Presence and the instance of E2 Temporal Entity, even if the absolute time-span is not known, and can be regarded as a phenomenal time-span. In the second, the instance of E52 Time-Span is a date range declared in or derived from historical sources or provided by dating methods: this is a declarative time-span.'),
(653, 1, 14, 'P164i_temporally_specifies', 'temporally specifies', NULL),
(654, 1, 14, 'P165_incorporates', 'incorporates', 'This property associates an instance of E73 Information Object with an instance of E90 Symbolic Object (or any of its subclasses) that was included in it.\nThis property makes it possible to recognise the autonomous status of the incorporated signs, which were created in a distinct context, and can be incorporated in many instances of E73 Information Object, and to highlight the difference between structural and accidental whole-part relationships between conceptual entities.\nIt accounts for many cultural facts that are quite frequent and significant: the inclusion of a poem in an anthology, the re-use of an operatic aria in a new opera, the use of a reproduction of a painting for a book cover or a CD booklet, the integration of textual quotations, the presence of lyrics in a song that sets those lyrics to music, the presence of the text of a play in a movie based on that play, etc.\nIn particular, this property allows for modelling relationships of different levels of symbolic specificity, such as the natural language words making up a particular text, the characters making up the words and punctuation, the choice of fonts and page layout for the characters.\nWhen restricted to information objects, that is, seen as a property with E73 Information Object as domain and range the property is transitive.\nA digital photograph of a manuscript page incorporates the text of a manuscript page, if the respective text is defined as a sequence of symbols of a particular type, such as Latin characters, and the resolution and quality of the digital image is sufficient to resolve these symbols so they are readable on the digital image.\nThis property is asymmetric.'),
(655, 1, 14, 'P165i_is_incorporated_in', 'is incorporated in', NULL),
(656, 1, 14, 'P166_was_a_presence_of', 'was a presence of', 'This property associates an instance of E93 Presence with the instance of E92 Spacetime Volume of which it represents a temporal restriction (i.e. a time-slice). Instantiating this property constitutes a necessary part of the identity of the respective instance of E93 Presence.'),
(657, 1, 14, 'P166i_had_presence', 'had presence', NULL),
(658, 1, 14, 'P167_was_within', 'was within', 'This property associates an instance of E93 Presence with an instance of E53 Place that geometrically includes the spatial projection of the respective instance of E93 Presence. Besides others, this property may be used to state in which space an object has been for some known time, such as a room of a castle or in a drawer. It may also be used to describe a confinement of the spatial extent of some realm during a known time-span.\nThis property is a shortcut of the more fully developed path from E93 Presence through P161 has spatial projection, E53 Place, P89 falls within (contains) to E53 Place.'),
(659, 1, 14, 'P167i_includes', 'includes', NULL),
(660, 1, 14, 'P168_place_is_defined_by', 'place is defined by', 'This property associates an instance of E53 Place with an instance of E94 Space Primitive that defines it. Syntactic variants or use of different scripts may result in multiple instances of E94 Space Primitive defining exactly the same place. Transformations between different reference systems always result in new definitions of places approximating each other and not in alternative definitions.'),
(661, 1, 14, 'P169i_spacetime_volume_is_defined_by', 'spacetime volume is defined by', 'Scope note for \'P169\': This property associates an instance of E95 Spacetime Primitive with the instance of E92 Spacetime Volume it defines.'),
(662, 1, 14, 'P170i_time_is_defined_by', 'time is defined by', 'Scope note for \'P170\': This property associates an instance of E61 Time Primitive with the instance of E52 Time-Span that constitutes the interpretation of the terms of the time primitive as an extent in absolute, real time.\nThe quantification allows several instances of E61 Time Primitive that are each expressed in different syntactic forms, to define the same instance of E52 Time-Span.'),
(663, 1, 14, 'P171_at_some_place_within', 'at some place within', 'This property describes the maximum spatial extent within which an instance of E53 Place falls. Since instances of E53 Places may not have precisely known spatial extents, the CIDOC CRM supports statements about maximum spatial extents of instances of E53 Place. This property allows an instance of E53 Place’s maximum spatial extent (i.e., its outer boundary) to be assigned an instance of E94 Space Primitive value.\nThis property is a shortcut of the fully developed path from E53 Place, P89 falls within, E53 Place, P168 place is defined by to E94 Space Primitive through a declarative Place that is not explicitly documented, to a Space Primitive: declarative places are defined in CRMgeo (Doerr and Hiebel 2013).'),
(664, 1, 14, 'P172_contains', 'contains', 'This property describes a minimum spatial extent which is contained within an instance of E53 Place. Since instances of E53 Place may not have precisely known spatial extents, the CIDOC CRM supports statements about minimum spatial extents of instances of E53 Place. This property allows an instance of E53 Place’s minimum spatial extent (i.e., its inner boundary or a point being within a Place) to be assigned an instance of E94 Space Primitive value.\nThis property is a shortcut of the fully developed path from E53 Place, P89i contains, E53 Place, P168 place is defined by to E94 Space Primitive.'),
(665, 1, 14, 'P173_starts_before_or_with_the_end_of', 'starts before or with the end of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity starts before or simultaneously with the end of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-start ≤ B-end is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to the disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets, met-by, overlaps, starts, started-by, contains, finishes, finished-by, equals, during, overlapped by}.\nThis property is not transitive.\n\nFigure 8: Temporal entity A starts before or with the end of temporal entity B. Here A is longer than B\n\nFigure 9: Temporal entity A starts before or with the end of temporal entity B. Here A is shorter than B'),
(666, 1, 14, 'P173i_ends_after_or_with_the_start_of', 'ends after or with the start of', NULL),
(667, 1, 14, 'P174_starts_before_the_end_of', 'starts before the end of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity starts definitely before the end of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-start &lt; B-end is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to a disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets, overlaps, starts, started-by, contains, finishes, finished-by, equals, during, overlapped by}\nTypically, this property is a consequence of a known influence of some event on another event or activity, such as a novel written by someone being continued by someone else, or the knowledge of a defeat on a distant battlefield causing people to end their ongoing activities. This property is not transitive. This property is irreflexive.\n\nFigure 10: Temporal entity A starts before the end of temporal entity B. Here A is longer than B\n\nFigure 11: Temporal entity A starts before the end of temporal entity B. Here A is shorter than B'),
(668, 1, 14, 'P174i_ends_after_the_start_of', 'ends after the start of', NULL),
(669, 1, 14, 'P175_starts_before_or_with_the_start_of', 'starts before or with the start of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity starts before or simultaneously with the start of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-start ≤ B-start is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to a disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets, overlaps, starts, started-by, contains, finished-by, equals}\nIn a model with fuzzy borders, this property will not be transitive.\nThis property is irreflexive.\n\nFigure 12: Temporal entity A starts before or with the start of temporal entity B. Here A is longer than B\n\nFigure 13: Temporal entity A starts before or with the start of temporal entity B. Here A is shorter than B'),
(670, 1, 14, 'P175i_starts_after_or_with_the_start_of', 'starts after or with the start of', NULL),
(671, 1, 14, 'P176_starts_before_the_start_of', 'starts before the start of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity starts definitely before the start of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-start &lt; B-start is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to a disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets, overlaps, contains, finished-by}. This property is transitive. This property is asymmetric.\n\nFigure 14: Temporal entity A starts before the start of temporal entity B. Here A is longer than B\n\nFigure 15: Temporal entity A starts before the start of temporal entity B. Here A is shorter than B'),
(672, 1, 14, 'P176i_starts_after_the_start_of', 'starts after the start of', NULL),
(673, 1, 14, 'P177_assigned_property_of_type', 'assigned property of type', 'This property associates an instance of E13 Attribute Assignment with the type of property or relation that this assignment maintains to hold between the item to which it assigns an attribute and the attribute itself. Note that the properties defined by the CIDOC CRM also constitute instances of E55 Type themselves. The direction of the assigned property of type is understood to be from the attributed item (the range of property P140 assigned attribute to) to the attribute item (the range of the property P141 assigned). More than one property type may be assigned to hold between two items.\nA comprehensive explanation about refining CIDOC CRM concepts by E55 Type is given in the section “About Types” in the section on “Specific Modelling Constructs” of this document.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(674, 1, 14, 'P177i_is_type_of_property_assigned', 'is type of property assigned', NULL),
(675, 1, 14, 'P179_had_sales_price', 'had sales price', 'This property establishes the relationship between an instance of E96 Purchase and the instance of E97 Monetary Amount that forms the compensation for the transaction. The monetary amount agreed upon may change in the course of the purchase activity.'),
(676, 1, 14, 'P179i_was_sales_price_of', 'was sales price of', NULL),
(677, 1, 14, 'P180_has_currency', 'has currency', 'This property establishes the relationship between an instance of E97 Monetary Amount and the instance of E98 Currency that it is measured in.'),
(678, 1, 14, 'P180i_was_currency_of', 'was currency of', NULL),
(679, 1, 14, 'P182_ends_before_or_with_the_start_of', 'ends before or with the start of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity ends before or simultaneously with the start of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-end ≤ B-start is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to a disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets}.\nThis property is transitive. This property is asymmetric.\n\nFigure 16: Temporal entity A ends before or with the start of temporal entity B. Here A is longer than B\n\nFigure 17: Temporal entity A ends before or with the start of temporal entity B. Here A is shorter than B'),
(680, 1, 14, 'P182i_starts_after_or_with_the_end_of', 'starts after or with the end of', NULL),
(681, 1, 14, 'P183_ends_before_the_start_of', 'ends before the start of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity ends definitely before the start of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-end &lt; B-start is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to the following Allen temporal relation (Allen, 1983) : {before}.\nThis property is transitive. This property is asymmetric.\n\nFigure 18: Temporal entity A ends before the start of temporal entity B. Here A is longer than B\n\nFigure 19: Temporal entity A ends before the start of temporal entity B. Here A is shorter than B'),
(682, 1, 14, 'P183i_starts_after_the_end_of', 'starts after the end of', NULL),
(683, 1, 14, 'P184_ends_before_or_with_the_end_of', 'ends before or with the end of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity ends before or simultaneously with the end of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-end ≤ B-end is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to a disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets, overlaps, finished by, start, equals, during, finishes}.\nThis property is irreflexive\n\nFigure 20: Temporal entity A ends before or with the end of temporal entity B. Here A is longer than B\n\nFigure 21: Temporal entity A ends before or with the end of temporal entity B. Here A is shorter than B'),
(684, 1, 14, 'P184i_ends_with_or_after_the_end_of', 'ends with or after the end of', NULL),
(685, 1, 14, 'P185_ends_before_the_end_of', 'ends before the end of', 'This property specifies that the temporal extent of the domain instance A of E2 Temporal Entity ends definitely before the end of the temporal extent of the range instance B of E2 Temporal Entity.\nIn other words, if A = [A-start, A-end] and B = [B-start, B-end], it means A-end &lt; B-end is true.\nThis property is part of the set of temporal primitives P173 – P176, P182 – P185.\nThis property corresponds to a disjunction (logical OR) of the following Allen temporal relations (Allen, 1983): {before, meets, overlaps, starts, during}.\nThis property is transitive. This property is asymmetric.\n\nFigure 22: Temporal entity A ends before the end of temporal entity B. Here A is longer than B\n\nFigure 23: Temporal entity A ends before the end of temporal entity B. Here A is shorter than B'),
(686, 1, 14, 'P185i_ends_after_the_end_of', 'ends after the end of', NULL),
(687, 1, 14, 'P186_produced_thing_of_product_type', 'produced thing of product type', 'This property associates an instance of E12 Production with the instance of E99 Production Type, that is, the type of the things it produces.'),
(688, 1, 14, 'P186i_is_produced_by', 'is produced by', NULL),
(689, 1, 14, 'P187_has_production_plan', 'has production plan', 'This property associates an instance of E99 Product Type with an instance of E29 Design or Procedure that completely determines the production of instances of E18 Physical Thing. The resulting instances of E18 Physical Thing are considered exemplars of this instance of E99 Product Type when the process specified is correctly executed. Note that the respective instance of E29 Design or Procedure may not necessarily be fixed in a written/graphical form, and may require the use of tools or models unique to the product type. The same instance of E99 Product Type may be associated with several variant plans.'),
(690, 1, 14, 'P187i_is_production_plan_for', 'is production plan for', NULL),
(691, 1, 14, 'P188_requires_production_tool', 'requires production tool', 'This property associates an instance of E99 Product Type with an instance of E19 Physical Object that is needed for the production of an instance of E18 Physical Thing. When the process of production is correctly executed in accordance with the plan and using the specified instance of E19 Physical Object, the resulting instance of E18 Physical Thing is considered an exemplar of this instance of E99 Product Type. The instance of E19 Physical Object may bear distinct features that are transformed into characteristic features of the resulting instance of E18 Physical Thing. Examples include models and moulds.'),
(692, 1, 14, 'P188i_is_production_tool_for', 'is production tool for', NULL),
(693, 1, 14, 'P189_approximates', 'approximates', 'This property associates an instance of E53 Place with another instance of E53 Place, which is defined in the same reference space, and which is used to approximate the former. The property does not necessarily state the quality or accuracy of this approximation, but rather indicates the use of the first instance of place to approximate the second.\nIn common documentation practice, find or encounter spots e.g. in archaeology, botany or zoology are often related to the closest village, river or other named place without detailing the relation, e.g. if it is located within the village or in a certain distance of the specified place. In this case the stated “phenomenal” place found in the documentation can be seen as an approximation of the actual encounter spot without more specific knowledge.\nIn more recent documentation often point coordinate information is provided that originates from GPS measurements or georeferencing from a map. This point coordinate information does not state the actual place of the encounter spot but tries to approximate it with a “declarative” place. The accuracy depends on the methodology used when creating the coordinates. It may be dependent on technical limitations like GPS accuracy but also on the method where the GPS location is taken in relation to the measured feature. If the methodology is known a maximum deviation from the measured point can be calculated and the encounter spot or feature may be related to the resulting circle using an instance of P171 at some place within.\nThis property is not transitive. This property is reflexive.'),
(694, 1, 14, 'P189i_is_approximated_by', 'is approximated by', NULL),
(695, 1, 14, 'P190_has_symbolic_content', 'has symbolic content', 'This property associates an instance of E90 Symbolic Object with a complete, identifying representation of its content in the form of an instance of E62 String.\nThis property only applies to instances of E90 Symbolic Object that can be represented completely in this form. The representation may be more specific than the symbolic level defining the identity condition of the represented. This depends on the type of the symbolic object represented. For instance, if a name has type “Modern Greek character sequence”, it may be represented in a loss-free Latin transcription, meaning however the sequence of Greek letters.\nAs another example, if the represented object has type “English words sequence”, American English or British English spelling variants may be chosen to represent the English word “colour” without defining a different symbolic object. If a name has type “European traditional name”, no particular string may define its content.'),
(696, 1, 14, 'P191_had_duration', 'had duration', 'This property describes the length of time covered by an instance of E52 Time-Span. It allows an instance of E52 Time-Span to be associated with an instance of E54 Dimension representing duration independent from the actual beginning and end. Indeterminacy of the duration value can be expressed by assigning a numerical interval to the property P90 has value of E54 Dimension.'),
(697, 1, 14, 'P191i_was_duration_of', 'was duration of', NULL),
(698, 1, 14, 'P195_was_a_presence_of', 'was a presence of', 'This property associates an instance of E93 Presence with the instance of E18 Physical Thing of which it represents a temporal restriction (i.e. a time-slice) of the thing’s trajectory through spacetime. In other words, it describes where the instance of E18 Physical Thing was or moved around within a given time-span. Instantiating this property constitutes a necessary part of the identity of the respective instance of E93 Presence.\nThis property is a shortcut of the fully developed path from E18 Physical Thing through P196 defines, E92 Spacetime Volume, P166 was a presence of (had presence) to E93 Presence.'),
(699, 1, 14, 'P195i_had_presence', 'had presence', NULL),
(700, 1, 14, 'P196_defines', 'defines', 'This property associates an instance of E18 Physical Thing with the instance of E92 Spacetime Volume that constitutes the complete trajectory of its geometric extent through spacetime for the whole time of the existence of the instance of E18 Physical Thing.\nAn instance of E18 Physical Thing not only occupies a particular geometric space at each instant of its existence, but in the course of its existence it also forms a trajectory through spacetime, which occupies a real, that is phenomenal, volume in spacetime, i.e. the instance of E92 Spacetime Volume this property associates it with. This real spatiotemporal extent of the instance of E18 Physical Thing is regarded as being unique, in all its details and fuzziness; the identity and existence of the instance of E92 Spacetime Volume depend uniquely on the identity of the instance of E18 Physical Thing, whose existence defines it. It constitutes a phenomenal spacetime volume as defined in CRMgeo (Doerr &amp; Hiebel, 2013).\nIncluded in this spacetime volume are both the spaces filled by the matter of the physical thing and any inner space that may exist, for instance the interior of a box. Physical things consisting of aggregations of physically unconnected objects, such as a set of chessmen, occupy a finite number of individually contiguous subsets of this spacetime volume equal to the number of objects that constitute the set and that are never connected during its existence.'),
(701, 1, 14, 'P196i_is_defined_by', 'is defined by', NULL),
(702, 1, 14, 'P197_covered_parts_of', 'covered parts of', 'This property associates an instance of E93 Presence with an instance of E53 Place that geometrically overlaps with the spatial projection of the respective instance of E93 Presence. A use case of this property is to state through which places an object or an instance of E21 Person has or was moved within a given time-span. It may also be used to describe a partial or complete, temporary or permanent extension of the spatial extent of some realm into a neighbouring region during a known time-span. It may also be used to describe a partial or complete, temporary or permanent extension of the spatial extent of some realm into a neighbouring region during a known time-span.\nThis property is a shortcut of the more fully developed path from E93 Presence through P161 has spatial projection, E53 Place, P121 overlaps with, to E53 Place.'),
(703, 1, 14, 'P197i_was_partially_covered_by', 'was partially covered by', NULL),
(704, 1, 14, 'P198_holds_or_supports', 'holds or supports', 'This property relates one instance of E18 Physical Thing which acts as a container or support to a supported or contained instance of E18 Physical Thing. Typical examples of E18 Physical Things which are intended to function as a container or support include shelves, folders or boxes. These containers or supports provide a stable surface which is intended for other physical objects to be placed upon for storage, display, transport or other similar functions.\nThis property is a shortcut of the more fully developed path from E18 Physical Thing through P59 has section, E53 Place, P53i is former or current location of, to E18 Physical Thing. It is not a sub-property of P46 is composed of, as the held or supported object is not a component of the container or support.\nThis property can be used to avoid explicitly instantiating the E53 Place which is defined by an instance of E18 Physical Thing, especially when the only intended use of that instance of E18 Physical Thing is to act as a container or surface for the storage of other instances of E18 Physical Thing. The place’s existence is defined by the existence of the container or surface, and will go out of existence at the same time as the destruction of the container or surface.\nThis property is transitive. This property is asymmetric.'),
(705, 1, 14, 'P198i_is_held_or_supported_by', 'is held or supported by', NULL),
(706, 1, 15, 'hasTRS', 'sistema de referencia temporal utilizado', 'El sistema de referencia temporal utilizado por una posición temporal o descripción de extensión.'),
(707, 1, 15, 'timeZone', 'in time zone', 'The time zone for clock elements in the temporal position'),
(708, 1, 15, 'monthOfYear', 'month of year', 'The month of the year, whose value is a member of the class time:MonthOfYear'),
(709, 1, 15, 'dayOfWeek', 'día de la semana', 'El día de la semana, cuyo valor es un miembro de la clase \'día de la semana\'.'),
(710, 1, 15, 'unitType', 'tipo de unidad temporal', 'La unidad de tiempo que proporciona la precisión de un valor fecha-hora o la escala de una extensión temporal.'),
(711, 1, 15, 'after', 'after', 'Gives directionality to time. If a temporal entity T1 is after another temporal entity T2, then the beginning of T1 is after the end of T2.'),
(712, 1, 15, 'before', 'antes', 'Asume una dirección en el tiempo. Si una entidad temporal T1 está antes que otra entidad temporal T2, entonces el final de T1 está antes que el principio de T2. Así, \"antes\" se puede considerar básica para instantes y derivada para intervalos.'),
(713, 1, 15, 'hasBeginning', 'has beginning', 'Beginning of a temporal entity'),
(714, 1, 15, 'hasTime', 'tiene tiempo', 'Proporciona soporte a la asociación de una entidad temporal (instante o intervalo) a cualquier cosa.'),
(715, 1, 15, 'hasDateTimeDescription', 'tiene descripción fecha-hora', 'Valor de intervalo de fecha-hora expresado como un valor estructurado. El principio y el final del intervalo coincide con los límites del elemento más corto en la descripción.'),
(716, 1, 15, 'hasDuration', 'tiene duración', 'Duración de una entidad temporal, expresada como un valor escalado o un valor nominal.'),
(717, 1, 15, 'hasTemporalDuration', 'tiene duración temporal', 'Duración de una entidad temporal.'),
(718, 1, 15, 'hasDurationDescription', 'tiene descripción de duración', 'Duración de una entidad temporal, expresada utilizando una descripción estructurada.'),
(719, 1, 15, 'hasEnd', 'tiene fin', 'End of a temporal entity.'),
(720, 1, 15, 'inDateTime', 'in date-time description', 'Position of an instant, expressed using a structured description'),
(721, 1, 15, 'inTemporalPosition', 'posición temporal', 'Posición de un instante de tiempo.'),
(722, 1, 15, 'inTimePosition', 'posición de tiempo', 'Posición de un instante, expresada como una coordenada temporal o un valor nominal.'),
(723, 1, 15, 'inside', 'tiene instante de tiempo dentro', 'Un instante que cae dentro del intervalo. Se asume que no es ni el principio ni el final de ningún intervalo.'),
(724, 1, 15, 'intervalAfter', 'interval after', 'If a proper interval T1 is intervalAfter another proper interval T2, then the beginning of T1 is after the end of T2.'),
(725, 1, 15, 'intervalDisjoint', 'interval disjoint', 'Si un intervalo propio T1 es disjunto con otro intervalo propio T2, entonces el principio de T1 está después del final de T2, o el final de T1 está antes que el principio de T2, es decir, los intervalos no se solapan de ninguna forma, aunque su relación de orden no se conozca.'),
(726, 1, 15, 'intervalBefore', 'interval before', 'Si un intervalo propio T1 está antes que otro intervalo propio T2, entonces el final de T1 está antes que el principio de T2.'),
(727, 1, 15, 'intervalContains', 'intervalo contiene', 'Si un intervalo propio T1 contiene otro intervalo propio T2, entonces el principio de T1 está antes que el principio de T2, y el final de T1 está después del final de T2.'),
(728, 1, 15, 'intervalDuring', 'intervalo durante', 'Si un intervalo propio T1 está durante otro intervalo propio T2, entonces del principio de T1 está después del principio de T2, y el final de T1 está antes que el final de T2.'),
(729, 1, 15, 'intervalIn', 'interval in', 'Si un intervalo propio T1 es un intervalo interior a otro intervalo propio T2, entonces el principio de T1 está después del principio de T2 o coincide con el principio de T2, y el final de T1 está antes que el final de T2, o coincide con el final de T2, excepto que el final de T1 puede no coincidir con el final de T2 si el principio de T1 coincide con el principio de T2.'),
(730, 1, 15, 'intervalEquals', 'intervalo igual', 'If a proper interval T1 is intervalEquals another proper interval T2, then the beginning of T1 is coincident with the beginning of T2, and the end of T1 is coincident with the end of T2.'),
(731, 1, 15, 'intervalFinishedBy', 'intervalo terminado por', 'If a proper interval T1 is intervalFinishedBy another proper interval T2, then the beginning of T1 is before the beginning of T2, and the end of T1 is coincident with the end of T2.'),
(732, 1, 15, 'intervalFinishes', 'intervalo termina', 'Si un intervalo propio T1 termina otro intervalo propio T2, entonces del principio de T1 está después del principio de T2, y el final de T1 coincide con el final de T2.'),
(733, 1, 15, 'intervalMeets', 'intervalo se encuentra', 'Si un intervalo propio T1 se encuentra con otro intervalo propio T2, entonces el final de T1 coincide con el principio de T2.'),
(734, 1, 15, 'intervalMetBy', 'intervalo encontrado por', 'Si un intervalo propio T1 es \'intervalo encontrado por\' otro intervalo propio T2, entonces el principio de T1 coincide con el final de T2.'),
(735, 1, 15, 'intervalOverlappedBy', 'intervalo solapado por', 'Si un intervalo propio T1 es \'intervalo solapado por\' otro intervalo propio T2, entonces el principio de T1 es posterior al principio de T2, y el principio de T1 es anterior al final de T2, y el final de T1 es posterior al final de T2.'),
(736, 1, 15, 'intervalOverlaps', 'interval overlaps', 'If a proper interval T1 is intervalOverlaps another proper interval T2, then the beginning of T1 is before the beginning of T2, the end of T1 is after the beginning of T2, and the end of T1 is before the end of T2.'),
(737, 1, 15, 'intervalStartedBy', 'interval started by', 'Si un intervalo propio T1 es empezado por otro intervalo propio T2, entonces el principio de T1 coincide con el principio de T2, y el final de T1 es posterior al final de T2.'),
(738, 1, 15, 'intervalStarts', 'interval starts', 'Si un intervalo propio T1 empieza otro intervalo propio T2, entonces del principio de T1 con el principio de T2, y el final de T1 es anterior al final de T2.'),
(739, 1, 15, 'days', 'duración en días', 'Longitud de, o elemento de la longitud de, una extensión temporal expresada en días.'),
(740, 1, 15, 'weeks', 'duración en semanas', 'Longitud de, o elemento de la longitud de, una extensión temporal expresada en semanas.'),
(741, 1, 15, 'hour', 'hora', 'Posición de hora en un sistema calendario-reloj.'),
(742, 1, 15, 'month', 'mes', 'Posición de mes en un sistema calendario-reloj.\n    El rango de esta propiedad no está especificado, por tanto, se puede reemplazar por cualquier representación específica de un mes de calendario de un calendario cualquiera.'),
(743, 1, 15, 'years', 'duración en años', 'Longitud de, o elemento de la longitud de, una extensión temporal expresada en años.'),
(744, 1, 15, 'second', 'segundo', 'Posición de segundo en un sistema calendario-reloj.'),
(745, 1, 15, 'seconds', 'duración en segundos', 'Longitud de, o elemento de la longitud de, una extensión temporal expresada en segundos.'),
(746, 1, 15, 'hours', 'duración en horas', 'Longitud de, o elemento de la longitud de, una extensión temporal expresada en horas.'),
(747, 1, 15, 'nominalPosition', 'nombre de posición temporal', 'El valor (nominal) que indica posición temporal en un sistema de referencia ordinal.'),
(748, 1, 15, 'minute', 'minuto', 'Posición de minuto en un sistema calendario-reloj.'),
(749, 1, 15, 'dayOfYear', 'día del año', 'El número de día en el año.'),
(750, 1, 15, 'week', 'semana', 'Número de semana en el año.'),
(751, 1, 15, 'year', 'year', 'Posición de año en un sistema calendario-reloj.\n\nl rango de esta propiedad no está especificado, por tanto, se puede reemplazar por cualquier representación específica de un año de calendario de un calendario cualquiera.'),
