(754, 1, 15, 'months', 'duración en meses', 'Longitud de, o elemento de la longitud de, una extensión temporal expresada en meses.'),
(755, 1, 15, 'numericDuration', 'valor numérico de duración temporal', 'Valor de una extensión temporal expresada como un número decimal escalado por una unidad de tiempo.'),
(756, 1, 15, 'numericPosition', 'valor numérico de posición temporal', 'El valor (numérico) que indica posición temporal en un sistema de referencia ordinal.'),
