(3009, 1, 18, 'reliesOn', 'relies on', 'Indicates that the subject vocabulary uses or extends some class or property of the object vocabulary'),
(3010, 1, 18, 'usedBy', 'used by', 'Indicates that the subject vocabulary is used by the object vocabulary'),
(3011, 1, 18, 'metadataVoc', 'metadata vocabulary', 'Indicates that the subject vocabulary uses the object vocabulary in metadata at global vocabulary level or at element level'),
(3012, 1, 18, 'extends', 'extends', 'Indicates that the subject vocabulary extends the expressivity of the object vocabulary by declaring subsumption relationships, using object vocabulary class as domain or range of a subject vocabulary property, defining local restrictions etc ...'),
(3013, 1, 18, 'specializes', 'specializes', 'Indicates that the subject vocabulary defines some subclasses or subproperties of the object vocabulary, or local restrictions on those.'),
(3014, 1, 18, 'generalizes', 'generalizes', 'Indicates that the subject vocabulary generalizes by some superclasses or superproperties the object vocabulary.'),
(3015, 1, 18, 'hasEquivalencesWith', 'has equivalences with', 'Indicates that the subject vocabulary declares some equivalent classes or properties with the object vocabulary.'),
(3016, 1, 18, 'hasDisjunctionsWith', 'has disjunctions with', 'Indicates that the subject vocabulary contains some declaration of disjoint classes with the object vocabulary.'),
(3017, 1, 18, 'dataset', 'dataset', 'Deprecated since v2.4'),
(3018, 1, 18, 'exampleDataset', 'example dataset', 'Deprecated since v1.1'),
(3019, 1, 18, 'toDoList', 'to-do list', 'Describes future tasks planned by a resource curator. This property is primarily intended to be used for vocabularies or datasets, but the domain is left open, it can be used for any resource. Use iCalendar Vtodo class and its properties to further describe the task calendar, priorities etc.'),
(3020, 1, 18, 'similar', 'similar', 'Used to assert that two vocabularies are similar in scope and objectives, independently of the fact that they otherwise refer to each other.'),
