(4510, 1, 20, 'associatedArticle', 'associatedArticle', 'A NewsArticle associated with the Media Object.'),
(4511, 1, 20, 'legislationChanges', 'legislationChanges', 'Another legislation that this legislation changes. This encompasses the notions of amendment, replacement, correction, repeal, or other types of change. This may be a direct change (textual or non-textual amendment) or a consequential or indirect change. The property is to be used to express the existence of a change relationship between two acts rather than the existence of a consolidated version of the text that shows the result of the change. For consolidation relationships, use the <a href=\"/legislationConsolidates\">legislationConsolidates</a> property.'),
(4512, 1, 20, 'interactionStatistic', 'interactionStatistic', 'The number of interactions for the CreativeWork using the WebSite or SoftwareApplication. The most specific child type of InteractionCounter should be used.'),
(4513, 1, 20, 'dayOfWeek', 'dayOfWeek', 'The day of the week for which these opening hours are valid.'),
(4514, 1, 20, 'boardingPolicy', 'boardingPolicy', 'The type of boarding policy used by the airline (e.g. zone-based or group-based).'),
(4515, 1, 20, 'printPage', 'printPage', 'If this NewsArticle appears in print, this field indicates the name of the page on which the article is found. Please note that this field is intended for the exact page name (e.g. A5, B18).'),
(4516, 1, 20, 'trainName', 'trainName', 'The name of the train (e.g. The Orient Express).'),
(4517, 1, 20, 'serviceType', 'serviceType', 'The type of service being offered, e.g. veterans\' benefits, emergency relief, etc.'),
(4518, 1, 20, 'targetPlatform', 'targetPlatform', 'Type of app development: phone, Metro style, desktop, XBox, etc.'),
(4519, 1, 20, 'doseSchedule', 'doseSchedule', 'A dosing schedule for the drug for a given population, either observed, recommended, or maximum dose based on the type used.'),
(4520, 1, 20, 'tissueSample', 'tissueSample', 'The type of tissue sample required for the test.'),
(4521, 1, 20, 'exercisePlan', 'exercisePlan', 'A sub property of instrument. The exercise plan used on this action.'),
(4522, 1, 20, 'instrument', 'instrument', 'The object that helped the agent perform the action. E.g. John wrote a book with *a pen*.'),
(4523, 1, 20, 'numberOfItems', 'numberOfItems', 'The number of items in an ItemList. Note that some descriptions might not fully describe all items in a list (e.g., multi-page pagination); in such cases, the numberOfItems would be for the entire list.'),
(4524, 1, 20, 'name', 'name', 'The name of the item.'),
(4525, 1, 20, 'usesHealthPlanIdStandard', 'usesHealthPlanIdStandard', 'The standard for interpreting the Plan ID. The preferred is \"HIOS\". See the Centers for Medicare & Medicaid Services for more details.'),
(4526, 1, 20, 'serviceLocation', 'serviceLocation', 'The location (e.g. civic structure, local business, etc.) where a person can go to access the service.'),
(4527, 1, 20, 'legalName', 'legalName', 'The official name of the organization, e.g. the registered company name.'),
(4528, 1, 20, 'hasCredential', 'hasCredential', 'A credential awarded to the Person or Organization.'),
(4529, 1, 20, 'arrivalTerminal', 'arrivalTerminal', 'Identifier of the flight\'s arrival terminal.'),
(4530, 1, 20, 'equal', 'equal', 'This ordering relation for qualitative values indicates that the subject is equal to the object.'),
(4531, 1, 20, 'preparation', 'preparation', 'Typical preparation that a patient must undergo before having the procedure performed.'),
(4532, 1, 20, 'photos', 'photos', 'Photographs of this place.'),
(4533, 1, 20, 'photo', 'photo', 'A photograph of this place.'),
(4534, 1, 20, 'releaseDate', 'releaseDate', 'The release date of a product or product model. This can be used to distinguish the exact variant of a product.'),
(4535, 1, 20, 'loanTerm', 'loanTerm', 'The duration of the loan or credit agreement.'),
(4536, 1, 20, 'duration', 'duration', 'The duration of the item (movie, audio recording, event, etc.) in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(4537, 1, 20, 'hasTierRequirement', 'hasTierRequirement', 'A requirement for a user to join a membership tier, for example: a CreditCard if the tier requires sign up for a credit card, A UnitPriceSpecification if the user is required to pay a (periodic) fee, or a MonetaryAmount if the user needs to spend a minimum amount to join the tier. If a tier is free to join then this property does not need to be specified.'),
(4538, 1, 20, 'disambiguatingDescription', 'disambiguatingDescription', 'A sub property of description. A short description of the item used to disambiguate from other, similar items. Information from other properties (in particular, name) may be necessary for the description to be useful for disambiguation.'),
(4539, 1, 20, 'description', 'description', 'A description of the item.'),
(4540, 1, 20, 'hasMemberProgram', 'hasMemberProgram', 'MemberProgram offered by an Organization, for example an eCommerce merchant or an airline.'),
(4541, 1, 20, 'certificationStatus', 'certificationStatus', 'Indicates the current status of a certification: active or inactive. See also  [gs1:certificationStatus](https://www.gs1.org/voc/certificationStatus).'),
(4542, 1, 20, 'itemOffered', 'itemOffered', 'An item being offered (or demanded). The transactional nature of the offer or demand is documented using [[businessFunction]], e.g. sell, lease etc. While several common expected types are listed explicitly in this definition, others can be used. Using a second type, such as Product or a subtype of Product, can clarify the nature of the offer.'),
(4543, 1, 20, 'offers', 'offers', 'An offer to provide this item&#x2014;for example, an offer to sell a product, rent the DVD of a movie, perform a service, or give away tickets to an event. Use [[businessFunction]] to indicate the kind of transaction offered, i.e. sell, lease, etc. This property can also be used to describe a [[Demand]]. While this property is listed as expected on a number of common types, it can be used in others. In that case, using a second type, such as Product or a subtype of Product, can clarify the nature of the offer.\n      '),
(4544, 1, 20, 'physicalRequirement', 'physicalRequirement', 'A description of the types of physical activity associated with the job. Defined terms such as those in O*net may be used, but note that there is no way to specify the level of ability as well as its nature when using a defined term.'),
(4545, 1, 20, 'proteinContent', 'proteinContent', 'The number of grams of protein.'),
(4546, 1, 20, 'query', 'query', 'A sub property of instrument. The query used on this action.'),
(4547, 1, 20, 'winner', 'winner', 'A sub property of participant. The winner of the action.'),
(4548, 1, 20, 'participant', 'participant', 'Other co-agents that participated in the action indirectly. E.g. John wrote a book with *Steve*.'),
(4549, 1, 20, 'vehicleSeatingCapacity', 'vehicleSeatingCapacity', 'The number of passengers that can be seated in the vehicle, both in terms of the physical space available, and in terms of limitations set by law.\\n\\nTypical unit code(s): C62 for persons.'),
(4550, 1, 20, 'performers', 'performers', 'The main performer or performers of the event&#x2014;for example, a presenter, musician, or actor.'),
(4551, 1, 20, 'performer', 'performer', 'A performer at the event&#x2014;for example, a presenter, musician, musical group or actor.'),
(4552, 1, 20, 'syllabusSections', 'syllabusSections', 'Indicates (typically several) Syllabus entities that lay out what each section of the overall course will cover.'),
(4553, 1, 20, 'memoryRequirements', 'memoryRequirements', 'Minimum memory requirements.'),
(4554, 1, 20, 'sodiumContent', 'sodiumContent', 'The number of milligrams of sodium.'),
(4555, 1, 20, 'availabilityStarts', 'availabilityStarts', 'The beginning of the availability of the product or service included in the offer.'),
(4556, 1, 20, 'restPeriods', 'restPeriods', 'How often one should break from the activity.'),
(4557, 1, 20, 'organizer', 'organizer', 'An organizer of an Event.'),
(4558, 1, 20, 'healthPlanCostSharing', 'healthPlanCostSharing', 'The costs to the patient for services under this network or formulary.'),
(4559, 1, 20, 'branch', 'branch', 'The branches that delineate from the nerve bundle. Not to be confused with [[branchOf]].'),
(4560, 1, 20, 'arterialBranch', 'arterialBranch', 'The branches that comprise the arterial structure.'),
(4561, 1, 20, 'colleague', 'colleague', 'A colleague of the person.'),
(4562, 1, 20, 'termsOfService', 'termsOfService', 'Human-readable terms of service documentation.'),
(4563, 1, 20, 'emissionsCO2', 'emissionsCO2', 'The CO2 emissions in g/km. When used in combination with a QuantitativeValue, put \"g/km\" into the unitText property of that value, since there is no UN/CEFACT Common Code for \"g/km\".'),
(4564, 1, 20, 'contactPoints', 'contactPoints', 'A contact point for a person or organization.'),
(4565, 1, 20, 'contactPoint', 'contactPoint', 'A contact point for a person or organization.'),
(4566, 1, 20, 'variablesMeasured', 'variablesMeasured', 'Originally named [[variablesMeasured]], the [[variableMeasured]] property can indicate (repeated as necessary) the  variables that are measured in some dataset, either described as text or as pairs of identifier and description using PropertyValue.'),
(4567, 1, 20, 'executableLibraryName', 'executableLibraryName', 'Library file name, e.g., mscorlib.dll, system.web.dll.'),
(4568, 1, 20, 'numberOfPreviousOwners', 'numberOfPreviousOwners', 'The number of owners of the vehicle, including the current one.\\n\\nTypical unit code(s): C62.'),
(4569, 1, 20, 'broadcastFrequency', 'broadcastFrequency', 'The frequency used for over-the-air broadcasts. Numeric values or simple ranges, e.g. 87-99. In addition a shortcut idiom is supported for frequencies of AM and FM radio channels, e.g. \"87 FM\".'),
(4570, 1, 20, 'eligibleDuration', 'eligibleDuration', 'The duration for which the given offer is valid.'),
(4571, 1, 20, 'percentile90', 'percentile90', 'The 90th percentile value.'),
(4572, 1, 20, 'spokenByCharacter', 'spokenByCharacter', 'The (e.g. fictional) character, Person or Organization to whom the quotation is attributed within the containing CreativeWork.'),
(4573, 1, 20, 'contributor', 'contributor', 'A secondary contributor to the CreativeWork or Event.'),
(4574, 1, 20, 'pathophysiology', 'pathophysiology', 'Changes in the normal mechanical, physical, and biochemical functions that are associated with this activity or condition.'),
(4575, 1, 20, 'netWorth', 'netWorth', 'The total financial value of the person as calculated by subtracting assets from liabilities.'),
(4576, 1, 20, 'beneficiaryBank', 'beneficiaryBank', 'A bank or bank’s branch, financial institution or international financial institution operating the beneficiary’s bank account or releasing funds for the beneficiary.'),
(4577, 1, 20, 'knowsAbout', 'knowsAbout', 'Of a [[Person]], and less typically of an [[Organization]], to indicate a topic that is known about - suggesting possible expertise but not implying it. We do not distinguish skill levels here, or relate this to educational content, events, objectives or [[JobPosting]] descriptions.'),
(4578, 1, 20, 'departureGate', 'departureGate', 'Identifier of the flight\'s departure gate.'),
(4579, 1, 20, 'additionalProperty', 'additionalProperty', 'A property-value pair representing an additional characteristic of the entity, e.g. a product feature or another characteristic for which there is no matching property in schema.org.\\n\\nNote: Publishers should be aware that applications designed to use specific schema.org properties (e.g. http://schema.org/width, http://schema.org/color, http://schema.org/gtin13, ...) will typically expect such data to be provided using those properties, rather than using the generic property/value mechanism.\n'),
(4580, 1, 20, 'inSupportOf', 'inSupportOf', 'Qualification, candidature, degree, application that Thesis supports.'),
(4581, 1, 20, 'iupacName', 'iupacName', 'Systematic method of naming chemical compounds as recommended by the International Union of Pure and Applied Chemistry (IUPAC).'),
(4582, 1, 20, 'pregnancyWarning', 'pregnancyWarning', 'Any precaution, guidance, contraindication, etc. related to this drug\'s use during pregnancy.'),
(4583, 1, 20, 'lesser', 'lesser', 'This ordering relation for qualitative values indicates that the subject is lesser than the object.'),
(4584, 1, 20, 'workPerformed', 'workPerformed', 'A work performed in some event, for example a play performed in a TheaterEvent.'),
(4585, 1, 20, 'workFeatured', 'workFeatured', 'A work featured in some event, e.g. exhibited in an ExhibitionEvent.\n       Specific subproperties are available for workPerformed (e.g. a play), or a workPresented (a Movie at a ScreeningEvent).'),
(4586, 1, 20, 'requiredMinAge', 'requiredMinAge', 'Audiences defined by a person\'s minimum age.'),
(4587, 1, 20, 'diagnosis', 'diagnosis', 'One or more alternative conditions considered in the differential diagnosis process as output of a diagnosis process.'),
(4588, 1, 20, 'publishingPrinciples', 'publishingPrinciples', 'The publishingPrinciples property indicates (typically via [[URL]]) a document describing the editorial principles of an [[Organization]] (or individual, e.g. a [[Person]] writing a blog) that relate to their activities as a publisher, e.g. ethics or diversity policies. When applied to a [[CreativeWork]] (e.g. [[NewsArticle]]) the principles are those of the party primarily responsible for the creation of the [[CreativeWork]].\n\nWhile such policies are most typically expressed in natural language, sometimes related information (e.g. indicating a [[funder]]) can be expressed using schema.org terminology.\n'),
(4589, 1, 20, 'realEstateAgent', 'realEstateAgent', 'A sub property of participant. The real estate agent involved in the action.'),
(4590, 1, 20, 'price', 'price', 'The offer price of a product, or of a price component when attached to PriceSpecification and its subtypes.\\n\\nUsage guidelines:\\n\\n* Use the [[priceCurrency]] property (with standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\") instead of including [ambiguous symbols](http://en.wikipedia.org/wiki/Dollar_sign#Currencies_that_use_the_dollar_or_peso_sign) such as \'$\' in the value.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.\\n* Note that both [RDFa](http://www.w3.org/TR/xhtml-rdfa-primer/#using-the-content-attribute) and Microdata syntax allow the use of a \"content=\" attribute for publishing simple machine-readable values alongside more human-friendly formatting.\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\n      '),
(4591, 1, 20, 'returnFees', 'returnFees', 'The type of return fees for purchased products (for any return reason).'),
(4592, 1, 20, 'mobileUrl', 'mobileUrl', 'The [[mobileUrl]] property is provided for specific situations in which data consumers need to determine whether one of several provided URLs is a dedicated \'mobile site\'.\n\nTo discourage over-use, and reflecting intial usecases, the property is expected only on [[Product]] and [[Offer]], rather than [[Thing]]. The general trend in web technology is towards [responsive design](https://en.wikipedia.org/wiki/Responsive_web_design) in which content can be flexibly adapted to a wide range of browsing environments. Pages and sites referenced with the long-established [[url]] property should ideally also be usable on a wide variety of devices, including mobile phones. In most cases, it would be pointless and counter productive to attempt to update all [[url]] markup to use [[mobileUrl]] for more mobile-oriented pages. The property is intended for the case when items (primarily [[Product]] and [[Offer]]) have extra URLs hosted on an additional \"mobile site\" alongside the main one. It should not be taken as an endorsement of this publication style.\n    '),
(4593, 1, 20, 'exampleOfWork', 'exampleOfWork', 'A creative work that this work is an example/instance/realization/derivation of.'),
(4594, 1, 20, 'workExample', 'workExample', 'Example/instance/realization/derivation of the concept of this creative work. E.g. the paperback edition, first edition, or e-book.'),
(4595, 1, 20, 'foodEstablishment', 'foodEstablishment', 'A sub property of location. The specific food establishment where the action occurred.'),
(4596, 1, 20, 'location', 'location', 'The location of, for example, where an event is happening, where an organization is located, or where an action takes place.'),
(4597, 1, 20, 'actor', 'actor', 'An actor (individual or a group), e.g. in TV, radio, movie, video games etc., or in an event. Actors can be associated with individual items or with a series, episode, clip.'),
(4598, 1, 20, 'smiles', 'smiles', 'A specification in form of a line notation for describing the structure of chemical species using short ASCII strings.  Double bond stereochemistry \\ indicators may need to be escaped in the string in formats where the backslash is an escape character.'),
(4599, 1, 20, 'hasRepresentation', 'hasRepresentation', 'A common representation such as a protein sequence or chemical structure for this entity. For images use schema.org/image.'),
(4600, 1, 20, 'payload', 'payload', 'The permitted weight of passengers and cargo, EXCLUDING the weight of the empty vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: Many databases specify the permitted TOTAL weight instead, which is the sum of [[weight]] and [[payload]]\\n* Note 2: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 3: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 4: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(4601, 1, 20, 'coverageStartTime', 'coverageStartTime', 'The time when the live blog will begin covering the Event. Note that coverage may begin before the Event\'s start time. The LiveBlogPosting may also be created before coverage begins.'),
(4602, 1, 20, 'byDay', 'byDay', 'Defines the day(s) of the week on which a recurring [[Event]] takes place. May be specified using either [[DayOfWeek]], or alternatively [[Text]] conforming to iCal\'s syntax for byDay recurrence rules.'),
(4603, 1, 20, 'meetsEmissionStandard', 'meetsEmissionStandard', 'Indicates that the vehicle meets the respective emission standard.'),
(4604, 1, 20, 'availableThrough', 'availableThrough', 'After this date, the item will no longer be available for pickup.'),
(4605, 1, 20, 'servicePhone', 'servicePhone', 'The phone number to use to access the service.'),
(4606, 1, 20, 'qualifications', 'qualifications', 'Specific qualifications required for this role or Occupation.'),
(4607, 1, 20, 'percentile10', 'percentile10', 'The 10th percentile value.'),
(4608, 1, 20, 'includesAttraction', 'includesAttraction', 'Attraction located at destination.'),
(4609, 1, 20, 'departureTime', 'departureTime', 'The expected departure time.'),
(4610, 1, 20, 'relatedStructure', 'relatedStructure', 'Related anatomical structure(s) that are not part of the system but relate or connect to it, such as vascular bundles associated with an organ system.'),
(4611, 1, 20, 'competitor', 'competitor', 'A competitor in a sports event.'),
(4612, 1, 20, 'alumni', 'alumni', 'Alumni of an organization.'),
(4613, 1, 20, 'alumniOf', 'alumniOf', 'An organization that the person is an alumni of.'),
(4614, 1, 20, 'webFeed', 'webFeed', 'The URL for a feed, e.g. associated with a podcast series, blog, or series of date-stamped updates. This is usually RSS or Atom.'),
(4615, 1, 20, 'contentReferenceTime', 'contentReferenceTime', 'The specific time described by a creative work, for works (e.g. articles, video objects etc.) that emphasise a particular moment within an Event.'),
(4616, 1, 20, 'isSimilarTo', 'isSimilarTo', 'A pointer to another, functionally similar product (or multiple products).'),
(4617, 1, 20, 'inPlaylist', 'inPlaylist', 'The playlist to which this recording belongs.'),
(4618, 1, 20, 'firstPerformance', 'firstPerformance', 'The date and place the work was first performed.'),
(4619, 1, 20, 'toLocation', 'toLocation', 'A sub property of location. The final location of the object or the agent after the action.'),
(4620, 1, 20, 'iataCode', 'iataCode', 'IATA identifier for an airline or airport.'),
(4621, 1, 20, 'gamePlatform', 'gamePlatform', 'The electronic systems used to play <a href=\"http://en.wikipedia.org/wiki/Category:Video_game_platforms\">video games</a>.'),
(4622, 1, 20, 'bloodSupply', 'bloodSupply', 'The blood vessel that carries blood from the heart to the muscle.'),
(4623, 1, 20, 'availability', 'availability', 'The availability of this item&#x2014;for example In stock, Out of stock, Pre-order, etc.'),
(4624, 1, 20, 'serialNumber', 'serialNumber', 'The serial number or any alphanumeric identifier of a particular product. When attached to an offer, it is a shortcut for the serial number of the product included in the offer.'),
(4625, 1, 20, 'identifier', 'identifier', 'The identifier property represents any kind of identifier for any kind of [[Thing]], such as ISBNs, GTIN codes, UUIDs etc. Schema.org provides dedicated properties for representing many of these, either as textual strings or as URL (URI) links. See [background notes](/docs/datamodel.html#identifierBg) for more details.\n        '),
(4626, 1, 20, 'model', 'model', 'The model of the product. Use with the URL of a ProductModel or a textual representation of the model identifier. The URL of the ProductModel can be from an external source. It is recommended to additionally provide strong product identifiers via the gtin8/gtin13/gtin14 and mpn properties.'),
(4627, 1, 20, 'device', 'device', 'Device required to run the application. Used in cases where a specific make/model is required to run the application.'),
(4628, 1, 20, 'availableOnDevice', 'availableOnDevice', 'Device required to run the application. Used in cases where a specific make/model is required to run the application.'),
(4629, 1, 20, 'isicV4', 'isicV4', 'The International Standard of Industrial Classification of All Economic Activities (ISIC), Revision 4 code for a particular organization, business person, or place.'),
(4630, 1, 20, 'hasCourse', 'hasCourse', 'A course or class that is one of the learning opportunities that constitute an educational / occupational program. No information is implied about whether the course is mandatory or optional; no guarantee is implied about whether the course will be available to everyone on the program.'),
(4631, 1, 20, 'surface', 'surface', 'A material used as a surface in some artwork, e.g. Canvas, Paper, Wood, Board, etc.'),
(4632, 1, 20, 'artworkSurface', 'artworkSurface', 'The supporting materials for the artwork, e.g. Canvas, Paper, Wood, Board, etc.'),
(4633, 1, 20, 'material', 'material', 'A material that something is made from, e.g. leather, wool, cotton, paper.'),
(4634, 1, 20, 'contactType', 'contactType', 'A person or organization can have different contact points, for different purposes. For example, a sales contact point, a PR contact point and so on. This property is used to specify the kind of contact point.'),
(4635, 1, 20, 'fileFormat', 'fileFormat', 'Media type, typically MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml)) of the content, e.g. application/zip of a SoftwareApplication binary. In cases where a CreativeWork has several media type representations, \'encoding\' can be used to indicate each MediaObject alongside particular fileFormat information. Unregistered or niche file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia entry.'),
(4636, 1, 20, 'encodingFormat', 'encodingFormat', 'Media type typically expressed using a MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml) and [MDN reference](https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/MIME_types)), e.g. application/zip for a SoftwareApplication binary, audio/mpeg for .mp3 etc.\n\nIn cases where a [[CreativeWork]] has several media type representations, [[encoding]] can be used to indicate each [[MediaObject]] alongside particular [[encodingFormat]] information.\n\nUnregistered or niche encoding and file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia/Wikidata entry.'),
(4637, 1, 20, 'membershipPointsEarned', 'membershipPointsEarned', 'The number of membership points earned by the member. If necessary, the unitText can be used to express the units the points are issued in. (E.g. stars, miles, etc.)'),
(4638, 1, 20, 'employmentType', 'employmentType', 'Type of employment (e.g. full-time, part-time, contract, temporary, seasonal, internship).'),
(4639, 1, 20, 'priceRange', 'priceRange', 'The price range of the business, for example ```$$$```.'),
(4640, 1, 20, 'pagination', 'pagination', 'Any description of pages that is not separated into pageStart and pageEnd; for example, \"1-6, 9, 55\" or \"10-12, 46-49\".'),
(4641, 1, 20, 'strengthUnit', 'strengthUnit', 'The units of an active ingredient\'s strength, e.g. mg.'),
(4642, 1, 20, 'menu', 'menu', 'Either the actual menu as a structured representation, as text, or a URL of the menu.'),
(4643, 1, 20, 'hasMenu', 'hasMenu', 'Either the actual menu as a structured representation, as text, or a URL of the menu.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(4644, 1, 20, 'aspect', 'aspect', 'An aspect of medical practice that is considered on the page, such as \'diagnosis\', \'treatment\', \'causes\', \'prognosis\', \'etiology\', \'epidemiology\', etc.'),
(4645, 1, 20, 'mainContentOfPage', 'mainContentOfPage', 'Indicates if this web page element is the main subject of the page.'),
(4646, 1, 20, 'broadcastTimezone', 'broadcastTimezone', 'The timezone in [ISO 8601 format](http://en.wikipedia.org/wiki/ISO_8601) for which the service bases its broadcasts.'),
(4647, 1, 20, 'contentSize', 'contentSize', 'File size in (mega/kilo)bytes.'),
(4648, 1, 20, 'departureAirport', 'departureAirport', 'The airport where the flight originates.'),
(4649, 1, 20, 'actionProcess', 'actionProcess', 'Description of the process by which the action was performed.'),
(4650, 1, 20, 'applicationDeadline', 'applicationDeadline', 'The date on which the program stops collecting applications for the next enrollment cycle. Flexible application deadlines (for example, a program with rolling admissions) can be described in a textual string, rather than as a DateTime.'),
(4651, 1, 20, 'additionalVariable', 'additionalVariable', 'Any additional component of the exercise prescription that may need to be articulated to the patient. This may include the order of exercises, the number of repetitions of movement, quantitative distance, progressions over time, etc.'),
(4652, 1, 20, 'programName', 'programName', 'The program providing the membership. It is preferable to use [:program](http://schema.org/program) instead.'),
(4653, 1, 20, 'steeringPosition', 'steeringPosition', 'The position of the steering wheel or similar device (mostly for cars).'),
(4654, 1, 20, 'frequency', 'frequency', 'How often the dose is taken, e.g. \'daily\'.'),
(4655, 1, 20, 'relatedLink', 'relatedLink', 'A link related to this web page, for example to other related web pages.'),
(4656, 1, 20, 'beforeMedia', 'beforeMedia', 'A media object representing the circumstances before performing this direction.'),
(4657, 1, 20, 'broadcaster', 'broadcaster', 'The organization owning or operating the broadcast service.'),
(4658, 1, 20, 'prepTime', 'prepTime', 'The length of time it takes to prepare the items to be used in instructions or a direction, in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(4659, 1, 20, 'buyer', 'buyer', 'A sub property of participant. The participant/person/organization that bought the object.'),
(4660, 1, 20, 'drugClass', 'drugClass', 'The class of drug this belongs to (e.g., statins).'),
(4661, 1, 20, 'productionDate', 'productionDate', 'The date of production of the item, e.g. vehicle.'),
(4662, 1, 20, 'copyrightNotice', 'copyrightNotice', 'Text of a notice appropriate for describing the copyright aspects of this Creative Work, ideally indicating the owner of the copyright for the Work.'),
(4663, 1, 20, 'partOfEpisode', 'partOfEpisode', 'The episode to which this clip belongs.'),
(4664, 1, 20, 'isPartOf', 'isPartOf', 'Indicates an item or CreativeWork that this item, or CreativeWork (in some sense), is part of.'),
(4665, 1, 20, 'includedDataCatalog', 'includedDataCatalog', 'A data catalog which contains this dataset (this property was previously \'catalog\', preferred name is now \'includedInDataCatalog\').'),
(4666, 1, 20, 'includedInDataCatalog', 'includedInDataCatalog', 'A data catalog which contains this dataset.'),
(4667, 1, 20, 'departureBoatTerminal', 'departureBoatTerminal', 'The terminal or port from which the boat departs.'),
(4668, 1, 20, 'valueMaxLength', 'valueMaxLength', 'Specifies the allowed range for number of characters in a literal value.'),
(4669, 1, 20, 'lesserOrEqual', 'lesserOrEqual', 'This ordering relation for qualitative values indicates that the subject is lesser than or equal to the object.'),
(4670, 1, 20, 'jobImmediateStart', 'jobImmediateStart', 'An indicator as to whether a position is available for an immediate start.'),
(4671, 1, 20, 'carrier', 'carrier', '\'carrier\' is an out-dated term indicating the \'provider\' for parcel delivery and flights.'),
(4672, 1, 20, 'provider', 'provider', 'The service provider, service operator, or service performer; the goods producer. Another party (a seller) may offer those services or goods on behalf of the provider. A provider may also serve as the seller.'),
(4673, 1, 20, 'resultReview', 'resultReview', 'A sub property of result. The review that resulted in the performing of the action.'),
(4674, 1, 20, 'result', 'result', 'The result produced in the action. E.g. John wrote *a book*.'),
(4675, 1, 20, 'letterer', 'letterer', 'The individual who adds lettering, including speech balloons and sound effects, to artwork.'),
(4676, 1, 20, 'eligibilityToWorkRequirement', 'eligibilityToWorkRequirement', 'The legal requirements such as citizenship, visa and other documentation required for an applicant to this job.'),
(4677, 1, 20, 'seatSection', 'seatSection', 'The section location of the reserved seat (e.g. Orchestra).'),
(4678, 1, 20, 'originalMediaLink', 'originalMediaLink', 'Link to the page containing an original version of the content, or directly to an online copy of the original [[MediaObject]] content, e.g. video file.'),
(4679, 1, 20, 'trailer', 'trailer', 'The trailer of a movie or TV/radio series, season, episode, etc.'),
(4680, 1, 20, 'incentiveCompensation', 'incentiveCompensation', 'Description of bonus and commission compensation aspects of the job.'),
(4681, 1, 20, 'acceptedOffer', 'acceptedOffer', 'The offer(s) -- e.g., product, quantity and price combinations -- included in the order.'),
(4682, 1, 20, 'potentialAction', 'potentialAction', 'Indicates a potential Action, which describes an idealized action in which this thing would play an \'object\' role.'),
(4683, 1, 20, 'benefitsSummaryUrl', 'benefitsSummaryUrl', 'The URL that goes directly to the summary of benefits and coverage for the specific standard plan or plan variation.'),
(4684, 1, 20, 'usedToDiagnose', 'usedToDiagnose', 'A condition the test is used to diagnose.'),
(4685, 1, 20, 'legalStatus', 'legalStatus', 'The drug or supplement\'s legal status, including any controlled substance schedules that apply.'),
(4686, 1, 20, 'procedure', 'procedure', 'A description of the procedure involved in setting up, using, and/or installing the device.'),
(4687, 1, 20, 'cvdNumICUBeds', 'cvdNumICUBeds', 'numicubeds - ICU BEDS: Total number of staffed inpatient intensive care unit (ICU) beds.'),
(4688, 1, 20, 'regionDrained', 'regionDrained', 'The anatomical or organ system drained by this vessel; generally refers to a specific part of an organ.'),
(4689, 1, 20, 'founder', 'founder', 'A person or organization who founded this organization.'),
(4690, 1, 20, 'vehicleIdentificationNumber', 'vehicleIdentificationNumber', 'The Vehicle Identification Number (VIN) is a unique serial number used by the automotive industry to identify individual motor vehicles.'),
(4691, 1, 20, 'containedInPlace', 'containedInPlace', 'The basic containment relation between a place and one that contains it.'),
(4692, 1, 20, 'containsPlace', 'containsPlace', 'The basic containment relation between a place and another that it contains.'),
(4693, 1, 20, 'exerciseCourse', 'exerciseCourse', 'A sub property of location. The course where this action was taken.'),
(4694, 1, 20, 'telephone', 'telephone', 'The telephone number.'),
(4695, 1, 20, 'appliesToPaymentMethod', 'appliesToPaymentMethod', 'The payment method(s) to which the payment charge specification applies.'),
(4696, 1, 20, 'geoEquals', 'geoEquals', 'Represents spatial relations in which two geometries (or the places they represent) are topologically equal, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM). \"Two geometries are topologically equal if their interiors intersect and no part of the interior or boundary of one geometry intersects the exterior of the other\" (a symmetric relationship).'),
(4697, 1, 20, 'customer', 'customer', 'Party placing the order or paying the invoice.'),
(4698, 1, 20, 'hasEnergyConsumptionDetails', 'hasEnergyConsumptionDetails', 'Defines the energy efficiency Category (also known as \"class\" or \"rating\") for a product according to an international energy efficiency standard.'),
(4699, 1, 20, 'interactionType', 'interactionType', 'The Action representing the type of interaction. For up votes, +1s, etc. use [[LikeAction]]. For down votes use [[DislikeAction]]. Otherwise, use the most specific Action.'),
(4700, 1, 20, 'cholesterolContent', 'cholesterolContent', 'The number of milligrams of cholesterol.'),
(4701, 1, 20, 'diversityPolicy', 'diversityPolicy', 'Statement on diversity policy by an [[Organization]] e.g. a [[NewsMediaOrganization]]. For a [[NewsMediaOrganization]], a statement describing the newsroom’s diversity policy on both staffing and sources, typically providing staffing data.'),
(4702, 1, 20, 'additionalNumberOfGuests', 'additionalNumberOfGuests', 'If responding yes, the number of guests who will attend in addition to the invitee.'),
(4703, 1, 20, 'inBroadcastLineup', 'inBroadcastLineup', 'The CableOrSatelliteService offering the channel.'),
(4704, 1, 20, 'instructor', 'instructor', 'A person assigned to instruct or provide instructional assistance for the [[CourseInstance]].'),
(4705, 1, 20, 'actionPlatform', 'actionPlatform', 'The high level platform(s) where the Action can be performed for the given URL. To specify a specific application or operating system instance, use actionApplication.'),
(4706, 1, 20, 'screenshot', 'screenshot', 'A link to a screenshot image of the app.'),
(4707, 1, 20, 'partOfSeason', 'partOfSeason', 'The season to which this episode belongs.'),
(4708, 1, 20, 'educationalAlignment', 'educationalAlignment', 'An alignment to an established educational framework.\n\nThis property should not be used where the nature of the alignment can be described using a simple property, for example to express that a resource [[teaches]] or [[assesses]] a competency.'),
(4709, 1, 20, 'inDefinedTermSet', 'inDefinedTermSet', 'A [[DefinedTermSet]] that contains this term.'),
(4710, 1, 20, 'titleEIDR', 'titleEIDR', 'An [EIDR](https://eidr.org/) (Entertainment Identifier Registry) [[identifier]] representing at the most general/abstract level, a work of film or television.\n\nFor example, the motion picture known as \"Ghostbusters\" has a titleEIDR of  \"10.5240/7EC7-228A-510A-053E-CBB8-J\". This title (or work) may have several variants, which EIDR calls \"edits\". See [[editEIDR]].\n\nSince schema.org types like [[Movie]], [[TVEpisode]], [[TVSeason]], and [[TVSeries]] can be used for both works and their multiple expressions, it is possible to use [[titleEIDR]] alone (for a general description), or alongside [[editEIDR]] for a more edit-specific description.\n'),
(4711, 1, 20, 'domainIncludes', 'domainIncludes', 'Relates a property to a class that is (one of) the type(s) the property is expected to be used on.'),
(4712, 1, 20, 'issuedBy', 'issuedBy', 'The organization issuing the item, for example a [[Permit]], [[Ticket]], or [[Certification]].'),
(4713, 1, 20, 'homeLocation', 'homeLocation', 'A contact location for a person\'s residence.'),
(4714, 1, 20, 'isLocatedInSubcellularLocation', 'isLocatedInSubcellularLocation', 'Subcellular location where this BioChemEntity is located; please use PropertyValue if you want to include any evidence.'),
(4715, 1, 20, 'recognizingAuthority', 'recognizingAuthority', 'If applicable, the organization that officially recognizes this entity as part of its endorsed system of medicine.'),
(4716, 1, 20, 'requiredMaxAge', 'requiredMaxAge', 'Audiences defined by a person\'s maximum age.'),
(4717, 1, 20, 'studyDesign', 'studyDesign', 'Specifics about the observational study design (enumerated).'),
(4718, 1, 20, 'mentions', 'mentions', 'Indicates that the CreativeWork contains a reference to, but is not necessarily about a concept.'),
(4719, 1, 20, 'returnPolicySeasonalOverride', 'returnPolicySeasonalOverride', 'Seasonal override of a return policy.'),
(4720, 1, 20, 'isGift', 'isGift', 'Indicates whether the offer was accepted as a gift for someone other than the buyer.'),
(4721, 1, 20, 'temporal', 'temporal', 'The \"temporal\" property can be used in cases where more specific properties\n(e.g. [[temporalCoverage]], [[dateCreated]], [[dateModified]], [[datePublished]]) are not known to be appropriate.'),
(4722, 1, 20, 'subOrganization', 'subOrganization', 'A relationship between two organizations where the first includes the second, e.g., as a subsidiary. See also: the more specific \'department\' property.'),
(4723, 1, 20, 'parentOrganization', 'parentOrganization', 'The larger organization that this organization is a [[subOrganization]] of, if any.'),
(4724, 1, 20, 'foundingDate', 'foundingDate', 'The date that this organization was founded.'),
(4725, 1, 20, 'clinicalPharmacology', 'clinicalPharmacology', 'Description of the absorption and elimination of drugs, including their concentration (pharmacokinetics, pK) and biological effects (pharmacodynamics, pD).'),
(4726, 1, 20, 'algorithm', 'algorithm', 'The algorithm or rules to follow to compute the score.'),
(4727, 1, 20, 'addOn', 'addOn', 'An additional offer that can only be obtained in combination with the first base offer (e.g. supplements and extensions that are available for a surcharge).'),
(4728, 1, 20, 'vatID', 'vatID', 'The Value-added Tax ID of the organization or person.'),
(4729, 1, 20, 'partOfTrip', 'partOfTrip', 'Identifies that this [[Trip]] is a subTrip of another Trip.  For example Day 1, Day 2, etc. of a multi-day trip.'),
(4730, 1, 20, 'subTrip', 'subTrip', 'Identifies a [[Trip]] that is a subTrip of this Trip.  For example Day 1, Day 2, etc. of a multi-day trip.'),
(4731, 1, 20, 'knowsLanguage', 'knowsLanguage', 'Of a [[Person]], and less typically of an [[Organization]], to indicate a known language. We do not distinguish skill levels or reading/writing/speaking/signing here. Use language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47).'),
(4732, 1, 20, 'educationalFramework', 'educationalFramework', 'The framework to which the resource being described is aligned.'),
(4733, 1, 20, 'language', 'language', 'A sub property of instrument. The language used on this action.'),
(4734, 1, 20, 'inLanguage', 'inLanguage', 'The language of the content or performance or used in an action. Please use one of the language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47). See also [[availableLanguage]].'),
(4735, 1, 20, 'energyEfficiencyScaleMin', 'energyEfficiencyScaleMin', 'Specifies the least energy efficient class on the regulated EU energy consumption scale for the product category a product belongs to. For example, energy consumption for televisions placed on the market after January 1, 2020 is scaled from D to A+++.'),
(4736, 1, 20, 'orderItemStatus', 'orderItemStatus', 'The current status of the order item.'),
(4737, 1, 20, 'familyName', 'familyName', 'Family name. In the U.S., the last name of a Person.'),
(4738, 1, 20, 'cookingMethod', 'cookingMethod', 'The method of cooking, such as Frying, Steaming, ...'),
(4739, 1, 20, 'closes', 'closes', 'The closing hour of the place or service on the given day(s) of the week.'),
(4740, 1, 20, 'iso6523Code', 'iso6523Code', 'An organization identifier as defined in [ISO 6523(-1)](https://en.wikipedia.org/wiki/ISO/IEC_6523). The identifier should be in the `XXXX:YYYYYY:ZZZ` or `XXXX:YYYYYY`format. Where `XXXX` is a 4 digit _ICD_ (International Code Designator), `YYYYYY` is an _OID_ (Organization Identifier) with all formatting characters (dots, dashes, spaces) removed with a maximal length of 35 characters, and `ZZZ` is an optional OPI (Organization Part Identifier) with a maximum length of 35 characters. The various components (ICD, OID, OPI) are joined with a colon character (ASCII `0x3a`). Note that many existing organization identifiers defined as attributes like [leiCode](http://schema.org/leiCode) (`0199`), [duns](http://schema.org/duns) (`0060`) or [GLN](http://schema.org/globalLocationNumber) (`0088`) can be expressed using ISO-6523. If possible, ISO-6523 codes should be preferred to populating [vatID](http://schema.org/vatID) or [taxID](http://schema.org/taxID), as ISO identifiers are less ambiguous.'),
(4741, 1, 20, 'auditDate', 'auditDate', 'Date when a certification was last audited. See also  [gs1:certificationAuditDate](https://www.gs1.org/voc/certificationAuditDate).'),
(4742, 1, 20, 'valueMinLength', 'valueMinLength', 'Specifies the minimum allowed range for number of characters in a literal value.'),
(4743, 1, 20, 'inStoreReturnsOffered', 'inStoreReturnsOffered', 'Are in-store returns offered? (For more advanced return methods use the [[returnMethod]] property.)'),
(4744, 1, 20, 'paymentMethod', 'paymentMethod', 'The name of the credit card or other method of payment for the order.'),
(4745, 1, 20, 'associatedMedia', 'associatedMedia', 'A media object that encodes this CreativeWork. This property is a synonym for encoding.'),
(4746, 1, 20, 'hasMeasurement', 'hasMeasurement', 'A measurement of an item, For example, the inseam of pants, the wheel size of a bicycle, the gauge of a screw, or the carbon footprint measured for certification by an authority. Usually an exact measurement, but can also be a range of measurements for adjustable products, for example belts and ski bindings.'),
(4747, 1, 20, 'possibleComplication', 'possibleComplication', 'A possible unexpected and unfavorable evolution of a medical condition. Complications may include worsening of the signs or symptoms of the disease, extension of the condition to other organ systems, etc.'),
(4748, 1, 20, 'actors', 'actors', 'An actor, e.g. in TV, radio, movie, video games etc. Actors can be associated with individual items or with a series, episode, clip.'),
(4749, 1, 20, 'paymentUrl', 'paymentUrl', 'The URL for sending a payment.'),
(4750, 1, 20, 'availableFrom', 'availableFrom', 'When the item is available for pickup from the store, locker, etc.'),
(4751, 1, 20, 'breadcrumb', 'breadcrumb', 'A set of links that can help a user understand and navigate a website hierarchy.'),
(4752, 1, 20, 'merchant', 'merchant', '\'merchant\' is an out-dated term for \'seller\'.'),
(4753, 1, 20, 'seller', 'seller', 'An entity which offers (sells / leases / lends / loans) the services / goods.  A seller may also be a provider.'),
(4754, 1, 20, 'broadcastChannelId', 'broadcastChannelId', 'The unique address by which the BroadcastService can be identified in a provider lineup. In US, this is typically a number.'),
(4755, 1, 20, 'studySubject', 'studySubject', 'A subject of the study, i.e. one of the medical conditions, therapies, devices, drugs, etc. investigated by the study.'),
(4756, 1, 20, 'partOfInvoice', 'partOfInvoice', 'The order is being paid as part of the referenced Invoice.'),
(4757, 1, 20, 'cookTime', 'cookTime', 'The time it takes to actually cook the dish, in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(4758, 1, 20, 'performTime', 'performTime', 'The length of time it takes to perform instructions or a direction (not including time to prepare the supplies), in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(4759, 1, 20, 'multipleValues', 'multipleValues', 'Whether multiple values are allowed for the property.  Default is false.'),
(4760, 1, 20, 'cssSelector', 'cssSelector', 'A CSS selector, e.g. of a [[SpeakableSpecification]] or [[WebPageElement]]. In the latter case, multiple matches within a page can constitute a single conceptual \"Web page element\".'),
(4761, 1, 20, 'contentType', 'contentType', 'The supported content type(s) for an EntryPoint response.'),
(4762, 1, 20, 'termCode', 'termCode', 'A code that identifies this [[DefinedTerm]] within a [[DefinedTermSet]].'),
(4763, 1, 20, 'courseMode', 'courseMode', 'The medium or means of delivery of the course instance or the mode of study, either as a text label (e.g. \"online\", \"onsite\" or \"blended\"; \"synchronous\" or \"asynchronous\"; \"full-time\" or \"part-time\") or as a URL reference to a term from a controlled vocabulary (e.g. https://ceds.ed.gov/element/001311#Asynchronous).'),
(4764, 1, 20, 'honorificPrefix', 'honorificPrefix', 'An honorific prefix preceding a Person\'s name such as Dr/Mrs/Mr.'),
(4765, 1, 20, 'minValue', 'minValue', 'The lower value of some characteristic or property.'),
(4766, 1, 20, 'enginePower', 'enginePower', 'The power of the vehicle\'s engine.\n    Typical unit code(s): KWT for kilowatt, BHP for brake horsepower, N12 for metric horsepower (PS, with 1 PS = 735,49875 W)\\n\\n* Note 1: There are many different ways of measuring an engine\'s power. For an overview, see  [http://en.wikipedia.org/wiki/Horsepower#Engine\\_power\\_test\\_codes](http://en.wikipedia.org/wiki/Horsepower#Engine_power_test_codes).\\n* Note 2: You can link to information about how the given value has been determined using the [[valueReference]] property.\\n* Note 3: You can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(4767, 1, 20, 'scheduledTime', 'scheduledTime', 'The time the object is scheduled to.'),
(4768, 1, 20, 'floorSize', 'floorSize', 'The size of the accommodation, e.g. in square meter or squarefoot.\nTypical unit code(s): MTK for square meter, FTK for square foot, or YDK for square yard.'),
(4769, 1, 20, 'tool', 'tool', 'A sub property of instrument. An object used (but not consumed) when performing instructions or a direction.'),
(4770, 1, 20, 'version', 'version', 'The version of the CreativeWork embodied by a specified resource.'),
(4771, 1, 20, 'childMaxAge', 'childMaxAge', 'Maximal age of the child.'),
(4772, 1, 20, 'exchangeRateSpread', 'exchangeRateSpread', 'The difference between the price at which a broker or other intermediary buys and sells foreign currency.'),
(4773, 1, 20, 'award', 'award', 'An award won by or for this item.'),
(4774, 1, 20, 'inverseOf', 'inverseOf', 'Relates a property to a property that is its inverse. Inverse properties relate the same pairs of items to each other, but in reversed direction. For example, the \'alumni\' and \'alumniOf\' properties are inverseOf each other. Some properties don\'t have explicit inverses; in these situations RDFa and JSON-LD syntax for reverse properties can be used.'),
(4775, 1, 20, 'containsSeason', 'containsSeason', 'A season that is part of the media series.'),
(4776, 1, 20, 'hasPart', 'hasPart', 'Indicates an item or CreativeWork that is part of this item, or CreativeWork (in some sense).'),
(4777, 1, 20, 'addressCountry', 'addressCountry', 'The country. Recommended to be in 2-letter [ISO 3166-1 alpha-2](http://en.wikipedia.org/wiki/ISO_3166-1) format, for example \"US\". For backward compatibility, a 3-letter [ISO 3166-1 alpha-3](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-3) country code such as \"SGP\" or a full country name such as \"Singapore\" can also be used.'),
(4778, 1, 20, 'publishedBy', 'publishedBy', 'An agent associated with the publication event.'),
(4779, 1, 20, 'passengerPriorityStatus', 'passengerPriorityStatus', 'The priority status assigned to a passenger for security or boarding (e.g. FastTrack or Priority).'),
(4780, 1, 20, 'loser', 'loser', 'A sub property of participant. The loser of the action.'),
(4781, 1, 20, 'availableDeliveryMethod', 'availableDeliveryMethod', 'The delivery method(s) available for this offer.'),
(4782, 1, 20, 'possibleTreatment', 'possibleTreatment', 'A possible treatment to address this condition, sign or symptom.'),
(4783, 1, 20, 'dosageForm', 'dosageForm', 'A dosage form in which this drug/supplement is available, e.g. \'tablet\', \'suspension\', \'injection\'.'),
(4784, 1, 20, 'itemDefectReturnFees', 'itemDefectReturnFees', 'The type of return fees for returns of defect products.'),
(4785, 1, 20, 'blogPost', 'blogPost', 'A posting that is part of this blog.'),
(4786, 1, 20, 'preOp', 'preOp', 'A description of the workup, testing, and other preparations required before implanting this device.'),
(4787, 1, 20, 'expressedIn', 'expressedIn', 'Tissue, organ, biological sample, etc in which activity of this gene has been observed experimentally. For example brain, digestive system.'),
(4788, 1, 20, 'recognizedBy', 'recognizedBy', 'An organization that acknowledges the validity, value or utility of a credential. Note: recognition may include a process of quality assurance or accreditation.'),
(4789, 1, 20, 'printEdition', 'printEdition', 'The edition of the print product in which the NewsArticle appears.'),
(4790, 1, 20, 'isAvailableGenerically', 'isAvailableGenerically', 'True if the drug is available in a generic form (regardless of name).'),
(4791, 1, 20, 'busNumber', 'busNumber', 'The unique identifier for the bus.'),
(4792, 1, 20, 'openingHours', 'openingHours', 'The general opening hours for a business. Opening hours can be specified as a weekly time range, starting with days, then times per day. Multiple days can be listed with commas \',\' separating each day. Day or time ranges are specified using a hyphen \'-\'.\\n\\n* Days are specified using the following two-letter combinations: ```Mo```, ```Tu```, ```We```, ```Th```, ```Fr```, ```Sa```, ```Su```.\\n* Times are specified using 24:00 format. For example, 3pm is specified as ```15:00```, 10am as ```10:00```. \\n* Here is an example: <code>&lt;time itemprop=\"openingHours\" datetime=&quot;Tu,Th 16:00-20:00&quot;&gt;Tuesdays and Thursdays 4-8pm&lt;/time&gt;</code>.\\n* If a business is open 7 days a week, then it can be specified as <code>&lt;time itemprop=&quot;openingHours&quot; datetime=&quot;Mo-Su&quot;&gt;Monday through Sunday, all day&lt;/time&gt;</code>.'),
(4793, 1, 20, 'prescriptionStatus', 'prescriptionStatus', 'Indicates the status of drug prescription, e.g. local catalogs classifications or whether the drug is available by prescription or over-the-counter, etc.'),
(4794, 1, 20, 'bookingTime', 'bookingTime', 'The date and time the reservation was booked.'),
(4795, 1, 20, 'productSupported', 'productSupported', 'The product or service this support contact point is related to (such as product support for a particular product line). This can be a specific product or product line (e.g. \"iPhone\") or a general category of products or services (e.g. \"smartphones\").'),
(4796, 1, 20, 'validIn', 'validIn', 'The geographic area where the item is valid. Applies for example to a [[Permit]], a [[Certification]], or an [[EducationalOccupationalCredential]]. '),
(4797, 1, 20, 'evidenceOrigin', 'evidenceOrigin', 'Source of the data used to formulate the guidance, e.g. RCT, consensus opinion, etc.'),
(4798, 1, 20, 'isPlanForApartment', 'isPlanForApartment', 'Indicates some accommodation that this floor plan describes.'),
(4799, 1, 20, 'learningResourceType', 'learningResourceType', 'The predominant type or kind characterizing the learning resource. For example, \'presentation\', \'handout\'.'),
(4800, 1, 20, 'ineligibleRegion', 'ineligibleRegion', 'The ISO 3166-1 (ISO 3166-1 alpha-2) or ISO 3166-2 code, the place, or the GeoShape for the geo-political region(s) for which the offer or delivery charge specification is not valid, e.g. a region where the transaction is not allowed.\\n\\nSee also [[eligibleRegion]].\n      '),
(4801, 1, 20, 'encoding', 'encoding', 'A media object that encodes this CreativeWork. This property is a synonym for associatedMedia.'),
(4802, 1, 20, 'encodesCreativeWork', 'encodesCreativeWork', 'The CreativeWork encoded by this media object.'),
(4803, 1, 20, 'accommodationCategory', 'accommodationCategory', 'Category of an [[Accommodation]], following real estate conventions, e.g. RESO (see [PropertySubType](https://ddwiki.reso.org/display/DDW17/PropertySubType+Field), and [PropertyType](https://ddwiki.reso.org/display/DDW17/PropertyType+Field) fields  for suggested values).'),
(4804, 1, 20, 'category', 'category', 'A category for the item. Greater signs or slashes can be used to informally indicate a category hierarchy.'),
(4805, 1, 20, 'hiringOrganization', 'hiringOrganization', 'Organization or Person offering the job position.'),
(4806, 1, 20, 'deliveryMethod', 'deliveryMethod', 'A sub property of instrument. The method of delivery.'),
(4807, 1, 20, 'address', 'address', 'Physical address of the item.'),
(4808, 1, 20, 'inker', 'inker', 'The individual who traces over the pencil drawings in ink after pencils are complete.'),
(4809, 1, 20, 'issn', 'issn', 'The International Standard Serial Number (ISSN) that identifies this serial publication. You can repeat this property to identify different formats of, or the linking ISSN (ISSN-L) for, this serial publication.'),
(4810, 1, 20, 'petsAllowed', 'petsAllowed', 'Indicates whether pets are allowed to enter the accommodation or lodging business. More detailed information can be put in a text value.'),
(4811, 1, 20, 'contactlessPayment', 'contactlessPayment', 'A secure method for consumers to purchase products or services via debit, credit or smartcards by using RFID or NFC technology.'),
(4812, 1, 20, 'hasProductReturnPolicy', 'hasProductReturnPolicy', 'Indicates a ProductReturnPolicy that may be applicable.'),
(4813, 1, 20, 'hasMerchantReturnPolicy', 'hasMerchantReturnPolicy', 'Specifies a MerchantReturnPolicy that may be applicable.'),
(4814, 1, 20, 'recordedAt', 'recordedAt', 'The Event where the CreativeWork was recorded. The CreativeWork may capture all or part of the event.'),
(4815, 1, 20, 'recordedIn', 'recordedIn', 'The CreativeWork that captured all or part of this Event.'),
(4816, 1, 20, 'dateline', 'dateline', 'A [dateline](https://en.wikipedia.org/wiki/Dateline) is a brief piece of text included in news articles that describes where and when the story was written or filed though the date is often omitted. Sometimes only a placename is provided.\n\nStructured representations of dateline-related information can also be expressed more explicitly using [[locationCreated]] (which represents where a work was created, e.g. where a news report was written).  For location depicted or described in the content, use [[contentLocation]].\n\nDateline summaries are oriented more towards human readers than towards automated processing, and can vary substantially. Some examples: \"BEIRUT, Lebanon, June 2.\", \"Paris, France\", \"December 19, 2017 11:43AM Reporting from Washington\", \"Beijing/Moscow\", \"QUEZON CITY, Philippines\".\n      '),
(4817, 1, 20, 'geoMidpoint', 'geoMidpoint', 'Indicates the GeoCoordinates at the centre of a GeoShape, e.g. GeoCircle.'),
(4818, 1, 20, 'recipient', 'recipient', 'A sub property of participant. The participant who is at the receiving end of the action.'),
(4819, 1, 20, 'courseCode', 'courseCode', 'The identifier for the [[Course]] used by the course [[provider]] (e.g. CS101 or 6.001).'),
(4820, 1, 20, 'customerRemorseReturnLabelSource', 'customerRemorseReturnLabelSource', 'The method (from an enumeration) by which the customer obtains a return shipping label for a product returned due to customer remorse.'),
(4821, 1, 20, 'arrivalStation', 'arrivalStation', 'The station where the train trip ends.'),
(4822, 1, 20, 'successorOf', 'successorOf', 'A pointer from a newer variant of a product  to its previous, often discontinued predecessor.'),
(4823, 1, 20, 'paymentDueDate', 'paymentDueDate', 'The date that payment is due.'),
(4824, 1, 20, 'itemListElement', 'itemListElement', 'For itemListElement values, you can use simple strings (e.g. \"Peter\", \"Paul\", \"Mary\"), existing entities, or use ListItem.\\n\\nText values are best if the elements in the list are plain strings. Existing entities are best for a simple, unordered list of existing things in your data. ListItem is used with ordered lists when you want to provide additional context about the element in that list or when the same item might be in different places in different lists.\\n\\nNote: The order of elements in your mark-up is not sufficient for indicating the order or elements.  Use ListItem with a \'position\' property in such cases.'),
(4825, 1, 20, 'partySize', 'partySize', 'Number of people the reservation should accommodate.'),
(4826, 1, 20, 'underName', 'underName', 'The person or organization the reservation or ticket is for.'),
(4827, 1, 20, 'inProductGroupWithID', 'inProductGroupWithID', 'Indicates the [[productGroupID]] for a [[ProductGroup]] that this product [[isVariantOf]]. '),
(4828, 1, 20, 'polygon', 'polygon', 'A polygon is the area enclosed by a point-to-point path for which the starting and ending points are the same. A polygon is expressed as a series of four or more space delimited points where the first and final points are identical.'),
(4829, 1, 20, 'distinguishingSign', 'distinguishingSign', 'One of a set of signs and symptoms that can be used to distinguish this diagnosis from others in the differential diagnosis.'),
(4830, 1, 20, 'accessibilitySummary', 'accessibilitySummary', 'A human-readable summary of specific accessibility features or deficiencies, consistent with the other accessibility metadata but expressing subtleties such as \"short descriptions are present but long descriptions will be needed for non-visual users\" or \"short descriptions are present and no long descriptions are needed\".'),
(4831, 1, 20, 'runsTo', 'runsTo', 'The vasculature the lymphatic structure runs, or efferents, to.'),
(4832, 1, 20, 'trainingSalary', 'trainingSalary', 'The estimated salary earned while in the program.'),
(4833, 1, 20, 'propertyID', 'propertyID', 'A commonly used identifier for the characteristic represented by the property, e.g. a manufacturer or a standard code for a property. propertyID can be\n(1) a prefixed string, mainly meant to be used with standards for product properties; (2) a site-specific, non-prefixed string (e.g. the primary key of the property or the vendor-specific ID of the property), or (3)\na URL indicating the type of the property, either pointing to an external vocabulary, or a Web resource that describes the property (e.g. a glossary entry).\nStandards bodies should promote a standard prefix for the identifiers of properties from their standards.'),
(4834, 1, 20, 'programType', 'programType', 'The type of educational or occupational program. For example, classroom, internship, alternance, etc.'),
(4835, 1, 20, 'readonlyValue', 'readonlyValue', 'Whether or not a property is mutable.  Default is false. Specifying this for a property that also has a value makes it act similar to a \"hidden\" input in an HTML form.'),
(4836, 1, 20, 'callSign', 'callSign', 'A [callsign](https://en.wikipedia.org/wiki/Call_sign), as used in broadcasting and radio communications to identify people, radio and TV stations, or vehicles.'),
(4837, 1, 20, 'membershipNumber', 'membershipNumber', 'A unique identifier for the membership.'),
(4838, 1, 20, 'yearlyRevenue', 'yearlyRevenue', 'The size of the business in annual revenue.'),
(4839, 1, 20, 'legislationLegalForce', 'legislationLegalForce', 'Whether the legislation is currently in force, not in force, or partially in force.'),
(4840, 1, 20, 'editor', 'editor', 'Specifies the Person who edited the CreativeWork.'),
(4841, 1, 20, 'pageStart', 'pageStart', 'The page on which the work starts; for example \"135\" or \"xiii\".'),
(4842, 1, 20, 'numberOfSeasons', 'numberOfSeasons', 'The number of seasons in this series.'),
(4843, 1, 20, 'passengerSequenceNumber', 'passengerSequenceNumber', 'The passenger\'s sequence number as assigned by the airline.'),
(4844, 1, 20, 'priceValidUntil', 'priceValidUntil', 'The date after which the price is no longer available.'),
(4845, 1, 20, 'geographicArea', 'geographicArea', 'The geographic area associated with the audience.'),
(4846, 1, 20, 'seasonNumber', 'seasonNumber', 'Position of the season within an ordered group of seasons.'),
(4847, 1, 20, 'position', 'position', 'The position of an item in a series or sequence of items.'),
(4848, 1, 20, 'quest', 'quest', 'The task that a player-controlled character, or group of characters may complete in order to gain a reward.'),
(4849, 1, 20, 'eventAttendanceMode', 'eventAttendanceMode', 'The eventAttendanceMode of an event indicates whether it occurs online, offline, or a mix.'),
(4850, 1, 20, 'fuelConsumption', 'fuelConsumption', 'The amount of fuel consumed for traveling a particular distance or temporal duration with the given vehicle (e.g. liters per 100 km).\\n\\n* Note 1: There are unfortunately no standard unit codes for liters per 100 km.  Use [[unitText]] to indicate the unit of measurement, e.g. L/100 km.\\n* Note 2: There are two ways of indicating the fuel consumption, [[fuelConsumption]] (e.g. 8 liters per 100 km) and [[fuelEfficiency]] (e.g. 30 miles per gallon). They are reciprocal.\\n* Note 3: Often, the absolute value is useful only when related to driving speed (\"at 80 km/h\") or usage pattern (\"city traffic\"). You can use [[valueReference]] to link the value for the fuel consumption to another value.'),
(4851, 1, 20, 'tripOrigin', 'tripOrigin', 'The location of origin of the trip, prior to any destination(s).'),
(4852, 1, 20, 'birthPlace', 'birthPlace', 'The place where the person was born.'),
(4853, 1, 20, 'associatedReview', 'associatedReview', 'An associated [[Review]].'),
(4854, 1, 20, 'copyrightHolder', 'copyrightHolder', 'The party holding the legal copyright to the CreativeWork.'),
(4855, 1, 20, 'sampleType', 'sampleType', 'What type of code sample: full (compile ready) solution, code snippet, inline code, scripts, template.'),
(4856, 1, 20, 'codeSampleType', 'codeSampleType', 'What type of code sample: full (compile ready) solution, code snippet, inline code, scripts, template.'),
(4857, 1, 20, 'follows', 'follows', 'The most generic uni-directional social relation.'),
(4858, 1, 20, 'pickupTime', 'pickupTime', 'When a taxi will pick up a passenger or a rental car can be picked up.'),
(4859, 1, 20, 'reviewedBy', 'reviewedBy', 'People or organizations that have reviewed the content on this web page for accuracy and/or completeness.'),
(4860, 1, 20, 'releaseNotes', 'releaseNotes', 'Description of what changed in this version.'),
(4861, 1, 20, 'funding', 'funding', 'A [[Grant]] that directly or indirectly provide funding or sponsorship for this item. See also [[ownershipFundingInfo]].'),
(4862, 1, 20, 'fundedItem', 'fundedItem', 'Indicates something directly or indirectly funded or sponsored through a [[Grant]]. See also [[ownershipFundingInfo]].'),
(4863, 1, 20, 'returnMethod', 'returnMethod', 'The type of return method offered, specified from an enumeration.'),
(4864, 1, 20, 'availableTest', 'availableTest', 'A diagnostic test or procedure offered by this lab.'),
(4865, 1, 20, 'maxValue', 'maxValue', 'The upper value of some characteristic or property.'),
(4866, 1, 20, 'endTime', 'endTime', 'The endTime of something. For a reserved event or service (e.g. FoodEstablishmentReservation), the time that it is expected to end. For actions that span a period of time, when the action was performed. E.g. John wrote a book from January to *December*. For media, including audio and video, it\'s the time offset of the end of a clip within a larger file.\\n\\nNote that Event uses startDate/endDate instead of startTime/endTime, even when describing dates with times. This situation may be clarified in future revisions.'),
(4867, 1, 20, 'refundType', 'refundType', 'A refund type, from an enumerated list.'),
(4868, 1, 20, 'targetUrl', 'targetUrl', 'The URL of a node in an established educational framework.'),
(4869, 1, 20, 'uploadDate', 'uploadDate', 'Date (including time if available) when this media object was uploaded to this site.'),
(4870, 1, 20, 'ticketNumber', 'ticketNumber', 'The unique identifier for the ticket.'),
(4871, 1, 20, 'supportingData', 'supportingData', 'Supporting data for a SoftwareApplication.'),
(4872, 1, 20, 'albumProductionType', 'albumProductionType', 'Classification of the album by its type of content: soundtrack, live album, studio album, etc.'),
(4873, 1, 20, 'dateRead', 'dateRead', 'The date/time at which the message has been read by the recipient if a single recipient exists.'),
(4874, 1, 20, 'seatNumber', 'seatNumber', 'The location of the reserved seat (e.g., 27).'),
(4875, 1, 20, 'suitableForDiet', 'suitableForDiet', 'Indicates a dietary restriction or guideline for which this recipe or menu item is suitable, e.g. diabetic, halal etc.'),
(4876, 1, 20, 'parentService', 'parentService', 'A broadcast service to which the broadcast service may belong to such as regional variations of a national channel.'),
(4877, 1, 20, 'aircraft', 'aircraft', 'The kind of aircraft (e.g., \"Boeing 747\").'),
(4878, 1, 20, 'courseSchedule', 'courseSchedule', 'Represents the length and pace of a course, expressed as a [[Schedule]].'),
(4879, 1, 20, 'transcript', 'transcript', 'If this MediaObject is an AudioObject or VideoObject, the transcript of that object.'),
(4880, 1, 20, 'datePosted', 'datePosted', 'Publication date of an online listing.'),
(4881, 1, 20, 'broker', 'broker', 'An entity that arranges for an exchange between a buyer and a seller.  In most cases a broker never acquires or releases ownership of a product or service involved in an exchange.  If it is not clear whether an entity is a broker, seller, or buyer, the latter two terms are preferred.'),
(4882, 1, 20, 'answerCount', 'answerCount', 'The number of answers this question has received.'),
(4883, 1, 20, 'isLiveBroadcast', 'isLiveBroadcast', 'True if the broadcast is of a live event.'),
(4884, 1, 20, 'freeShippingThreshold', 'freeShippingThreshold', 'A monetary value above (or at) which the shipping rate becomes free. Intended to be used via an [[OfferShippingDetails]] with [[shippingSettingsLink]] matching this [[ShippingRateSettings]].'),
(4885, 1, 20, 'jobLocation', 'jobLocation', 'A (typically single) geographic location associated with the job position.'),
(4886, 1, 20, 'hasOfferCatalog', 'hasOfferCatalog', 'Indicates an OfferCatalog listing for this Organization, Person, or Service.'),
(4887, 1, 20, 'tickerSymbol', 'tickerSymbol', 'The exchange traded instrument associated with a Corporation object. The tickerSymbol is expressed as an exchange and an instrument name separated by a space character. For the exchange component of the tickerSymbol attribute, we recommend using the controlled vocabulary of Market Identifier Codes (MIC) specified in ISO 15022.'),
(4888, 1, 20, 'hasCertification', 'hasCertification', 'Certification information about a product, organization, service, place, or person.'),
(4889, 1, 20, 'parentTaxon', 'parentTaxon', 'Closest parent taxon of the taxon in question.'),
(4890, 1, 20, 'childTaxon', 'childTaxon', 'Closest child taxa of the taxon in question.'),
(4891, 1, 20, 'maximumVirtualAttendeeCapacity', 'maximumVirtualAttendeeCapacity', 'The maximum virtual attendee capacity of an [[Event]] whose [[eventAttendanceMode]] is [[OnlineEventAttendanceMode]] (or the online aspects, in the case of a [[MixedEventAttendanceMode]]). '),
(4892, 1, 20, 'url', 'url', 'URL of the item.'),
(4893, 1, 20, 'subEvent', 'subEvent', 'An Event that is part of this event. For example, a conference event includes many presentations, each of which is a subEvent of the conference.'),
(4894, 1, 20, 'superEvent', 'superEvent', 'An event that this event is a part of. For example, a collection of individual music performances might each have a music festival as their superEvent.'),
(4895, 1, 20, 'numberOfDoors', 'numberOfDoors', 'The number of doors.\\n\\nTypical unit code(s): C62.'),
(4896, 1, 20, 'securityClearanceRequirement', 'securityClearanceRequirement', 'A description of any security clearance requirements of the job.'),
(4897, 1, 20, 'occupancy', 'occupancy', 'The allowed total occupancy for the accommodation in persons (including infants etc). For individual accommodations, this is not necessarily the legal maximum but defines the permitted usage as per the contractual agreement (e.g. a double room used by a single person).\nTypical unit code(s): C62 for person.'),
(4898, 1, 20, 'fatContent', 'fatContent', 'The number of grams of fat.'),
(4899, 1, 20, 'antagonist', 'antagonist', 'The muscle whose action counteracts the specified muscle.'),
(4900, 1, 20, 'infectiousAgentClass', 'infectiousAgentClass', 'The class of infectious agent (bacteria, prion, etc.) that causes the disease.'),
(4901, 1, 20, 'shippingRate', 'shippingRate', 'The shipping rate is the cost of shipping to the specified destination. Typically, the maxValue and currency values (of the [[MonetaryAmount]]) are most appropriate.'),
(4902, 1, 20, 'insertion', 'insertion', 'The place of attachment of a muscle, or what the muscle moves.'),
(4903, 1, 20, 'manufacturer', 'manufacturer', 'The manufacturer of the product.'),
(4904, 1, 20, 'serviceSmsNumber', 'serviceSmsNumber', 'The number to access the service by text message.'),
(4905, 1, 20, 'recommendedIntake', 'recommendedIntake', 'Recommended intake of this supplement for a given population as defined by a specific recommending authority.'),
(4906, 1, 20, 'touristType', 'touristType', 'Attraction suitable for type(s) of tourist. E.g. children, visitors from a particular country, etc. '),
(4907, 1, 20, 'mediaItemAppearance', 'mediaItemAppearance', 'In the context of a [[MediaReview]], indicates specific media item(s) that are grouped using a [[MediaReviewItem]].'),
(4908, 1, 20, 'validForMemberTier', 'validForMemberTier', 'The membership program tier an Offer (or a PriceSpecification, OfferShippingDetails, or MerchantReturnPolicy under an Offer) is valid for.'),
(4909, 1, 20, 'branchCode', 'branchCode', 'A short textual code (also called \"store code\") that uniquely identifies a place of business. The code is typically assigned by the parentOrganization and used in structured URLs.\\n\\nFor example, in the URL http://www.starbucks.co.uk/store-locator/etc/detail/3047 the code \"3047\" is a branchCode for a particular branch.\n      '),
(4910, 1, 20, 'namedPosition', 'namedPosition', 'A position played, performed or filled by a person or organization, as part of an organization. For example, an athlete in a SportsTeam might play in the position named \'Quarterback\'.'),
(4911, 1, 20, 'roleName', 'roleName', 'A role played, performed or filled by a person or organization. For example, the team of creators for a comic book might fill the roles named \'inker\', \'penciller\', and \'letterer\'; or an athlete in a SportsTeam might play in the position named \'Quarterback\'.'),
(4912, 1, 20, 'recordedAs', 'recordedAs', 'An audio recording of the work.'),
(4913, 1, 20, 'recordingOf', 'recordingOf', 'The composition this track is a recording of.'),
(4914, 1, 20, 'about', 'about', 'The subject matter of the content.'),
(4915, 1, 20, 'subjectOf', 'subjectOf', 'A CreativeWork or Event about this Thing.'),
(4916, 1, 20, 'givenName', 'givenName', 'Given name. In the U.S., the first name of a Person.'),
(4917, 1, 20, 'knownVehicleDamages', 'knownVehicleDamages', 'A textual description of known damages, both repaired and unrepaired.'),
(4918, 1, 20, 'cvdNumC19OverflowPats', 'cvdNumC19OverflowPats', 'numc19overflowpats - ED/OVERFLOW: Patients with suspected or confirmed COVID-19 who are in the ED or any overflow location awaiting an inpatient bed.'),
(4919, 1, 20, 'alternativeHeadline', 'alternativeHeadline', 'A secondary title of the CreativeWork.'),
(4920, 1, 20, 'ethicsPolicy', 'ethicsPolicy', 'Statement about ethics policy, e.g. of a [[NewsMediaOrganization]] regarding journalistic and publishing practices, or of a [[Restaurant]], a page describing food source policies. In the case of a [[NewsMediaOrganization]], an ethicsPolicy is typically a statement describing the personal, organizational, and corporate standards of behavior expected by the organization.'),
(4921, 1, 20, 'serviceAudience', 'serviceAudience', 'The audience eligible for this service.'),
(4922, 1, 20, 'audience', 'audience', 'An intended audience, i.e. a group for whom something was created.'),
(4923, 1, 20, 'actionApplication', 'actionApplication', 'An application that can complete the request.'),
(4924, 1, 20, 'assemblyVersion', 'assemblyVersion', 'Associated product/technology version. E.g., .NET Framework 4.5.'),
(4925, 1, 20, 'currency', 'currency', 'The currency in which the monetary amount is expressed.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(4926, 1, 20, 'molecularFormula', 'molecularFormula', 'The empirical formula is the simplest whole number ratio of all the atoms in a molecule.'),
(4927, 1, 20, 'broadcastOfEvent', 'broadcastOfEvent', 'The event being broadcast such as a sporting event or awards ceremony.'),
(4928, 1, 20, 'totalPaymentDue', 'totalPaymentDue', 'The total amount due.'),
(4929, 1, 20, 'certificationIdentification', 'certificationIdentification', 'Identifier of a certification instance (as registered with an independent certification body). Typically this identifier can be used to consult and verify the certification instance. See also [gs1:certificationIdentification](https://www.gs1.org/voc/certificationIdentification).'),
(4930, 1, 20, 'commentCount', 'commentCount', 'The number of comments this CreativeWork (e.g. Article, Question or Answer) has received. This is most applicable to works published in Web sites with commenting system; additional comments may exist elsewhere.'),
(4931, 1, 20, 'dataset', 'dataset', 'A dataset contained in this catalog.'),
(4932, 1, 20, 'hasPOS', 'hasPOS', 'Points-of-Sales operated by the organization or person.'),
(4933, 1, 20, 'deliveryAddress', 'deliveryAddress', 'Destination address.'),
(4934, 1, 20, 'cashBack', 'cashBack', 'A cardholder benefit that pays the cardholder a small percentage of their net expenditures.'),
(4935, 1, 20, 'lyrics', 'lyrics', 'The words in the song.'),
(4936, 1, 20, 'procedureType', 'procedureType', 'The type of procedure, for example Surgical, Noninvasive, or Percutaneous.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(4937, 1, 20, 'funder', 'funder', 'A person or organization that supports (sponsors) something through some kind of financial contribution.'),
(4938, 1, 20, 'sponsor', 'sponsor', 'A person or organization that supports a thing through a pledge, promise, or financial contribution. E.g. a sponsor of a Medical Study or a corporate sponsor of an event.'),
(4939, 1, 20, 'healthPlanMarketingUrl', 'healthPlanMarketingUrl', 'The URL that goes directly to the plan brochure for the specific standard plan or plan variation.'),
(4940, 1, 20, 'gameServer', 'gameServer', 'The server on which  it is possible to play the game.'),
(4941, 1, 20, 'game', 'game', 'Video game which is played on this server.'),
(4942, 1, 20, 'fromLocation', 'fromLocation', 'A sub property of location. The original location of the object or the agent before the action.'),
(4943, 1, 20, 'lowPrice', 'lowPrice', 'The lowest price of all offers available.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(4944, 1, 20, 'breastfeedingWarning', 'breastfeedingWarning', 'Any precaution, guidance, contraindication, etc. related to this drug\'s use by breastfeeding mothers.'),
(4945, 1, 20, 'certificationRating', 'certificationRating', 'Rating of a certification instance (as defined by an independent certification body). Typically this rating can be used to rate the level to which the requirements of the certification instance are fulfilled. See also [gs1:certificationValue](https://www.gs1.org/voc/certificationValue).'),
(4946, 1, 20, 'potentialUse', 'potentialUse', 'Intended use of the BioChemEntity by humans.'),
(4947, 1, 20, 'alcoholWarning', 'alcoholWarning', 'Any precaution, guidance, contraindication, etc. related to consumption of alcohol while taking this drug.'),
(4948, 1, 20, 'feesAndCommissionsSpecification', 'feesAndCommissionsSpecification', 'Description of fees, commissions, and other terms applied either to a class of financial product, or by a financial service organization.'),
(4949, 1, 20, 'healthPlanPharmacyCategory', 'healthPlanPharmacyCategory', 'The category or type of pharmacy associated with this cost sharing.'),
(4950, 1, 20, 'repeatCount', 'repeatCount', 'Defines the number of times a recurring [[Event]] will take place.'),
(4951, 1, 20, 'itinerary', 'itinerary', 'Destination(s) ( [[Place]] ) that make up a trip. For a trip where destination order is important use [[ItemList]] to specify that order (see examples).'),
(4952, 1, 20, 'broadcastAffiliateOf', 'broadcastAffiliateOf', 'The media network(s) whose content is broadcast on this station.'),
(4953, 1, 20, 'characterName', 'characterName', 'The name of a character played in some acting or performing role, i.e. in a PerformanceRole.'),
(4954, 1, 20, 'albumRelease', 'albumRelease', 'A release of this album.'),
(4955, 1, 20, 'releaseOf', 'releaseOf', 'The album this is a release of.'),
(4956, 1, 20, 'hasBioPolymerSequence', 'hasBioPolymerSequence', 'A symbolic representation of a BioChemEntity. For example, a nucleotide sequence of a Gene or an amino acid sequence of a Protein.'),
(4957, 1, 20, 'priceComponentType', 'priceComponentType', 'Identifies a price component (for example, a line item on an invoice), part of the total price for an offer.'),
(4958, 1, 20, 'experienceRequirements', 'experienceRequirements', 'Description of skills and experience needed for the position or Occupation.'),
(4959, 1, 20, 'healthPlanNetworkId', 'healthPlanNetworkId', 'Name or unique ID of network. (Networks are often reused across different insurance plans.)'),
(4960, 1, 20, 'relatedDrug', 'relatedDrug', 'Any other drug related to this one, for example commonly-prescribed alternatives.'),
(4961, 1, 20, 'parents', 'parents', 'A parents of the person.'),
(4962, 1, 20, 'parent', 'parent', 'A parent of this person.'),
(4963, 1, 20, 'alignmentType', 'alignmentType', 'A category of alignment between the learning resource and the framework node. Recommended values include: \'requires\', \'textComplexity\', \'readingLevel\', and \'educationalSubject\'.'),
(4964, 1, 20, 'postalCode', 'postalCode', 'The postal code. For example, 94043.'),
(4965, 1, 20, 'datePublished', 'datePublished', 'Date of first publication or broadcast. For example the date a [[CreativeWork]] was broadcast or a [[Certification]] was issued.'),
(4966, 1, 20, 'significantLink', 'significantLink', 'One of the more significant URLs on the page. Typically, these are the non-navigation links that are clicked on the most.'),
(4967, 1, 20, 'reservedTicket', 'reservedTicket', 'A ticket associated with the reservation.'),
(4968, 1, 20, 'numberOfBedrooms', 'numberOfBedrooms', 'The total integer number of bedrooms in a some [[Accommodation]], [[ApartmentComplex]] or [[FloorPlan]].'),
(4969, 1, 20, 'cvdNumVent', 'cvdNumVent', 'numvent - MECHANICAL VENTILATORS: Total number of ventilators available.'),
(4970, 1, 20, 'isFamilyFriendly', 'isFamilyFriendly', 'Indicates whether this content is family friendly.'),
(4971, 1, 20, 'recipeYield', 'recipeYield', 'The quantity produced by the recipe (for example, number of people served, number of servings, etc).'),
(4972, 1, 20, 'yield', 'yield', 'The quantity that results by performing instructions. For example, a paper airplane, 10 personalized candles.'),
(4973, 1, 20, 'fuelCapacity', 'fuelCapacity', 'The capacity of the fuel tank or in the case of electric cars, the battery. If there are multiple components for storage, this should indicate the total of all storage of the same type.\\n\\nTypical unit code(s): LTR for liters, GLL of US gallons, GLI for UK / imperial gallons, AMH for ampere-hours (for electrical vehicles).'),
(4974, 1, 20, 'bankAccountType', 'bankAccountType', 'The type of a bank account.'),
(4975, 1, 20, 'comment', 'comment', 'Comments, typically from users.'),
(4976, 1, 20, 'isPartOfBioChemEntity', 'isPartOfBioChemEntity', 'Indicates a BioChemEntity that is (in some sense) a part of this BioChemEntity. '),
(4977, 1, 20, 'hasBioChemEntityPart', 'hasBioChemEntityPart', 'Indicates a BioChemEntity that (in some sense) has this BioChemEntity as a part. '),
(4978, 1, 20, 'geoWithin', 'geoWithin', 'Represents a relationship between two geometries (or the places they represent), relating a geometry to one that contains it, i.e. it is inside (i.e. within) its interior. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(4979, 1, 20, 'encodingType', 'encodingType', 'The supported encoding type(s) for an EntryPoint request.'),
(4980, 1, 20, 'leaseLength', 'leaseLength', 'Length of the lease for some [[Accommodation]], either particular to some [[Offer]] or in some cases intrinsic to the property.'),
(4981, 1, 20, 'cargoVolume', 'cargoVolume', 'The available volume for cargo or luggage. For automobiles, this is usually the trunk volume.\\n\\nTypical unit code(s): LTR for liters, FTQ for cubic foot/feet\\n\\nNote: You can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(4982, 1, 20, 'howPerformed', 'howPerformed', 'How the procedure is performed.'),
(4983, 1, 20, 'discount', 'discount', 'Any discount applied (to an Order).'),
(4984, 1, 20, 'estimatedSalary', 'estimatedSalary', 'An estimated salary for a job posting or occupation, based on a variety of variables including, but not limited to industry, job title, and location. Estimated salaries  are often computed by outside organizations rather than the hiring organization, who may not have committed to the estimated value.'),
(4985, 1, 20, 'countryOfAssembly', 'countryOfAssembly', 'The place where the product was assembled.'),
(4986, 1, 20, 'median', 'median', 'The median value.'),
(4987, 1, 20, 'expectedPrognosis', 'expectedPrognosis', 'The likely outcome in either the short term or long term of the medical condition.'),
(4988, 1, 20, 'warrantyScope', 'warrantyScope', 'The scope of the warranty promise.'),
(4989, 1, 20, 'priceType', 'priceType', 'Defines the type of a price specified for an offered product, for example a list price, a (temporary) sale price or a manufacturer suggested retail price. If multiple prices are specified for an offer the [[priceType]] property can be used to identify the type of each such specified price. The value of priceType can be specified as a value from enumeration PriceTypeEnumeration or as a free form text string for price types that are not already predefined in PriceTypeEnumeration.'),
(4990, 1, 20, 'occupationalCredentialAwarded', 'occupationalCredentialAwarded', 'A description of the qualification, award, certificate, diploma or other occupational credential awarded as a consequence of successful completion of this course or program.'),
(4991, 1, 20, 'itemDefectReturnLabelSource', 'itemDefectReturnLabelSource', 'The method (from an enumeration) by which the customer obtains a return shipping label for a defect product.'),
(4992, 1, 20, 'costPerUnit', 'costPerUnit', 'The cost per unit of the drug.'),
(4993, 1, 20, 'broadcastServiceTier', 'broadcastServiceTier', 'The type of service required to have access to the channel (e.g. Standard or Premium).'),
(4994, 1, 20, 'dropoffTime', 'dropoffTime', 'When a rental car can be dropped off.'),
(4995, 1, 20, 'videoFormat', 'videoFormat', 'The type of screening or video broadcast used (e.g. IMAX, 3D, SD, HD, etc.).'),
(4996, 1, 20, 'suggestedAge', 'suggestedAge', 'The age or age range for the intended audience or person, for example 3-12 months for infants, 1-5 years for toddlers.'),
(4997, 1, 20, 'cutoffTime', 'cutoffTime', 'Order cutoff time allows merchants to describe the time after which they will no longer process orders received on that day. For orders processed after cutoff time, one day gets added to the delivery time estimate. This property is expected to be most typically used via the [[ShippingRateSettings]] publication pattern. The time is indicated using the ISO-8601 Time format, e.g. \"23:30:00-05:00\" would represent 6:30 pm Eastern Standard Time (EST) which is 5 hours behind Coordinated Universal Time (UTC).'),
(4998, 1, 20, 'secondaryPrevention', 'secondaryPrevention', 'A preventative therapy used to prevent reoccurrence of the medical condition after an initial episode of the condition.'),
(4999, 1, 20, 'loanMortgageMandateAmount', 'loanMortgageMandateAmount', 'Amount of mortgage mandate that can be converted into a proper mortgage at a later stage.'),
(5000, 1, 20, 'isBasedOn', 'isBasedOn', 'A resource from which this work is derived or from which it is a modification or adaptation.'),
(5001, 1, 20, 'orderDate', 'orderDate', 'Date order was placed.'),
(5002, 1, 20, 'signDetected', 'signDetected', 'A sign detected by the test.'),
(5003, 1, 20, 'scheduledPaymentDate', 'scheduledPaymentDate', 'The date the invoice is scheduled to be paid.'),
(5004, 1, 20, 'salaryCurrency', 'salaryCurrency', 'The currency (coded using [ISO 4217](http://en.wikipedia.org/wiki/ISO_4217)) used for the main salary information in this job posting or for this employee.'),
(5005, 1, 20, 'valueAddedTaxIncluded', 'valueAddedTaxIncluded', 'Specifies whether the applicable value-added tax (VAT) is included in the price specification or not.'),
(5006, 1, 20, 'episode', 'episode', 'An episode of a TV, radio or game media within a series or season.'),
(5007, 1, 20, 'serviceOperator', 'serviceOperator', 'The operating organization, if different from the provider.  This enables the representation of services that are provided by an organization, but operated by another organization like a subcontractor.'),
(5008, 1, 20, 'termsPerYear', 'termsPerYear', 'The number of times terms of study are offered per year. Semesters and quarters are common units for term. For example, if the student can only take 2 semesters for the program in one year, then termsPerYear should be 2.'),
(5009, 1, 20, 'deliveryStatus', 'deliveryStatus', 'New entry added as the package passes through each leg of its journey (from shipment to final delivery).'),
(5010, 1, 20, 'printColumn', 'printColumn', 'The number of the column in which the NewsArticle appears in the print edition.'),
(5011, 1, 20, 'jobBenefits', 'jobBenefits', 'Description of benefits associated with the job.'),
(5012, 1, 20, 'biomechnicalClass', 'biomechnicalClass', 'The biomechanical properties of the bone.'),
(5013, 1, 20, 'parentItem', 'parentItem', 'The parent of a question, answer or item in general. Typically used for Q/A discussion threads e.g. a chain of comments with the first comment being an [[Article]] or other [[CreativeWork]]. See also [[comment]] which points from something to a comment about it.'),
(5014, 1, 20, 'isrcCode', 'isrcCode', 'The International Standard Recording Code for the recording.'),
(5015, 1, 20, 'jobLocationType', 'jobLocationType', 'A description of the job location (e.g. TELECOMMUTE for telecommute jobs).'),
(5016, 1, 20, 'firstAppearance', 'firstAppearance', 'Indicates the first known occurrence of a [[Claim]] in some [[CreativeWork]].'),
(5017, 1, 20, 'faxNumber', 'faxNumber', 'The fax number.'),
(5018, 1, 20, 'xpath', 'xpath', 'An XPath, e.g. of a [[SpeakableSpecification]] or [[WebPageElement]]. In the latter case, multiple matches within a page can constitute a single conceptual \"Web page element\".'),
(5019, 1, 20, 'cvdCollectionDate', 'cvdCollectionDate', 'collectiondate - Date for which patient counts are reported.'),
(5020, 1, 20, 'artMedium', 'artMedium', 'The material used. (E.g. Oil, Watercolour, Acrylic, Linoprint, Marble, Cyanotype, Digital, Lithograph, DryPoint, Intaglio, Pastel, Woodcut, Pencil, Mixed Media, etc.)'),
(5021, 1, 20, 'agent', 'agent', 'The direct performer or driver of the action (animate or inanimate). E.g. *John* wrote a book.'),
(5022, 1, 20, 'paymentMethodId', 'paymentMethodId', 'An identifier for the method of payment used (e.g. the last 4 digits of the credit card).'),
(5023, 1, 20, 'mechanismOfAction', 'mechanismOfAction', 'The specific biochemical interaction through which this drug or supplement produces its pharmacological effect.'),
(5024, 1, 20, 'byArtist', 'byArtist', 'The artist that performed this album or recording.'),
(5025, 1, 20, 'bed', 'bed', 'The type of bed or beds included in the accommodation. For the single case of just one bed of a certain type, you use bed directly with a text.\n      If you want to indicate the quantity of a certain kind of bed, use an instance of BedDetails. For more detailed information, use the amenityFeature property.'),
(5026, 1, 20, 'returnPolicyCountry', 'returnPolicyCountry', 'The country where the product has to be sent to for returns, for example \"Ireland\" using the [[name]] property of [[Country]]. You can also provide the two-letter [ISO 3166-1 alpha-2 country code](http://en.wikipedia.org/wiki/ISO_3166-1). Note that this can be different from the country where the product was originally shipped from or sent to.'),
(5027, 1, 20, 'ratingCount', 'ratingCount', 'The count of total number of ratings.'),
(5028, 1, 20, 'resultComment', 'resultComment', 'A sub property of result. The Comment created or sent as a result of this action.'),
(5029, 1, 20, 'stage', 'stage', 'The stage of the condition, if applicable.'),
(5030, 1, 20, 'expectsAcceptanceOf', 'expectsAcceptanceOf', 'An Offer which must be accepted before the user can perform the Action. For example, the user may need to buy a movie before being able to watch it.'),
(5031, 1, 20, 'hasMenuItem', 'hasMenuItem', 'A food or drink item contained in a menu or menu section.'),
(5032, 1, 20, 'deathPlace', 'deathPlace', 'The place where the person died.'),
(5033, 1, 20, 'stepValue', 'stepValue', 'The stepValue attribute indicates the granularity that is expected (and required) of the value in a PropertyValueSpecification.'),
(5034, 1, 20, 'sourceOrganization', 'sourceOrganization', 'The Organization on whose behalf the creator was working.'),
(5035, 1, 20, 'coursePrerequisites', 'coursePrerequisites', 'Requirements for taking the Course. May be completion of another [[Course]] or a textual description like \"permission of instructor\". Requirements may be a pre-requisite competency, referenced using [[AlignmentObject]].'),
(5036, 1, 20, 'email', 'email', 'Email address.'),
(5037, 1, 20, 'representativeOfPage', 'representativeOfPage', 'Indicates whether this image is representative of the content of the page.'),
(5038, 1, 20, 'geoRadius', 'geoRadius', 'Indicates the approximate radius of a GeoCircle (metres unless indicated otherwise via Distance notation).'),
(5039, 1, 20, 'gameTip', 'gameTip', 'Links to tips, tactics, etc.'),
(5040, 1, 20, 'hasCourseInstance', 'hasCourseInstance', 'An offering of the course at a specific time and place or through specific media or mode of study or to a specific section of students.'),
(5041, 1, 20, 'isInvolvedInBiologicalProcess', 'isInvolvedInBiologicalProcess', 'Biological process this BioChemEntity is involved in; please use PropertyValue if you want to include any evidence.'),
(5042, 1, 20, 'naics', 'naics', 'The North American Industry Classification System (NAICS) code for a particular organization or business person.'),
(5043, 1, 20, 'isBasedOnUrl', 'isBasedOnUrl', 'A resource that was used in the creation of this resource. This term can be repeated for multiple sources. For example, http://example.com/great-multiplication-intro.html.'),
(5044, 1, 20, 'printSection', 'printSection', 'If this NewsArticle appears in print, this field indicates the print section in which the article appeared.'),
(5045, 1, 20, 'broadcastDisplayName', 'broadcastDisplayName', 'The name displayed in the channel guide. For many US affiliates, it is the network name.'),
(5046, 1, 20, 'event', 'event', 'Upcoming or past event associated with this place, organization, or action.'),
(5047, 1, 20, 'subEvents', 'subEvents', 'Events that are a part of this event. For example, a conference event includes many presentations, each subEvents of the conference.'),
(5048, 1, 20, 'muscleAction', 'muscleAction', 'The movement the muscle generates.'),
(5049, 1, 20, 'mathExpression', 'mathExpression', 'A mathematical expression (e.g. \'x^2-3x=0\') that may be solved for a specific variable, simplified, or transformed. This can take many formats, e.g. LaTeX, Ascii-Math, or math as you would write with a keyboard.'),
(5050, 1, 20, 'legislationJurisdiction', 'legislationJurisdiction', 'The jurisdiction from which the legislation originates.'),
(5051, 1, 20, 'spatialCoverage', 'spatialCoverage', 'The spatialCoverage of a CreativeWork indicates the place(s) which are the focus of the content. It is a subproperty of\n      contentLocation intended primarily for more technical and detailed materials. For example with a Dataset, it indicates\n      areas that the dataset describes: a dataset of New York weather would have spatialCoverage which was the place: the state of New York.'),
(5052, 1, 20, 'jurisdiction', 'jurisdiction', 'Indicates a legal jurisdiction, e.g. of some legislation, or where some government service is based.'),
(5053, 1, 20, 'itemListOrder', 'itemListOrder', 'Type of ordering (e.g. Ascending, Descending, Unordered).'),
(5054, 1, 20, 'events', 'events', 'Upcoming or past events associated with this place or organization.'),
(5055, 1, 20, 'numConstraints', 'numConstraints', 'Indicates the number of constraints property values defined for a particular [[ConstraintNode]] such as [[StatisticalVariable]]. This helps applications understand if they have access to a sufficiently complete description of a [[StatisticalVariable]] or other construct that is defined using properties on template-style nodes.'),
(5056, 1, 20, 'program', 'program', 'The [MemberProgram](http://schema.org/MemberProgram) associated with a [ProgramMembership](http://schema.org/ProgramMembership).'),
(5057, 1, 20, 'thumbnail', 'thumbnail', 'Thumbnail image for an image or video.'),
(5058, 1, 20, 'structuralClass', 'structuralClass', 'The name given to how bone physically connects to each other.'),
(5059, 1, 20, 'dateSent', 'dateSent', 'The date/time at which the message was sent.'),
(5060, 1, 20, 'relevantOccupation', 'relevantOccupation', 'The Occupation for the JobPosting.'),
(5061, 1, 20, 'claimReviewed', 'claimReviewed', 'A short summary of the specific claims reviewed in a ClaimReview.'),
(5062, 1, 20, 'circle', 'circle', 'A circle is the circular region of a specified radius centered at a specified latitude and longitude. A circle is expressed as a pair followed by a radius in meters.'),
(5063, 1, 20, 'unitCode', 'unitCode', 'The unit of measurement given using the UN/CEFACT Common Code (3 characters) or a URL. Other codes than the UN/CEFACT Common Code may be used with a prefix followed by a colon.'),
(5064, 1, 20, 'ownedFrom', 'ownedFrom', 'The date and time of obtaining the product.'),
(5065, 1, 20, 'screenCount', 'screenCount', 'The number of screens in the movie theater.'),
(5066, 1, 20, 'bioChemInteraction', 'bioChemInteraction', 'A BioChemEntity that is known to interact with this item.'),
(5067, 1, 20, 'homeTeam', 'homeTeam', 'The home team in a sports event.'),
(5068, 1, 20, 'album', 'album', 'A music album.'),
(5069, 1, 20, 'numberOfPlayers', 'numberOfPlayers', 'Indicate how many people can play this game (minimum, maximum, or range).'),
(5070, 1, 20, 'latitude', 'latitude', 'The latitude of a location. For example ```37.42242``` ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)).'),
(5071, 1, 20, 'bioChemSimilarity', 'bioChemSimilarity', 'A similar BioChemEntity, e.g., obtained by fingerprint similarity algorithms.'),
(5072, 1, 20, 'permittedUsage', 'permittedUsage', 'Indications regarding the permitted usage of the accommodation.'),
(5073, 1, 20, 'serviceUrl', 'serviceUrl', 'The website to access the service.'),
(5074, 1, 20, 'measuredProperty', 'measuredProperty', 'The measuredProperty of an [[Observation]], typically via its [[StatisticalVariable]]. There are various kinds of applicable [[Property]]: a schema.org property, a property from other RDF-compatible systems, e.g. W3C RDF Data Cube, Data Commons, Wikidata, or schema.org extensions such as [GS1\'s](https://www.gs1.org/voc/?show=properties).'),
(5075, 1, 20, 'suggestedGender', 'suggestedGender', 'The suggested gender of the intended person or audience, for example \"male\", \"female\", or \"unisex\".'),
(5076, 1, 20, 'video', 'video', 'An embedded video object.'),
(5077, 1, 20, 'keywords', 'keywords', 'Keywords or tags used to describe some item. Multiple textual entries in a keywords list are typically delimited by commas, or by repeating the property.'),
(5078, 1, 20, 'creditText', 'creditText', 'Text that can be used to credit person(s) and/or organization(s) associated with a published Creative Work.'),
(5079, 1, 20, 'typicalTest', 'typicalTest', 'A medical test typically performed given this condition.'),
(5080, 1, 20, 'liveBlogUpdate', 'liveBlogUpdate', 'An update to the LiveBlog.'),
(5081, 1, 20, 'orderedItem', 'orderedItem', 'The item ordered.'),
(5082, 1, 20, 'colorist', 'colorist', 'The individual who adds color to inked drawings.'),
(5083, 1, 20, 'courseWorkload', 'courseWorkload', 'The amount of work expected of students taking the course, often provided as a figure per week or per month, and may be broken down by type. For example, \"2 hours of lectures, 1 hour of lab work and 3 hours of independent study per week\".'),
(5084, 1, 20, 'size', 'size', 'A standardized size of a product or creative work, specified either through a simple textual string (for example \'XL\', \'32Wx34L\'), a  QuantitativeValue with a unitCode, or a comprehensive and structured [[SizeSpecification]]; in other cases, the [[width]], [[height]], [[depth]] and [[weight]] properties may be more applicable. '),
(5085, 1, 20, 'accountMinimumInflow', 'accountMinimumInflow', 'A minimum amount that has to be paid in every month.'),
(5086, 1, 20, 'children', 'children', 'A child of the person.'),
(5087, 1, 20, 'paymentDue', 'paymentDue', 'The date that payment is due.'),
(5088, 1, 20, 'legislationApplies', 'legislationApplies', 'Indicates that this legislation (or part of a legislation) somehow transfers another legislation in a different legislative context. This is an informative link, and it has no legal value. For legally-binding links of transposition, use the <a href=\"/legislationTransposes\">legislationTransposes</a> property. For example an informative consolidated law of a European Union\'s member state \"applies\" the consolidated version of the European Directive implemented in it.'),
(5089, 1, 20, 'memberOf', 'memberOf', 'An Organization (or ProgramMembership) to which this Person or Organization belongs.'),
(5090, 1, 20, 'member', 'member', 'A member of an Organization or a ProgramMembership. Organizations can be members of organizations; ProgramMembership is typically for individuals.'),
(5091, 1, 20, 'error', 'error', 'For failed actions, more information on the cause of the failure.'),
(5092, 1, 20, 'paymentAccepted', 'paymentAccepted', 'Cash, Credit Card, Cryptocurrency, Local Exchange Tradings System, etc.'),
(5093, 1, 20, 'license', 'license', 'A license document that applies to this content, typically indicated by URL.'),
(5094, 1, 20, 'artEdition', 'artEdition', 'The number of copies when multiple copies of a piece of artwork are produced - e.g. for a limited edition of 20 prints, \'artEdition\' refers to the total number of copies (in this example \"20\").'),
(5095, 1, 20, 'totalJobOpenings', 'totalJobOpenings', 'The number of positions open for this job posting. Use a positive integer. Do not use if the number of positions is unclear or not known.'),
(5096, 1, 20, 'validFor', 'validFor', 'The duration of validity of a permit or similar thing.'),
(5097, 1, 20, 'vehicleConfiguration', 'vehicleConfiguration', 'A short text indicating the configuration of the vehicle, e.g. \'5dr hatchback ST 2.5 MT 225 hp\' or \'limited edition\'.'),
(5098, 1, 20, 'childMinAge', 'childMinAge', 'Minimal age of the child.'),
(5099, 1, 20, 'floorLevel', 'floorLevel', 'The floor level for an [[Accommodation]] in a multi-storey building. Since counting\n  systems [vary internationally](https://en.wikipedia.org/wiki/Storey#Consecutive_number_floor_designations), the local system should be used where possible.'),
(5100, 1, 20, 'applicationCategory', 'applicationCategory', 'Type of software application, e.g. \'Game, Multimedia\'.'),
(5101, 1, 20, 'pickupLocation', 'pickupLocation', 'Where a taxi will pick up a passenger or a rental car can be picked up.'),
(5102, 1, 20, 'smokingAllowed', 'smokingAllowed', 'Indicates whether it is allowed to smoke in the place, e.g. in the restaurant, hotel or hotel room.'),
(5103, 1, 20, 'numAdults', 'numAdults', 'The number of adults staying in the unit.'),
(5104, 1, 20, 'isAccessibleForFree', 'isAccessibleForFree', 'A flag to signal that the item, event, or place is accessible for free.'),
(5105, 1, 20, 'carrierRequirements', 'carrierRequirements', 'Specifies specific carrier(s) requirements for the application (e.g. an application may only work on a specific carrier network).'),
(5106, 1, 20, 'vehicleInteriorColor', 'vehicleInteriorColor', 'The color or color combination of the interior of the vehicle.'),
(5107, 1, 20, 'shippingDestination', 'shippingDestination', 'indicates (possibly multiple) shipping destinations. These can be defined in several ways, e.g. postalCode ranges.'),
(5108, 1, 20, 'amount', 'amount', 'The amount of money.'),
(5109, 1, 20, 'acquireLicensePage', 'acquireLicensePage', 'Indicates a page documenting how licenses can be purchased or otherwise acquired, for the current item.'),
(5110, 1, 20, 'usageInfo', 'usageInfo', 'The schema.org [[usageInfo]] property indicates further information about a [[CreativeWork]]. This property is applicable both to works that are freely available and to those that require payment or other transactions. It can reference additional information, e.g. community expectations on preferred linking and citation conventions, as well as purchasing details. For something that can be commercially licensed, usageInfo can provide detailed, resource-specific information about licensing options.\n\nThis property can be used alongside the license property which indicates license(s) applicable to some piece of content. The usageInfo property can provide information about other licensing options, e.g. acquiring commercial usage rights for an image that is also available under non-commercial creative commons licenses.'),
(5111, 1, 20, 'healthPlanCopay', 'healthPlanCopay', 'The copay amount.'),
(5112, 1, 20, 'priceComponent', 'priceComponent', 'This property links to all [[UnitPriceSpecification]] nodes that apply in parallel for the [[CompoundPriceSpecification]] node.'),
(5113, 1, 20, 'eligibleQuantity', 'eligibleQuantity', 'The interval and unit of measurement of ordering quantities for which the offer or price specification is valid. This allows e.g. specifying that a certain freight charge is valid only for a certain quantity.'),
(5114, 1, 20, 'eligibleCustomerType', 'eligibleCustomerType', 'The type(s) of customers for which the given offer is valid.'),
(5115, 1, 20, 'masthead', 'masthead', 'For a [[NewsMediaOrganization]], a link to the masthead page or a page listing top editorial management.'),
(5116, 1, 20, 'downvoteCount', 'downvoteCount', 'The number of downvotes this question, answer or comment has received from the community.'),
(5117, 1, 20, 'starRating', 'starRating', 'An official rating for a lodging business or food establishment, e.g. from national associations or standards bodies. Use the author property to indicate the rating organization, e.g. as an Organization with name such as (e.g. HOTREC, DEHOGA, WHR, or Hotelstars).'),
(5118, 1, 20, 'musicReleaseFormat', 'musicReleaseFormat', 'Format of this release (the type of recording media used, i.e. compact disc, digital media, LP, etc.).'),
(5119, 1, 20, 'iswcCode', 'iswcCode', 'The International Standard Musical Work Code for the composition.'),
(5120, 1, 20, 'numberOfBathroomsTotal', 'numberOfBathroomsTotal', 'The total integer number of bathrooms in some [[Accommodation]], following real estate conventions as [documented in RESO](https://ddwiki.reso.org/display/DDW17/BathroomsTotalInteger+Field): \"The simple sum of the number of bathrooms. For example for a property with two Full Bathrooms and one Half Bathroom, the Bathrooms Total Integer will be 3.\". See also [[numberOfRooms]].'),
(5121, 1, 20, 'salaryUponCompletion', 'salaryUponCompletion', 'The expected salary upon completing the training.'),
(5122, 1, 20, 'discussionUrl', 'discussionUrl', 'A link to the page containing the comments of the CreativeWork.'),
(5123, 1, 20, 'landlord', 'landlord', 'A sub property of participant. The owner of the real estate property.'),
(5124, 1, 20, 'engineDisplacement', 'engineDisplacement', 'The volume swept by all of the pistons inside the cylinders of an internal combustion engine in a single movement. \\n\\nTypical unit code(s): CMQ for cubic centimeter, LTR for liters, INQ for cubic inches\\n* Note 1: You can link to information about how the given value has been determined using the [[valueReference]] property.\\n* Note 2: You can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(5125, 1, 20, 'functionalClass', 'functionalClass', 'The degree of mobility the joint allows.'),
(5126, 1, 20, 'lastReviewed', 'lastReviewed', 'Date on which the content on this web page was last reviewed for accuracy and/or completeness.'),
(5127, 1, 20, 'awayTeam', 'awayTeam', 'The away team in a sports event.'),
(5128, 1, 20, 'previousStartDate', 'previousStartDate', 'Used in conjunction with eventStatus for rescheduled or cancelled events. This property contains the previously scheduled start date. For rescheduled events, the startDate property should be used for the newly scheduled start date. In the (rare) case of an event that has been postponed and rescheduled multiple times, this field may be repeated.'),
(5129, 1, 20, 'expertConsiderations', 'expertConsiderations', 'Medical expert advice related to the plan.'),
(5130, 1, 20, 'taxID', 'taxID', 'The Tax / Fiscal ID of the organization or person, e.g. the TIN in the US or the CIF/NIF in Spain.'),
(5131, 1, 20, 'vehicleModelDate', 'vehicleModelDate', 'The release date of a vehicle model (often used to differentiate versions of the same make and model).'),
(5132, 1, 20, 'guidelineDate', 'guidelineDate', 'Date on which this guideline\'s recommendation was made.'),
(5133, 1, 20, 'earlyPrepaymentPenalty', 'earlyPrepaymentPenalty', 'The amount to be paid as a penalty in the event of early payment of the loan.'),
(5134, 1, 20, 'menuAddOn', 'menuAddOn', 'Additional menu item(s) such as a side dish of salad or side order of fries that can be added to this menu item. Additionally it can be a menu section containing allowed add-on menu items for this menu item.'),
(5135, 1, 20, 'cvdNumICUBedsOcc', 'cvdNumICUBedsOcc', 'numicubedsocc - ICU BED OCCUPANCY: Total number of staffed inpatient ICU beds that are occupied.'),
(5136, 1, 20, 'backstory', 'backstory', 'For an [[Article]], typically a [[NewsArticle]], the backstory property provides a textual summary giving a brief explanation of why and how an article was created. In a journalistic setting this could include information about reporting process, methods, interviews, data sources, etc.'),
(5137, 1, 20, 'mileageFromOdometer', 'mileageFromOdometer', 'The total distance travelled by the particular vehicle since its initial production, as read from its odometer.\\n\\nTypical unit code(s): KMT for kilometers, SMI for statute miles.'),
(5138, 1, 20, 'lender', 'lender', 'A sub property of participant. The person that lends the object being borrowed.'),
(5139, 1, 20, 'editEIDR', 'editEIDR', 'An [EIDR](https://eidr.org/) (Entertainment Identifier Registry) [[identifier]] representing a specific edit / edition for a work of film or television.\n\nFor example, the motion picture known as \"Ghostbusters\" whose [[titleEIDR]] is \"10.5240/7EC7-228A-510A-053E-CBB8-J\" has several edits, e.g. \"10.5240/1F2A-E1C5-680A-14C6-E76B-I\" and \"10.5240/8A35-3BEE-6497-5D12-9E4F-3\".\n\nSince schema.org types like [[Movie]] and [[TVEpisode]] can be used for both works and their multiple expressions, it is possible to use [[titleEIDR]] alone (for a general description), or alongside [[editEIDR]] for a more edit-specific description.\n'),
(5140, 1, 20, 'knows', 'knows', 'The most generic bi-directional social/work relation.'),
(5141, 1, 20, 'elevation', 'elevation', 'The elevation of a location ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)). Values may be of the form \'NUMBER UNIT\\_OF\\_MEASUREMENT\' (e.g., \'1,000 m\', \'3,200 ft\') while numbers alone should be assumed to be a value in meters.'),
(5142, 1, 20, 'contentLocation', 'contentLocation', 'The location depicted or described in the content. For example, the location in a photograph or painting.'),
(5143, 1, 20, 'safetyConsideration', 'safetyConsideration', 'Any potential safety concern associated with the supplement. May include interactions with other drugs and foods, pregnancy, breastfeeding, known adverse reactions, and documented efficacy of the supplement.'),
(5144, 1, 20, 'diseasePreventionInfo', 'diseasePreventionInfo', 'Information about disease prevention.'),
(5145, 1, 20, 'logo', 'logo', 'An associated logo.'),
(5146, 1, 20, 'image', 'image', 'An image of the item. This can be a [[URL]] or a fully described [[ImageObject]].'),
(5147, 1, 20, 'option', 'option', 'A sub property of object. The options subject to this action.'),
(5148, 1, 20, 'actionOption', 'actionOption', 'A sub property of object. The options subject to this action.'),
(5149, 1, 20, 'object', 'object', 'The object upon which the action is carried out, whose state is kept intact or changed. Also known as the semantic roles patient, affected or undergoer (which change their state) or theme (which doesn\'t). E.g. John read *a book*.'),
(5150, 1, 20, 'endorsers', 'endorsers', 'People or organizations that endorse the plan.'),
(5151, 1, 20, 'programmingLanguage', 'programmingLanguage', 'The computer programming language.'),
(5152, 1, 20, 'inChIKey', 'inChIKey', 'InChIKey is a hashed version of the full InChI (using the SHA-256 algorithm).'),
(5153, 1, 20, 'geoCovers', 'geoCovers', 'Represents a relationship between two geometries (or the places they represent), relating a covering geometry to a covered geometry. \"Every point of b is a point of (the interior or boundary of) a\". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(5154, 1, 20, 'holdingArchive', 'holdingArchive', '[[ArchiveOrganization]] that holds, keeps or maintains the [[ArchiveComponent]].'),
(5155, 1, 20, 'archiveHeld', 'archiveHeld', 'Collection, [fonds](https://en.wikipedia.org/wiki/Fonds), or item held, kept or maintained by an [[ArchiveOrganization]].'),
(5156, 1, 20, 'sdPublisher', 'sdPublisher', 'Indicates the party responsible for generating and publishing the current structured data markup, typically in cases where the structured data is derived automatically from existing published content but published on a different site. For example, student projects and open data initiatives often re-publish existing content with more explicitly structured metadata. The\n[[sdPublisher]] property helps make such practices more explicit.'),
(5157, 1, 20, 'warranty', 'warranty', 'The warranty promise(s) included in the offer.'),
(5158, 1, 20, 'artist', 'artist', 'The primary artist for a work\n    	in a medium other than pencils or digital line art--for example, if the\n    	primary artwork is done in watercolors or digital paints.'),
(5159, 1, 20, 'asin', 'asin', 'An Amazon Standard Identification Number (ASIN) is a 10-character alphanumeric unique identifier assigned by Amazon.com and its partners for product identification within the Amazon organization (summary from [Wikipedia](https://en.wikipedia.org/wiki/Amazon_Standard_Identification_Number)\'s article).\n\nNote also that this is a definition for how to include ASINs in Schema.org data, and not a definition of ASINs in general - see documentation from Amazon for authoritative details.\nASINs are most commonly encoded as text strings, but the [asin] property supports URL/URI as potential values too.'),
(5160, 1, 20, 'isProprietary', 'isProprietary', 'True if this item\'s name is a proprietary/brand name (vs. generic name).'),
(5161, 1, 20, 'timeToComplete', 'timeToComplete', 'The expected length of time to complete the program if attending full-time.'),
(5162, 1, 20, 'statType', 'statType', 'Indicates the kind of statistic represented by a [[StatisticalVariable]], e.g. mean, count etc. The value of statType is a property, either from within Schema.org (e.g. [[median]], [[marginOfError]], [[maxValue]], [[minValue]]) or from other compatible (e.g. RDF) systems such as DataCommons.org or Wikidata.org. '),
(5163, 1, 20, 'tocEntry', 'tocEntry', 'Indicates a [[HyperTocEntry]] in a [[HyperToc]].'),
(5164, 1, 20, 'dateCreated', 'dateCreated', 'The date on which the CreativeWork was created or the item was added to a DataFeed.'),
(5165, 1, 20, 'checkoutPageURLTemplate', 'checkoutPageURLTemplate', 'A URL template (RFC 6570) for a checkout page for an offer. This approach allows merchants to specify a URL for online checkout of the offered product, by interpolating parameters such as the logged in user ID, product ID, quantity, discount code etc. Parameter naming and standardization are not specified here.'),
(5166, 1, 20, 'gtin13', 'gtin13', 'The GTIN-13 code of the product, or the product to which the offer refers. This is equivalent to 13-digit ISBN codes and EAN UCC-13. Former 12-digit UPC codes can be converted into a GTIN-13 code by simply adding a preceding zero. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(5167, 1, 20, 'gtin', 'gtin', 'A Global Trade Item Number ([GTIN](https://www.gs1.org/standards/id-keys/gtin)). GTINs identify trade items, including products and services, using numeric identification codes.\n\nA correct [[gtin]] value should be a valid GTIN, which means that it should be an all-numeric string of either 8, 12, 13 or 14 digits, or a \"GS1 Digital Link\" URL based on such a string. The numeric component should also have a [valid GS1 check digit](https://www.gs1.org/services/check-digit-calculator) and meet the other rules for valid GTINs. See also [GS1\'s GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) and [Wikipedia](https://en.wikipedia.org/wiki/Global_Trade_Item_Number) for more details. Left-padding of the gtin values is not required or encouraged. The [[gtin]] property generalizes the earlier [[gtin8]], [[gtin12]], [[gtin13]], and [[gtin14]] properties.\n\nThe GS1 [digital link specifications](https://www.gs1.org/standards/Digital-Link/) expresses GTINs as URLs (URIs, IRIs, etc.).\nDigital Links should be populated into the [[hasGS1DigitalLink]] attribute.\n\nNote also that this is a definition for how to include GTINs in Schema.org data, and not a definition of GTINs in general - see the GS1 documentation for authoritative details.'),
(5168, 1, 20, 'significance', 'significance', 'The significance associated with the superficial anatomy; as an example, how characteristics of the superficial anatomy can suggest underlying medical conditions or courses of treatment.'),
(5169, 1, 20, 'medicalAudience', 'medicalAudience', 'Medical audience for page.'),
(5170, 1, 20, 'drug', 'drug', 'Specifying a drug or medicine used in a medication procedure.'),
(5171, 1, 20, 'skills', 'skills', 'A statement of knowledge, skill, ability, task or any other assertion expressing a competency that is either claimed by a person, an organization or desired or required to fulfill a role or to work in an occupation.'),
(5172, 1, 20, 'proficiencyLevel', 'proficiencyLevel', 'Proficiency needed for this content; expected values: \'Beginner\', \'Expert\'.'),
(5173, 1, 20, 'totalTime', 'totalTime', 'The total time required to perform instructions or a direction (including time to prepare the supplies), in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(5174, 1, 20, 'yearsInOperation', 'yearsInOperation', 'The age of the business.'),
(5175, 1, 20, 'accommodationFloorPlan', 'accommodationFloorPlan', 'A floorplan of some [[Accommodation]].'),
(5176, 1, 20, 'hasMenuSection', 'hasMenuSection', 'A subgrouping of the menu (by dishes, course, serving time period, etc.).'),
(5177, 1, 20, 'programMembershipUsed', 'programMembershipUsed', 'Any membership in a frequent flyer, hotel loyalty program, etc. being applied to the reservation.'),
(5178, 1, 20, 'supersededBy', 'supersededBy', 'Relates a term (i.e. a property, class or enumeration) to one that supersedes it.'),
(5179, 1, 20, 'interactingDrug', 'interactingDrug', 'Another drug that is known to interact with this drug in a way that impacts the effect of this drug or causes a risk to the patient. Note: disease interactions are typically captured as contraindications.'),
(5180, 1, 20, 'userInteractionCount', 'userInteractionCount', 'The number of interactions for the CreativeWork using the WebSite or SoftwareApplication.'),
(5181, 1, 20, 'encodings', 'encodings', 'A media object that encodes this CreativeWork.'),
(5182, 1, 20, 'steps', 'steps', 'A single step item (as HowToStep, text, document, video, etc.) or a HowToSection (originally misnamed \'steps\'; \'step\' is preferred).'),
(5183, 1, 20, 'step', 'step', 'A single step item (as HowToStep, text, document, video, etc.) or a HowToSection.'),
(5184, 1, 20, 'birthDate', 'birthDate', 'Date of birth.'),
(5185, 1, 20, 'typeOfBed', 'typeOfBed', 'The type of bed to which the BedDetail refers, i.e. the type of bed available in the quantity indicated by quantity.'),
(5186, 1, 20, 'roofLoad', 'roofLoad', 'The permitted total weight of cargo and installations (e.g. a roof rack) on top of the vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]]\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(5187, 1, 20, 'issuedThrough', 'issuedThrough', 'The service through which the permit was granted.'),
(5188, 1, 20, 'arrivalTime', 'arrivalTime', 'The expected arrival time.'),
(5189, 1, 20, 'interactionCount', 'interactionCount', 'This property is deprecated, alongside the UserInteraction types on which it depended.'),
(5190, 1, 20, 'clincalPharmacology', 'clincalPharmacology', 'Description of the absorption and elimination of drugs, including their concentration (pharmacokinetics, pK) and biological effects (pharmacodynamics, pD).'),
(5191, 1, 20, 'applicantLocationRequirements', 'applicantLocationRequirements', 'The location(s) applicants can apply from. This is usually used for telecommuting jobs where the applicant does not need to be in a physical office. Note: This should not be used for citizenship or work visa requirements.'),
(5192, 1, 20, 'hasAdultConsideration', 'hasAdultConsideration', 'Used to tag an item to be intended or suitable for consumption or use by adults only.'),
(5193, 1, 20, 'partOfOrder', 'partOfOrder', 'The overall order the items in this delivery were included in.'),
(5194, 1, 20, 'longitude', 'longitude', 'The longitude of a location. For example ```-122.08585``` ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)).'),
(5195, 1, 20, 'ingredients', 'ingredients', 'A single ingredient used in the recipe, e.g. sugar, flour or garlic.'),
(5196, 1, 20, 'recipeIngredient', 'recipeIngredient', 'A single ingredient used in the recipe, e.g. sugar, flour or garlic.'),
(5197, 1, 20, 'supply', 'supply', 'A sub-property of instrument. A supply consumed when performing instructions or a direction.'),
(5198, 1, 20, 'affiliation', 'affiliation', 'An organization that this person is affiliated with. For example, a school/university, a club, or a team.'),
(5199, 1, 20, 'constraintProperty', 'constraintProperty', 'Indicates a property used as a constraint. For example, in the definition of a [[StatisticalVariable]]. The value is a property, either from within Schema.org or from other compatible (e.g. RDF) systems such as DataCommons.org or Wikidata.org. '),
(5200, 1, 20, 'countriesNotSupported', 'countriesNotSupported', 'Countries for which the application is not supported. You can also provide the two-letter ISO 3166-1 alpha-2 country code.'),
(5201, 1, 20, 'foodEvent', 'foodEvent', 'A sub property of location. The specific food event where the action occurred.'),
(5202, 1, 20, 'ownedThrough', 'ownedThrough', 'The date and time of giving up ownership on the product.'),
(5203, 1, 20, 'directApply', 'directApply', 'Indicates whether an [[url]] that is associated with a [[JobPosting]] enables direct application for the job, via the posting website. A job posting is considered to have directApply of [[True]] if an application process for the specified job can be directly initiated via the url(s) given (noting that e.g. multiple internet domains might nevertheless be involved at an implementation level). A value of [[False]] is appropriate if there is no clear path to applying directly online for the specified job, navigating directly from the JobPosting url(s) supplied.'),
(5204, 1, 20, 'areaServed', 'areaServed', 'The geographic area where a service or offered item is provided.'),
(5205, 1, 20, 'positiveNotes', 'positiveNotes', 'Provides positive considerations regarding something, for example product highlights or (alongside [[negativeNotes]]) pro/con lists for reviews.\n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described.\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most positive is at the beginning of the list).'),
(5206, 1, 20, 'gameAvailabilityType', 'gameAvailabilityType', 'Indicates the availability type of the game content associated with this action, such as whether it is a full version or a demo.'),
(5207, 1, 20, 'healthPlanCoinsuranceRate', 'healthPlanCoinsuranceRate', 'The rate of coinsurance expressed as a number between 0.0 and 1.0.'),
(5208, 1, 20, 'includedComposition', 'includedComposition', 'Smaller compositions included in this work (e.g. a movement in a symphony).'),
(5209, 1, 20, 'discountCurrency', 'discountCurrency', 'The currency of the discount.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(5210, 1, 20, 'loanPaymentAmount', 'loanPaymentAmount', 'The amount of money to pay in a single payment.'),
(5211, 1, 20, 'cvdNumBedsOcc', 'cvdNumBedsOcc', 'numbedsocc - HOSPITAL INPATIENT BED OCCUPANCY: Total number of staffed inpatient beds that are occupied.'),
(5212, 1, 20, 'relatedTo', 'relatedTo', 'The most generic familial relation.'),
(5213, 1, 20, 'trackingNumber', 'trackingNumber', 'Shipper tracking number.'),
(5214, 1, 20, 'sportsActivityLocation', 'sportsActivityLocation', 'A sub property of location. The sports activity location where this action occurred.'),
(5215, 1, 20, 'itemDefectReturnShippingFeesAmount', 'itemDefectReturnShippingFeesAmount', 'Amount of shipping costs for defect product returns. Applicable when property [[itemDefectReturnFees]] equals [[ReturnShippingFees]].'),
(5216, 1, 20, 'returnLabelSource', 'returnLabelSource', 'The method (from an enumeration) by which the customer obtains a return shipping label for a product returned for any reason.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(5217, 1, 20, 'healthPlanDrugTier', 'healthPlanDrugTier', 'The tier(s) of drugs offered by this formulary or insurance plan.'),
(5218, 1, 20, 'affectedBy', 'affectedBy', 'Drugs that affect the test\'s results.'),
(5219, 1, 20, 'codingSystem', 'codingSystem', 'The coding system, e.g. \'ICD-10\'.'),
(5220, 1, 20, 'stupidProperty', 'stupidProperty', 'This is a StupidProperty! - for testing only.'),
(5221, 1, 20, 'jobTitle', 'jobTitle', 'The job title of the person (for example, Financial Manager).'),
(5222, 1, 20, 'relatedTherapy', 'relatedTherapy', 'A medical therapy related to this anatomy.'),
(5223, 1, 20, 'isEncodedByBioChemEntity', 'isEncodedByBioChemEntity', 'Another BioChemEntity encoding by this one.'),
(5224, 1, 20, 'encodesBioChemEntity', 'encodesBioChemEntity', 'Another BioChemEntity encoded by this one. '),
(5225, 1, 20, 'appearance', 'appearance', 'Indicates an occurrence of a [[Claim]] in some [[CreativeWork]].'),
(5226, 1, 20, 'contactOption', 'contactOption', 'An option available on this contact point (e.g. a toll-free number or support for hearing-impaired callers).'),
(5227, 1, 20, 'byMonthWeek', 'byMonthWeek', 'Defines the week(s) of the month on which a recurring Event takes place. Specified as an Integer between 1-5. For clarity, byMonthWeek is best used in conjunction with byDay to indicate concepts like the first and third Mondays of a month.'),
(5228, 1, 20, 'line', 'line', 'A line is a point-to-point path consisting of two or more points. A line is expressed as a series of two or more point objects separated by space.'),
(5229, 1, 20, 'hasDriveThroughService', 'hasDriveThroughService', 'Indicates whether some facility (e.g. [[FoodEstablishment]], [[CovidTestingFacility]]) offers a service that can be used by driving through in a car. In the case of [[CovidTestingFacility]] such facilities could potentially help with social distancing from other potentially-infected users.'),
(5230, 1, 20, 'predecessorOf', 'predecessorOf', 'A pointer from a previous, often discontinued variant of the product to its newer variant.'),
(5231, 1, 20, 'layoutImage', 'layoutImage', 'A schematic image showing the floorplan layout.'),
(5232, 1, 20, 'returnShippingFeesAmount', 'returnShippingFeesAmount', 'Amount of shipping costs for product returns (for any reason). Applicable when property [[returnFees]] equals [[ReturnShippingFees]].'),
(5233, 1, 20, 'athlete', 'athlete', 'A person that acts as performing member of a sports team; a player as opposed to a coach.'),
(5234, 1, 20, 'originatesFrom', 'originatesFrom', 'The vasculature the lymphatic structure originates, or afferents, from.'),
(5235, 1, 20, 'bccRecipient', 'bccRecipient', 'A sub property of recipient. The recipient blind copied on a message.'),
(5236, 1, 20, 'directors', 'directors', 'A director of e.g. TV, radio, movie, video games etc. content. Directors can be associated with individual items or with a series, episode, clip.'),
(5237, 1, 20, 'director', 'director', 'A director of e.g. TV, radio, movie, video gaming etc. content, or of an event. Directors can be associated with individual items or with a series, episode, clip.'),
(5238, 1, 20, 'merchantReturnLink', 'merchantReturnLink', 'Specifies a Web page or service by URL, for product returns.'),
(5239, 1, 20, 'employerOverview', 'employerOverview', 'A description of the employer, career opportunities and work environment for this position.'),
(5240, 1, 20, 'hasVariant', 'hasVariant', 'Indicates a [[Product]] that is a member of this [[ProductGroup]] (or [[ProductModel]]).'),
(5241, 1, 20, 'isVariantOf', 'isVariantOf', 'Indicates the kind of product that this is a variant of. In the case of [[ProductModel]], this is a pointer (from a ProductModel) to a base product from which this product is a variant. It is safe to infer that the variant inherits all product features from the base model, unless defined locally. This is not transitive. In the case of a [[ProductGroup]], the group description also serves as a template, representing a set of Products that vary on explicitly defined, specific dimensions only (so it defines both a set of variants, as well as which values distinguish amongst those variants). When used with [[ProductGroup]], this property can apply to any [[Product]] included in the group.'),
(5242, 1, 20, 'ratingExplanation', 'ratingExplanation', 'A short explanation (e.g. one to two sentences) providing background context and other information that led to the conclusion expressed in the rating. This is particularly applicable to ratings associated with \"fact check\" markup using [[ClaimReview]].'),
(5243, 1, 20, 'addressLocality', 'addressLocality', 'The locality in which the street address is, and which is in the region. For example, Mountain View.'),
(5244, 1, 20, 'fiberContent', 'fiberContent', 'The number of grams of fiber.'),
(5245, 1, 20, 'geoCrosses', 'geoCrosses', 'Represents a relationship between two geometries (or the places they represent), relating a geometry to another that crosses it: \"a crosses b: they have some but not all interior points in common, and the dimension of the intersection is less than that of at least one of them\". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(5246, 1, 20, 'permissions', 'permissions', 'Permission(s) required to run the app (for example, a mobile app may require full internet access or may run only on wifi).'),
(5247, 1, 20, 'imagingTechnique', 'imagingTechnique', 'Imaging technique used.'),
(5248, 1, 20, 'isUnlabelledFallback', 'isUnlabelledFallback', 'This can be marked \'true\' to indicate that some published [[DeliveryTimeSettings]] or [[ShippingRateSettings]] are intended to apply to all [[OfferShippingDetails]] published by the same merchant, when referenced by a [[shippingSettingsLink]] in those settings. It is not meaningful to use a \'true\' value for this property alongside a transitTimeLabel (for [[DeliveryTimeSettings]]) or shippingLabel (for [[ShippingRateSettings]]), since this property is for use with unlabelled settings.'),
(5249, 1, 20, 'urlTemplate', 'urlTemplate', 'An url template (RFC6570) that will be used to construct the target of the execution of the action.'),
(5250, 1, 20, 'totalHistoricalEnrollment', 'totalHistoricalEnrollment', 'The total number of students that have enrolled in the history of the course.'),
(5251, 1, 20, 'cheatCode', 'cheatCode', 'Cheat codes to the game.'),
(5252, 1, 20, 'validThrough', 'validThrough', 'The date after when the item is not valid. For example the end of an offer, salary period, or a period of opening hours.'),
(5253, 1, 20, 'itemLocation', 'itemLocation', 'Current location of the item.'),
(5254, 1, 20, 'mpn', 'mpn', 'The Manufacturer Part Number (MPN) of the product, or the product to which the offer refers.'),
(5255, 1, 20, 'bestRating', 'bestRating', 'The highest value allowed in this rating system.'),
(5256, 1, 20, 'overdosage', 'overdosage', 'Any information related to overdose on a drug, including signs or symptoms, treatments, contact information for emergency response.'),
(5257, 1, 20, 'question', 'question', 'A sub property of object. A question.'),
(5258, 1, 20, 'department', 'department', 'A relationship between an organization and a department of that organization, also described as an organization (allowing different urls, logos, opening hours). For example: a store with a pharmacy, or a bakery with a cafe.'),
(5259, 1, 20, 'priceSpecification', 'priceSpecification', 'One or more detailed price specifications, indicating the unit price and delivery or payment charges.'),
(5260, 1, 20, 'duringMedia', 'duringMedia', 'A media object representing the circumstances while performing this direction.'),
(5261, 1, 20, 'numberOfPages', 'numberOfPages', 'The number of pages in the book.'),
(5262, 1, 20, 'occupationalCategory', 'occupationalCategory', 'A category describing the job, preferably using a term from a taxonomy such as [BLS O*NET-SOC](http://www.onetcenter.org/taxonomy.html), [ISCO-08](https://www.ilo.org/public/english/bureau/stat/isco/isco08/) or similar, with the property repeated for each applicable value. Ideally the taxonomy should be identified, and both the textual label and formal code for the category should be provided.\\n\nNote: for historical reasons, any textual label and formal code provided as a literal may be assumed to be from O*NET-SOC.'),
(5263, 1, 20, 'honorificSuffix', 'honorificSuffix', 'An honorific suffix following a Person\'s name such as M.D./PhD/MSCSW.'),
(5264, 1, 20, 'measurementMethod', 'measurementMethod', 'A subproperty of [[measurementTechnique]] that can be used for specifying specific methods, in particular via [[MeasurementMethodEnum]].'),
(5265, 1, 20, 'measurementTechnique', 'measurementTechnique', 'A technique, method or technology used in an [[Observation]], [[StatisticalVariable]] or [[Dataset]] (or [[DataDownload]], [[DataCatalog]]), corresponding to the method used for measuring the corresponding variable(s) (for datasets, described using [[variableMeasured]]; for [[Observation]], a [[StatisticalVariable]]). Often but not necessarily each [[variableMeasured]] will have an explicit representation as (or mapping to) an property such as those defined in Schema.org, or other RDF vocabularies and \"knowledge graphs\". In that case the subproperty of [[variableMeasured]] called [[measuredProperty]] is applicable.\n    \nThe [[measurementTechnique]] property helps when extra clarification is needed about how a [[measuredProperty]] was measured. This is oriented towards scientific and scholarly dataset publication but may have broader applicability; it is not intended as a full representation of measurement, but can often serve as a high level summary for dataset discovery. \n\nFor example, if [[variableMeasured]] is: molecule concentration, [[measurementTechnique]] could be: \"mass spectrometry\" or \"nmr spectroscopy\" or \"colorimetry\" or \"immunofluorescence\". If the [[variableMeasured]] is \"depression rating\", the [[measurementTechnique]] could be \"Zung Scale\" or \"HAM-D\" or \"Beck Depression Inventory\". \n\nIf there are several [[variableMeasured]] properties recorded for some given data object, use a [[PropertyValue]] for each [[variableMeasured]] and attach the corresponding [[measurementTechnique]]. The value can also be from an enumeration, organized as a [[MeasurementMetholdEnumeration]].'),
(5266, 1, 20, 'operatingSystem', 'operatingSystem', 'Operating systems supported (Windows 7, OS X 10.6, Android 1.6).'),
(5267, 1, 20, 'issueNumber', 'issueNumber', 'Identifies the issue of publication; for example, \"iii\" or \"2\".'),
(5268, 1, 20, 'guidelineSubject', 'guidelineSubject', 'The medical conditions, treatments, etc. that are the subject of the guideline.'),
(5269, 1, 20, 'arrivalGate', 'arrivalGate', 'Identifier of the flight\'s arrival gate.'),
(5270, 1, 20, 'measurementQualifier', 'measurementQualifier', 'Provides additional qualification to an observation. For example, a GDP observation measures the Nominal value.'),
(5271, 1, 20, 'dateDeleted', 'dateDeleted', 'The datetime the item was removed from the DataFeed.'),
(5272, 1, 20, 'sensoryRequirement', 'sensoryRequirement', 'A description of any sensory requirements and levels necessary to function on the job, including hearing and vision. Defined terms such as those in O*net may be used, but note that there is no way to specify the level of ability as well as its nature when using a defined term.'),
(5273, 1, 20, 'maximumEnrollment', 'maximumEnrollment', 'The maximum number of students who may be enrolled in the program.'),
(5274, 1, 20, 'runtime', 'runtime', 'Runtime platform or script interpreter dependencies (example: Java v1, Python 2.3, .NET Framework 3.0).'),
(5275, 1, 20, 'runtimePlatform', 'runtimePlatform', 'Runtime platform or script interpreter dependencies (example: Java v1, Python 2.3, .NET Framework 3.0).'),
(5276, 1, 20, 'vendor', 'vendor', '\'vendor\' is an earlier term for \'seller\'.'),
(5277, 1, 20, 'code', 'code', 'A medical code for the entity, taken from a controlled vocabulary or ontology such as ICD-9, DiseasesDB, MeSH, SNOMED-CT, RxNorm, etc.'),
(5278, 1, 20, 'adverseOutcome', 'adverseOutcome', 'A possible complication and/or side effect of this therapy. If it is known that an adverse outcome is serious (resulting in death, disability, or permanent damage; requiring hospitalization; or otherwise life-threatening or requiring immediate medical attention), tag it as a seriousAdverseOutcome instead.'),
(5279, 1, 20, 'estimatedCost', 'estimatedCost', 'The estimated cost of the supply or supplies consumed when performing instructions.'),
(5280, 1, 20, 'geoOverlaps', 'geoOverlaps', 'Represents a relationship between two geometries (or the places they represent), relating a geometry to another that geospatially overlaps it, i.e. they have some but not all points in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(5281, 1, 20, 'lodgingUnitType', 'lodgingUnitType', 'Textual description of the unit type (including suite vs. room, size of bed, etc.).'),
(5282, 1, 20, 'comprisedOf', 'comprisedOf', 'Specifying something physically contained by something else. Typically used here for the underlying anatomical structures, such as organs, that comprise the anatomical system.'),
(5283, 1, 20, 'citation', 'citation', 'A citation or reference to another creative work, such as another publication, web page, scholarly article, etc.'),
(5284, 1, 20, 'recipeInstructions', 'recipeInstructions', 'A step in making the recipe, in the form of a single item (document, video, etc.) or an ordered list with HowToStep and/or HowToSection items.'),
(5285, 1, 20, 'geo', 'geo', 'The geo coordinates of the place.'),
(5286, 1, 20, 'offeredBy', 'offeredBy', 'A pointer to the organization or person making the offer.'),
(5287, 1, 20, 'makesOffer', 'makesOffer', 'A pointer to products or services offered by the organization or person.'),
(5288, 1, 20, 'coach', 'coach', 'A person that acts in a coaching role for a sports team.'),
(5289, 1, 20, 'cvdNumTotBeds', 'cvdNumTotBeds', 'numtotbeds - ALL HOSPITAL BEDS: Total number of all inpatient and outpatient beds, including all staffed, ICU, licensed, and overflow (surge) beds used for inpatients or outpatients.'),
(5290, 1, 20, 'timeRequired', 'timeRequired', 'Approximate or typical time it usually takes to work with or through the content of this work for the typical or target audience.'),
(5291, 1, 20, 'numTracks', 'numTracks', 'The number of tracks in this album or playlist.'),
(5292, 1, 20, 'seasons', 'seasons', 'A season in a media series.'),
(5293, 1, 20, 'season', 'season', 'A season in a media series.'),
(5294, 1, 20, 'serviceArea', 'serviceArea', 'The geographic area where the service is provided.'),
(5295, 1, 20, 'publicTransportClosuresInfo', 'publicTransportClosuresInfo', 'Information about public transport closures.'),
(5296, 1, 20, 'character', 'character', 'Fictional person connected with a creative work.'),
(5297, 1, 20, 'softwareHelp', 'softwareHelp', 'Software application help.'),
(5298, 1, 20, 'actionStatus', 'actionStatus', 'Indicates the current disposition of the Action.'),
(5299, 1, 20, 'lyricist', 'lyricist', 'The person who wrote the words.'),
(5300, 1, 20, 'gameItem', 'gameItem', 'An item is an object within the game world that can be collected by a player or, occasionally, a non-player character.'),
(5301, 1, 20, 'servingSize', 'servingSize', 'The serving size, in terms of the number of volume or mass.'),
(5302, 1, 20, 'durationOfWarranty', 'durationOfWarranty', 'The duration of the warranty promise. Common unitCode values are ANN for year, MON for months, or DAY for days.'),
(5303, 1, 20, 'targetProduct', 'targetProduct', 'Target Operating System / Product to which the code applies.  If applies to several versions, just the product name can be used.'),
(5304, 1, 20, 'educationalProgramMode', 'educationalProgramMode', 'Similar to courseMode, the medium or means of delivery of the program as a whole. The value may either be a text label (e.g. \"online\", \"onsite\" or \"blended\"; \"synchronous\" or \"asynchronous\"; \"full-time\" or \"part-time\") or a URL reference to a term from a controlled vocabulary (e.g. https://ceds.ed.gov/element/001311#Asynchronous ).'),
(5305, 1, 20, 'nutrition', 'nutrition', 'Nutrition information about the recipe or menu item.'),
(5306, 1, 20, 'seatingCapacity', 'seatingCapacity', 'The number of persons that can be seated (e.g. in a vehicle), both in terms of the physical space available, and in terms of limitations set by law.\\n\\nTypical unit code(s): C62 for persons.'),
(5307, 1, 20, 'medicalSpecialty', 'medicalSpecialty', 'A medical specialty of the provider.'),
(5308, 1, 20, 'pattern', 'pattern', 'A pattern that something has, for example \'polka dot\', \'striped\', \'Canadian flag\'. Values are typically expressed as text, although links to controlled value schemes are also supported.'),
(5309, 1, 20, 'shippingSettingsLink', 'shippingSettingsLink', 'Link to a page containing [[ShippingRateSettings]] and [[DeliveryTimeSettings]] details.'),
(5310, 1, 20, 'reviewCount', 'reviewCount', 'The count of total number of reviews.'),
(5311, 1, 20, 'associatedClaimReview', 'associatedClaimReview', 'An associated [[ClaimReview]], related by specific common content, topic or claim. The expectation is that this property would be most typically used in cases where a single activity is conducting both claim reviews and media reviews, in which case [[relatedMediaReview]] would commonly be used on a [[ClaimReview]], while [[relatedClaimReview]] would be used on [[MediaReview]].'),
(5312, 1, 20, 'coverageEndTime', 'coverageEndTime', 'The time when the live blog will stop covering the Event. Note that coverage may continue after the Event concludes.'),
(5313, 1, 20, 'cvdNumC19HospPats', 'cvdNumC19HospPats', 'numc19hosppats - HOSPITALIZED: Patients currently hospitalized in an inpatient care location who have suspected or confirmed COVID-19.'),
(5314, 1, 20, 'availableService', 'availableService', 'A medical service available from this provider.'),
(5315, 1, 20, 'startDate', 'startDate', 'The start date and time of the item (in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601)).'),
(5316, 1, 20, 'branchOf', 'branchOf', 'The larger organization that this local business is a branch of, if any. Not to be confused with (anatomical) [[branch]].'),
(5317, 1, 20, 'distance', 'distance', 'The distance travelled, e.g. exercising or travelling.'),
(5318, 1, 20, 'variableMeasured', 'variableMeasured', 'The variableMeasured property can indicate (repeated as necessary) the  variables that are measured in some dataset, either described as text or as pairs of identifier and description using PropertyValue, or more explicitly as a [[StatisticalVariable]].'),
(5319, 1, 20, 'serverStatus', 'serverStatus', 'Status of a game server.'),
(5320, 1, 20, 'box', 'box', 'A box is the area enclosed by the rectangle formed by two points. The first point is the lower corner, the second point is the upper corner. A box is expressed as two points separated by a space character.'),
(5321, 1, 20, 'loanPaymentFrequency', 'loanPaymentFrequency', 'Frequency of payments due, i.e. number of months between payments. This is defined as a frequency, i.e. the reciprocal of a period of time.'),
(5322, 1, 20, 'typicalAgeRange', 'typicalAgeRange', 'The typical expected age range, e.g. \'7-9\', \'11-\'.'),
(5323, 1, 20, 'productReturnLink', 'productReturnLink', 'Indicates a Web page or service by URL, for product return.'),
(5324, 1, 20, 'differentialDiagnosis', 'differentialDiagnosis', 'One of a set of differential diagnoses for the condition. Specifically, a closely-related or competing diagnosis typically considered later in the cognitive process whereby this medical condition is distinguished from others most likely responsible for a similar collection of signs and symptoms to reach the most parsimonious diagnosis or diagnoses in a patient.'),
(5325, 1, 20, 'httpMethod', 'httpMethod', 'An HTTP method that specifies the appropriate HTTP method for a request to an HTTP EntryPoint. Values are capitalized strings as used in HTTP.'),
(5326, 1, 20, 'verificationFactCheckingPolicy', 'verificationFactCheckingPolicy', 'Disclosure about verification and fact-checking processes for a [[NewsMediaOrganization]] or other fact-checking [[Organization]].'),
(5327, 1, 20, 'noBylinesPolicy', 'noBylinesPolicy', 'For a [[NewsMediaOrganization]] or other news-related [[Organization]], a statement explaining when authors of articles are not named in bylines.'),
(5328, 1, 20, 'orderDelivery', 'orderDelivery', 'The delivery of the parcel related to this order or order item.'),
(5329, 1, 20, 'recipeCategory', 'recipeCategory', 'The category of the recipe—for example, appetizer, entree, etc.'),
(5330, 1, 20, 'translator', 'translator', 'Organization or person who adapts a creative work to different languages, regional differences and technical requirements of a target market, or that translates during some event.'),
(5331, 1, 20, 'acceptedAnswer', 'acceptedAnswer', 'The answer(s) that has been accepted as best, typically on a Question/Answer site. Sites vary in their selection mechanisms, e.g. drawing on community opinion and/or the view of the Question author.'),
(5332, 1, 20, 'suggestedAnswer', 'suggestedAnswer', 'An answer (possibly one of several, possibly incorrect) to a Question, e.g. on a Question/Answer site.'),
(5333, 1, 20, 'riskFactor', 'riskFactor', 'A modifiable or non-modifiable factor that increases the risk of a patient contracting this condition, e.g. age,  coexisting condition.'),
(5334, 1, 20, 'musicArrangement', 'musicArrangement', 'An arrangement derived from the composition.'),
(5335, 1, 20, 'numberOfEmployees', 'numberOfEmployees', 'The number of employees in an organization, e.g. business.'),
(5336, 1, 20, 'thumbnailUrl', 'thumbnailUrl', 'A thumbnail image relevant to the Thing.'),
(5337, 1, 20, 'broadcastSubChannel', 'broadcastSubChannel', 'The subchannel used for the broadcast.'),
(5338, 1, 20, 'albums', 'albums', 'A collection of music albums.'),
(5339, 1, 20, 'transmissionMethod', 'transmissionMethod', 'How the disease spreads, either as a route or vector, for example \'direct contact\', \'Aedes aegypti\', etc.'),
(5340, 1, 20, 'workHours', 'workHours', 'The typical working hours for this job (e.g. 1st shift, night shift, 8am-5pm).'),
(5341, 1, 20, 'unnamedSourcesPolicy', 'unnamedSourcesPolicy', 'For an [[Organization]] (typically a [[NewsMediaOrganization]]), a statement about policy on use of unnamed sources and the decision process required.'),
(5342, 1, 20, 'tocContinuation', 'tocContinuation', 'A [[HyperTocEntry]] can have a [[tocContinuation]] indicated, which is another [[HyperTocEntry]] that would be the default next item to play or render.'),
(5343, 1, 20, 'ticketedSeat', 'ticketedSeat', 'The seat associated with the ticket.'),
(5344, 1, 20, 'webCheckinTime', 'webCheckinTime', 'The time when a passenger can check into the flight online.'),
(5345, 1, 20, 'spouse', 'spouse', 'The person\'s spouse.'),
(5346, 1, 20, 'billingAddress', 'billingAddress', 'The billing address for the order.'),
(5347, 1, 20, 'catalog', 'catalog', 'A data catalog which contains this dataset.'),
(5348, 1, 20, 'targetPopulation', 'targetPopulation', 'Characteristics of the population for which this is intended, or which typically uses it, e.g. \'adults\'.'),
(5349, 1, 20, 'articleBody', 'articleBody', 'The actual body of the article.'),
(5350, 1, 20, 'foodWarning', 'foodWarning', 'Any precaution, guidance, contraindication, etc. related to consumption of specific foods while taking this drug.'),
(5351, 1, 20, 'workLocation', 'workLocation', 'A contact location for a person\'s place of work.'),
(5352, 1, 20, 'contentUrl', 'contentUrl', 'Actual bytes of the media object, for example the image file or video file.'),
(5353, 1, 20, 'digitalSourceType', 'digitalSourceType', 'Indicates an IPTCDigitalSourceEnumeration code indicating the nature of the digital source(s) for some [[CreativeWork]].'),
(5354, 1, 20, 'bookFormat', 'bookFormat', 'The format of the book.'),
(5355, 1, 20, 'brand', 'brand', 'The brand(s) associated with a product or service, or the brand(s) maintained by an organization or business person.'),
(5356, 1, 20, 'employmentUnit', 'employmentUnit', 'Indicates the department, unit and/or facility where the employee reports and/or in which the job is to be performed.'),
(5357, 1, 20, 'hasMolecularFunction', 'hasMolecularFunction', 'Molecular function performed by this BioChemEntity; please use PropertyValue if you want to include any evidence.'),
(5358, 1, 20, 'blogPosts', 'blogPosts', 'Indicates a post that is part of a [[Blog]]. Note that historically, what we term a \"Blog\" was once known as a \"weblog\", and that what we term a \"BlogPosting\" is now often colloquially referred to as a \"blog\".'),
(5359, 1, 20, 'pregnancyCategory', 'pregnancyCategory', 'Pregnancy category of this drug.'),
(5360, 1, 20, 'colleagues', 'colleagues', 'A colleague of the person.'),
(5361, 1, 20, 'collection', 'collection', 'A sub property of object. The collection target of the action.'),
(5362, 1, 20, 'targetCollection', 'targetCollection', 'A sub property of object. The collection target of the action.'),
(5363, 1, 20, 'producer', 'producer', 'The person or organization who produced the work (e.g. music album, movie, TV/radio series etc.).'),
(5364, 1, 20, 'ccRecipient', 'ccRecipient', 'A sub property of recipient. The recipient copied on a message.'),
(5365, 1, 20, 'partOfSystem', 'partOfSystem', 'The anatomical or organ system that this structure is part of.'),
(5366, 1, 20, 'recordLabel', 'recordLabel', 'The label that issued the release.'),
(5367, 1, 20, 'defaultValue', 'defaultValue', 'The default value of the input.  For properties that expect a literal, the default is a literal value, for properties that expect an object, it\'s an ID reference to one of the current values.'),
(5368, 1, 20, 'departureStation', 'departureStation', 'The station from which the train departs.'),
(5369, 1, 20, 'healthcareReportingData', 'healthcareReportingData', 'Indicates data describing a hospital, e.g. a CDC [[CDCPMDRecord]] or as some kind of [[Dataset]].'),
(5370, 1, 20, 'availableStrength', 'availableStrength', 'An available dosage strength for the drug.'),
(5371, 1, 20, 'billingPeriod', 'billingPeriod', 'The time interval used to compute the invoice.'),
(5372, 1, 20, 'intensity', 'intensity', 'Quantitative measure gauging the degree of force involved in the exercise, for example, heartbeats per minute. May include the velocity of the movement.'),
(5373, 1, 20, 'providesBroadcastService', 'providesBroadcastService', 'The BroadcastService offered on this channel.'),
(5374, 1, 20, 'hasBroadcastChannel', 'hasBroadcastChannel', 'A broadcast channel of a broadcast service.'),
(5375, 1, 20, 'replacer', 'replacer', 'A sub property of object. The object that replaces.'),
(5376, 1, 20, 'typicalCreditsPerTerm', 'typicalCreditsPerTerm', 'The number of credits or units a full-time student would be expected to take in 1 term however \'term\' is defined by the institution.'),
(5377, 1, 20, 'dietFeatures', 'dietFeatures', 'Nutritional information specific to the dietary plan. May include dietary recommendations on what foods to avoid, what foods to consume, and specific alterations/deviations from the USDA or other regulatory body\'s approved dietary guidelines.'),
(5378, 1, 20, 'dissolutionDate', 'dissolutionDate', 'The date that this organization was dissolved.'),
(5379, 1, 20, 'cvdNumBeds', 'cvdNumBeds', 'numbeds - HOSPITAL INPATIENT BEDS: Inpatient beds, including all staffed, licensed, and overflow (surge) beds used for inpatients.'),
(5380, 1, 20, 'identifyingTest', 'identifyingTest', 'A diagnostic test that can identify this sign.'),
(5381, 1, 20, 'includesHealthPlanFormulary', 'includesHealthPlanFormulary', 'Formularies covered by this plan.'),
(5382, 1, 20, 'molecularWeight', 'molecularWeight', 'This is the molecular weight of the entity being described, not of the parent. Units should be included in the form \'&lt;Number&gt; &lt;unit&gt;\', for example \'12 amu\' or as \'&lt;QuantitativeValue&gt;.'),
(5383, 1, 20, 'illustrator', 'illustrator', 'The illustrator of the book.'),
(5384, 1, 20, 'inChI', 'inChI', 'Non-proprietary identifier for molecular entity that can be used in printed and electronic data sources thus enabling easier linking of diverse data compilations.'),
(5385, 1, 20, 'originalMediaContextDescription', 'originalMediaContextDescription', 'Describes, in a [[MediaReview]] when dealing with [[DecontextualizedContent]], background information that can contribute to better interpretation of the [[MediaObject]].'),
(5386, 1, 20, 'numberOfAvailableAccommodationUnits', 'numberOfAvailableAccommodationUnits', 'Indicates the number of available accommodation units in an [[ApartmentComplex]], or the number of accommodation units for a specific [[FloorPlan]] (within its specific [[ApartmentComplex]]). See also [[numberOfAccommodationUnits]].'),
(5387, 1, 20, 'eduQuestionType', 'eduQuestionType', 'For questions that are part of learning resources (e.g. Quiz), eduQuestionType indicates the format of question being given. Example: \"Multiple choice\", \"Open ended\", \"Flashcard\".'),
(5388, 1, 20, 'strengthValue', 'strengthValue', 'The value of an active ingredient\'s strength, e.g. 325.'),
(5389, 1, 20, 'nationality', 'nationality', 'Nationality of the person.'),
(5390, 1, 20, 'numberedPosition', 'numberedPosition', 'A number associated with a role in an organization, for example, the number on an athlete\'s jersey.'),
(5391, 1, 20, 'diet', 'diet', 'A sub property of instrument. The diet used in this action.'),
(5392, 1, 20, 'broadcastSignalModulation', 'broadcastSignalModulation', 'The modulation (e.g. FM, AM, etc) used by a particular broadcast service.'),
(5393, 1, 20, 'marginOfError', 'marginOfError', 'A [[marginOfError]] for an [[Observation]].'),
(5394, 1, 20, 'musicCompositionForm', 'musicCompositionForm', 'The type of composition (e.g. overture, sonata, symphony, etc.).'),
(5395, 1, 20, 'owns', 'owns', 'Products owned by the organization or person.'),
(5396, 1, 20, 'accessibilityControl', 'accessibilityControl', 'Identifies input methods that are sufficient to fully control the described resource. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityControl-vocabulary).'),
(5397, 1, 20, 'interactionService', 'interactionService', 'The WebSite or SoftwareApplication where the interactions took place.'),
(5398, 1, 20, 'author', 'author', 'The author of this content or rating. Please note that author is special in that HTML 5 provides a special mechanism for indicating authorship via the rel tag. That is equivalent to this and may be used interchangeably.'),
(5399, 1, 20, 'experienceInPlaceOfEducation', 'experienceInPlaceOfEducation', 'Indicates whether a [[JobPosting]] will accept experience (as indicated by [[OccupationalExperienceRequirements]]) in place of its formal educational qualifications (as indicated by [[educationRequirements]]). If true, indicates that satisfying one of these requirements is sufficient.'),
(5400, 1, 20, 'reviewBody', 'reviewBody', 'The actual body of the review.'),
(5401, 1, 20, 'includesObject', 'includesObject', 'This links to a node or nodes indicating the exact quantity of the products included in  an [[Offer]] or [[ProductCollection]].'),
(5402, 1, 20, 'byMonthDay', 'byMonthDay', 'Defines the day(s) of the month on which a recurring [[Event]] takes place. Specified as an [[Integer]] between 1-31.'),
(5403, 1, 20, 'performerIn', 'performerIn', 'Event that this person is a performer or participant in.'),
(5404, 1, 20, 'contraindication', 'contraindication', 'A contraindication for this therapy.'),
(5405, 1, 20, 'startTime', 'startTime', 'The startTime of something. For a reserved event or service (e.g. FoodEstablishmentReservation), the time that it is expected to start. For actions that span a period of time, when the action was performed. E.g. John wrote a book from *January* to December. For media, including audio and video, it\'s the time offset of the start of a clip within a larger file.\\n\\nNote that Event uses startDate/endDate instead of startTime/endTime, even when describing dates with times. This situation may be clarified in future revisions.'),
(5406, 1, 20, 'itemReviewed', 'itemReviewed', 'The item that is being reviewed/rated.'),
(5407, 1, 20, 'byMonth', 'byMonth', 'Defines the month(s) of the year on which a recurring [[Event]] takes place. Specified as an [[Integer]] between 1-12. January is 1.'),
(5408, 1, 20, 'numberOfAirbags', 'numberOfAirbags', 'The number or type of airbags in the vehicle.'),
(5409, 1, 20, 'commentTime', 'commentTime', 'The time at which the UserComment was made.'),
(5410, 1, 20, 'inCodeSet', 'inCodeSet', 'A [[CategoryCodeSet]] that contains this category code.'),
(5411, 1, 20, 'subtitleLanguage', 'subtitleLanguage', 'Languages in which subtitles/captions are available, in [IETF BCP 47 standard format](http://tools.ietf.org/html/bcp47).'),
(5412, 1, 20, 'publicAccess', 'publicAccess', 'A flag to signal that the [[Place]] is open to public visitors.  If this property is omitted there is no assumed default boolean value.'),
(5413, 1, 20, 'leiCode', 'leiCode', 'An organization identifier that uniquely identifies a legal entity as defined in ISO 17442.'),
(5414, 1, 20, 'modifiedTime', 'modifiedTime', 'The date and time the reservation was modified.'),
(5415, 1, 20, 'checkoutTime', 'checkoutTime', 'The latest someone may check out of a lodging establishment.'),
(5416, 1, 20, 'applicationStartDate', 'applicationStartDate', 'The date at which the program begins collecting applications for the next enrollment cycle.'),
(5417, 1, 20, 'supplyTo', 'supplyTo', 'The area to which the artery supplies blood.'),
(5418, 1, 20, 'deathDate', 'deathDate', 'Date of death.'),
(5419, 1, 20, 'correctionsPolicy', 'correctionsPolicy', 'For an [[Organization]] (e.g. [[NewsMediaOrganization]]), a statement describing (in news media, the newsroom’s) disclosure and correction policy for errors.'),
(5420, 1, 20, 'floorLimit', 'floorLimit', 'A floor limit is the amount of money above which credit card transactions must be authorized.'),
(5421, 1, 20, 'loanType', 'loanType', 'The type of a loan or credit.'),
(5422, 1, 20, 'isAcceptingNewPatients', 'isAcceptingNewPatients', 'Whether the provider is accepting new patients.'),
(5423, 1, 20, 'additionalType', 'additionalType', 'An additional type for the item, typically used for adding more specific types from external vocabularies in microdata syntax. This is a relationship between something and a class that the thing is in. Typically the value is a URI-identified RDF class, and in this case corresponds to the\n    use of rdf:type in RDF. Text values can be used sparingly, for cases where useful information can be added without their being an appropriate schema to reference. In the case of text values, the class label should follow the schema.org <a href=\"http://schema.org/docs/styleguide.html\">style guide</a>.'),
(5424, 1, 20, 'exerciseRelatedDiet', 'exerciseRelatedDiet', 'A sub property of instrument. The diet used in this action.'),
(5425, 1, 20, 'practicesAt', 'practicesAt', 'A [[MedicalOrganization]] where the [[IndividualPhysician]] practices.'),
(5426, 1, 20, 'borrower', 'borrower', 'A sub property of participant. The person that borrows the object being lent.'),
(5427, 1, 20, 'item', 'item', 'An entity represented by an entry in a list or data feed (e.g. an \'artist\' in a list of \'artists\').'),
(5428, 1, 20, 'publishedOn', 'publishedOn', 'A broadcast service associated with the publication event.'),
(5429, 1, 20, 'responsibilities', 'responsibilities', 'Responsibilities associated with this role or Occupation.'),
(5430, 1, 20, 'sportsTeam', 'sportsTeam', 'A sub property of participant. The sports team that participated on this action.'),
(5431, 1, 20, 'acceptedPaymentMethod', 'acceptedPaymentMethod', 'The payment method(s) that are accepted in general by an organization, or for some specific demand or offer.'),
(5432, 1, 20, 'estimatesRiskOf', 'estimatesRiskOf', 'The condition, complication, or symptom whose risk is being estimated.'),
(5433, 1, 20, 'toRecipient', 'toRecipient', 'A sub property of recipient. The recipient who was directly sent the message.'),
(5434, 1, 20, 'numberOfFullBathrooms', 'numberOfFullBathrooms', 'Number of full bathrooms - The total number of full and ¾ bathrooms in an [[Accommodation]]. This corresponds to the [BathroomsFull field in RESO](https://ddwiki.reso.org/display/DDW17/BathroomsFull+Field).'),
(5435, 1, 20, 'confirmationNumber', 'confirmationNumber', 'A number that confirms the given order or payment has been received.'),
(5436, 1, 20, 'paymentStatus', 'paymentStatus', 'The status of payment; whether the invoice has been paid or not.'),
(5437, 1, 20, 'programmingModel', 'programmingModel', 'Indicates whether API is managed or unmanaged.'),
(5438, 1, 20, 'browserRequirements', 'browserRequirements', 'Specifies browser requirements in human-readable text. For example, \'requires HTML5 support\'.'),
(5439, 1, 20, 'observationDate', 'observationDate', 'The observationDate of an [[Observation]].'),
(5440, 1, 20, 'replacee', 'replacee', 'A sub property of object. The object that is being replaced.'),
(5441, 1, 20, 'vehicleTransmission', 'vehicleTransmission', 'The type of component used for transmitting the power from a rotating power source to the wheels or other relevant component(s) (\"gearbox\" for cars).'),
(5442, 1, 20, 'highPrice', 'highPrice', 'The highest price of all offers available.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(5443, 1, 20, 'associatedAnatomy', 'associatedAnatomy', 'The anatomy of the underlying organ system or structures associated with this entity.'),
(5444, 1, 20, 'reviewAspect', 'reviewAspect', 'This Review or Rating is relevant to this part or facet of the itemReviewed.'),
(5445, 1, 20, 'educationalLevel', 'educationalLevel', 'The level in terms of progression through an educational or training context. Examples of educational levels include \'beginner\', \'intermediate\' or \'advanced\', and formal sets of level indicators.'),
(5446, 1, 20, 'worksFor', 'worksFor', 'Organizations that the person works for.'),
(5447, 1, 20, 'cvdNumC19HOPats', 'cvdNumC19HOPats', 'numc19hopats - HOSPITAL ONSET: Patients hospitalized in an NHSN inpatient care location with onset of suspected or confirmed COVID-19 14 or more days after hospitalization.'),
(5448, 1, 20, 'claimInterpreter', 'claimInterpreter', 'For a [[Claim]] interpreted from [[MediaObject]] content, the [[interpretedAsClaim]] property can be used to indicate a claim contained, implied or refined from the content of a [[MediaObject]].'),
(5449, 1, 20, 'genre', 'genre', 'Genre of the creative work, broadcast channel or group.'),
(5450, 1, 20, 'originAddress', 'originAddress', 'Shipper\'s address.'),
(5451, 1, 20, 'volumeNumber', 'volumeNumber', 'Identifies the volume of publication or multi-part work; for example, \"iii\" or \"2\".'),
(5452, 1, 20, 'accountOverdraftLimit', 'accountOverdraftLimit', 'An overdraft is an extension of credit from a lending institution when an account reaches zero. An overdraft allows the individual to continue withdrawing money even if the account has no funds in it. Basically the bank allows people to borrow a set amount of money.'),
(5453, 1, 20, 'modelDate', 'modelDate', 'The release date of a vehicle model (often used to differentiate versions of the same make and model).'),
(5454, 1, 20, 'busName', 'busName', 'The name of the bus (e.g. Bolt Express).'),
(5455, 1, 20, 'codeValue', 'codeValue', 'A short textual code that uniquely identifies the value.'),
(5456, 1, 20, 'trackingUrl', 'trackingUrl', 'Tracking url for the parcel delivery.'),
(5457, 1, 20, 'validUntil', 'validUntil', 'The date when the item is no longer valid.'),
(5458, 1, 20, 'numberOfForwardGears', 'numberOfForwardGears', 'The total number of forward gears available for the transmission system of the vehicle.\\n\\nTypical unit code(s): C62.'),
(5459, 1, 20, 'diagram', 'diagram', 'An image containing a diagram that illustrates the structure and/or its component substructures and/or connections with other structures.'),
(5460, 1, 20, 'estimatedFlightDuration', 'estimatedFlightDuration', 'The estimated time the flight will take.'),
(5461, 1, 20, 'stageAsNumber', 'stageAsNumber', 'The stage represented as a number, e.g. 3.'),
(5462, 1, 20, 'opens', 'opens', 'The opening hour of the place or service on the given day(s) of the week.'),
(5463, 1, 20, 'map', 'map', 'A URL to a map of the place.'),
(5464, 1, 20, 'hasMap', 'hasMap', 'A URL to a map of the place.'),
(5465, 1, 20, 'candidate', 'candidate', 'A sub property of object. The candidate subject of this action.'),
(5466, 1, 20, 'followee', 'followee', 'A sub property of object. The person or organization being followed.'),
(5467, 1, 20, 'usNPI', 'usNPI', 'A <a href=\"https://en.wikipedia.org/wiki/National_Provider_Identifier\">National Provider Identifier</a> (NPI) \n    is a unique 10-digit identification number issued to health care providers in the United States by the Centers for Medicare and Medicaid Services.'),
(5468, 1, 20, 'hasTierBenefit', 'hasTierBenefit', 'A member benefit for a particular tier of a loyalty program.'),
(5469, 1, 20, 'nonprofitStatus', 'nonprofitStatus', 'nonprofitStatus indicates the legal status of a non-profit organization in its primary place of business.'),
(5470, 1, 20, 'warning', 'warning', 'Any FDA or other warnings about the drug (text or URL).'),
(5471, 1, 20, 'hasEnergyEfficiencyCategory', 'hasEnergyEfficiencyCategory', 'Defines the energy efficiency Category (which could be either a rating out of range of values or a yes/no certification) for a product according to an international energy efficiency standard.'),
(5472, 1, 20, 'hasGS1DigitalLink', 'hasGS1DigitalLink', 'The <a href=\"https://www.gs1.org/standards/gs1-digital-link\">GS1 digital link</a> associated with the object. This URL should conform to the particular requirements of digital links. The link should only contain the Application Identifiers (AIs) that are relevant for the entity being annotated, for instance a [[Product]] or an [[Organization]], and for the correct granularity. In particular, for products:<ul><li>A Digital Link that contains a serial number (AI <code>21</code>) should only be present on instances of [[IndividualProduct]]</li><li>A Digital Link that contains a lot number (AI <code>10</code>) should be annotated as [[SomeProduct]] if only products from that lot are sold, or [[IndividualProduct]] if there is only a specific product.</li><li>A Digital Link that contains a global model number (AI <code>8013</code>)  should be attached to a [[Product]] or a [[ProductModel]].</li></ul> Other item types should be adapted similarly.'),
(5473, 1, 20, 'vehicleSpecialUsage', 'vehicleSpecialUsage', 'Indicates whether the vehicle has been used for special purposes, like commercial rental, driving school, or as a taxi. The legislation in many countries requires this information to be revealed when offering a car for sale.'),
(5474, 1, 20, 'orderStatus', 'orderStatus', 'The current status of the order.'),
(5475, 1, 20, 'repetitions', 'repetitions', 'Number of times one should repeat the activity.'),
(5476, 1, 20, 'gameLocation', 'gameLocation', 'Real or fictional location of the game (or part of game).'),
(5477, 1, 20, 'providerMobility', 'providerMobility', 'Indicates the mobility of a provided service (e.g. \'static\', \'dynamic\').'),
(5478, 1, 20, 'transitTimeLabel', 'transitTimeLabel', 'Label to match an [[OfferShippingDetails]] with a [[DeliveryTimeSettings]] (within the context of a [[shippingSettingsLink]] cross-reference).'),
(5479, 1, 20, 'variesBy', 'variesBy', 'Indicates the property or properties by which the variants in a [[ProductGroup]] vary, e.g. their size, color etc. Schema.org properties can be referenced by their short name e.g. \"color\"; terms defined elsewhere can be referenced with their URIs.'),
(5480, 1, 20, 'codeRepository', 'codeRepository', 'Link to the repository where the un-compiled, human readable code and related code is located (SVN, GitHub, CodePlex).'),
(5481, 1, 20, 'customerRemorseReturnShippingFeesAmount', 'customerRemorseReturnShippingFeesAmount', 'The amount of shipping costs if a product is returned due to customer remorse. Applicable when property [[customerRemorseReturnFees]] equals [[ReturnShippingFees]].'),
(5482, 1, 20, 'subStageSuffix', 'subStageSuffix', 'The substage, e.g. \'a\' for Stage IIIa.'),
(5483, 1, 20, 'saturatedFatContent', 'saturatedFatContent', 'The number of grams of saturated fat.'),
(5484, 1, 20, 'additionalName', 'additionalName', 'An additional name for a Person, can be used for a middle name.'),
(5485, 1, 20, 'alternateName', 'alternateName', 'An alias for the item.'),
(5486, 1, 20, 'engineType', 'engineType', 'The type of engine or engines powering the vehicle.'),
(5487, 1, 20, 'archivedAt', 'archivedAt', 'Indicates a page or other link involved in archival of a [[CreativeWork]]. In the case of [[MediaReview]], the items in a [[MediaReviewItem]] may often become inaccessible, but be archived by archival, journalistic, activist, or law enforcement organizations. In such cases, the referenced page may not directly publish the content.'),
(5488, 1, 20, 'clipNumber', 'clipNumber', 'Position of the clip within an ordered group of clips.'),
(5489, 1, 20, 'relatedAnatomy', 'relatedAnatomy', 'Anatomical systems or structures that relate to the superficial anatomy.'),
(5490, 1, 20, 'seatRow', 'seatRow', 'The row location of the reserved seat (e.g., B).'),
(5491, 1, 20, 'costOrigin', 'costOrigin', 'Additional details to capture the origin of the cost data. For example, \'Medicare Part B\'.'),
(5492, 1, 20, 'accelerationTime', 'accelerationTime', 'The time needed to accelerate the vehicle from a given start velocity to a given target velocity.\\n\\nTypical unit code(s): SEC for seconds\\n\\n* Note: There are unfortunately no standard unit codes for seconds/0..100 km/h or seconds/0..60 mph. Simply use \"SEC\" for seconds and indicate the velocities in the [[name]] of the [[QuantitativeValue]], or use [[valueReference]] with a [[QuantitativeValue]] of 0..60 mph or 0..100 km/h to specify the reference speeds.'),
(5493, 1, 20, 'schoolClosuresInfo', 'schoolClosuresInfo', 'Information about school closures.'),
(5494, 1, 20, 'usesDevice', 'usesDevice', 'Device used to perform the test.'),
(5495, 1, 20, 'streetAddress', 'streetAddress', 'The street address. For example, 1600 Amphitheatre Pkwy.'),
(5496, 1, 20, 'hasCategoryCode', 'hasCategoryCode', 'A Category code contained in this code set.'),
(5497, 1, 20, 'hasDefinedTerm', 'hasDefinedTerm', 'A Defined Term contained in this term set.'),
(5498, 1, 20, 'includesHealthPlanNetwork', 'includesHealthPlanNetwork', 'Networks covered by this plan.'),
(5499, 1, 20, 'previousItem', 'previousItem', 'A link to the ListItem that precedes the current one.'),
(5500, 1, 20, 'unsaturatedFatContent', 'unsaturatedFatContent', 'The number of grams of unsaturated fat.'),
(5501, 1, 20, 'seriousAdverseOutcome', 'seriousAdverseOutcome', 'A possible serious complication and/or serious side effect of this therapy. Serious adverse outcomes include those that are life-threatening; result in death, disability, or permanent damage; require hospitalization or prolong existing hospitalization; cause congenital anomalies or birth defects; or jeopardize the patient and may require medical or surgical intervention to prevent one of the outcomes in this definition.'),
(5502, 1, 20, 'flightDistance', 'flightDistance', 'The distance of the flight.'),
(5503, 1, 20, 'relatedCondition', 'relatedCondition', 'A medical condition associated with this anatomy.'),
(5504, 1, 20, 'copyrightYear', 'copyrightYear', 'The year during which the claimed copyright for the CreativeWork was first asserted.'),
(5505, 1, 20, 'headline', 'headline', 'Headline of the article.'),
(5506, 1, 20, 'evidenceLevel', 'evidenceLevel', 'Strength of evidence of the data used to formulate the guideline (enumerated).'),
(5507, 1, 20, 'jobStartDate', 'jobStartDate', 'The date on which a successful applicant for this job would be expected to start work. Choose a specific date in the future or use the jobImmediateStart property to indicate the position is to be filled as soon as possible.'),
(5508, 1, 20, 'quarantineGuidelines', 'quarantineGuidelines', 'Guidelines about quarantine rules, e.g. in the context of a pandemic.'),
(5509, 1, 20, 'fileSize', 'fileSize', 'Size of the application / package (e.g. 18MB). In the absence of a unit (MB, KB etc.), KB will be assumed.'),
(5510, 1, 20, 'sibling', 'sibling', 'A sibling of the person.'),
(5511, 1, 20, 'siblings', 'siblings', 'A sibling of the person.'),
(5512, 1, 20, 'target', 'target', 'Indicates a target EntryPoint, or url, for an Action.'),
(5513, 1, 20, 'hasDigitalDocumentPermission', 'hasDigitalDocumentPermission', 'A permission related to the access to this document (e.g. permission to read or write an electronic document). For a public document, specify a grantee with an Audience with audienceType equal to \"public\".'),
(5514, 1, 20, 'cvdFacilityId', 'cvdFacilityId', 'Identifier of the NHSN facility that this data record applies to. Use [[cvdFacilityCounty]] to indicate the county. To provide other details, [[healthcareReportingData]] can be used on a [[Hospital]] entry.'),
(5515, 1, 20, 'itemShipped', 'itemShipped', 'Item(s) being shipped.'),
(5516, 1, 20, 'mapType', 'mapType', 'Indicates the kind of Map, from the MapCategoryType Enumeration.'),
(5517, 1, 20, 'sportsEvent', 'sportsEvent', 'A sub property of location. The sports event where this action occurred.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(5518, 1, 20, 'endOffset', 'endOffset', 'The end time of the clip expressed as the number of seconds from the beginning of the work.'),
(5519, 1, 20, 'chemicalRole', 'chemicalRole', 'A role played by the BioChemEntity within a chemical context.'),
(5520, 1, 20, 'discusses', 'discusses', 'Specifies the CreativeWork associated with the UserComment.'),
(5521, 1, 20, 'nerveMotor', 'nerveMotor', 'The neurological pathway extension that involves muscle control.'),
(5522, 1, 20, 'gameEdition', 'gameEdition', 'The edition of a video game.'),
(5523, 1, 20, 'vehicleEngine', 'vehicleEngine', 'Information about the engine or engines of the vehicle.'),
(5524, 1, 20, 'processingTime', 'processingTime', 'Estimated processing time for the service using this channel.'),
(5525, 1, 20, 'primaryImageOfPage', 'primaryImageOfPage', 'Indicates the main image on the page.'),
(5526, 1, 20, 'expectedArrivalUntil', 'expectedArrivalUntil', 'The latest date the package may arrive.'),
(5527, 1, 20, 'healthPlanDrugOption', 'healthPlanDrugOption', 'TODO.'),
(5528, 1, 20, 'gtin8', 'gtin8', 'The GTIN-8 code of the product, or the product to which the offer refers. This code is also known as EAN/UCC-8 or 8-digit EAN. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(5529, 1, 20, 'reviews', 'reviews', 'Review of the item.'),
(5530, 1, 20, 'review', 'review', 'A review of the item.'),
(5531, 1, 20, 'employees', 'employees', 'People working for this organization.'),
(5532, 1, 20, 'employee', 'employee', 'Someone working for this organization.'),
(5533, 1, 20, 'dateReceived', 'dateReceived', 'The date/time the message was received if a single recipient exists.'),
(5534, 1, 20, 'weightTotal', 'weightTotal', 'The permitted total weight of the loaded vehicle, including passengers and cargo and the weight of the empty vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(5535, 1, 20, 'legislationConsolidates', 'legislationConsolidates', 'Indicates another legislation taken into account in this consolidated legislation (which is usually the product of an editorial process that revises the legislation). This property should be used multiple times to refer to both the original version or the previous consolidated version, and to the legislations making the change.'),
(5536, 1, 20, 'checkinTime', 'checkinTime', 'The earliest someone may check into a lodging establishment.'),
(5537, 1, 20, 'globalLocationNumber', 'globalLocationNumber', 'The [Global Location Number](http://www.gs1.org/gln) (GLN, sometimes also referred to as International Location Number or ILN) of the respective organization, person, or place. The GLN is a 13-digit number used to identify parties and physical locations.'),
(5538, 1, 20, 'videoQuality', 'videoQuality', 'The quality of the video.'),
(5539, 1, 20, 'signOrSymptom', 'signOrSymptom', 'A sign or symptom of this condition. Signs are objective or physically observable manifestations of the medical condition while symptoms are the subjective experience of the medical condition.'),
(5540, 1, 20, 'interestRate', 'interestRate', 'The interest rate, charged or paid, applicable to the financial product. Note: This is different from the calculated annualPercentageRate.'),
(5541, 1, 20, 'linkRelationship', 'linkRelationship', 'Indicates the relationship type of a Web link. '),
(5542, 1, 20, 'interpretedAsClaim', 'interpretedAsClaim', 'Used to indicate a specific claim contained, implied, translated or refined from the content of a [[MediaObject]] or other [[CreativeWork]]. The interpreting party can be indicated using [[claimInterpreter]].'),
(5543, 1, 20, 'publisher', 'publisher', 'The publisher of the creative work.'),
(5544, 1, 20, 'credentialCategory', 'credentialCategory', 'The category or type of credential being described, for example \"degree”, “certificate”, “badge”, or more specific term.'),
(5545, 1, 20, 'baseSalary', 'baseSalary', 'The base salary of the job or of an employee in an EmployeeRole.'),
(5546, 1, 20, 'significantLinks', 'significantLinks', 'The most significant URLs on the page. Typically, these are the non-navigation links that are clicked on the most.'),
(5547, 1, 20, 'referencesOrder', 'referencesOrder', 'The Order(s) related to this Invoice. One or more Orders may be combined into a single Invoice.'),
(5548, 1, 20, 'readBy', 'readBy', 'A person who reads (performs) the audiobook.'),
(5549, 1, 20, 'amountOfThisGood', 'amountOfThisGood', 'The quantity of the goods included in the offer.'),
(5550, 1, 20, 'value', 'value', 'The value of a [[QuantitativeValue]] (including [[Observation]]) or property value node.\\n\\n* For [[QuantitativeValue]] and [[MonetaryAmount]], the recommended type for values is \'Number\'.\\n* For [[PropertyValue]], it can be \'Text\', \'Number\', \'Boolean\', or \'StructuredValue\'.\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(5551, 1, 20, 'recourseLoan', 'recourseLoan', 'The only way you get the money back in the event of default is the security. Recourse is where you still have the opportunity to go back to the borrower for the rest of the money.'),
(5552, 1, 20, 'geoDisjoint', 'geoDisjoint', 'Represents spatial relations in which two geometries (or the places they represent) are topologically disjoint: \"they have no point in common. They form a set of disconnected geometries.\" (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)'),
(5553, 1, 20, 'opponent', 'opponent', 'A sub property of participant. The opponent on this action.'),
(5554, 1, 20, 'reportNumber', 'reportNumber', 'The number or other unique designator assigned to a Report by the publishing organization.'),
(5555, 1, 20, 'videoFrameSize', 'videoFrameSize', 'The frame size of the video.'),
(5556, 1, 20, 'isRelatedTo', 'isRelatedTo', 'A pointer to another, somehow related product (or multiple products).'),
(5557, 1, 20, 'musicalKey', 'musicalKey', 'The key, mode, or scale this composition uses.'),
(5558, 1, 20, 'hoursAvailable', 'hoursAvailable', 'The hours during which this service or contact is available.'),
(5559, 1, 20, 'dropoffLocation', 'dropoffLocation', 'Where a rental car can be dropped off.'),
(5560, 1, 20, 'offersPrescriptionByMail', 'offersPrescriptionByMail', 'Whether prescriptions can be delivered by mail.'),
(5561, 1, 20, 'nextItem', 'nextItem', 'A link to the ListItem that follows the current one.'),
(5562, 1, 20, 'incentives', 'incentives', 'Description of bonus and commission compensation aspects of the job.'),
(5563, 1, 20, 'administrationRoute', 'administrationRoute', 'A route by which this drug may be administered, e.g. \'oral\'.'),
(5564, 1, 20, 'cvdNumVentUse', 'cvdNumVentUse', 'numventuse - MECHANICAL VENTILATORS IN USE: Total number of ventilators in use.'),
(5565, 1, 20, 'reservationFor', 'reservationFor', 'The thing -- flight, event, restaurant, etc. being reserved.'),
(5566, 1, 20, 'requirements', 'requirements', 'Component dependency requirements for application. This includes runtime environments and shared libraries that are not included in the application distribution package, but required to run the application (examples: DirectX, Java or .NET runtime).'),
(5567, 1, 20, 'softwareRequirements', 'softwareRequirements', 'Component dependency requirements for application. This includes runtime environments and shared libraries that are not included in the application distribution package, but required to run the application (examples: DirectX, Java or .NET runtime).'),
(5568, 1, 20, 'status', 'status', 'The status of the study (enumerated).'),
(5569, 1, 20, 'valueName', 'valueName', 'Indicates the name of the PropertyValueSpecification to be used in URL templates and form encoding in a manner analogous to HTML\'s input@name.'),
(5570, 1, 20, 'numberOfAccommodationUnits', 'numberOfAccommodationUnits', 'Indicates the total (available plus unavailable) number of accommodation units in an [[ApartmentComplex]], or the number of accommodation units for a specific [[FloorPlan]] (within its specific [[ApartmentComplex]]). See also [[numberOfAvailableAccommodationUnits]].'),
(5571, 1, 20, 'currentExchangeRate', 'currentExchangeRate', 'The current price of a currency.'),
(5572, 1, 20, 'hasDeliveryMethod', 'hasDeliveryMethod', 'Method used for delivery or shipping.'),
(5573, 1, 20, 'productionCompany', 'productionCompany', 'The production company or studio responsible for the item, e.g. series, video game, episode etc.'),
(5574, 1, 20, 'healthCondition', 'healthCondition', 'Specifying the health condition(s) of a patient, medical study, or other target audience.'),
(5575, 1, 20, 'suggestedMeasurement', 'suggestedMeasurement', 'A suggested range of body measurements for the intended audience or person, for example inseam between 32 and 34 inches or height between 170 and 190 cm. Typically found on a size chart for wearable products.'),
(5576, 1, 20, 'remainingAttendeeCapacity', 'remainingAttendeeCapacity', 'The number of attendee places for an event that remain unallocated.'),
(5577, 1, 20, 'trailerWeight', 'trailerWeight', 'The permitted weight of a trailer attached to the vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(5578, 1, 20, 'creativeWorkStatus', 'creativeWorkStatus', 'The status of a creative work in terms of its stage in a lifecycle. Example terms include Incomplete, Draft, Published, Obsolete. Some organizations define a set of terms for the stages of their publication lifecycle.'),
(5579, 1, 20, 'storageRequirements', 'storageRequirements', 'Storage requirements (free space required).'),
(5580, 1, 20, 'duplicateTherapy', 'duplicateTherapy', 'A therapy that duplicates or overlaps this one.'),
(5581, 1, 20, 'legislationDate', 'legislationDate', 'The date of adoption or signature of the legislation. This is the date at which the text is officially aknowledged to be a legislation, even though it might not even be published or in force.'),
(5582, 1, 20, 'monoisotopicMolecularWeight', 'monoisotopicMolecularWeight', 'The monoisotopic mass is the sum of the masses of the atoms in a molecule using the unbound, ground-state, rest mass of the principal (most abundant) isotope for each element instead of the isotopic average mass. Please include the units in the form \'&lt;Number&gt; &lt;unit&gt;\', for example \'770.230488 g/mol\' or as \'&lt;QuantitativeValue&gt;.'),
(5583, 1, 20, 'color', 'color', 'The color of the product.'),
(5584, 1, 20, 'biologicalRole', 'biologicalRole', 'A role played by the BioChemEntity within a biological context.'),
(5585, 1, 20, 'occupationLocation', 'occupationLocation', ' The region/country for which this occupational description is appropriate. Note that educational requirements and qualifications can vary between jurisdictions.'),
(5586, 1, 20, 'produces', 'produces', 'The tangible thing generated by the service, e.g. a passport, permit, etc.'),
(5587, 1, 20, 'serviceOutput', 'serviceOutput', 'The tangible thing generated by the service, e.g. a passport, permit, etc.'),
(5588, 1, 20, 'audio', 'audio', 'An embedded audio object.'),
(5589, 1, 20, 'subReservation', 'subReservation', 'The individual reservations included in the package. Typically a repeated property.'),
(5590, 1, 20, 'educationalUse', 'educationalUse', 'The purpose of a work in the context of education; for example, \'assignment\', \'group work\'.'),
(5591, 1, 20, 'increasesRiskOf', 'increasesRiskOf', 'The condition, complication, etc. influenced by this factor.'),
(5592, 1, 20, 'processorRequirements', 'processorRequirements', 'Processor architecture required to run the application (e.g. IA64).'),
(5593, 1, 20, 'renegotiableLoan', 'renegotiableLoan', 'Whether the terms for payment of interest can be renegotiated during the life of the loan.'),
(5594, 1, 20, 'downPayment', 'downPayment', 'a type of payment made in cash during the onset of the purchase of an expensive good/service. The payment typically represents only a percentage of the full purchase price.'),
(5595, 1, 20, 'wordCount', 'wordCount', 'The number of words in the text of the Article.'),
(5596, 1, 20, 'priceCurrency', 'priceCurrency', 'The currency of the price, or a price component when attached to [[PriceSpecification]] and its subtypes.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(5597, 1, 20, 'nerve', 'nerve', 'The underlying innervation associated with the muscle.'),
(5598, 1, 20, 'countriesSupported', 'countriesSupported', 'Countries for which the application is supported. You can also provide the two-letter ISO 3166-1 alpha-2 country code.'),
(5599, 1, 20, 'countryOfOrigin', 'countryOfOrigin', 'The country of origin of something, including products as well as creative  works such as movie and TV content.\n\nIn the case of TV and movie, this would be the country of the principle offices of the production company or individual responsible for the movie. For other kinds of [[CreativeWork]] it is difficult to provide fully general guidance, and properties such as [[contentLocation]] and [[locationCreated]] may be more applicable.\n\nIn the case of products, the country of origin of the product. The exact interpretation of this may vary by context and product type, and cannot be fully enumerated here.'),
(5600, 1, 20, 'taxonRank', 'taxonRank', 'The taxonomic rank of this taxon given preferably as a URI from a controlled vocabulary – typically the ranks from TDWG TaxonRank ontology or equivalent Wikidata URIs.'),
(5601, 1, 20, 'servicePostalAddress', 'servicePostalAddress', 'The address for accessing the service by mail.'),
(5602, 1, 20, 'broadcastFrequencyValue', 'broadcastFrequencyValue', 'The frequency in MHz for a particular broadcast.'),
(5603, 1, 20, 'applicationContact', 'applicationContact', 'Contact details for further information relevant to this job posting.'),
(5604, 1, 20, 'numberOfCredits', 'numberOfCredits', 'The number of credits or units awarded by a Course or required to complete an EducationalOccupationalProgram.'),
(5605, 1, 20, 'gtin14', 'gtin14', 'The GTIN-14 code of the product, or the product to which the offer refers. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(5606, 1, 20, 'interactivityType', 'interactivityType', 'The predominant mode of learning supported by the learning resource. Acceptable values are \'active\', \'expositive\', or \'mixed\'.'),
(5607, 1, 20, 'softwareAddOn', 'softwareAddOn', 'Additional content for a software application.'),
(5608, 1, 20, 'valuePattern', 'valuePattern', 'Specifies a regular expression for testing literal values according to the HTML spec.'),
(5609, 1, 20, 'postOfficeBoxNumber', 'postOfficeBoxNumber', 'The post office box number for PO box addresses.'),
(5610, 1, 20, 'subStructure', 'subStructure', 'Component (sub-)structure(s) that comprise this anatomical structure.'),
(5611, 1, 20, 'eventSchedule', 'eventSchedule', 'Associates an [[Event]] with a [[Schedule]]. There are circumstances where it is preferable to share a schedule for a series of\n      repeating events rather than data on the individual events themselves. For example, a website or application might prefer to publish a schedule for a weekly\n      gym class rather than provide data on every event. A schedule could be processed by applications to add forthcoming events to a calendar. An [[Event]] that\n      is associated with a [[Schedule]] using this property should not have [[startDate]] or [[endDate]] properties. These are instead defined within the associated\n      [[Schedule]], this avoids any ambiguity for clients using the data. The property might have repeated values to specify different schedules, e.g. for different months\n      or seasons.'),
(5612, 1, 20, 'reviewRating', 'reviewRating', 'The rating given in this review. Note that reviews can themselves be rated. The ```reviewRating``` applies to rating given by the review. The [[aggregateRating]] property applies to the review itself, as a creative work.'),
(5613, 1, 20, 'typeOfGood', 'typeOfGood', 'The product that this structured value is referring to.'),
(5614, 1, 20, 'proprietaryName', 'proprietaryName', 'Proprietary name given to the diet plan, typically by its originator or creator.'),
(5615, 1, 20, 'deliveryTime', 'deliveryTime', 'The total delay between the receipt of the order and the goods reaching the final customer.'),
(5616, 1, 20, 'height', 'height', 'The height of the item.'),
(5617, 1, 20, 'characterAttribute', 'characterAttribute', 'A piece of data that represents a particular aspect of a fictional character (skill, power, character points, advantage, disadvantage).'),
(5618, 1, 20, 'ownershipFundingInfo', 'ownershipFundingInfo', 'For an [[Organization]] (often but not necessarily a [[NewsMediaOrganization]]), a description of organizational ownership structure; funding and grants. In a news/media setting, this is with particular reference to editorial independence.   Note that the [[funder]] is also available and can be used to make basic funder information machine-readable.'),
(5619, 1, 20, 'legislationPassedBy', 'legislationPassedBy', 'The person or organization that originally passed or made the law: typically parliament (for primary legislation) or government (for secondary legislation). This indicates the \"legal author\" of the law, as opposed to its physical author.'),
(5620, 1, 20, 'creator', 'creator', 'The creator/author of this CreativeWork. This is the same as the Author property for CreativeWork.'),
(5621, 1, 20, 'observationAbout', 'observationAbout', 'The [[observationAbout]] property identifies an entity, often a [[Place]], associated with an [[Observation]].'),
(5622, 1, 20, 'accessCode', 'accessCode', 'Password, PIN, or access code needed for delivery (e.g. from a locker).'),
(5623, 1, 20, 'temporalCoverage', 'temporalCoverage', 'The temporalCoverage of a CreativeWork indicates the period that the content applies to, i.e. that it describes, either as a DateTime or as a textual string indicating a time period in [ISO 8601 time interval format](https://en.wikipedia.org/wiki/ISO_8601#Time_intervals). In\n      the case of a Dataset it will typically indicate the relevant time period in a precise notation (e.g. for a 2011 census dataset, the year 2011 would be written \"2011/2012\"). Other forms of content, e.g. ScholarlyArticle, Book, TVSeries or TVEpisode, may indicate their temporalCoverage in broader terms - textually or via well-known URL.\n      Written works such as books may sometimes have precise temporal coverage too, e.g. a work set in 1939 - 1945 can be indicated in ISO 8601 interval format format via \"1939/1945\".\n\nOpen-ended date ranges can be written with \"..\" in place of the end date. For example, \"2015-11/..\" indicates a range beginning in November 2015 and with no specified final date. This is tentative and might be updated in future when ISO 8601 is officially updated.'),
(5624, 1, 20, 'playMode', 'playMode', 'Indicates whether this game is multi-player, co-op or single-player.  The game can be marked as multi-player, co-op and single-player at the same time.'),
(5625, 1, 20, 'governmentBenefitsInfo', 'governmentBenefitsInfo', 'governmentBenefitsInfo provides information about government benefits associated with a SpecialAnnouncement.'),
(5626, 1, 20, 'maps', 'maps', 'A URL to a map of the place.'),
(5627, 1, 20, 'primaryPrevention', 'primaryPrevention', 'A preventative therapy used to prevent an initial occurrence of the medical condition, such as vaccination.'),
(5628, 1, 20, 'sdLicense', 'sdLicense', 'A license document that applies to this structured data, typically indicated by URL.'),
(5629, 1, 20, 'discountCode', 'discountCode', 'Code used to redeem a discount.'),
(5630, 1, 20, 'numberOfAxles', 'numberOfAxles', 'The number of axles.\\n\\nTypical unit code(s): C62.'),
(5631, 1, 20, 'followup', 'followup', 'Typical or recommended followup care after the procedure is performed.'),
(5632, 1, 20, 'offerCount', 'offerCount', 'The number of offers for the product.'),
(5633, 1, 20, 'customerRemorseReturnFees', 'customerRemorseReturnFees', 'The type of return fees if the product is returned due to customer remorse.'),
(5634, 1, 20, 'openingHoursSpecification', 'openingHoursSpecification', 'The opening hours of a certain place.'),
(5635, 1, 20, 'accountId', 'accountId', 'The identifier for the account the payment will be applied to.'),
(5636, 1, 20, 'sizeGroup', 'sizeGroup', 'The size group (also known as \"size type\") for a product\'s size. Size groups are common in the fashion industry to define size segments and suggested audiences for wearable products. Multiple values can be combined, for example \"men\'s big and tall\", \"petite maternity\" or \"regular\".'),
(5637, 1, 20, 'publisherImprint', 'publisherImprint', 'The publishing division which published the comic.'),
(5638, 1, 20, 'answerExplanation', 'answerExplanation', 'A step-by-step or full explanation about Answer. Can outline how this Answer was achieved or contain more broad clarification or statement about it. '),
(5639, 1, 20, 'gender', 'gender', 'Gender of something, typically a [[Person]], but possibly also fictional characters, animals, etc. While http://schema.org/Male and http://schema.org/Female may be used, text strings are also acceptable for people who do not identify as a binary gender. The [[gender]] property can also be used in an extended sense to cover e.g. the gender of sports teams. As with the gender of individuals, we do not try to enumerate all possibilities. A mixed-gender [[SportsTeam]] can be indicated with a text value of \"Mixed\".'),
(5640, 1, 20, 'educationRequirements', 'educationRequirements', 'Educational background needed for the position or Occupation.'),
(5641, 1, 20, 'assembly', 'assembly', 'Library file name, e.g., mscorlib.dll, system.web.dll.'),
(5642, 1, 20, 'isAccessoryOrSparePartFor', 'isAccessoryOrSparePartFor', 'A pointer to another product (or multiple products) for which this product is an accessory or spare part.'),
(5643, 1, 20, 'sha256', 'sha256', 'The [SHA-2](https://en.wikipedia.org/wiki/SHA-2) SHA256 hash of the content of the item. For example, a zero-length input has value \'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\'.'),
(5644, 1, 20, 'geoContains', 'geoContains', 'Represents a relationship between two geometries (or the places they represent), relating a containing geometry to a contained geometry. \"a contains b iff no points of b lie in the exterior of a, and at least one point of the interior of b lies in the interior of a\". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(5645, 1, 20, 'addressRegion', 'addressRegion', 'The region in which the locality is, and which is in the country. For example, California or another appropriate first-level [Administrative division](https://en.wikipedia.org/wiki/List_of_administrative_divisions_by_country).'),
(5646, 1, 20, 'afterMedia', 'afterMedia', 'A media object representing the circumstances after performing this direction.'),
(5647, 1, 20, 'monthlyMinimumRepaymentAmount', 'monthlyMinimumRepaymentAmount', 'The minimum payment is the lowest amount of money that one is required to pay on a credit card statement each month.'),
(5648, 1, 20, 'postalCodePrefix', 'postalCodePrefix', 'A defined range of postal codes indicated by a common textual prefix. Used for non-numeric systems such as UK.'),
(5649, 1, 20, 'programPrerequisites', 'programPrerequisites', 'Prerequisites for enrolling in the program.'),
(5650, 1, 20, 'accountablePerson', 'accountablePerson', 'Specifies the Person that is legally accountable for the CreativeWork.'),
(5651, 1, 20, 'shippingDetails', 'shippingDetails', 'Indicates information about the shipping policies and options associated with an [[Offer]].'),
(5652, 1, 20, 'workTranslation', 'workTranslation', 'A work that is a translation of the content of this work. E.g. 西遊記 has an English workTranslation “Journey to the West”, a German workTranslation “Monkeys Pilgerfahrt” and a Vietnamese  translation Tây du ký bình khảo.'),
(5653, 1, 20, 'translationOfWork', 'translationOfWork', 'The work that this work has been translated from. E.g. 物种起源 is a translationOf “On the Origin of Species”.'),
(5654, 1, 20, 'carbohydrateContent', 'carbohydrateContent', 'The number of grams of carbohydrates.'),
(5655, 1, 20, 'artform', 'artform', 'e.g. Painting, Drawing, Sculpture, Print, Photograph, Assemblage, Collage, etc.'),
(5656, 1, 20, 'sameAs', 'sameAs', 'URL of a reference Web page that unambiguously indicates the item\'s identity. E.g. the URL of the item\'s Wikipedia page, Wikidata entry, or official website.'),
(5657, 1, 20, 'inventoryLevel', 'inventoryLevel', 'The current approximate inventory level for the item or items.'),
(5658, 1, 20, 'partOfSeries', 'partOfSeries', 'The series to which this episode or season belongs.'),
(5659, 1, 20, 'tracks', 'tracks', 'A music recording (track)&#x2014;usually a single song.'),
(5660, 1, 20, 'track', 'track', 'A music recording (track)&#x2014;usually a single song. If an ItemList is given, the list should contain items of type MusicRecording.'),
(5661, 1, 20, 'startOffset', 'startOffset', 'The start time of the clip expressed as the number of seconds from the beginning of the work.'),
(5662, 1, 20, 'phoneticText', 'phoneticText', 'Representation of a text [[textValue]] using the specified [[speechToTextMarkup]]. For example the city name of Houston in IPA: /ˈhjuːstən/.'),
(5663, 1, 20, 'numberOfRooms', 'numberOfRooms', 'The number of rooms (excluding bathrooms and closets) of the accommodation or lodging business.\nTypical unit code(s): ROM for room or C62 for no unit. The type of room can be put in the unitText property of the QuantitativeValue.'),
(5664, 1, 20, 'requiredGender', 'requiredGender', 'Audiences defined by a person\'s gender.'),
(5665, 1, 20, 'contentRating', 'contentRating', 'Official rating of a piece of content&#x2014;for example, \'MPAA PG-13\'.'),
(5666, 1, 20, 'legislationIdentifier', 'legislationIdentifier', 'An identifier for the legislation. This can be either a string-based identifier, like the CELEX at EU level or the NOR in France, or a web-based, URL/URI identifier, like an ELI (European Legislation Identifier) or an URN-Lex.'),
(5667, 1, 20, 'studyLocation', 'studyLocation', 'The location in which the study is taking/took place.'),
(5668, 1, 20, 'repeatFrequency', 'repeatFrequency', 'Defines the frequency at which [[Event]]s will occur according to a schedule [[Schedule]]. The intervals between\n      events should be defined as a [[Duration]] of time.'),
(5669, 1, 20, 'orderQuantity', 'orderQuantity', 'The number of the item ordered. If the property is not set, assume the quantity is one.'),
(5670, 1, 20, 'businessFunction', 'businessFunction', 'The business function (e.g. sell, lease, repair, dispose) of the offer or component of a bundle (TypeAndQuantityNode). The default is http://purl.org/goodrelations/v1#Sell.'),
(5671, 1, 20, 'itemCondition', 'itemCondition', 'A predefined value from OfferItemCondition specifying the condition of the product or service, or the products or services included in the offer. Also used for product return policies to specify the condition of products accepted for returns.'),
(5672, 1, 20, 'awards', 'awards', 'Awards won by or for this item.'),
(5673, 1, 20, 'spatial', 'spatial', 'The \"spatial\" property can be used in cases when more specific properties\n(e.g. [[locationCreated]], [[spatialCoverage]], [[contentLocation]]) are not known to be appropriate.'),
(5674, 1, 20, 'specialCommitments', 'specialCommitments', 'Any special commitments associated with this job posting. Valid entries include VeteranCommit, MilitarySpouseCommit, etc.'),
(5675, 1, 20, 'containedIn', 'containedIn', 'The basic containment relation between a place and one that contains it.'),
(5676, 1, 20, 'trialDesign', 'trialDesign', 'Specifics about the trial design (enumerated).'),
(5677, 1, 20, 'postalCodeRange', 'postalCodeRange', 'A defined range of postal codes.'),
(5678, 1, 20, 'mealService', 'mealService', 'Description of the meals that will be provided or available for purchase.'),
(5679, 1, 20, 'speed', 'speed', 'The speed range of the vehicle. If the vehicle is powered by an engine, the upper limit of the speed range (indicated by [[maxValue]]) should be the maximum speed achievable under regular conditions.\\n\\nTypical unit code(s): KMH for km/h, HM for mile per hour (0.447 04 m/s), KNT for knot\\n\\n*Note 1: Use [[minValue]] and [[maxValue]] to indicate the range. Typically, the minimal value is zero.\\n* Note 2: There are many different ways of measuring the speed range. You can link to information about how the given value has been determined using the [[valueReference]] property.'),
(5680, 1, 20, 'isbn', 'isbn', 'The ISBN of the book.'),
(5681, 1, 20, 'applicationSuite', 'applicationSuite', 'The name of the application suite to which the application belongs (e.g. Excel belongs to Office).'),
(5682, 1, 20, 'activityDuration', 'activityDuration', 'Length of time to engage in the activity.'),
(5683, 1, 20, 'actionAccessibilityRequirement', 'actionAccessibilityRequirement', 'A set of requirements that must be fulfilled in order to perform an Action. If more than one value is specified, fulfilling one set of requirements will allow the Action to be performed.'),
(5684, 1, 20, 'entertainmentBusiness', 'entertainmentBusiness', 'A sub property of location. The entertainment business where the action occurred.'),
(5685, 1, 20, 'availableIn', 'availableIn', 'The location in which the strength is available.'),
(5686, 1, 20, 'pageEnd', 'pageEnd', 'The page on which the work ends; for example \"138\" or \"xvi\".'),
(5687, 1, 20, 'numberOfLoanPayments', 'numberOfLoanPayments', 'The number of payments contractually required at origination to repay the loan. For monthly paying loans this is the number of months from the contractual first payment date to the maturity date.'),
(5688, 1, 20, 'width', 'width', 'The width of the item.'),
(5689, 1, 20, 'totalPrice', 'totalPrice', 'The total price for the reservation or ticket, including applicable taxes, shipping, etc.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(5690, 1, 20, 'assesses', 'assesses', 'The item being described is intended to assess the competency or learning outcome defined by the referenced term.'),
(5691, 1, 20, 'playersOnline', 'playersOnline', 'Number of players on the server.'),
(5692, 1, 20, 'datasetTimeInterval', 'datasetTimeInterval', 'The range of temporal applicability of a dataset, e.g. for a 2011 census dataset, the year 2011 (in ISO 8601 time interval format).'),
(5693, 1, 20, 'travelBans', 'travelBans', 'Information about travel bans, e.g. in the context of a pandemic.'),
(5694, 1, 20, 'foundingLocation', 'foundingLocation', 'The place where the Organization was founded.'),
(5695, 1, 20, 'costCategory', 'costCategory', 'The category of cost, such as wholesale, retail, reimbursement cap, etc.'),
(5696, 1, 20, 'schemaVersion', 'schemaVersion', 'Indicates (by URL or string) a particular version of a schema used in some CreativeWork. This property was created primarily to\n    indicate the use of a specific schema.org release, e.g. ```10.0``` as a simple string, or more explicitly via URL, ```http://schema.org/docs/releases.html#v10.0```. There may be situations in which other schemas might usefully be referenced this way, e.g. ```http://dublincore.org/specifications/dublin-core/dces/1999-07-02/``` but this has not been carefully explored in the community.'),
(5697, 1, 20, 'deliveryLeadTime', 'deliveryLeadTime', 'The typical delay between the receipt of the order and the goods either leaving the warehouse or being prepared for pickup, in case the delivery method is on site pickup.'),
(5698, 1, 20, 'requiredQuantity', 'requiredQuantity', 'The required quantity of the item(s).'),
(5699, 1, 20, 'bitrate', 'bitrate', 'The bitrate of the media object.'),
(5700, 1, 20, 'productReturnDays', 'productReturnDays', 'The productReturnDays property indicates the number of days (from purchase) within which relevant product return policy is applicable.'),
(5701, 1, 20, 'merchantReturnDays', 'merchantReturnDays', 'Specifies either a fixed return date or the number of days (from the delivery date) that a product can be returned. Used when the [[returnPolicyCategory]] property is specified as [[MerchantReturnFiniteReturnWindow]].'),
(5702, 1, 20, 'distribution', 'distribution', 'A downloadable form of this dataset, at a specific location, in a specific format. This property can be repeated if different variations are available. There is no expectation that different downloadable distributions must contain exactly equivalent information (see also [DCAT](https://www.w3.org/TR/vocab-dcat-3/#Class:Distribution) on this point). Different distributions might include or exclude different subsets of the entire dataset, for example.'),
(5703, 1, 20, 'workPresented', 'workPresented', 'The movie presented during this event.'),
(5704, 1, 20, 'embedUrl', 'embedUrl', 'A URL pointing to a player for a specific video. In general, this is the information in the ```src``` element of an ```embed``` tag and should not be the same as the content of the ```loc``` tag.'),
(5705, 1, 20, 'downloadUrl', 'downloadUrl', 'If the file can be downloaded, URL to download the binary.'),
(5706, 1, 20, 'isConsumableFor', 'isConsumableFor', 'A pointer to another product (or multiple products) for which this product is a consumable.'),
(5707, 1, 20, 'diversityStaffingReport', 'diversityStaffingReport', 'For an [[Organization]] (often but not necessarily a [[NewsMediaOrganization]]), a report on staffing diversity issues. In a news context this might be for example ASNE or RTDNA (US) reports, or self-reported.'),
(5708, 1, 20, 'locationCreated', 'locationCreated', 'The location where the CreativeWork was created, which may not be the same as the location depicted in the CreativeWork.'),
(5709, 1, 20, 'teaches', 'teaches', 'The item being described is intended to help a person learn the competency or learning outcome defined by the referenced term.'),
(5710, 1, 20, 'healthPlanId', 'healthPlanId', 'The 14-character, HIOS-generated Plan ID number. (Plan IDs must be unique, even across different markets.)'),
(5711, 1, 20, 'prescribingInfo', 'prescribingInfo', 'Link to prescribing information for the drug.'),
(5712, 1, 20, 'naturalProgression', 'naturalProgression', 'The expected progression of the condition if it is not treated and allowed to progress naturally.'),
(5713, 1, 20, 'permissionType', 'permissionType', 'The type of permission granted the person, organization, or audience.'),
(5714, 1, 20, 'subTest', 'subTest', 'A component test of the panel.'),
(5715, 1, 20, 'chemicalComposition', 'chemicalComposition', 'The chemical composition describes the identity and relative ratio of the chemical elements that make up the substance.'),
(5716, 1, 20, 'grantee', 'grantee', 'The person, organization, contact point, or audience that has been granted this permission.'),
(5717, 1, 20, 'dependencies', 'dependencies', 'Prerequisites needed to fulfill steps in article.'),
(5718, 1, 20, 'mainEntity', 'mainEntity', 'Indicates the primary entity described in some page or other CreativeWork.'),
(5719, 1, 20, 'mainEntityOfPage', 'mainEntityOfPage', 'Indicates a page (or other CreativeWork) for which this thing is the main entity being described. See [background notes](/docs/datamodel.html#mainEntityBackground) for details.'),
(5720, 1, 20, 'conditionsOfAccess', 'conditionsOfAccess', 'Conditions that affect the availability of, or method(s) of access to, an item. Typically used for real world items such as an [[ArchiveComponent]] held by an [[ArchiveOrganization]]. This property is not suitable for use as a general Web access control mechanism. It is expressed only in natural language.\\n\\nFor example \"Available by appointment from the Reading Room\" or \"Accessible only from logged-in accounts \". '),
(5721, 1, 20, 'publication', 'publication', 'A publication event associated with the item.'),
(5722, 1, 20, 'doseUnit', 'doseUnit', 'The unit of the dose, e.g. \'mg\'.'),
(5723, 1, 20, 'legislationTransposes', 'legislationTransposes', 'Indicates that this legislation (or part of legislation) fulfills the objectives set by another legislation, by passing appropriate implementation measures. Typically, some legislations of European Union\'s member states or regions transpose European Directives. This indicates a legally binding link between the 2 legislations.'),
(5724, 1, 20, 'currenciesAccepted', 'currenciesAccepted', 'The currency accepted.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(5725, 1, 20, 'geoTouches', 'geoTouches', 'Represents spatial relations in which two geometries (or the places they represent) touch: \"they have at least one boundary point in common, but no interior points.\" (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)'),
(5726, 1, 20, 'orderItemNumber', 'orderItemNumber', 'The identifier of the order item.'),
(5727, 1, 20, 'suggestedMinAge', 'suggestedMinAge', 'Minimum recommended age in years for the audience or user.'),
(5728, 1, 20, 'medicineSystem', 'medicineSystem', 'The system of medicine that includes this MedicalEntity, for example \'evidence-based\', \'homeopathic\', \'chiropractic\', etc.'),
(5729, 1, 20, 'numberOfEpisodes', 'numberOfEpisodes', 'The number of episodes in this season or series.'),
(5730, 1, 20, 'materialExtent', 'materialExtent', 'The quantity of the materials being described or an expression of the physical space they occupy.'),
(5731, 1, 20, 'industry', 'industry', 'The industry associated with the job position.'),
(5732, 1, 20, 'legislationLegalValue', 'legislationLegalValue', 'The legal value of this legislation file. The same legislation can be written in multiple files with different legal values. Typically a digitally signed PDF have a \"stronger\" legal value than the HTML file of the same act.'),
(5733, 1, 20, 'requiresSubscription', 'requiresSubscription', 'Indicates if use of the media require a subscription  (either paid or free). Allowed values are ```true``` or ```false``` (note that an earlier version had \'yes\', \'no\').'),
(5734, 1, 20, 'connectedTo', 'connectedTo', 'Other anatomical structures to which this structure is connected.'),
(5735, 1, 20, 'departureTerminal', 'departureTerminal', 'Identifier of the flight\'s departure terminal.'),
(5736, 1, 20, 'physiologicalBenefits', 'physiologicalBenefits', 'Specific physiologic benefits associated to the plan.'),
(5737, 1, 20, 'sharedContent', 'sharedContent', 'A CreativeWork such as an image, video, or audio clip shared as part of this posting.'),
(5738, 1, 20, 'softwareVersion', 'softwareVersion', 'Version of the software instance.'),
(5739, 1, 20, 'measurementDenominator', 'measurementDenominator', 'Identifies the denominator variable when an observation represents a ratio or percentage.'),
(5740, 1, 20, 'slogan', 'slogan', 'A slogan or motto associated with the item.'),
(5741, 1, 20, 'trainNumber', 'trainNumber', 'The unique identifier for the train.'),
(5742, 1, 20, 'partOfTVSeries', 'partOfTVSeries', 'The TV series to which this episode or season belongs.'),
(5743, 1, 20, 'eligibleRegion', 'eligibleRegion', 'The ISO 3166-1 (ISO 3166-1 alpha-2) or ISO 3166-2 code, the place, or the GeoShape for the geo-political region(s) for which the offer or delivery charge specification is valid.\\n\\nSee also [[ineligibleRegion]].\n    '),
(5744, 1, 20, 'accessModeSufficient', 'accessModeSufficient', 'A list of single or combined accessModes that are sufficient to understand all the intellectual content of a resource. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessModeSufficient-vocabulary).'),
(5745, 1, 20, 'gracePeriod', 'gracePeriod', 'The period of time after any due date that the borrower has to fulfil its obligations before a default (failure to pay) is deemed to have occurred.'),
(5746, 1, 20, 'maintainer', 'maintainer', 'A maintainer of a [[Dataset]], software package ([[SoftwareApplication]]), or other [[Project]]. A maintainer is a [[Person]] or [[Organization]] that manages contributions to, and/or publication of, some (typically complex) artifact. It is common for distributions of software and data to be based on \"upstream\" sources. When [[maintainer]] is applied to a specific version of something e.g. a particular version or packaging of a [[Dataset]], it is always  possible that the upstream source has a different maintainer. The [[isBasedOn]] property can be used to indicate such relationships between datasets to make the different maintenance roles clear. Similarly in the case of software, a package may have dedicated maintainers working on integration into software distributions such as Ubuntu, as well as upstream maintainers of the underlying work.\n      '),
(5747, 1, 20, 'countryOfLastProcessing', 'countryOfLastProcessing', 'The place where the item (typically [[Product]]) was last processed and tested before importation.'),
(5748, 1, 20, 'causeOf', 'causeOf', 'The condition, complication, symptom, sign, etc. caused.'),
(5749, 1, 20, 'publicationType', 'publicationType', 'The type of the medical article, taken from the US NLM MeSH publication type catalog. See also [MeSH documentation](http://www.nlm.nih.gov/mesh/pubtypes.html).'),
(5750, 1, 20, 'lodgingUnitDescription', 'lodgingUnitDescription', 'A full description of the lodging unit.'),
(5751, 1, 20, 'providesService', 'providesService', 'The service provided by this channel.'),
(5752, 1, 20, 'rangeIncludes', 'rangeIncludes', 'Relates a property to a class that constitutes (one of) the expected type(s) for values of the property.'),
(5753, 1, 20, 'playerType', 'playerType', 'Player type required&#x2014;for example, Flash or Silverlight.'),
(5754, 1, 20, 'amenityFeature', 'amenityFeature', 'An amenity feature (e.g. a characteristic or service) of the Accommodation. This generic property does not make a statement about whether the feature is included in an offer for the main accommodation or available at extra costs.'),
(5755, 1, 20, 'risks', 'risks', 'Specific physiologic risks associated to the diet plan.'),
(5756, 1, 20, 'percentile75', 'percentile75', 'The 75th percentile value.'),
(5757, 1, 20, 'course', 'course', 'A sub property of location. The course where this action was taken.'),
(5758, 1, 20, 'referenceQuantity', 'referenceQuantity', 'The reference quantity for which a certain price applies, e.g. 1 EUR per 4 kWh of electricity. This property is a replacement for unitOfMeasurement for the advanced cases where the price does not relate to a standard unit.'),
(5759, 1, 20, 'featureList', 'featureList', 'Features or modules provided by this application (and possibly required by other applications).'),
(5760, 1, 20, 'benefits', 'benefits', 'Description of benefits associated with the job.'),
(5761, 1, 20, 'reservationId', 'reservationId', 'A unique identifier for the reservation.'),
(5762, 1, 20, 'doorTime', 'doorTime', 'The time admission will commence.'),
(5763, 1, 20, 'founders', 'founders', 'A person who founded this organization.'),
(5764, 1, 20, 'educationalCredentialAwarded', 'educationalCredentialAwarded', 'A description of the qualification, award, certificate, diploma or other educational credential awarded as a consequence of successful completion of this course or program.'),
(5765, 1, 20, 'torque', 'torque', 'The torque (turning force) of the vehicle\'s engine.\\n\\nTypical unit code(s): NU for newton metre (N m), F17 for pound-force per foot, or F48 for pound-force per inch\\n\\n* Note 1: You can link to information about how the given value has been determined (e.g. reference RPM) using the [[valueReference]] property.\\n* Note 2: You can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(5766, 1, 20, 'seatingType', 'seatingType', 'The type/class of the seat.'),
(5767, 1, 20, 'domiciledMortgage', 'domiciledMortgage', 'Whether borrower is a resident of the jurisdiction where the property is located.'),
(5768, 1, 20, 'diseaseSpreadStatistics', 'diseaseSpreadStatistics', 'Statistical information about the spread of a disease, either as [[WebContent]], or\n  described directly as a [[Dataset]], or the specific [[Observation]]s in the dataset. When a [[WebContent]] URL is\n  provided, the page indicated might also contain more such markup.'),
(5769, 1, 20, 'dateIssued', 'dateIssued', 'The date the ticket was issued.'),
(5770, 1, 20, 'mediaAuthenticityCategory', 'mediaAuthenticityCategory', 'Indicates a MediaManipulationRatingEnumeration classification of a media object (in the context of how it was published or shared).'),
(5771, 1, 20, 'maximumPhysicalAttendeeCapacity', 'maximumPhysicalAttendeeCapacity', 'The maximum physical attendee capacity of an [[Event]] whose [[eventAttendanceMode]] is [[OfflineEventAttendanceMode]] (or the offline aspects, in the case of a [[MixedEventAttendanceMode]]). '),
(5772, 1, 20, 'maximumIntake', 'maximumIntake', 'Recommended intake of this supplement for a given population as defined by a specific recommending authority.'),
(5773, 1, 20, 'nonProprietaryName', 'nonProprietaryName', 'The generic name of this drug or supplement.'),
(5774, 1, 20, 'regionsAllowed', 'regionsAllowed', 'The regions where the media is allowed. If not specified, then it\'s assumed to be allowed everywhere. Specify the countries in [ISO 3166 format](http://en.wikipedia.org/wiki/ISO_3166).'),
(5775, 1, 20, 'caption', 'caption', 'The caption for this object. For downloadable machine formats (closed caption, subtitles etc.) use MediaObject and indicate the [[encodingFormat]].'),
(5776, 1, 20, 'attendee', 'attendee', 'A person or organization attending the event.'),
(5777, 1, 20, 'penciler', 'penciler', 'The individual who draws the primary narrative artwork.'),
(5778, 1, 20, 'workload', 'workload', 'Quantitative measure of the physiologic output of the exercise; also referred to as energy expenditure.'),
(5779, 1, 20, 'weight', 'weight', 'The weight of the product or person.'),
(5780, 1, 20, 'availableLanguage', 'availableLanguage', 'A language someone may use with or at the item, service or place. Please use one of the language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47). See also [[inLanguage]].'),
(5781, 1, 20, 'geoIntersects', 'geoIntersects', 'Represents spatial relations in which two geometries (or the places they represent) have at least one point in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(5782, 1, 20, 'accessibilityAPI', 'accessibilityAPI', 'Indicates that the resource is compatible with the referenced accessibility API. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityAPI-vocabulary).'),
(5783, 1, 20, 'title', 'title', 'The title of the job.'),
(5784, 1, 20, 'departurePlatform', 'departurePlatform', 'The platform from which the train departs.'),
(5785, 1, 20, 'arrivalBusStop', 'arrivalBusStop', 'The stop or station from which the bus arrives.'),
(5786, 1, 20, 'study', 'study', 'A medical study or trial related to this entity.'),
(5787, 1, 20, 'gtin12', 'gtin12', 'The GTIN-12 code of the product, or the product to which the offer refers. The GTIN-12 is the 12-digit GS1 Identification Key composed of a U.P.C. Company Prefix, Item Reference, and Check Digit used to identify trade items. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(5788, 1, 20, 'hasOccupation', 'hasOccupation', 'The Person\'s occupation. For past professions, use Role for expressing dates.'),
(5789, 1, 20, 'nsn', 'nsn', 'Indicates the [NATO stock number](https://en.wikipedia.org/wiki/NATO_Stock_Number) (nsn) of a [[Product]]. '),
(5790, 1, 20, 'tourBookingPage', 'tourBookingPage', 'A page providing information on how to book a tour of some [[Place]], such as an [[Accommodation]] or [[ApartmentComplex]] in a real estate setting, as well as other kinds of tours as appropriate.'),
(5791, 1, 20, 'free', 'free', 'A flag to signal that the item, event, or place is accessible for free.'),
(5792, 1, 20, 'duns', 'duns', 'The Dun & Bradstreet DUNS number for identifying an organization or business person.'),
(5793, 1, 20, 'gettingTestedInfo', 'gettingTestedInfo', 'Information about getting tested (for a [[MedicalCondition]]), e.g. in the context of a pandemic.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(5794, 1, 20, 'identifyingExam', 'identifyingExam', 'A physical examination that can identify this sign.'),
(5795, 1, 20, 'paymentMethodType', 'paymentMethodType', 'The type of a payment method.'),
(5796, 1, 20, 'accessibilityFeature', 'accessibilityFeature', 'Content features of the resource, such as accessible media, alternatives and supported enhancements for accessibility. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityFeature-vocabulary).'),
(5797, 1, 20, 'hospitalAffiliation', 'hospitalAffiliation', 'A hospital with which the physician or office is affiliated.'),
(5798, 1, 20, 'vehicleInteriorType', 'vehicleInteriorType', 'The type or material of the interior of the vehicle (e.g. synthetic fabric, leather, wood, etc.). While most interior types are characterized by the material used, an interior type can also be based on vehicle usage or target audience.'),
(5799, 1, 20, 'annualPercentageRate', 'annualPercentageRate', 'The annual rate that is charged for borrowing (or made by investing), expressed as a single percentage number that represents the actual yearly cost of funds over the term of a loan. This includes any fees or additional costs associated with the transaction.'),
(5800, 1, 20, 'maxPrice', 'maxPrice', 'The highest price if the price is a range.'),
(5801, 1, 20, 'messageAttachment', 'messageAttachment', 'A CreativeWork attached to the message.'),
(5802, 1, 20, 'targetDescription', 'targetDescription', 'The description of a node in an established educational framework.'),
(5803, 1, 20, 'text', 'text', 'The textual content of this CreativeWork.'),
(5804, 1, 20, 'validFrom', 'validFrom', 'The date when the item becomes valid.'),
(5805, 1, 20, 'competencyRequired', 'competencyRequired', 'Knowledge, skill, ability or personal attribute that must be demonstrated by a person or other entity in order to do something such as earn an Educational Occupational Credential or understand a LearningResource.'),
(5806, 1, 20, 'fuelEfficiency', 'fuelEfficiency', 'The distance traveled per unit of fuel used; most commonly miles per gallon (mpg) or kilometers per liter (km/L).\\n\\n* Note 1: There are unfortunately no standard unit codes for miles per gallon or kilometers per liter. Use [[unitText]] to indicate the unit of measurement, e.g. mpg or km/L.\\n* Note 2: There are two ways of indicating the fuel consumption, [[fuelConsumption]] (e.g. 8 liters per 100 km) and [[fuelEfficiency]] (e.g. 30 miles per gallon). They are reciprocal.\\n* Note 3: Often, the absolute value is useful only when related to driving speed (\"at 80 km/h\") or usage pattern (\"city traffic\"). You can use [[valueReference]] to link the value for the fuel economy to another value.'),
(5807, 1, 20, 'correction', 'correction', 'Indicates a correction to a [[CreativeWork]], either via a [[CorrectionComment]], textually or in another document.'),
(5808, 1, 20, 'productGroupID', 'productGroupID', 'Indicates a textual identifier for a ProductGroup.'),
(5809, 1, 20, 'hasHealthAspect', 'hasHealthAspect', 'Indicates the aspect or aspects specifically addressed in some [[HealthTopicContent]]. For example, that the content is an overview, or that it talks about treatment, self-care, treatments or their side-effects.'),
(5810, 1, 20, 'worstRating', 'worstRating', 'The lowest value allowed in this rating system.'),
(5811, 1, 20, 'termDuration', 'termDuration', 'The amount of time in a term as defined by the institution. A term is a length of time where students take one or more classes. Semesters and quarters are common units for term.'),
(5812, 1, 20, 'dateVehicleFirstRegistered', 'dateVehicleFirstRegistered', 'The date of the first registration of the vehicle with the respective public authorities.'),
(5813, 1, 20, 'drugUnit', 'drugUnit', 'The unit in which the drug is measured, e.g. \'5 mg tablet\'.'),
(5814, 1, 20, 'legislationDateVersion', 'legislationDateVersion', 'The point-in-time at which the provided description of the legislation is valid (e.g.: when looking at the law on the 2016-04-07 (= dateVersion), I get the consolidation of 2015-04-12 of the \"National Insurance Contributions Act 2015\")'),
(5815, 1, 20, 'utterances', 'utterances', 'Text of an utterances (spoken words, lyrics etc.) that occurs at a certain section of a media object, represented as a [[HyperTocEntry]].'),
(5816, 1, 20, 'activeIngredient', 'activeIngredient', 'An active ingredient, typically chemical compounds and/or biologic substances.'),
(5817, 1, 20, 'loanRepaymentForm', 'loanRepaymentForm', 'A form of paying back money previously borrowed from a lender. Repayment usually takes the form of periodic payments that normally include part principal plus interest in each payment.'),
(5818, 1, 20, 'cvdFacilityCounty', 'cvdFacilityCounty', 'Name of the County of the NHSN facility that this data record applies to. Use [[cvdFacilityId]] to identify the facility. To provide other details, [[healthcareReportingData]] can be used on a [[Hospital]] entry.'),
(5819, 1, 20, 'educationalRole', 'educationalRole', 'An educationalRole of an EducationalAudience.'),
(5820, 1, 20, 'normalRange', 'normalRange', 'Range of acceptable values for a typical patient, when applicable.'),
(5821, 1, 20, 'geoCoveredBy', 'geoCoveredBy', 'Represents a relationship between two geometries (or the places they represent), relating a geometry to another that covers it. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(5822, 1, 20, 'musicBy', 'musicBy', 'The composer of the soundtrack.'),
(5823, 1, 20, 'healthPlanNetworkTier', 'healthPlanNetworkTier', 'The tier(s) for this network.'),
(5824, 1, 20, 'abstract', 'abstract', 'An abstract is a short description that summarizes a [[CreativeWork]].'),
(5825, 1, 20, 'area', 'area', 'The area within which users can expect to reach the broadcast service.'),
(5826, 1, 20, 'appliesToDeliveryMethod', 'appliesToDeliveryMethod', 'The delivery method(s) to which the delivery charge or payment charge specification applies.'),
(5827, 1, 20, 'infectiousAgent', 'infectiousAgent', 'The actual infectious agent, such as a specific bacterium.'),
(5828, 1, 20, 'audienceType', 'audienceType', 'The target group associated with a given audience (e.g. veterans, car owners, musicians, etc.).'),
(5829, 1, 20, 'businessDays', 'businessDays', 'Days of the week when the merchant typically operates, indicated via opening hours markup.'),
(5830, 1, 20, 'billingIncrement', 'billingIncrement', 'This property specifies the minimal quantity and rounding increment that will be the basis for the billing. The unit of measurement is specified by the unitCode property.'),
(5831, 1, 20, 'hasTiers', 'hasTiers', 'The tiers of a member program.'),
(5832, 1, 20, 'isTierOf', 'isTierOf', 'The member program this tier is a part of.'),
(5833, 1, 20, 'fuelType', 'fuelType', 'The type of fuel suitable for the engine or engines of the vehicle. If the vehicle has only one engine, this property can be attached directly to the vehicle.'),
(5834, 1, 20, 'documentation', 'documentation', 'Further documentation describing the Web API in more detail.'),
(5835, 1, 20, 'financialAidEligible', 'financialAidEligible', 'A financial aid type or program which students may use to pay for tuition or fees associated with the program.'),
(5836, 1, 20, 'dataFeedElement', 'dataFeedElement', 'An item within a data feed. Data feeds may have many elements.'),
(5837, 1, 20, 'depth', 'depth', 'The depth of the item.'),
(5838, 1, 20, 'availabilityEnds', 'availabilityEnds', 'The end of the availability of the product or service included in the offer.'),
(5839, 1, 20, 'includedRiskFactor', 'includedRiskFactor', 'A modifiable or non-modifiable risk factor included in the calculation, e.g. age, coexisting condition.'),
(5840, 1, 20, 'alternativeOf', 'alternativeOf', 'Another gene which is a variation of this one.'),
(5841, 1, 20, 'actionableFeedbackPolicy', 'actionableFeedbackPolicy', 'For a [[NewsMediaOrganization]] or other news-related [[Organization]], a statement about public engagement activities (for news media, the newsroom’s), including involving the public - digitally or otherwise -- in coverage decisions, reporting and activities after publication.'),
(5842, 1, 20, 'sport', 'sport', 'A type of sport (e.g. Baseball).'),
(5843, 1, 20, 'bodyType', 'bodyType', 'Indicates the design and body style of the vehicle (e.g. station wagon, hatchback, etc.).'),
(5844, 1, 20, 'valueRequired', 'valueRequired', 'Whether the property must be filled in to complete the action.  Default is false.'),
(5845, 1, 20, 'colorSwatch', 'colorSwatch', 'A color swatch image, visualizing the color of a [[Product]]. Should match the textual description specified in the [[color]] property. This can be a URL or a fully described ImageObject.'),
(5846, 1, 20, 'aggregateRating', 'aggregateRating', 'The overall rating, based on a collection of reviews or ratings, of the item.'),
(5847, 1, 20, 'bookEdition', 'bookEdition', 'The edition of the book.'),
(5848, 1, 20, 'arrivalBoatTerminal', 'arrivalBoatTerminal', 'The terminal or port from which the boat arrives.'),
(5849, 1, 20, 'transFatContent', 'transFatContent', 'The number of grams of trans fat.'),
(5850, 1, 20, 'scheduleTimezone', 'scheduleTimezone', 'Indicates the timezone for which the time(s) indicated in the [[Schedule]] are given. The value provided should be among those listed in the IANA Time Zone Database.'),
(5851, 1, 20, 'suggestedMaxAge', 'suggestedMaxAge', 'Maximum recommended age in years for the audience or user.'),
(5852, 1, 20, 'recipe', 'recipe', 'A sub property of instrument. The recipe/instructions used to perform the action.'),
(5853, 1, 20, 'announcementLocation', 'announcementLocation', 'Indicates a specific [[CivicStructure]] or [[LocalBusiness]] associated with the SpecialAnnouncement. For example, a specific testing facility or business with special opening hours. For a larger geographic region like a quarantine of an entire region, use [[spatialCoverage]].'),
(5854, 1, 20, 'healthPlanCoinsuranceOption', 'healthPlanCoinsuranceOption', 'Whether the coinsurance applies before or after deductible, etc. TODO: Is this a closed set?'),
(5855, 1, 20, 'advanceBookingRequirement', 'advanceBookingRequirement', 'The amount of time that is required between accepting the offer and the actual usage of the resource or service.'),
(5856, 1, 20, 'taxonomicRange', 'taxonomicRange', 'The taxonomic grouping of the organism that expresses, encodes, or in some way related to the BioChemEntity.'),
(5857, 1, 20, 'icaoCode', 'icaoCode', 'ICAO identifier for an airport.'),
(5858, 1, 20, 'postalCodeEnd', 'postalCodeEnd', 'Last postal code in the range (included). Needs to be after [[postalCodeBegin]].'),
(5859, 1, 20, 'returnPolicyCategory', 'returnPolicyCategory', 'Specifies an applicable return policy (from an enumeration).'),
(5860, 1, 20, 'hostingOrganization', 'hostingOrganization', 'The Organization (airline, travelers\' club, retailer, etc.) the membership is made with or which offers the  MemberProgram.'),
(5861, 1, 20, 'exifData', 'exifData', 'exif data for this object.'),
(5862, 1, 20, 'sender', 'sender', 'A sub property of participant. The participant who is at the sending end of the action.'),
(5863, 1, 20, 'billingDuration', 'billingDuration', 'Specifies for how long this price (or price component) will be billed. Can be used, for example, to model the contractual duration of a subscription or payment plan. Type can be either a Duration or a Number (in which case the unit of measurement, for example month, is specified by the unitCode property).'),
(5864, 1, 20, 'sizeSystem', 'sizeSystem', 'The size system used to identify a product\'s size. Typically either a standard (for example, \"GS1\" or \"ISO-EN13402\"), country code (for example \"US\" or \"JP\"), or a measuring system (for example \"Metric\" or \"Imperial\").'),
(5865, 1, 20, 'minimumPaymentDue', 'minimumPaymentDue', 'The minimum payment required at this time.'),
(5866, 1, 20, 'greaterOrEqual', 'greaterOrEqual', 'This ordering relation for qualitative values indicates that the subject is greater than or equal to the object.'),
(5867, 1, 20, 'calories', 'calories', 'The number of calories.'),
(5868, 1, 20, 'numberOfPartialBathrooms', 'numberOfPartialBathrooms', 'Number of partial bathrooms - The total number of half and ¼ bathrooms in an [[Accommodation]]. This corresponds to the [BathroomsPartial field in RESO](https://ddwiki.reso.org/display/DDW17/BathroomsPartial+Field). '),
(5869, 1, 20, 'seeks', 'seeks', 'A pointer to products or services sought by the organization or person (demand).'),
(5870, 1, 20, 'requiredCollateral', 'requiredCollateral', 'Assets required to secure loan or credit repayments. It may take form of third party pledge, goods, financial instruments (cash, securities, etc.)'),
(5871, 1, 20, 'specialty', 'specialty', 'One of the domain specialities to which this web page\'s content applies.'),
(5872, 1, 20, 'negativeNotes', 'negativeNotes', 'Provides negative considerations regarding something, most typically in pro/con lists for reviews (alongside [[positiveNotes]]). For symmetry \n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described. Since product descriptions \ntend to emphasise positive claims, it may be relatively unusual to find [[negativeNotes]] used in this way. Nevertheless for the sake of symmetry, [[negativeNotes]] can be used on [[Product]].\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most negative is at the beginning of the list).'),
(5873, 1, 20, 'billingStart', 'billingStart', 'Specifies after how much time this price (or price component) becomes valid and billing starts. Can be used, for example, to model a price increase after the first year of a subscription. The unit of measurement is specified by the unitCode property.'),
(5874, 1, 20, 'drainsTo', 'drainsTo', 'The vasculature that the vein drains into.'),
(5875, 1, 20, 'rsvpResponse', 'rsvpResponse', 'The response (yes, no, maybe) to the RSVP.'),
(5876, 1, 20, 'labelDetails', 'labelDetails', 'Link to the drug\'s label details.'),
(5877, 1, 20, 'applicationSubCategory', 'applicationSubCategory', 'Subcategory of the application, e.g. \'Arcade Game\'.'),
(5878, 1, 20, 'applicableCountry', 'applicableCountry', 'A country where a particular merchant return policy applies to, for example the two-letter ISO 3166-1 alpha-2 country code.'),
(5879, 1, 20, 'expires', 'expires', 'Date the content expires and is no longer useful or available. For example a [[VideoObject]] or [[NewsArticle]] whose availability or relevance is time-limited, a [[ClaimReview]] fact check whose publisher wants to indicate that it may no longer be relevant (or helpful to highlight) after some date, or a [[Certification]] the validity has expired.'),
(5880, 1, 20, 'legislationType', 'legislationType', 'The type of the legislation. Examples of values are \"law\", \"act\", \"directive\", \"decree\", \"regulation\", \"statutory instrument\", \"loi organique\", \"règlement grand-ducal\", etc., depending on the country.'),
(5881, 1, 20, 'orderNumber', 'orderNumber', 'The identifier of the transaction.'),
(5882, 1, 20, 'sensoryUnit', 'sensoryUnit', 'The neurological pathway extension that inputs and sends information to the brain or spinal cord.'),
(5883, 1, 20, 'textValue', 'textValue', 'Text value being annotated.'),
(5884, 1, 20, 'greater', 'greater', 'This ordering relation for qualitative values indicates that the subject is greater than the object.'),
(5885, 1, 20, 'associatedDisease', 'associatedDisease', 'Disease associated to this BioChemEntity. Such disease can be a MedicalCondition or a URL. If you want to add an evidence supporting the association, please use PropertyValue.'),
(5886, 1, 20, 'warrantyPromise', 'warrantyPromise', 'The warranty promise(s) included in the offer.'),
(5887, 1, 20, 'expectedArrivalFrom', 'expectedArrivalFrom', 'The earliest date the package may arrive.'),
(5888, 1, 20, 'boardingGroup', 'boardingGroup', 'The airline-specific indicator of boarding order / preference.'),
(5889, 1, 20, 'doesNotShip', 'doesNotShip', 'Indicates when shipping to a particular [[shippingDestination]] is not available.'),
(5890, 1, 20, 'agentInteractionStatistic', 'agentInteractionStatistic', 'The number of completed interactions for this entity, in a particular role (the \'agent\'), in a particular action (indicated in the statistic), and in a particular context (i.e. interactionService).'),
(5891, 1, 20, 'cvdNumC19Died', 'cvdNumC19Died', 'numc19died - DEATHS: Patients with suspected or confirmed COVID-19 who died in the hospital, ED, or any overflow location.'),
(5892, 1, 20, 'shippingLabel', 'shippingLabel', 'Label to match an [[OfferShippingDetails]] with a [[ShippingRateSettings]] (within the context of a [[shippingSettingsLink]] cross-reference).'),
(5893, 1, 20, 'reservationStatus', 'reservationStatus', 'The current status of the reservation.'),
(5894, 1, 20, 'authenticator', 'authenticator', 'The Organization responsible for authenticating the user\'s subscription. For example, many media apps require a cable/satellite provider to authenticate your subscription before playing media.'),
(5895, 1, 20, 'transitTime', 'transitTime', 'The typical delay the order has been sent for delivery and the goods reach the final customer. Typical properties: minValue, maxValue, unitCode (d for DAY).'),
(5896, 1, 20, 'commentText', 'commentText', 'The text of the UserComment.'),
(5897, 1, 20, 'creditedTo', 'creditedTo', 'The group the release is credited to if different than the byArtist. For example, Red and Blue is credited to \"Stefani Germanotta Band\", but by Lady Gaga.'),
(5898, 1, 20, 'driveWheelConfiguration', 'driveWheelConfiguration', 'The drive wheel configuration, i.e. which roadwheels will receive torque from the vehicle\'s engine via the drivetrain.'),
(5899, 1, 20, 'postOp', 'postOp', 'A description of the postoperative procedures, care, and/or followups for this device.'),
(5900, 1, 20, 'upvoteCount', 'upvoteCount', 'The number of upvotes this question, answer or comment has received from the community.'),
(5901, 1, 20, 'servesCuisine', 'servesCuisine', 'The cuisine of the restaurant.'),
(5902, 1, 20, 'embeddedTextCaption', 'embeddedTextCaption', 'Represents textual captioning from a [[MediaObject]], e.g. text of a \'meme\'.'),
(5903, 1, 20, 'endorsee', 'endorsee', 'A sub property of participant. The person/organization being supported.'),
(5904, 1, 20, 'sdDatePublished', 'sdDatePublished', 'Indicates the date on which the current structured data was generated / published. Typically used alongside [[sdPublisher]].'),
(5905, 1, 20, 'availableAtOrFrom', 'availableAtOrFrom', 'The place(s) from which the offer can be obtained (e.g. store locations).'),
(5906, 1, 20, 'arrivalAirport', 'arrivalAirport', 'The airport where the flight terminates.'),
(5907, 1, 20, 'acceptsReservations', 'acceptsReservations', 'Indicates whether a FoodEstablishment accepts reservations. Values can be Boolean, an URL at which reservations can be made or (for backwards compatibility) the strings ```Yes``` or ```No```.'),
(5908, 1, 20, 'associatedMediaReview', 'associatedMediaReview', 'An associated [[MediaReview]], related by specific common content, topic or claim. The expectation is that this property would be most typically used in cases where a single activity is conducting both claim reviews and media reviews, in which case [[relatedMediaReview]] would commonly be used on a [[ClaimReview]], while [[relatedClaimReview]] would be used on [[MediaReview]].'),
(5909, 1, 20, 'endDate', 'endDate', 'The end date and time of the item (in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601)).'),
(5910, 1, 20, 'permitAudience', 'permitAudience', 'The target audience for this permit.'),
(5911, 1, 20, 'costCurrency', 'costCurrency', 'The currency (in 3-letter) of the drug cost. See: http://en.wikipedia.org/wiki/ISO_4217. '),
(5912, 1, 20, 'energyEfficiencyScaleMax', 'energyEfficiencyScaleMax', 'Specifies the most energy efficient class on the regulated EU energy consumption scale for the product category a product belongs to. For example, energy consumption for televisions placed on the market after January 1, 2020 is scaled from D to A+++.'),
(5913, 1, 20, 'musicGroupMember', 'musicGroupMember', 'A member of a music group&#x2014;for example, John, Paul, George, or Ringo.'),
(5914, 1, 20, 'catalogNumber', 'catalogNumber', 'The catalog number for the release.'),
(5915, 1, 20, 'cvdNumC19OFMechVentPats', 'cvdNumC19OFMechVentPats', 'numc19ofmechventpats - ED/OVERFLOW and VENTILATED: Patients with suspected or confirmed COVID-19 who are in the ED or any overflow location awaiting an inpatient bed and on a mechanical ventilator.'),
(5916, 1, 20, 'releasedEvent', 'releasedEvent', 'The place and time the release was issued, expressed as a PublicationEvent.'),
(5917, 1, 20, 'applicableLocation', 'applicableLocation', 'The location in which the status applies.'),
(5918, 1, 20, 'inAlbum', 'inAlbum', 'The album to which this recording belongs.'),
(5919, 1, 20, 'replyToUrl', 'replyToUrl', 'The URL at which a reply may be posted to the specified UserComment.'),
(5920, 1, 20, 'cvdNumC19MechVentPats', 'cvdNumC19MechVentPats', 'numc19mechventpats - HOSPITALIZED and VENTILATED: Patients hospitalized in an NHSN inpatient care location who have suspected or confirmed COVID-19 and are on a mechanical ventilator.'),
(5921, 1, 20, 'restockingFee', 'restockingFee', 'Use [[MonetaryAmount]] to specify a fixed restocking fee for product returns, or use [[Number]] to specify a percentage of the product price paid by the customer.'),
(5922, 1, 20, 'dateModified', 'dateModified', 'The date on which the CreativeWork was most recently modified or when the item\'s entry was modified within a DataFeed.'),
(5923, 1, 20, 'sourcedFrom', 'sourcedFrom', 'The neurological pathway that originates the neurons.'),
(5924, 1, 20, 'nonEqual', 'nonEqual', 'This ordering relation for qualitative values indicates that the subject is not equal to the object.'),
(5925, 1, 20, 'availableChannel', 'availableChannel', 'A means of accessing the service (e.g. a phone bank, a web site, a location, etc.).'),
(5926, 1, 20, 'application', 'application', 'An application that can complete the request.'),
(5927, 1, 20, 'timeOfDay', 'timeOfDay', 'The time of day the program normally runs. For example, \"evenings\".'),
(5928, 1, 20, 'episodeNumber', 'episodeNumber', 'Position of the episode within an ordered group of episodes.'),
(5929, 1, 20, 'numberOfBeds', 'numberOfBeds', 'The quantity of the given bed type available in the HotelRoom, Suite, House, or Apartment.'),
(5930, 1, 20, 'doseValue', 'doseValue', 'The value of the dose, e.g. 500.'),
(5931, 1, 20, 'exerciseType', 'exerciseType', 'Type(s) of exercise or activity, such as strength training, flexibility training, aerobics, cardiac rehabilitation, etc.'),
(5932, 1, 20, 'accessibilityHazard', 'accessibilityHazard', 'A characteristic of the described resource that is physiologically dangerous to some users. Related to WCAG 2.0 guideline 2.3. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityHazard-vocabulary).'),
(5933, 1, 20, 'sku', 'sku', 'The Stock Keeping Unit (SKU), i.e. a merchant-specific identifier for a product or service, or the product to which the offer refers.'),
(5934, 1, 20, 'numChildren', 'numChildren', 'The number of children staying in the unit.'),
(5935, 1, 20, 'acquiredFrom', 'acquiredFrom', 'The organization or person from which the product was acquired.'),
(5936, 1, 20, 'arrivalPlatform', 'arrivalPlatform', 'The platform where the train arrives.'),
(5937, 1, 20, 'postalCodeBegin', 'postalCodeBegin', 'First postal code in a range (included).'),
(5938, 1, 20, 'accessMode', 'accessMode', 'The human sensory perceptual system or cognitive faculty through which a person may process or perceive information. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessMode-vocabulary).'),
(5939, 1, 20, 'attendees', 'attendees', 'A person attending the event.'),
(5940, 1, 20, 'tongueWeight', 'tongueWeight', 'The permitted vertical load (TWR) of a trailer attached to the vehicle. Also referred to as Tongue Load Rating (TLR) or Vertical Load Rating (VLR).\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(5941, 1, 20, 'sugarContent', 'sugarContent', 'The number of grams of sugar.'),
(5942, 1, 20, 'isResizable', 'isResizable', 'Whether the 3DModel allows resizing. For example, room layout applications often do not allow 3DModel elements to be resized to reflect reality.'),
(5943, 1, 20, 'newsUpdatesAndGuidelines', 'newsUpdatesAndGuidelines', 'Indicates a page with news updates and guidelines. This could often be (but is not required to be) the main page containing [[SpecialAnnouncement]] markup on a site.'),
(5944, 1, 20, 'rxcui', 'rxcui', 'The RxCUI drug identifier from RXNORM.'),
(5945, 1, 20, 'minPrice', 'minPrice', 'The lowest price if the price is a range.'),
(5946, 1, 20, 'bookingAgent', 'bookingAgent', '\'bookingAgent\' is an out-dated term indicating a \'broker\' that serves as a booking agent.'),
(5947, 1, 20, 'epidemiology', 'epidemiology', 'The characteristics of associated patients, such as age, gender, race etc.'),
(5948, 1, 20, 'tributary', 'tributary', 'The anatomical or organ system that the vein flows into; a larger structure that the vein connects to.'),
(5949, 1, 20, 'shippingOrigin', 'shippingOrigin', 'Indicates the origin of a shipment, i.e. where it should be coming from.'),
(5950, 1, 20, 'percentile25', 'percentile25', 'The 25th percentile value.'),
(5951, 1, 20, 'legislationResponsible', 'legislationResponsible', 'An individual or organization that has some kind of responsibility for the legislation. Typically the ministry who is/was in charge of elaborating the legislation, or the adressee for potential questions about the legislation once it is published.'),
(5952, 1, 20, 'valueReference', 'valueReference', 'A secondary value that provides additional information on the original value, e.g. a reference temperature or a type of measurement.'),
(5953, 1, 20, 'yearBuilt', 'yearBuilt', 'The year an [[Accommodation]] was constructed. This corresponds to the [YearBuilt field in RESO](https://ddwiki.reso.org/display/DDW17/YearBuilt+Field). '),
(5954, 1, 20, 'securityScreening', 'securityScreening', 'The type of security screening the passenger is subject to.'),
(5955, 1, 20, 'ratingValue', 'ratingValue', 'The rating for the content.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(5956, 1, 20, 'abridged', 'abridged', 'Indicates whether the book is an abridged edition.'),
(5957, 1, 20, 'productID', 'productID', 'The product identifier, such as ISBN. For example: ``` meta itemprop=\"productID\" content=\"isbn:123-456-789\" ```.'),
(5958, 1, 20, 'exceptDate', 'exceptDate', 'Defines a [[Date]] or [[DateTime]] during which a scheduled [[Event]] will not take place. The property allows exceptions to\n      a [[Schedule]] to be specified. If an exception is specified as a [[DateTime]] then only the event that would have started at that specific date and time\n      should be excluded from the schedule. If an exception is specified as a [[Date]] then any event that is scheduled for that 24 hour period should be\n      excluded from the schedule. This allows a whole day to be excluded from the schedule without having to itemise every scheduled event.'),
(5959, 1, 20, 'collectionSize', 'collectionSize', 'The number of items in the [[Collection]].'),
(5960, 1, 20, 'eventStatus', 'eventStatus', 'An eventStatus of an event represents its status; particularly useful when an event is cancelled or rescheduled.'),
(5961, 1, 20, 'bodyLocation', 'bodyLocation', 'Location in the body of the anatomical structure.'),
(5962, 1, 20, 'acrissCode', 'acrissCode', 'The ACRISS Car Classification Code is a code used by many car rental companies, for classifying vehicles. ACRISS stands for Association of Car Rental Industry Systems and Standards.'),
(5963, 1, 20, 'maximumAttendeeCapacity', 'maximumAttendeeCapacity', 'The total number of individuals that may attend an event or venue.'),
(5964, 1, 20, 'recommendationStrength', 'recommendationStrength', 'Strength of the guideline\'s recommendation (e.g. \'class I\').'),
(5965, 1, 20, 'recipeCuisine', 'recipeCuisine', 'The cuisine of the recipe (for example, French or Ethiopian).'),
(5966, 1, 20, 'composer', 'composer', 'The person or organization who wrote a composition, or who is the composer of a work performed at some event.'),
(5967, 1, 20, 'departureBusStop', 'departureBusStop', 'The stop or station from which the bus departs.'),
(5968, 1, 20, 'purchaseDate', 'purchaseDate', 'The date the item, e.g. vehicle, was purchased by the current owner.'),
(5969, 1, 20, 'albumReleaseType', 'albumReleaseType', 'The kind of release which this album is: single, EP or album.'),
(5970, 1, 20, 'guideline', 'guideline', 'A medical guideline related to this entity.'),
(5971, 1, 20, 'monthsOfExperience', 'monthsOfExperience', 'Indicates the minimal number of months of experience required for a position.'),
(5972, 1, 20, 'activityFrequency', 'activityFrequency', 'How often one should engage in the activity.'),
(5973, 1, 20, 'includedInHealthInsurancePlan', 'includedInHealthInsurancePlan', 'The insurance plans that cover this drug.'),
(5974, 1, 20, 'relevantSpecialty', 'relevantSpecialty', 'If applicable, a medical specialty in which this entity is relevant.'),
(5975, 1, 20, 'variantCover', 'variantCover', 'A description of the variant cover\n    	for the issue, if the issue is a variant printing. For example, \"Bryan Hitch\n    	Variant Cover\" or \"2nd Printing Variant\".'),
(5976, 1, 20, 'wheelbase', 'wheelbase', 'The distance between the centers of the front and rear wheels.\\n\\nTypical unit code(s): CMT for centimeters, MTR for meters, INH for inches, FOT for foot/feet.'),
(5977, 1, 20, 'observationPeriod', 'observationPeriod', 'The length of time an Observation took place over. The format follows `P[0-9]*[Y|M|D|h|m|s]`. For example, P1Y is Period 1 Year, P3M is Period 3 Months, P3h is Period 3 hours.'),
(5978, 1, 20, 'episodes', 'episodes', 'An episode of a TV/radio series or season.'),
(5979, 1, 20, 'unitText', 'unitText', 'A string or text indicating the unit of measurement. Useful if you cannot provide a standard unit code for\n<a href=\'unitCode\'>unitCode</a>.'),
(5980, 1, 20, 'speakable', 'speakable', 'Indicates sections of a Web page that are particularly \'speakable\' in the sense of being highlighted as being especially appropriate for text-to-speech conversion. Other sections of a page may also be usefully spoken in particular circumstances; the \'speakable\' property serves to indicate the parts most likely to be generally useful for speech.\n\nThe *speakable* property can be repeated an arbitrary number of times, with three kinds of possible \'content-locator\' values:\n\n1.) *id-value* URL references - uses *id-value* of an element in the page being annotated. The simplest use of *speakable* has (potentially relative) URL values, referencing identified sections of the document concerned.\n\n2.) CSS Selectors - addresses content in the annotated page, e.g. via class attribute. Use the [[cssSelector]] property.\n\n3.)  XPaths - addresses content via XPaths (assuming an XML view of the content). Use the [[xpath]] property.\n\n\nFor more sophisticated markup of speakable sections beyond simple ID references, either CSS selectors or XPath expressions to pick out document section(s) as speakable. For this\nwe define a supporting type, [[SpeakableSpecification]]  which is defined to be a possible value of the *speakable* property.\n         '),
(5981, 1, 20, 'healthPlanCopayOption', 'healthPlanCopayOption', 'Whether the copay is before or after deductible, etc. TODO: Is this a closed set?'),
(5982, 1, 20, 'targetName', 'targetName', 'The name of a node in an established educational framework.'),
(5983, 1, 20, 'speechToTextMarkup', 'speechToTextMarkup', 'Form of markup used. eg. [SSML](https://www.w3.org/TR/speech-synthesis11) or [IPA](https://www.wikidata.org/wiki/Property:P898).'),
(5984, 1, 20, 'members', 'members', 'A member of this organization.'),
(5985, 1, 20, 'specialOpeningHoursSpecification', 'specialOpeningHoursSpecification', 'The special opening hours of a certain place.\\n\\nUse this to explicitly override general opening hours brought in scope by [[openingHoursSpecification]] or [[openingHours]].\n      '),
(5986, 1, 20, 'associatedPathophysiology', 'associatedPathophysiology', 'If applicable, a description of the pathophysiology associated with the anatomical system, including potential abnormal changes in the mechanical, physical, and biochemical functions of the system.'),
(5987, 1, 20, 'missionCoveragePrioritiesPolicy', 'missionCoveragePrioritiesPolicy', 'For a [[NewsMediaOrganization]], a statement on coverage priorities, including any public agenda or stance on issues.'),
(5988, 1, 20, 'articleSection', 'articleSection', 'Articles may belong to one or more \'sections\' in a magazine or newspaper, such as Sports, Lifestyle, etc.'),
(5989, 1, 20, 'eligibleTransactionVolume', 'eligibleTransactionVolume', 'The transaction volume, in a monetary unit, for which the offer or price specification is valid, e.g. for indicating a minimal purchasing volume, to express free shipping above a certain order volume, or to limit the acceptance of credit cards to purchases to a certain minimal amount.'),
(5990, 1, 20, 'ticketToken', 'ticketToken', 'Reference to an asset (e.g., Barcode, QR code image or PDF) usable for entrance.'),
(5991, 1, 20, 'populationType', 'populationType', 'Indicates the populationType common to all members of a [[StatisticalPopulation]] or all cases within the scope of a [[StatisticalVariable]].'),
(5992, 1, 20, 'handlingTime', 'handlingTime', 'The typical delay between the receipt of the order and the goods either leaving the warehouse or being prepared for pickup, in case the delivery method is on site pickup. Typical properties: minValue, maxValue, unitCode (d for DAY).  This is by common convention assumed to mean business days (if a unitCode is used, coded as \"d\"), i.e. only counting days when the business normally operates.'),
(5993, 1, 20, 'installUrl', 'installUrl', 'URL at which the app may be installed, if different from the URL of the item.'),
(5994, 1, 20, 'flightNumber', 'flightNumber', 'The unique identifier for a flight including the airline IATA code. For example, if describing United flight 110, where the IATA code for United is \'UA\', the flightNumber is \'UA110\'.'),
(5995, 1, 21, 'comment', 'comment', 'A description of the subject resource.'),
(5996, 1, 21, 'domain', 'domain', 'A domain of the subject property.'),
(5997, 1, 21, 'isDefinedBy', 'isDefinedBy', 'The definition of the subject resource.'),
(5998, 1, 21, 'seeAlso', 'seeAlso', 'Further information about the subject resource.'),
(5999, 1, 21, 'label', 'label', 'A human-readable name for the subject.'),
(6000, 1, 21, 'member', 'member', 'A member of the subject resource.'),
(6001, 1, 21, 'range', 'range', 'A range of the subject property.'),
(6002, 1, 21, 'subClassOf', 'subClassOf', 'The subject is a subclass of a class.'),
(6003, 1, 21, 'subPropertyOf', 'subPropertyOf', 'The subject is a subproperty of a property.'),
(6004, 1, 22, 'maximumAttendeeCapacity', 'maximumAttendeeCapacity', 'The total number of individuals that may attend an event or venue.'),
(6005, 1, 22, 'printEdition', 'printEdition', 'The edition of the print product in which the NewsArticle appears.'),
(6006, 1, 22, 'actors', 'actors', 'An actor, e.g. in TV, radio, movie, video games etc. Actors can be associated with individual items or with a series, episode, clip.'),
(6007, 1, 22, 'actor', 'actor', 'An actor, e.g. in TV, radio, movie, video games etc., or in an event. Actors can be associated with individual items or with a series, episode, clip.'),
(6008, 1, 22, 'latitude', 'latitude', 'The latitude of a location. For example ```37.42242``` ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)).'),
(6009, 1, 22, 'geoCoveredBy', 'geoCoveredBy', 'Represents a relationship between two geometries (or the places they represent), relating a geometry to another that covers it. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(6010, 1, 22, 'requiredQuantity', 'requiredQuantity', 'The required quantity of the item(s).'),
(6011, 1, 22, 'price', 'price', 'The offer price of a product, or of a price component when attached to PriceSpecification and its subtypes.\\n\\nUsage guidelines:\\n\\n* Use the [[priceCurrency]] property (with standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\") instead of including [ambiguous symbols](http://en.wikipedia.org/wiki/Dollar_sign#Currencies_that_use_the_dollar_or_peso_sign) such as \'$\' in the value.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.\\n* Note that both [RDFa](http://www.w3.org/TR/xhtml-rdfa-primer/#using-the-content-attribute) and Microdata syntax allow the use of a \"content=\" attribute for publishing simple machine-readable values alongside more human-friendly formatting.\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\n      '),
(6012, 1, 22, 'homeLocation', 'homeLocation', 'A contact location for a person\'s residence.'),
(6013, 1, 22, 'location', 'location', 'The location of, for example, where an event is happening, where an organization is located, or where an action takes place.'),
(6014, 1, 22, 'dayOfWeek', 'dayOfWeek', 'The day of the week for which these opening hours are valid.'),
(6015, 1, 22, 'cvdNumC19OFMechVentPats', 'cvdNumC19OFMechVentPats', 'numc19ofmechventpats - ED/OVERFLOW and VENTILATED: Patients with suspected or confirmed COVID-19 who are in the ED or any overflow location awaiting an inpatient bed and on a mechanical ventilator.'),
(6016, 1, 22, 'diversityStaffingReport', 'diversityStaffingReport', 'For an [[Organization]] (often but not necessarily a [[NewsMediaOrganization]]), a report on staffing diversity issues. In a news context this might be for example ASNE or RTDNA (US) reports, or self-reported.'),
(6017, 1, 22, 'publishingPrinciples', 'publishingPrinciples', 'The publishingPrinciples property indicates (typically via [[URL]]) a document describing the editorial principles of an [[Organization]] (or individual, e.g. a [[Person]] writing a blog) that relate to their activities as a publisher, e.g. ethics or diversity policies. When applied to a [[CreativeWork]] (e.g. [[NewsArticle]]) the principles are those of the party primarily responsible for the creation of the [[CreativeWork]].\n\nWhile such policies are most typically expressed in natural language, sometimes related information (e.g. indicating a [[funder]]) can be expressed using schema.org terminology.\n'),
(6018, 1, 22, 'billingDuration', 'billingDuration', 'Specifies for how long this price (or price component) will be billed. Can be used, for example, to model the contractual duration of a subscription or payment plan. Type can be either a Duration or a Number (in which case the unit of measurement, for example month, is specified by the unitCode property).'),
(6019, 1, 22, 'prescriptionStatus', 'prescriptionStatus', 'Indicates the status of drug prescription, e.g. local catalogs classifications or whether the drug is available by prescription or over-the-counter, etc.'),
(6020, 1, 22, 'monthlyMinimumRepaymentAmount', 'monthlyMinimumRepaymentAmount', 'The minimum payment is the lowest amount of money that one is required to pay on a credit card statement each month.'),
(6021, 1, 22, 'associatedMediaReview', 'associatedMediaReview', 'An associated [[MediaReview]], related by specific common content, topic or claim. The expectation is that this property would be most typically used in cases where a single activity is conducting both claim reviews and media reviews, in which case [[relatedMediaReview]] would commonly be used on a [[ClaimReview]], while [[relatedClaimReview]] would be used on [[MediaReview]].'),
(6022, 1, 22, 'associatedReview', 'associatedReview', 'An associated [[Review]].'),
(6023, 1, 22, 'infectiousAgent', 'infectiousAgent', 'The actual infectious agent, such as a specific bacterium.'),
(6024, 1, 22, 'occupancy', 'occupancy', 'The allowed total occupancy for the accommodation in persons (including infants etc). For individual accommodations, this is not necessarily the legal maximum but defines the permitted usage as per the contractual agreement (e.g. a double room used by a single person).\nTypical unit code(s): C62 for person'),
(6025, 1, 22, 'merchantReturnLink', 'merchantReturnLink', 'Specifies a Web page or service by URL, for product returns.'),
(6026, 1, 22, 'valueReference', 'valueReference', 'A secondary value that provides additional information on the original value, e.g. a reference temperature or a type of measurement.'),
(6027, 1, 22, 'jobLocation', 'jobLocation', 'A (typically single) geographic location associated with the job position.'),
(6028, 1, 22, 'geoRadius', 'geoRadius', 'Indicates the approximate radius of a GeoCircle (metres unless indicated otherwise via Distance notation).'),
(6029, 1, 22, 'steps', 'steps', 'A single step item (as HowToStep, text, document, video, etc.) or a HowToSection (originally misnamed \'steps\'; \'step\' is preferred).'),
(6030, 1, 22, 'step', 'step', 'A single step item (as HowToStep, text, document, video, etc.) or a HowToSection.'),
(6031, 1, 22, 'followup', 'followup', 'Typical or recommended followup care after the procedure is performed.'),
(6032, 1, 22, 'hasPOS', 'hasPOS', 'Points-of-Sales operated by the organization or person.'),
(6033, 1, 22, 'floorLevel', 'floorLevel', 'The floor level for an [[Accommodation]] in a multi-storey building. Since counting\n  systems [vary internationally](https://en.wikipedia.org/wiki/Storey#Consecutive_number_floor_designations), the local system should be used where possible.'),
(6034, 1, 22, 'variesBy', 'variesBy', 'Indicates the property or properties by which the variants in a [[ProductGroup]] vary, e.g. their size, color etc. Schema.org properties can be referenced by their short name e.g. \"color\"; terms defined elsewhere can be referenced with their URIs.'),
(6035, 1, 22, 'estimatesRiskOf', 'estimatesRiskOf', 'The condition, complication, or symptom whose risk is being estimated.'),
(6036, 1, 22, 'countryOfLastProcessing', 'countryOfLastProcessing', 'The place where the item (typically [[Product]]) was last processed and tested before importation.'),
(6037, 1, 22, 'releaseDate', 'releaseDate', 'The release date of a product or product model. This can be used to distinguish the exact variant of a product.'),
(6038, 1, 22, 'isSimilarTo', 'isSimilarTo', 'A pointer to another, functionally similar product (or multiple products).'),
(6039, 1, 22, 'trailer', 'trailer', 'The trailer of a movie or TV/radio series, season, episode, etc.'),
(6040, 1, 22, 'relatedCondition', 'relatedCondition', 'A medical condition associated with this anatomy.'),
(6041, 1, 22, 'postalCodePrefix', 'postalCodePrefix', 'A defined range of postal codes indicated by a common textual prefix. Used for non-numeric systems such as UK.'),
(6042, 1, 22, 'departureBusStop', 'departureBusStop', 'The stop or station from which the bus departs.'),
(6043, 1, 22, 'datasetTimeInterval', 'datasetTimeInterval', 'The range of temporal applicability of a dataset, e.g. for a 2011 census dataset, the year 2011 (in ISO 8601 time interval format).'),
(6044, 1, 22, 'temporalCoverage', 'temporalCoverage', 'The temporalCoverage of a CreativeWork indicates the period that the content applies to, i.e. that it describes, either as a DateTime or as a textual string indicating a time period in [ISO 8601 time interval format](https://en.wikipedia.org/wiki/ISO_8601#Time_intervals). In\n      the case of a Dataset it will typically indicate the relevant time period in a precise notation (e.g. for a 2011 census dataset, the year 2011 would be written \"2011/2012\"). Other forms of content, e.g. ScholarlyArticle, Book, TVSeries or TVEpisode, may indicate their temporalCoverage in broader terms - textually or via well-known URL.\n      Written works such as books may sometimes have precise temporal coverage too, e.g. a work set in 1939 - 1945 can be indicated in ISO 8601 interval format format via \"1939/1945\".\n\nOpen-ended date ranges can be written with \"..\" in place of the end date. For example, \"2015-11/..\" indicates a range beginning in November 2015 and with no specified final date. This is tentative and might be updated in future when ISO 8601 is officially updated.'),
(6045, 1, 22, 'cvdNumBedsOcc', 'cvdNumBedsOcc', 'numbedsocc - HOSPITAL INPATIENT BED OCCUPANCY: Total number of staffed inpatient beds that are occupied.'),
(6046, 1, 22, 'diseasePreventionInfo', 'diseasePreventionInfo', 'Information about disease prevention.'),
(6047, 1, 22, 'flightDistance', 'flightDistance', 'The distance of the flight.'),
(6048, 1, 22, 'exceptDate', 'exceptDate', 'Defines a [[Date]] or [[DateTime]] during which a scheduled [[Event]] will not take place. The property allows exceptions to\n      a [[Schedule]] to be specified. If an exception is specified as a [[DateTime]] then only the event that would have started at that specific date and time\n      should be excluded from the schedule. If an exception is specified as a [[Date]] then any event that is scheduled for that 24 hour period should be\n      excluded from the schedule. This allows a whole day to be excluded from the schedule without having to itemise every scheduled event.'),
(6049, 1, 22, 'catalogNumber', 'catalogNumber', 'The catalog number for the release.'),
(6050, 1, 22, 'costPerUnit', 'costPerUnit', 'The cost per unit of the drug.'),
(6051, 1, 22, 'comprisedOf', 'comprisedOf', 'Specifying something physically contained by something else. Typically used here for the underlying anatomical structures, such as organs, that comprise the anatomical system.'),
(6052, 1, 22, 'spokenByCharacter', 'spokenByCharacter', 'The (e.g. fictional) character, Person or Organization to whom the quotation is attributed within the containing CreativeWork.'),
(6053, 1, 22, 'salaryCurrency', 'salaryCurrency', 'The currency (coded using [ISO 4217](http://en.wikipedia.org/wiki/ISO_4217)) used for the main salary information in this job posting or for this employee.'),
(6054, 1, 22, 'acrissCode', 'acrissCode', 'The ACRISS Car Classification Code is a code used by many car rental companies, for classifying vehicles. ACRISS stands for Association of Car Rental Industry Systems and Standards.'),
(6055, 1, 22, 'exercisePlan', 'exercisePlan', 'A sub property of instrument. The exercise plan used on this action.'),
(6056, 1, 22, 'instrument', 'instrument', 'The object that helped the agent perform the action. E.g. John wrote a book with *a pen*.'),
(6057, 1, 22, 'endorsers', 'endorsers', 'People or organizations that endorse the plan.'),
(6058, 1, 22, 'transFatContent', 'transFatContent', 'The number of grams of trans fat.'),
(6059, 1, 22, 'guidelineDate', 'guidelineDate', 'Date on which this guideline\'s recommendation was made.'),
(6060, 1, 22, 'issueNumber', 'issueNumber', 'Identifies the issue of publication; for example, \"iii\" or \"2\".'),
(6061, 1, 22, 'position', 'position', 'The position of an item in a series or sequence of items.'),
(6062, 1, 22, 'workLocation', 'workLocation', 'A contact location for a person\'s place of work.'),
(6063, 1, 22, 'hiringOrganization', 'hiringOrganization', 'Organization or Person offering the job position.'),
(6064, 1, 22, 'broadcastChannelId', 'broadcastChannelId', 'The unique address by which the BroadcastService can be identified in a provider lineup. In US, this is typically a number.'),
(6065, 1, 22, 'query', 'query', 'A sub property of instrument. The query used on this action.'),
(6066, 1, 22, 'jobImmediateStart', 'jobImmediateStart', 'An indicator as to whether a position is available for an immediate start.'),
(6067, 1, 22, 'applicationSuite', 'applicationSuite', 'The name of the application suite to which the application belongs (e.g. Excel belongs to Office).'),
(6068, 1, 22, 'aircraft', 'aircraft', 'The kind of aircraft (e.g., \"Boeing 747\").'),
(6069, 1, 22, 'grantee', 'grantee', 'The person, organization, contact point, or audience that has been granted this permission.'),
(6070, 1, 22, 'medicineSystem', 'medicineSystem', 'The system of medicine that includes this MedicalEntity, for example \'evidence-based\', \'homeopathic\', \'chiropractic\', etc.'),
(6071, 1, 22, 'correctionsPolicy', 'correctionsPolicy', 'For an [[Organization]] (e.g. [[NewsMediaOrganization]]), a statement describing (in news media, the newsroom’s) disclosure and correction policy for errors.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(6072, 1, 22, 'sizeSystem', 'sizeSystem', 'The size system used to identify a product\'s size. Typically either a standard (for example, \"GS1\" or \"ISO-EN13402\"), country code (for example \"US\" or \"JP\"), or a measuring system (for example \"Metric\" or \"Imperial\").'),
(6073, 1, 22, 'playersOnline', 'playersOnline', 'Number of players on the server.'),
(6074, 1, 22, 'industry', 'industry', 'The industry associated with the job position.'),
(6075, 1, 22, 'menuAddOn', 'menuAddOn', 'Additional menu item(s) such as a side dish of salad or side order of fries that can be added to this menu item. Additionally it can be a menu section containing allowed add-on menu items for this menu item.'),
(6076, 1, 22, 'directApply', 'directApply', 'Indicates whether an [[url]] that is associated with a [[JobPosting]] enables direct application for the job, via the posting website. A job posting is considered to have directApply of [[True]] if an application process for the specified job can be directly initiated via the url(s) given (noting that e.g. multiple internet domains might nevertheless be involved at an implementation level). A value of [[False]] is appropriate if there is no clear path to applying directly online for the specified job, navigating directly from the JobPosting url(s) supplied.'),
(6077, 1, 22, 'evidenceOrigin', 'evidenceOrigin', 'Source of the data used to formulate the guidance, e.g. RCT, consensus opinion, etc.'),
(6078, 1, 22, 'actionableFeedbackPolicy', 'actionableFeedbackPolicy', 'For a [[NewsMediaOrganization]] or other news-related [[Organization]], a statement about public engagement activities (for news media, the newsroom’s), including involving the public - digitally or otherwise -- in coverage decisions, reporting and activities after publication.'),
(6079, 1, 22, 'utterances', 'utterances', 'Text of an utterances (spoken words, lyrics etc.) that occurs at a certain section of a media object, represented as a [[HyperTocEntry]].'),
(6080, 1, 22, 'studyLocation', 'studyLocation', 'The location in which the study is taking/took place.'),
(6081, 1, 22, 'accessibilityControl', 'accessibilityControl', 'Identifies input methods that are sufficient to fully control the described resource. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityControl-vocabulary).'),
(6082, 1, 22, 'maximumEnrollment', 'maximumEnrollment', 'The maximum number of students who may be enrolled in the program.'),
(6083, 1, 22, 'checkoutPageURLTemplate', 'checkoutPageURLTemplate', 'A URL template (RFC 6570) for a checkout page for an offer. This approach allows merchants to specify a URL for online checkout of the offered product, by interpolating parameters such as the logged in user ID, product ID, quantity, discount code etc. Parameter naming and standardization are not specified here.'),
(6084, 1, 22, 'musicBy', 'musicBy', 'The composer of the soundtrack.'),
(6085, 1, 22, 'lastReviewed', 'lastReviewed', 'Date on which the content on this web page was last reviewed for accuracy and/or completeness.'),
(6086, 1, 22, 'courseMode', 'courseMode', 'The medium or means of delivery of the course instance or the mode of study, either as a text label (e.g. \"online\", \"onsite\" or \"blended\"; \"synchronous\" or \"asynchronous\"; \"full-time\" or \"part-time\") or as a URL reference to a term from a controlled vocabulary (e.g. https://ceds.ed.gov/element/001311#Asynchronous).'),
(6087, 1, 22, 'competencyRequired', 'competencyRequired', 'Knowledge, skill, ability or personal attribute that must be demonstrated by a person or other entity in order to do something such as earn an Educational Occupational Credential or understand a LearningResource.'),
(6088, 1, 22, 'paymentMethod', 'paymentMethod', 'The name of the credit card or other method of payment for the order.'),
(6089, 1, 22, 'honorificPrefix', 'honorificPrefix', 'An honorific prefix preceding a Person\'s name such as Dr/Mrs/Mr.'),
(6090, 1, 22, 'bed', 'bed', 'The type of bed or beds included in the accommodation. For the single case of just one bed of a certain type, you use bed directly with a text.\n      If you want to indicate the quantity of a certain kind of bed, use an instance of BedDetails. For more detailed information, use the amenityFeature property.'),
(6091, 1, 22, 'tracks', 'tracks', 'A music recording (track)&#x2014;usually a single song.'),
(6092, 1, 22, 'track', 'track', 'A music recording (track)&#x2014;usually a single song. If an ItemList is given, the list should contain items of type MusicRecording.'),
(6093, 1, 22, 'mathExpression', 'mathExpression', 'A mathematical expression (e.g. \'x^2-3x=0\') that may be solved for a specific variable, simplified, or transformed. This can take many formats, e.g. LaTeX, Ascii-Math, or math as you would write with a keyboard.'),
(6094, 1, 22, 'isbn', 'isbn', 'The ISBN of the book.'),
(6095, 1, 22, 'identifier', 'identifier', 'The identifier property represents any kind of identifier for any kind of [[Thing]], such as ISBNs, GTIN codes, UUIDs etc. Schema.org provides dedicated properties for representing many of these, either as textual strings or as URL (URI) links. See [background notes](/docs/datamodel.html#identifierBg) for more details.\n        '),
(6096, 1, 22, 'countriesSupported', 'countriesSupported', 'Countries for which the application is supported. You can also provide the two-letter ISO 3166-1 alpha-2 country code.'),
(6097, 1, 22, 'checkinTime', 'checkinTime', 'The earliest someone may check into a lodging establishment.'),
(6098, 1, 22, 'deliveryMethod', 'deliveryMethod', 'A sub property of instrument. The method of delivery.'),
(6099, 1, 22, 'hasBioPolymerSequence', 'hasBioPolymerSequence', 'A symbolic representation of a BioChemEntity. For example, a nucleotide sequence of a Gene or an amino acid sequence of a Protein.'),
(6100, 1, 22, 'hasRepresentation', 'hasRepresentation', 'A common representation such as a protein sequence or chemical structure for this entity. For images use schema.org/image.'),
(6101, 1, 22, 'distribution', 'distribution', 'A downloadable form of this dataset, at a specific location, in a specific format. This property can be repeated if different variations are available. There is no expectation that different downloadable distributions must contain exactly equivalent information (see also [DCAT](https://www.w3.org/TR/vocab-dcat-3/#Class:Distribution) on this point). Different distributions might include or exclude different subsets of the entire dataset, for example.'),
(6102, 1, 22, 'bankAccountType', 'bankAccountType', 'The type of a bank account.'),
(6103, 1, 22, 'mediaItemAppearance', 'mediaItemAppearance', 'In the context of a [[MediaReview]], indicates specific media item(s) that are grouped using a [[MediaReviewItem]].'),
(6104, 1, 22, 'audio', 'audio', 'An embedded audio object.'),
(6105, 1, 22, 'playMode', 'playMode', 'Indicates whether this game is multi-player, co-op or single-player.  The game can be marked as multi-player, co-op and single-player at the same time.'),
(6106, 1, 22, 'foodWarning', 'foodWarning', 'Any precaution, guidance, contraindication, etc. related to consumption of specific foods while taking this drug.'),
(6107, 1, 22, 'vehicleInteriorType', 'vehicleInteriorType', 'The type or material of the interior of the vehicle (e.g. synthetic fabric, leather, wood, etc.). While most interior types are characterized by the material used, an interior type can also be based on vehicle usage or target audience.'),
(6108, 1, 22, 'assesses', 'assesses', 'The item being described is intended to assess the competency or learning outcome defined by the referenced term.'),
(6109, 1, 22, 'currentExchangeRate', 'currentExchangeRate', 'The current price of a currency.'),
(6110, 1, 22, 'numberOfBathroomsTotal', 'numberOfBathroomsTotal', 'The total integer number of bathrooms in some [[Accommodation]], following real estate conventions as [documented in RESO](https://ddwiki.reso.org/display/DDW17/BathroomsTotalInteger+Field): \"The simple sum of the number of bathrooms. For example for a property with two Full Bathrooms and one Half Bathroom, the Bathrooms Total Integer will be 3.\". See also [[numberOfRooms]].'),
(6111, 1, 22, 'experienceInPlaceOfEducation', 'experienceInPlaceOfEducation', 'Indicates whether a [[JobPosting]] will accept experience (as indicated by [[OccupationalExperienceRequirements]]) in place of its formal educational qualifications (as indicated by [[educationRequirements]]). If true, indicates that satisfying one of these requirements is sufficient.'),
(6112, 1, 22, 'legislationTransposes', 'legislationTransposes', 'Indicates that this legislation (or part of legislation) fulfills the objectives set by another legislation, by passing appropriate implementation measures. Typically, some legislations of European Union\'s member states or regions transpose European Directives. This indicates a legally binding link between the 2 legislations.'),
(6113, 1, 22, 'legislationApplies', 'legislationApplies', 'Indicates that this legislation (or part of a legislation) somehow transfers another legislation in a different legislative context. This is an informative link, and it has no legal value. For legally-binding links of transposition, use the <a href=\"/legislationTransposes\">legislationTransposes</a> property. For example an informative consolidated law of a European Union\'s member state \"applies\" the consolidated version of the European Directive implemented in it.'),
(6114, 1, 22, 'distinguishingSign', 'distinguishingSign', 'One of a set of signs and symptoms that can be used to distinguish this diagnosis from others in the differential diagnosis.'),
(6115, 1, 22, 'legislationJurisdiction', 'legislationJurisdiction', 'The jurisdiction from which the legislation originates.'),
(6116, 1, 22, 'jurisdiction', 'jurisdiction', 'Indicates a legal jurisdiction, e.g. of some legislation, or where some government service is based.'),
(6117, 1, 22, 'spatialCoverage', 'spatialCoverage', 'The spatialCoverage of a CreativeWork indicates the place(s) which are the focus of the content. It is a subproperty of\n      contentLocation intended primarily for more technical and detailed materials. For example with a Dataset, it indicates\n      areas that the dataset describes: a dataset of New York weather would have spatialCoverage which was the place: the state of New York.'),
(6118, 1, 22, 'arrivalAirport', 'arrivalAirport', 'The airport where the flight terminates.'),
(6119, 1, 22, 'interactingDrug', 'interactingDrug', 'Another drug that is known to interact with this drug in a way that impacts the effect of this drug or causes a risk to the patient. Note: disease interactions are typically captured as contraindications.'),
(6120, 1, 22, 'availabilityStarts', 'availabilityStarts', 'The beginning of the availability of the product or service included in the offer.'),
(6121, 1, 22, 'vehicleSeatingCapacity', 'vehicleSeatingCapacity', 'The number of passengers that can be seated in the vehicle, both in terms of the physical space available, and in terms of limitations set by law.\\n\\nTypical unit code(s): C62 for persons.'),
(6122, 1, 22, 'relevantOccupation', 'relevantOccupation', 'The Occupation for the JobPosting.'),
(6123, 1, 22, 'phoneticText', 'phoneticText', 'Representation of a text [[textValue]] using the specified [[speechToTextMarkup]]. For example the city name of Houston in IPA: /ˈhjuːstən/.'),
(6124, 1, 22, 'vehicleInteriorColor', 'vehicleInteriorColor', 'The color or color combination of the interior of the vehicle.'),
(6125, 1, 22, 'broadcastSubChannel', 'broadcastSubChannel', 'The subchannel used for the broadcast.'),
(6126, 1, 22, 'targetPlatform', 'targetPlatform', 'Type of app development: phone, Metro style, desktop, XBox, etc.'),
(6127, 1, 22, 'naics', 'naics', 'The North American Industry Classification System (NAICS) code for a particular organization or business person.'),
(6128, 1, 22, 'color', 'color', 'The color of the product.'),
(6129, 1, 22, 'risks', 'risks', 'Specific physiologic risks associated to the diet plan.'),
(6130, 1, 22, 'dateIssued', 'dateIssued', 'The date the ticket was issued.'),
(6131, 1, 22, 'propertyID', 'propertyID', 'A commonly used identifier for the characteristic represented by the property, e.g. a manufacturer or a standard code for a property. propertyID can be\n(1) a prefixed string, mainly meant to be used with standards for product properties; (2) a site-specific, non-prefixed string (e.g. the primary key of the property or the vendor-specific ID of the property), or (3)\na URL indicating the type of the property, either pointing to an external vocabulary, or a Web resource that describes the property (e.g. a glossary entry).\nStandards bodies should promote a standard prefix for the identifiers of properties from their standards.'),
(6132, 1, 22, 'directors', 'directors', 'A director of e.g. TV, radio, movie, video games etc. content. Directors can be associated with individual items or with a series, episode, clip.'),
(6133, 1, 22, 'director', 'director', 'A director of e.g. TV, radio, movie, video gaming etc. content, or of an event. Directors can be associated with individual items or with a series, episode, clip.'),
(6134, 1, 22, 'map', 'map', 'A URL to a map of the place.'),
(6135, 1, 22, 'hasMap', 'hasMap', 'A URL to a map of the place.'),
(6136, 1, 22, 'stageAsNumber', 'stageAsNumber', 'The stage represented as a number, e.g. 3.'),
(6137, 1, 22, 'awards', 'awards', 'Awards won by or for this item.'),
(6138, 1, 22, 'award', 'award', 'An award won by or for this item.'),
(6139, 1, 22, 'associatedDisease', 'associatedDisease', 'Disease associated to this BioChemEntity. Such disease can be a MedicalCondition or a URL. If you want to add an evidence supporting the association, please use PropertyValue.'),
(6140, 1, 22, 'amenityFeature', 'amenityFeature', 'An amenity feature (e.g. a characteristic or service) of the Accommodation. This generic property does not make a statement about whether the feature is included in an offer for the main accommodation or available at extra costs.'),
(6141, 1, 22, 'birthDate', 'birthDate', 'Date of birth.'),
(6142, 1, 22, 'valueMaxLength', 'valueMaxLength', 'Specifies the allowed range for number of characters in a literal value.'),
(6143, 1, 22, 'programName', 'programName', 'The program providing the membership.'),
(6144, 1, 22, 'isRelatedTo', 'isRelatedTo', 'A pointer to another, somehow related product (or multiple products).'),
(6145, 1, 22, 'vehicleModelDate', 'vehicleModelDate', 'The release date of a vehicle model (often used to differentiate versions of the same make and model).'),
(6146, 1, 22, 'typicalCreditsPerTerm', 'typicalCreditsPerTerm', 'The number of credits or units a full-time student would be expected to take in 1 term however \'term\' is defined by the institution.'),
(6147, 1, 22, 'titleEIDR', 'titleEIDR', 'An [EIDR](https://eidr.org/) (Entertainment Identifier Registry) [[identifier]] representing at the most general/abstract level, a work of film or television.\n\nFor example, the motion picture known as \"Ghostbusters\" has a titleEIDR of  \"10.5240/7EC7-228A-510A-053E-CBB8-J\". This title (or work) may have several variants, which EIDR calls \"edits\". See [[editEIDR]].\n\nSince schema.org types like [[Movie]] and [[TVEpisode]] can be used for both works and their multiple expressions, it is possible to use [[titleEIDR]] alone (for a general description), or alongside [[editEIDR]] for a more edit-specific description.\n'),
(6148, 1, 22, 'editEIDR', 'editEIDR', 'An [EIDR](https://eidr.org/) (Entertainment Identifier Registry) [[identifier]] representing a specific edit / edition for a work of film or television.\n\nFor example, the motion picture known as \"Ghostbusters\" whose [[titleEIDR]] is \"10.5240/7EC7-228A-510A-053E-CBB8-J\" has several edits, e.g. \"10.5240/1F2A-E1C5-680A-14C6-E76B-I\" and \"10.5240/8A35-3BEE-6497-5D12-9E4F-3\".\n\nSince schema.org types like [[Movie]] and [[TVEpisode]] can be used for both works and their multiple expressions, it is possible to use [[titleEIDR]] alone (for a general description), or alongside [[editEIDR]] for a more edit-specific description.\n'),
(6149, 1, 22, 'embeddedTextCaption', 'embeddedTextCaption', 'Represents textual captioning from a [[MediaObject]], e.g. text of a \'meme\'.'),
(6150, 1, 22, 'caption', 'caption', 'The caption for this object. For downloadable machine formats (closed caption, subtitles etc.) use MediaObject and indicate the [[encodingFormat]].'),
(6151, 1, 22, 'recommendedIntake', 'recommendedIntake', 'Recommended intake of this supplement for a given population as defined by a specific recommending authority.'),
(6152, 1, 22, 'instructor', 'instructor', 'A person assigned to instruct or provide instructional assistance for the [[CourseInstance]].'),
(6153, 1, 22, 'administrationRoute', 'administrationRoute', 'A route by which this drug may be administered, e.g. \'oral\'.'),
(6154, 1, 22, 'postOp', 'postOp', 'A description of the postoperative procedures, care, and/or followups for this device.'),
(6155, 1, 22, 'subStructure', 'subStructure', 'Component (sub-)structure(s) that comprise this anatomical structure.'),
(6156, 1, 22, 'isResizable', 'isResizable', 'Whether the 3DModel allows resizing. For example, room layout applications often do not allow 3DModel elements to be resized to reflect reality.'),
(6157, 1, 22, 'affectedBy', 'affectedBy', 'Drugs that affect the test\'s results.'),
(6158, 1, 22, 'healthPlanPharmacyCategory', 'healthPlanPharmacyCategory', 'The category or type of pharmacy associated with this cost sharing.'),
(6159, 1, 22, 'authenticator', 'authenticator', 'The Organization responsible for authenticating the user\'s subscription. For example, many media apps require a cable/satellite provider to authenticate your subscription before playing media.'),
(6160, 1, 22, 'vehicleIdentificationNumber', 'vehicleIdentificationNumber', 'The Vehicle Identification Number (VIN) is a unique serial number used by the automotive industry to identify individual motor vehicles.'),
(6161, 1, 22, 'serialNumber', 'serialNumber', 'The serial number or any alphanumeric identifier of a particular product. When attached to an offer, it is a shortcut for the serial number of the product included in the offer.'),
(6162, 1, 22, 'coverageStartTime', 'coverageStartTime', 'The time when the live blog will begin covering the Event. Note that coverage may begin before the Event\'s start time. The LiveBlogPosting may also be created before coverage begins.'),
(6163, 1, 22, 'contentReferenceTime', 'contentReferenceTime', 'The specific time described by a creative work, for works (e.g. articles, video objects etc.) that emphasise a particular moment within an Event.'),
(6164, 1, 22, 'epidemiology', 'epidemiology', 'The characteristics of associated patients, such as age, gender, race etc.'),
(6165, 1, 22, 'schoolClosuresInfo', 'schoolClosuresInfo', 'Information about school closures.'),
(6166, 1, 22, 'callSign', 'callSign', 'A [callsign](https://en.wikipedia.org/wiki/Call_sign), as used in broadcasting and radio communications to identify people, radio and TV stations, or vehicles.'),
(6167, 1, 22, 'acquiredFrom', 'acquiredFrom', 'The organization or person from which the product was acquired.'),
(6168, 1, 22, 'branchCode', 'branchCode', 'A short textual code (also called \"store code\") that uniquely identifies a place of business. The code is typically assigned by the parentOrganization and used in structured URLs.\\n\\nFor example, in the URL http://www.starbucks.co.uk/store-locator/etc/detail/3047 the code \"3047\" is a branchCode for a particular branch.\n      '),
(6169, 1, 22, 'drug', 'drug', 'Specifying a drug or medicine used in a medication procedure.'),
(6170, 1, 22, 'code', 'code', 'A medical code for the entity, taken from a controlled vocabulary or ontology such as ICD-9, DiseasesDB, MeSH, SNOMED-CT, RxNorm, etc.'),
(6171, 1, 22, 'codingSystem', 'codingSystem', 'The coding system, e.g. \'ICD-10\'.'),
(6172, 1, 22, 'gtin12', 'gtin12', 'The GTIN-12 code of the product, or the product to which the offer refers. The GTIN-12 is the 12-digit GS1 Identification Key composed of a U.P.C. Company Prefix, Item Reference, and Check Digit used to identify trade items. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(6173, 1, 22, 'gtin', 'gtin', 'A Global Trade Item Number ([GTIN](https://www.gs1.org/standards/id-keys/gtin)). GTINs identify trade items, including products and services, using numeric identification codes.\n\nThe GS1 [digital link specifications](https://www.gs1.org/standards/Digital-Link/) express GTINs as URLs (URIs, IRIs, etc.). Details including regular expression examples can be found in, Section 6 of the GS1 URI Syntax specification; see also [schema.org tracking issue](https://github.com/schemaorg/schemaorg/issues/3156#issuecomment-1209522809) for schema.org-specific discussion. A correct [[gtin]] value should be a valid GTIN, which means that it should be an all-numeric string of either 8, 12, 13 or 14 digits, or a \"GS1 Digital Link\" URL based on such a string. The numeric component should also have a [valid GS1 check digit](https://www.gs1.org/services/check-digit-calculator) and meet the other rules for valid GTINs. See also [GS1\'s GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) and [Wikipedia](https://en.wikipedia.org/wiki/Global_Trade_Item_Number) for more details. Left-padding of the gtin values is not required or encouraged. The [[gtin]] property generalizes the earlier [[gtin8]], [[gtin12]], [[gtin13]], and [[gtin14]] properties.\n\nNote also that this is a definition for how to include GTINs in Schema.org data, and not a definition of GTINs in general - see the GS1 documentation for authoritative details.'),
(6174, 1, 22, 'applicationStartDate', 'applicationStartDate', 'The date at which the program begins collecting applications for the next enrollment cycle.'),
(6175, 1, 22, 'includesObject', 'includesObject', 'This links to a node or nodes indicating the exact quantity of the products included in  an [[Offer]] or [[ProductCollection]].'),
(6176, 1, 22, 'volumeNumber', 'volumeNumber', 'Identifies the volume of publication or multi-part work; for example, \"iii\" or \"2\".'),
(6177, 1, 22, 'acceptedOffer', 'acceptedOffer', 'The offer(s) -- e.g., product, quantity and price combinations -- included in the order.'),
(6178, 1, 22, 'cvdNumC19HospPats', 'cvdNumC19HospPats', 'numc19hosppats - HOSPITALIZED: Patients currently hospitalized in an inpatient care location who have suspected or confirmed COVID-19.'),
(6179, 1, 22, 'entertainmentBusiness', 'entertainmentBusiness', 'A sub property of location. The entertainment business where the action occurred.'),
(6180, 1, 22, 'educationalLevel', 'educationalLevel', 'The level in terms of progression through an educational or training context. Examples of educational levels include \'beginner\', \'intermediate\' or \'advanced\', and formal sets of level indicators.'),
(6181, 1, 22, 'uploadDate', 'uploadDate', 'Date when this media object was uploaded to this site.'),
(6182, 1, 22, 'programType', 'programType', 'The type of educational or occupational program. For example, classroom, internship, alternance, etc.'),
(6183, 1, 22, 'highPrice', 'highPrice', 'The highest price of all offers available.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(6184, 1, 22, 'byDay', 'byDay', 'Defines the day(s) of the week on which a recurring [[Event]] takes place. May be specified using either [[DayOfWeek]], or alternatively [[Text]] conforming to iCal\'s syntax for byDay recurrence rules.'),
(6185, 1, 22, 'additionalProperty', 'additionalProperty', 'A property-value pair representing an additional characteristic of the entity, e.g. a product feature or another characteristic for which there is no matching property in schema.org.\\n\\nNote: Publishers should be aware that applications designed to use specific schema.org properties (e.g. https://schema.org/width, https://schema.org/color, https://schema.org/gtin13, ...) will typically expect such data to be provided using those properties, rather than using the generic property/value mechanism.\n'),
(6186, 1, 22, 'catalog', 'catalog', 'A data catalog which contains this dataset.'),
(6187, 1, 22, 'includedInDataCatalog', 'includedInDataCatalog', 'A data catalog which contains this dataset.'),
(6188, 1, 22, 'seriousAdverseOutcome', 'seriousAdverseOutcome', 'A possible serious complication and/or serious side effect of this therapy. Serious adverse outcomes include those that are life-threatening; result in death, disability, or permanent damage; require hospitalization or prolong existing hospitalization; cause congenital anomalies or birth defects; or jeopardize the patient and may require medical or surgical intervention to prevent one of the outcomes in this definition.'),
(6189, 1, 22, 'brand', 'brand', 'The brand(s) associated with a product or service, or the brand(s) maintained by an organization or business person.'),
(6190, 1, 22, 'isLiveBroadcast', 'isLiveBroadcast', 'True if the broadcast is of a live event.'),
(6191, 1, 22, 'sensoryRequirement', 'sensoryRequirement', 'A description of any sensory requirements and levels necessary to function on the job, including hearing and vision. Defined terms such as those in O*net may be used, but note that there is no way to specify the level of ability as well as its nature when using a defined term.'),
(6192, 1, 22, 'linkRelationship', 'linkRelationship', 'Indicates the relationship type of a Web link. '),
(6193, 1, 22, 'productSupported', 'productSupported', 'The product or service this support contact point is related to (such as product support for a particular product line). This can be a specific product or product line (e.g. \"iPhone\") or a general category of products or services (e.g. \"smartphones\").'),
(6194, 1, 22, 'ccRecipient', 'ccRecipient', 'A sub property of recipient. The recipient copied on a message.'),
(6195, 1, 22, 'recipient', 'recipient', 'A sub property of participant. The participant who is at the receiving end of the action.'),
(6196, 1, 22, 'occupationalCategory', 'occupationalCategory', 'A category describing the job, preferably using a term from a taxonomy such as [BLS O*NET-SOC](http://www.onetcenter.org/taxonomy.html), [ISCO-08](https://www.ilo.org/public/english/bureau/stat/isco/isco08/) or similar, with the property repeated for each applicable value. Ideally the taxonomy should be identified, and both the textual label and formal code for the category should be provided.\\n\nNote: for historical reasons, any textual label and formal code provided as a literal may be assumed to be from O*NET-SOC.'),
(6197, 1, 22, 'responsibilities', 'responsibilities', 'Responsibilities associated with this role or Occupation.'),
(6198, 1, 22, 'nonEqual', 'nonEqual', 'This ordering relation for qualitative values indicates that the subject is not equal to the object.'),
(6199, 1, 22, 'qualifications', 'qualifications', 'Specific qualifications required for this role or Occupation.'),
(6200, 1, 22, 'contactlessPayment', 'contactlessPayment', 'A secure method for consumers to purchase products or services via debit, credit or smartcards by using RFID or NFC technology.'),
(6201, 1, 22, 'causeOf', 'causeOf', 'The condition, complication, symptom, sign, etc. caused.'),
(6202, 1, 22, 'passengerPriorityStatus', 'passengerPriorityStatus', 'The priority status assigned to a passenger for security or boarding (e.g. FastTrack or Priority).'),
(6203, 1, 22, 'freeShippingThreshold', 'freeShippingThreshold', 'A monetary value above (or at) which the shipping rate becomes free. Intended to be used via an [[OfferShippingDetails]] with [[shippingSettingsLink]] matching this [[ShippingRateSettings]].'),
(6204, 1, 22, 'marginOfError', 'marginOfError', 'A marginOfError for an [[Observation]].'),
(6205, 1, 22, 'pageStart', 'pageStart', 'The page on which the work starts; for example \"135\" or \"xiii\".'),
(6206, 1, 22, 'dateRead', 'dateRead', 'The date/time at which the message has been read by the recipient if a single recipient exists.'),
(6207, 1, 22, 'tool', 'tool', 'A sub property of instrument. An object used (but not consumed) when performing instructions or a direction.'),
(6208, 1, 22, 'priceCurrency', 'priceCurrency', 'The currency of the price, or a price component when attached to [[PriceSpecification]] and its subtypes.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(6209, 1, 22, 'merchantReturnDays', 'merchantReturnDays', 'Specifies either a fixed return date or the number of days (from the delivery date) that a product can be returned. Used when the [[returnPolicyCategory]] property is specified as [[MerchantReturnFiniteReturnWindow]].'),
(6210, 1, 22, 'sugarContent', 'sugarContent', 'The number of grams of sugar.'),
(6211, 1, 22, 'thumbnail', 'thumbnail', 'Thumbnail image for an image or video.'),
(6212, 1, 22, 'hasMenuSection', 'hasMenuSection', 'A subgrouping of the menu (by dishes, course, serving time period, etc.).'),
(6213, 1, 22, 'loanRepaymentForm', 'loanRepaymentForm', 'A form of paying back money previously borrowed from a lender. Repayment usually takes the form of periodic payments that normally include part principal plus interest in each payment.'),
(6214, 1, 22, 'publisherImprint', 'publisherImprint', 'The publishing division which published the comic.'),
(6215, 1, 22, 'productionCompany', 'productionCompany', 'The production company or studio responsible for the item, e.g. series, video game, episode etc.'),
(6216, 1, 22, 'startTime', 'startTime', 'The startTime of something. For a reserved event or service (e.g. FoodEstablishmentReservation), the time that it is expected to start. For actions that span a period of time, when the action was performed. E.g. John wrote a book from *January* to December. For media, including audio and video, it\'s the time offset of the start of a clip within a larger file.\\n\\nNote that Event uses startDate/endDate instead of startTime/endTime, even when describing dates with times. This situation may be clarified in future revisions.'),
(6217, 1, 22, 'contactPoints', 'contactPoints', 'A contact point for a person or organization.'),
(6218, 1, 22, 'contactPoint', 'contactPoint', 'A contact point for a person or organization.'),
(6219, 1, 22, 'candidate', 'candidate', 'A sub property of object. The candidate subject of this action.'),
(6220, 1, 22, 'object', 'object', 'The object upon which the action is carried out, whose state is kept intact or changed. Also known as the semantic roles patient, affected or undergoer (which change their state) or theme (which doesn\'t). E.g. John read *a book*.'),
(6221, 1, 22, 'netWorth', 'netWorth', 'The total financial value of the person as calculated by subtracting assets from liabilities.'),
(6222, 1, 22, 'recordLabel', 'recordLabel', 'The label that issued the release.'),
(6223, 1, 22, 'offerCount', 'offerCount', 'The number of offers for the product.'),
(6224, 1, 22, 'seasons', 'seasons', 'A season in a media series.'),
(6225, 1, 22, 'season', 'season', 'A season in a media series.'),
(6226, 1, 22, 'status', 'status', 'The status of the study (enumerated).'),
(6227, 1, 22, 'includedComposition', 'includedComposition', 'Smaller compositions included in this work (e.g. a movement in a symphony).'),
(6228, 1, 22, 'inventoryLevel', 'inventoryLevel', 'The current approximate inventory level for the item or items.'),
(6229, 1, 22, 'isPlanForApartment', 'isPlanForApartment', 'Indicates some accommodation that this floor plan describes.'),
(6230, 1, 22, 'teaches', 'teaches', 'The item being described is intended to help a person learn the competency or learning outcome defined by the referenced term.'),
(6231, 1, 22, 'numberedPosition', 'numberedPosition', 'A number associated with a role in an organization, for example, the number on an athlete\'s jersey.'),
(6232, 1, 22, 'governmentBenefitsInfo', 'governmentBenefitsInfo', 'governmentBenefitsInfo provides information about government benefits associated with a SpecialAnnouncement.'),
(6233, 1, 22, 'cvdNumC19OverflowPats', 'cvdNumC19OverflowPats', 'numc19overflowpats - ED/OVERFLOW: Patients with suspected or confirmed COVID-19 who are in the ED or any overflow location awaiting an inpatient bed.'),
(6234, 1, 22, 'procedure', 'procedure', 'A description of the procedure involved in setting up, using, and/or installing the device.'),
(6235, 1, 22, 'paymentUrl', 'paymentUrl', 'The URL for sending a payment.'),
(6236, 1, 22, 'endTime', 'endTime', 'The endTime of something. For a reserved event or service (e.g. FoodEstablishmentReservation), the time that it is expected to end. For actions that span a period of time, when the action was performed. E.g. John wrote a book from January to *December*. For media, including audio and video, it\'s the time offset of the end of a clip within a larger file.\\n\\nNote that Event uses startDate/endDate instead of startTime/endTime, even when describing dates with times. This situation may be clarified in future revisions.'),
(6237, 1, 22, 'itemListElement', 'itemListElement', 'For itemListElement values, you can use simple strings (e.g. \"Peter\", \"Paul\", \"Mary\"), existing entities, or use ListItem.\\n\\nText values are best if the elements in the list are plain strings. Existing entities are best for a simple, unordered list of existing things in your data. ListItem is used with ordered lists when you want to provide additional context about the element in that list or when the same item might be in different places in different lists.\\n\\nNote: The order of elements in your mark-up is not sufficient for indicating the order or elements.  Use ListItem with a \'position\' property in such cases.'),
(6238, 1, 22, 'successorOf', 'successorOf', 'A pointer from a newer variant of a product  to its previous, often discontinued predecessor.'),
(6239, 1, 22, 'cvdNumVent', 'cvdNumVent', 'numvent - MECHANICAL VENTILATORS: Total number of ventilators available.'),
(6240, 1, 22, 'numberOfRooms', 'numberOfRooms', 'The number of rooms (excluding bathrooms and closets) of the accommodation or lodging business.\nTypical unit code(s): ROM for room or C62 for no unit. The type of room can be put in the unitText property of the QuantitativeValue.'),
(6241, 1, 22, 'potentialUse', 'potentialUse', 'Intended use of the BioChemEntity by humans.'),
(6242, 1, 22, 'characterAttribute', 'characterAttribute', 'A piece of data that represents a particular aspect of a fictional character (skill, power, character points, advantage, disadvantage).'),
(6243, 1, 22, 'chemicalComposition', 'chemicalComposition', 'The chemical composition describes the identity and relative ratio of the chemical elements that make up the substance.'),
(6244, 1, 22, 'numberOfSeasons', 'numberOfSeasons', 'The number of seasons in this series.'),
(6245, 1, 22, 'offersPrescriptionByMail', 'offersPrescriptionByMail', 'Whether prescriptions can be delivered by mail.'),
(6246, 1, 22, 'lyricist', 'lyricist', 'The person who wrote the words.'),
(6247, 1, 22, 'sdPublisher', 'sdPublisher', 'Indicates the party responsible for generating and publishing the current structured data markup, typically in cases where the structured data is derived automatically from existing published content but published on a different site. For example, student projects and open data initiatives often re-publish existing content with more explicitly structured metadata. The\n[[sdPublisher]] property helps make such practices more explicit.'),
(6248, 1, 22, 'isAvailableGenerically', 'isAvailableGenerically', 'True if the drug is available in a generic form (regardless of name).'),
(6249, 1, 22, 'algorithm', 'algorithm', 'The algorithm or rules to follow to compute the score.'),
(6250, 1, 22, 'includedRiskFactor', 'includedRiskFactor', 'A modifiable or non-modifiable risk factor included in the calculation, e.g. age, coexisting condition.'),
(6251, 1, 22, 'colorist', 'colorist', 'The individual who adds color to inked drawings.'),
(6252, 1, 22, 'recipeInstructions', 'recipeInstructions', 'A step in making the recipe, in the form of a single item (document, video, etc.) or an ordered list with HowToStep and/or HowToSection items.'),
(6253, 1, 22, 'repeatFrequency', 'repeatFrequency', 'Defines the frequency at which [[Event]]s will occur according to a schedule [[Schedule]]. The intervals between\n      events should be defined as a [[Duration]] of time.'),
(6254, 1, 22, 'frequency', 'frequency', 'How often the dose is taken, e.g. \'daily\'.'),
(6255, 1, 22, 'beneficiaryBank', 'beneficiaryBank', 'A bank or bank’s branch, financial institution or international financial institution operating the beneficiary’s bank account or releasing funds for the beneficiary.'),
(6256, 1, 22, 'arrivalGate', 'arrivalGate', 'Identifier of the flight\'s arrival gate.'),
(6257, 1, 22, 'contentType', 'contentType', 'The supported content type(s) for an EntryPoint response.'),
(6258, 1, 22, 'arrivalBoatTerminal', 'arrivalBoatTerminal', 'The terminal or port from which the boat arrives.'),
(6259, 1, 22, 'address', 'address', 'Physical address of the item.'),
(6260, 1, 22, 'checkoutTime', 'checkoutTime', 'The latest someone may check out of a lodging establishment.'),
(6261, 1, 22, 'billingAddress', 'billingAddress', 'The billing address for the order.'),
(6262, 1, 22, 'eventSchedule', 'eventSchedule', 'Associates an [[Event]] with a [[Schedule]]. There are circumstances where it is preferable to share a schedule for a series of\n      repeating events rather than data on the individual events themselves. For example, a website or application might prefer to publish a schedule for a weekly\n      gym class rather than provide data on every event. A schedule could be processed by applications to add forthcoming events to a calendar. An [[Event]] that\n      is associated with a [[Schedule]] using this property should not have [[startDate]] or [[endDate]] properties. These are instead defined within the associated\n      [[Schedule]], this avoids any ambiguity for clients using the data. The property might have repeated values to specify different schedules, e.g. for different months\n      or seasons.'),
(6263, 1, 22, 'validThrough', 'validThrough', 'The date after when the item is not valid. For example the end of an offer, salary period, or a period of opening hours.'),
(6264, 1, 22, 'warrantyPromise', 'warrantyPromise', 'The warranty promise(s) included in the offer.'),
(6265, 1, 22, 'warranty', 'warranty', 'The warranty promise(s) included in the offer.'),
(6266, 1, 22, 'relatedTherapy', 'relatedTherapy', 'A medical therapy related to this anatomy.'),
(6267, 1, 22, 'slogan', 'slogan', 'A slogan or motto associated with the item.'),
(6268, 1, 22, 'employmentUnit', 'employmentUnit', 'Indicates the department, unit and/or facility where the employee reports and/or in which the job is to be performed.'),
(6269, 1, 22, 'geographicArea', 'geographicArea', 'The geographic area associated with the audience.'),
(6270, 1, 22, 'inverseOf', 'inverseOf', 'Relates a property to a property that is its inverse. Inverse properties relate the same pairs of items to each other, but in reversed direction. For example, the \'alumni\' and \'alumniOf\' properties are inverseOf each other. Some properties don\'t have explicit inverses; in these situations RDFa and JSON-LD syntax for reverse properties can be used.'),
(6271, 1, 22, 'broadcastTimezone', 'broadcastTimezone', 'The timezone in [ISO 8601 format](http://en.wikipedia.org/wiki/ISO_8601) for which the service bases its broadcasts.'),
(6272, 1, 22, 'timeOfDay', 'timeOfDay', 'The time of day the program normally runs. For example, \"evenings\".'),
(6273, 1, 22, 'bestRating', 'bestRating', 'The highest value allowed in this rating system. If bestRating is omitted, 5 is assumed.'),
(6274, 1, 22, 'processingTime', 'processingTime', 'Estimated processing time for the service using this channel.'),
(6275, 1, 22, 'membershipPointsEarned', 'membershipPointsEarned', 'The number of membership points earned by the member. If necessary, the unitText can be used to express the units the points are issued in. (E.g. stars, miles, etc.)'),
(6276, 1, 22, 'elevation', 'elevation', 'The elevation of a location ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)). Values may be of the form \'NUMBER UNIT\\_OF\\_MEASUREMENT\' (e.g., \'1,000 m\', \'3,200 ft\') while numbers alone should be assumed to be a value in meters.'),
(6277, 1, 22, 'creditedTo', 'creditedTo', 'The group the release is credited to if different than the byArtist. For example, Red and Blue is credited to \"Stefani Germanotta Band\", but by Lady Gaga.'),
(6278, 1, 22, 'sport', 'sport', 'A type of sport (e.g. Baseball).'),
(6279, 1, 22, 'seeks', 'seeks', 'A pointer to products or services sought by the organization or person (demand).'),
(6280, 1, 22, 'additionalName', 'additionalName', 'An additional name for a Person, can be used for a middle name.'),
(6281, 1, 22, 'alternateName', 'alternateName', 'An alias for the item.'),
(6282, 1, 22, 'downPayment', 'downPayment', 'a type of payment made in cash during the onset of the purchase of an expensive good/service. The payment typically represents only a percentage of the full purchase price.'),
(6283, 1, 22, 'postOfficeBoxNumber', 'postOfficeBoxNumber', 'The post office box number for PO box addresses.'),
(6284, 1, 22, 'energyEfficiencyScaleMax', 'energyEfficiencyScaleMax', 'Specifies the most energy efficient class on the regulated EU energy consumption scale for the product category a product belongs to. For example, energy consumption for televisions placed on the market after January 1, 2020 is scaled from D to A+++.'),
(6285, 1, 22, 'userInteractionCount', 'userInteractionCount', 'The number of interactions for the CreativeWork using the WebSite or SoftwareApplication.'),
(6286, 1, 22, 'sizeGroup', 'sizeGroup', 'The size group (also known as \"size type\") for a product\'s size. Size groups are common in the fashion industry to define size segments and suggested audiences for wearable products. Multiple values can be combined, for example \"men\'s big and tall\", \"petite maternity\" or \"regular\"'),
(6287, 1, 22, 'productionDate', 'productionDate', 'The date of production of the item, e.g. vehicle.'),
(6288, 1, 22, 'hostingOrganization', 'hostingOrganization', 'The organization (airline, travelers\' club, etc.) the membership is made with.'),
(6289, 1, 22, 'addOn', 'addOn', 'An additional offer that can only be obtained in combination with the first base offer (e.g. supplements and extensions that are available for a surcharge).'),
(6290, 1, 22, 'hasOfferCatalog', 'hasOfferCatalog', 'Indicates an OfferCatalog listing for this Organization, Person, or Service.'),
(6291, 1, 22, 'shippingDetails', 'shippingDetails', 'Indicates information about the shipping policies and options associated with an [[Offer]].'),
(6292, 1, 22, 'seasonNumber', 'seasonNumber', 'Position of the season within an ordered group of seasons.'),
(6293, 1, 22, 'loanType', 'loanType', 'The type of a loan or credit.'),
(6294, 1, 22, 'documentation', 'documentation', 'Further documentation describing the Web API in more detail.'),
(6295, 1, 22, 'domiciledMortgage', 'domiciledMortgage', 'Whether borrower is a resident of the jurisdiction where the property is located.'),
(6296, 1, 22, 'drugUnit', 'drugUnit', 'The unit in which the drug is measured, e.g. \'5 mg tablet\'.'),
(6297, 1, 22, 'physicalRequirement', 'physicalRequirement', 'A description of the types of physical activity associated with the job. Defined terms such as those in O*net may be used, but note that there is no way to specify the level of ability as well as its nature when using a defined term.'),
(6298, 1, 22, 'numberOfCredits', 'numberOfCredits', 'The number of credits or units awarded by a Course or required to complete an EducationalOccupationalProgram.'),
(6299, 1, 22, 'funder', 'funder', 'A person or organization that supports (sponsors) something through some kind of financial contribution.'),
(6300, 1, 22, 'sponsor', 'sponsor', 'A person or organization that supports a thing through a pledge, promise, or financial contribution. E.g. a sponsor of a Medical Study or a corporate sponsor of an event.'),
(6301, 1, 22, 'nonProprietaryName', 'nonProprietaryName', 'The generic name of this drug or supplement.'),
(6302, 1, 22, 'returnPolicyCountry', 'returnPolicyCountry', 'The country where the product has to be sent to for returns, for example \"Ireland\" using the [[name]] property of [[Country]]. You can also provide the two-letter [ISO 3166-1 alpha-2 country code](http://en.wikipedia.org/wiki/ISO_3166-1). Note that this can be different from the country where the product was originally shipped from or sent to.'),
(6303, 1, 22, 'screenCount', 'screenCount', 'The number of screens in the movie theater.'),
(6304, 1, 22, 'cashBack', 'cashBack', 'A cardholder benefit that pays the cardholder a small percentage of their net expenditures.'),
(6305, 1, 22, 'underName', 'underName', 'The person or organization the reservation or ticket is for.'),
(6306, 1, 22, 'logo', 'logo', 'An associated logo.'),
(6307, 1, 22, 'image', 'image', 'An image of the item. This can be a [[URL]] or a fully described [[ImageObject]].'),
(6308, 1, 22, 'domainIncludes', 'domainIncludes', 'Relates a property to a class that is (one of) the type(s) the property is expected to be used on.'),
(6309, 1, 22, 'inChI', 'inChI', 'Non-proprietary identifier for molecular entity that can be used in printed and electronic data sources thus enabling easier linking of diverse data compilations.'),
(6310, 1, 22, 'quarantineGuidelines', 'quarantineGuidelines', 'Guidelines about quarantine rules, e.g. in the context of a pandemic.'),
(6311, 1, 22, 'discountCode', 'discountCode', 'Code used to redeem a discount.'),
(6312, 1, 22, 'musicalKey', 'musicalKey', 'The key, mode, or scale this composition uses.'),
(6313, 1, 22, 'productID', 'productID', 'The product identifier, such as ISBN. For example: ``` meta itemprop=\"productID\" content=\"isbn:123-456-789\" ```.'),
(6314, 1, 22, 'breastfeedingWarning', 'breastfeedingWarning', 'Any precaution, guidance, contraindication, etc. related to this drug\'s use by breastfeeding mothers.'),
(6315, 1, 22, 'relatedStructure', 'relatedStructure', 'Related anatomical structure(s) that are not part of the system but relate or connect to it, such as vascular bundles associated with an organ system.'),
(6316, 1, 22, 'currency', 'currency', 'The currency in which the monetary amount is expressed.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(6317, 1, 22, 'cvdNumC19MechVentPats', 'cvdNumC19MechVentPats', 'numc19mechventpats - HOSPITALIZED and VENTILATED: Patients hospitalized in an NHSN inpatient care location who have suspected or confirmed COVID-19 and are on a mechanical ventilator.'),
(6318, 1, 22, 'ethicsPolicy', 'ethicsPolicy', 'Statement about ethics policy, e.g. of a [[NewsMediaOrganization]] regarding journalistic and publishing practices, or of a [[Restaurant]], a page describing food source policies. In the case of a [[NewsMediaOrganization]], an ethicsPolicy is typically a statement describing the personal, organizational, and corporate standards of behavior expected by the organization.'),
(6319, 1, 22, 'refundType', 'refundType', 'A refund type, from an enumerated list.'),
(6320, 1, 22, 'postalCodeRange', 'postalCodeRange', 'A defined range of postal codes.'),
(6321, 1, 22, 'recognizedBy', 'recognizedBy', 'An organization that acknowledges the validity, value or utility of a credential. Note: recognition may include a process of quality assurance or accreditation.'),
(6322, 1, 22, 'workPerformed', 'workPerformed', 'A work performed in some event, for example a play performed in a TheaterEvent.'),
(6323, 1, 22, 'workFeatured', 'workFeatured', 'A work featured in some event, e.g. exhibited in an ExhibitionEvent.\n       Specific subproperties are available for workPerformed (e.g. a play), or a workPresented (a Movie at a ScreeningEvent).'),
(6324, 1, 22, 'mentions', 'mentions', 'Indicates that the CreativeWork contains a reference to, but is not necessarily about a concept.'),
(6325, 1, 22, 'customerRemorseReturnLabelSource', 'customerRemorseReturnLabelSource', 'The method (from an enumeration) by which the customer obtains a return shipping label for a product returned due to customer remorse.'),
(6326, 1, 22, 'legislationConsolidates', 'legislationConsolidates', 'Indicates another legislation taken into account in this consolidated legislation (which is usually the product of an editorial process that revises the legislation). This property should be used multiple times to refer to both the original version or the previous consolidated version, and to the legislations making the change.'),
(6327, 1, 22, 'aggregateRating', 'aggregateRating', 'The overall rating, based on a collection of reviews or ratings, of the item.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(6328, 1, 22, 'itinerary', 'itinerary', 'Destination(s) ( [[Place]] ) that make up a trip. For a trip where destination order is important use [[ItemList]] to specify that order (see examples).'),
(6329, 1, 22, 'globalLocationNumber', 'globalLocationNumber', 'The [Global Location Number](http://www.gs1.org/gln) (GLN, sometimes also referred to as International Location Number or ILN) of the respective organization, person, or place. The GLN is a 13-digit number used to identify parties and physical locations.'),
(6330, 1, 22, 'applicantLocationRequirements', 'applicantLocationRequirements', 'The location(s) applicants can apply from. This is usually used for telecommuting jobs where the applicant does not need to be in a physical office. Note: This should not be used for citizenship or work visa requirements.'),
(6331, 1, 22, 'unitCode', 'unitCode', 'The unit of measurement given using the UN/CEFACT Common Code (3 characters) or a URL. Other codes than the UN/CEFACT Common Code may be used with a prefix followed by a colon.'),
(6332, 1, 22, 'parents', 'parents', 'A parents of the person.'),
(6333, 1, 22, 'parent', 'parent', 'A parent of this person.'),
(6334, 1, 22, 'renegotiableLoan', 'renegotiableLoan', 'Whether the terms for payment of interest can be renegotiated during the life of the loan.'),
(6335, 1, 22, 'priceComponent', 'priceComponent', 'This property links to all [[UnitPriceSpecification]] nodes that apply in parallel for the [[CompoundPriceSpecification]] node.'),
(6336, 1, 22, 'eligibleDuration', 'eligibleDuration', 'The duration for which the given offer is valid.'),
(6337, 1, 22, 'copyrightYear', 'copyrightYear', 'The year during which the claimed copyright for the CreativeWork was first asserted.'),
(6338, 1, 22, 'trialDesign', 'trialDesign', 'Specifics about the trial design (enumerated).'),
(6339, 1, 22, 'serviceAudience', 'serviceAudience', 'The audience eligible for this service.'),
(6340, 1, 22, 'audience', 'audience', 'An intended audience, i.e. a group for whom something was created.'),
(6341, 1, 22, 'vehicleSpecialUsage', 'vehicleSpecialUsage', 'Indicates whether the vehicle has been used for special purposes, like commercial rental, driving school, or as a taxi. The legislation in many countries requires this information to be revealed when offering a car for sale.'),
(6342, 1, 22, 'comment', 'comment', 'Comments, typically from users.'),
(6343, 1, 22, 'publicationType', 'publicationType', 'The type of the medical article, taken from the US NLM MeSH publication type catalog. See also [MeSH documentation](http://www.nlm.nih.gov/mesh/pubtypes.html).'),
(6344, 1, 22, 'availableIn', 'availableIn', 'The location in which the strength is available.'),
(6345, 1, 22, 'legislationIdentifier', 'legislationIdentifier', 'An identifier for the legislation. This can be either a string-based identifier, like the CELEX at EU level or the NOR in France, or a web-based, URL/URI identifier, like an ELI (European Legislation Identifier) or an URN-Lex.'),
(6346, 1, 22, 'discount', 'discount', 'Any discount applied (to an Order).'),
(6347, 1, 22, 'model', 'model', 'The model of the product. Use with the URL of a ProductModel or a textual representation of the model identifier. The URL of the ProductModel can be from an external source. It is recommended to additionally provide strong product identifiers via the gtin8/gtin13/gtin14 and mpn properties.'),
(6348, 1, 22, 'numberOfEpisodes', 'numberOfEpisodes', 'The number of episodes in this season or series.'),
(6349, 1, 22, 'deathDate', 'deathDate', 'Date of death.'),
(6350, 1, 22, 'servingSize', 'servingSize', 'The serving size, in terms of the number of volume or mass.'),
(6351, 1, 22, 'ownershipFundingInfo', 'ownershipFundingInfo', 'For an [[Organization]] (often but not necessarily a [[NewsMediaOrganization]]), a description of organizational ownership structure; funding and grants. In a news/media setting, this is with particular reference to editorial independence.   Note that the [[funder]] is also available and can be used to make basic funder information machine-readable.'),
(6352, 1, 22, 'playerType', 'playerType', 'Player type required&#x2014;for example, Flash or Silverlight.'),
(6353, 1, 22, 'priceComponentType', 'priceComponentType', 'Identifies a price component (for example, a line item on an invoice), part of the total price for an offer.'),
(6354, 1, 22, 'abridged', 'abridged', 'Indicates whether the book is an abridged edition.'),
(6355, 1, 22, 'reviewAspect', 'reviewAspect', 'This Review or Rating is relevant to this part or facet of the itemReviewed.'),
(6356, 1, 22, 'advanceBookingRequirement', 'advanceBookingRequirement', 'The amount of time that is required between accepting the offer and the actual usage of the resource or service.'),
(6357, 1, 22, 'sender', 'sender', 'A sub property of participant. The participant who is at the sending end of the action.'),
(6358, 1, 22, 'participant', 'participant', 'Other co-agents that participated in the action indirectly. E.g. John wrote a book with *Steve*.'),
(6359, 1, 22, 'ingredients', 'ingredients', 'A single ingredient used in the recipe, e.g. sugar, flour or garlic.'),
(6360, 1, 22, 'recipeIngredient', 'recipeIngredient', 'A single ingredient used in the recipe, e.g. sugar, flour or garlic.'),
(6361, 1, 22, 'supply', 'supply', 'A sub-property of instrument. A supply consumed when performing instructions or a direction.'),
(6362, 1, 22, 'area', 'area', 'The area within which users can expect to reach the broadcast service.'),
(6363, 1, 22, 'serviceArea', 'serviceArea', 'The geographic area where the service is provided.'),
(6364, 1, 22, 'downvoteCount', 'downvoteCount', 'The number of downvotes this question, answer or comment has received from the community.'),
(6365, 1, 22, 'children', 'children', 'A child of the person.'),
(6366, 1, 22, 'arrivalPlatform', 'arrivalPlatform', 'The platform where the train arrives.'),
(6367, 1, 22, 'firstPerformance', 'firstPerformance', 'The date and place the work was first performed.'),
(6368, 1, 22, 'ratingValue', 'ratingValue', 'The rating for the content.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(6369, 1, 22, 'collectionSize', 'collectionSize', 'The number of items in the [[Collection]].'),
(6370, 1, 22, 'resultReview', 'resultReview', 'A sub property of result. The review that resulted in the performing of the action.'),
(6371, 1, 22, 'result', 'result', 'The result produced in the action. E.g. John wrote *a book*.'),
(6372, 1, 22, 'albums', 'albums', 'A collection of music albums.'),
(6373, 1, 22, 'album', 'album', 'A music album.'),
(6374, 1, 22, 'datePublished', 'datePublished', 'Date of first broadcast/publication.'),
(6375, 1, 22, 'includesAttraction', 'includesAttraction', 'Attraction located at destination.'),
(6376, 1, 22, 'publishedOn', 'publishedOn', 'A broadcast service associated with the publication event.'),
(6377, 1, 22, 'actionStatus', 'actionStatus', 'Indicates the current disposition of the Action.'),
(6378, 1, 22, 'orderDate', 'orderDate', 'Date order was placed.'),
(6379, 1, 22, 'prescribingInfo', 'prescribingInfo', 'Link to prescribing information for the drug.'),
(6380, 1, 22, 'contributor', 'contributor', 'A secondary contributor to the CreativeWork or Event.'),
(6381, 1, 22, 'yearBuilt', 'yearBuilt', 'The year an [[Accommodation]] was constructed. This corresponds to the [YearBuilt field in RESO](https://ddwiki.reso.org/display/DDW17/YearBuilt+Field). '),
(6382, 1, 22, 'trainingSalary', 'trainingSalary', 'The estimated salary earned while in the program.'),
(6383, 1, 22, 'orderQuantity', 'orderQuantity', 'The number of the item ordered. If the property is not set, assume the quantity is one.'),
(6384, 1, 22, 'bioChemInteraction', 'bioChemInteraction', 'A BioChemEntity that is known to interact with this item.'),
(6385, 1, 22, 'healthPlanId', 'healthPlanId', 'The 14-character, HIOS-generated Plan ID number. (Plan IDs must be unique, even across different markets.)'),
(6386, 1, 22, 'valuePattern', 'valuePattern', 'Specifies a regular expression for testing literal values according to the HTML spec.'),
(6387, 1, 22, 'orderItemNumber', 'orderItemNumber', 'The identifier of the order item.'),
(6388, 1, 22, 'accommodationCategory', 'accommodationCategory', 'Category of an [[Accommodation]], following real estate conventions, e.g. RESO (see [PropertySubType](https://ddwiki.reso.org/display/DDW17/PropertySubType+Field), and [PropertyType](https://ddwiki.reso.org/display/DDW17/PropertyType+Field) fields  for suggested values).'),
(6389, 1, 22, 'category', 'category', 'A category for the item. Greater signs or slashes can be used to informally indicate a category hierarchy.'),
(6390, 1, 22, 'sdLicense', 'sdLicense', 'A license document that applies to this structured data, typically indicated by URL.'),
(6391, 1, 22, 'broadcastFrequency', 'broadcastFrequency', 'The frequency used for over-the-air broadcasts. Numeric values or simple ranges, e.g. 87-99. In addition a shortcut idiom is supported for frequences of AM and FM radio channels, e.g. \"87 FM\".'),
(6392, 1, 22, 'abstract', 'abstract', 'An abstract is a short description that summarizes a [[CreativeWork]].'),
(6393, 1, 22, 'floorSize', 'floorSize', 'The size of the accommodation, e.g. in square meter or squarefoot.\nTypical unit code(s): MTK for square meter, FTK for square foot, or YDK for square yard '),
(6394, 1, 22, 'measurementTechnique', 'measurementTechnique', 'A technique or technology used in a [[Dataset]] (or [[DataDownload]], [[DataCatalog]]),\ncorresponding to the method used for measuring the corresponding variable(s) (described using [[variableMeasured]]). This is oriented towards scientific and scholarly dataset publication but may have broader applicability; it is not intended as a full representation of measurement, but rather as a high level summary for dataset discovery.\n\nFor example, if [[variableMeasured]] is: molecule concentration, [[measurementTechnique]] could be: \"mass spectrometry\" or \"nmr spectroscopy\" or \"colorimetry\" or \"immunofluorescence\".\n\nIf the [[variableMeasured]] is \"depression rating\", the [[measurementTechnique]] could be \"Zung Scale\" or \"HAM-D\" or \"Beck Depression Inventory\".\n\nIf there are several [[variableMeasured]] properties recorded for some given data object, use a [[PropertyValue]] for each [[variableMeasured]] and attach the corresponding [[measurementTechnique]].\n      '),
(6395, 1, 22, 'seatRow', 'seatRow', 'The row location of the reserved seat (e.g., B).'),
(6396, 1, 22, 'programPrerequisites', 'programPrerequisites', 'Prerequisites for enrolling in the program.'),
(6397, 1, 22, 'endOffset', 'endOffset', 'The end time of the clip expressed as the number of seconds from the beginning of the work.'),
(6398, 1, 22, 'associatedClaimReview', 'associatedClaimReview', 'An associated [[ClaimReview]], related by specific common content, topic or claim. The expectation is that this property would be most typically used in cases where a single activity is conducting both claim reviews and media reviews, in which case [[relatedMediaReview]] would commonly be used on a [[ClaimReview]], while [[relatedClaimReview]] would be used on [[MediaReview]].'),
(6399, 1, 22, 'application', 'application', 'An application that can complete the request.'),
(6400, 1, 22, 'actionApplication', 'actionApplication', 'An application that can complete the request.'),
(6401, 1, 22, 'cookTime', 'cookTime', 'The time it takes to actually cook the dish, in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(6402, 1, 22, 'performTime', 'performTime', 'The length of time it takes to perform instructions or a direction (not including time to prepare the supplies), in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(6403, 1, 22, 'availableChannel', 'availableChannel', 'A means of accessing the service (e.g. a phone bank, a web site, a location, etc.).'),
(6404, 1, 22, 'seatNumber', 'seatNumber', 'The location of the reserved seat (e.g., 27).'),
(6405, 1, 22, 'costCategory', 'costCategory', 'The category of cost, such as wholesale, retail, reimbursement cap, etc.'),
(6406, 1, 22, 'associatedAnatomy', 'associatedAnatomy', 'The anatomy of the underlying organ system or structures associated with this entity.'),
(6407, 1, 22, 'homeTeam', 'homeTeam', 'The home team in a sports event.'),
(6408, 1, 22, 'competitor', 'competitor', 'A competitor in a sports event.'),
(6409, 1, 22, 'iswcCode', 'iswcCode', 'The International Standard Musical Work Code for the composition.'),
(6410, 1, 22, 'inChIKey', 'inChIKey', 'InChIKey is a hashed version of the full InChI (using the SHA-256 algorithm).'),
(6411, 1, 22, 'gameAvailabilityType', 'gameAvailabilityType', 'Indicates the availability type of the game content associated with this action, such as whether it is a full version or a demo.'),
(6412, 1, 22, 'publishedBy', 'publishedBy', 'An agent associated with the publication event.'),
(6413, 1, 22, 'shippingOrigin', 'shippingOrigin', 'Indicates the origin of a shipment, i.e. where it should be coming from.'),
(6414, 1, 22, 'requirements', 'requirements', 'Component dependency requirements for application. This includes runtime environments and shared libraries that are not included in the application distribution package, but required to run the application (examples: DirectX, Java or .NET runtime).'),
(6415, 1, 22, 'softwareRequirements', 'softwareRequirements', 'Component dependency requirements for application. This includes runtime environments and shared libraries that are not included in the application distribution package, but required to run the application (examples: DirectX, Java or .NET runtime).'),
(6416, 1, 22, 'thumbnailUrl', 'thumbnailUrl', 'A thumbnail image relevant to the Thing.'),
(6417, 1, 22, 'newsUpdatesAndGuidelines', 'newsUpdatesAndGuidelines', 'Indicates a page with news updates and guidelines. This could often be (but is not required to be) the main page containing [[SpecialAnnouncement]] markup on a site.'),
(6418, 1, 22, 'priceSpecification', 'priceSpecification', 'One or more detailed price specifications, indicating the unit price and delivery or payment charges.'),
(6419, 1, 22, 'availableStrength', 'availableStrength', 'An available dosage strength for the drug.'),
(6420, 1, 22, 'musicArrangement', 'musicArrangement', 'An arrangement derived from the composition.'),
(6421, 1, 22, 'healthPlanCoinsuranceOption', 'healthPlanCoinsuranceOption', 'Whether the coinsurance applies before or after deductible, etc. TODO: Is this a closed set?'),
(6422, 1, 22, 'datePosted', 'datePosted', 'Publication date of an online listing.'),
(6423, 1, 22, 'reviews', 'reviews', 'Review of the item.'),
(6424, 1, 22, 'review', 'review', 'A review of the item.'),
(6425, 1, 22, 'validUntil', 'validUntil', 'The date when the item is no longer valid.'),
(6426, 1, 22, 'requiresSubscription', 'requiresSubscription', 'Indicates if use of the media require a subscription  (either paid or free). Allowed values are ```true``` or ```false``` (note that an earlier version had \'yes\', \'no\').'),
(6427, 1, 22, 'ratingCount', 'ratingCount', 'The count of total number of ratings.'),
(6428, 1, 22, 'expectedArrivalFrom', 'expectedArrivalFrom', 'The earliest date the package may arrive.'),
(6429, 1, 22, 'version', 'version', 'The version of the CreativeWork embodied by a specified resource.'),
(6430, 1, 22, 'dropoffTime', 'dropoffTime', 'When a rental car can be dropped off.'),
(6431, 1, 22, 'infectiousAgentClass', 'infectiousAgentClass', 'The class of infectious agent (bacteria, prion, etc.) that causes the disease.'),
(6432, 1, 22, 'doseValue', 'doseValue', 'The value of the dose, e.g. 500.'),
(6433, 1, 22, 'cvdNumC19Died', 'cvdNumC19Died', 'numc19died - DEATHS: Patients with suspected or confirmed COVID-19 who died in the hospital, ED, or any overflow location.'),
(6434, 1, 22, 'alternativeHeadline', 'alternativeHeadline', 'A secondary title of the CreativeWork.'),
(6435, 1, 22, 'longitude', 'longitude', 'The longitude of a location. For example ```-122.08585``` ([WGS 84](https://en.wikipedia.org/wiki/World_Geodetic_System)).'),
(6436, 1, 22, 'energyEfficiencyScaleMin', 'energyEfficiencyScaleMin', 'Specifies the least energy efficient class on the regulated EU energy consumption scale for the product category a product belongs to. For example, energy consumption for televisions placed on the market after January 1, 2020 is scaled from D to A+++.'),
(6437, 1, 22, 'appliesToPaymentMethod', 'appliesToPaymentMethod', 'The payment method(s) to which the payment charge specification applies.'),
(6438, 1, 22, 'credentialCategory', 'credentialCategory', 'The category or type of credential being described, for example \"degree”, “certificate”, “badge”, or more specific term.'),
(6439, 1, 22, 'appliesToDeliveryMethod', 'appliesToDeliveryMethod', 'The delivery method(s) to which the delivery charge or payment charge specification applies.'),
(6440, 1, 22, 'targetName', 'targetName', 'The name of a node in an established educational framework.'),
(6441, 1, 22, 'repetitions', 'repetitions', 'Number of times one should repeat the activity.'),
(6442, 1, 22, 'originatesFrom', 'originatesFrom', 'The vasculature the lymphatic structure originates, or afferents, from.'),
(6443, 1, 22, 'positiveNotes', 'positiveNotes', 'Provides positive considerations regarding something, for example product highlights or (alongside [[negativeNotes]]) pro/con lists for reviews.\n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described.\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most positive is at the beginning of the list).'),
(6444, 1, 22, 'passengerSequenceNumber', 'passengerSequenceNumber', 'The passenger\'s sequence number as assigned by the airline.'),
(6445, 1, 22, 'clipNumber', 'clipNumber', 'Position of the clip within an ordered group of clips.'),
(6446, 1, 22, 'gtin13', 'gtin13', 'The GTIN-13 code of the product, or the product to which the offer refers. This is equivalent to 13-digit ISBN codes and EAN UCC-13. Former 12-digit UPC codes can be converted into a GTIN-13 code by simply adding a preceding zero. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(6447, 1, 22, 'hasAdultConsideration', 'hasAdultConsideration', 'Used to tag an item to be intended or suitable for consumption or use by adults only.'),
(6448, 1, 22, 'asin', 'asin', 'An Amazon Standard Identification Number (ASIN) is a 10-character alphanumeric unique identifier assigned by Amazon.com and its partners for product identification within the Amazon organization (summary from [Wikipedia](https://en.wikipedia.org/wiki/Amazon_Standard_Identification_Number)\'s article).\n\nNote also that this is a definition for how to include ASINs in Schema.org data, and not a definition of ASINs in general - see documentation from Amazon for authoritative details.\nASINs are most commonly encoded as text strings, but the [asin] property supports URL/URI as potential values too.'),
(6449, 1, 22, 'reservedTicket', 'reservedTicket', 'A ticket associated with the reservation.'),
(6450, 1, 22, 'commentCount', 'commentCount', 'The number of comments this CreativeWork (e.g. Article, Question or Answer) has received. This is most applicable to works published in Web sites with commenting system; additional comments may exist elsewhere.'),
(6451, 1, 22, 'programMembershipUsed', 'programMembershipUsed', 'Any membership in a frequent flyer, hotel loyalty program, etc. being applied to the reservation.'),
(6452, 1, 22, 'alcoholWarning', 'alcoholWarning', 'Any precaution, guidance, contraindication, etc. related to consumption of alcohol while taking this drug.'),
(6453, 1, 22, 'typicalTest', 'typicalTest', 'A medical test typically performed given this condition.'),
(6454, 1, 22, 'duringMedia', 'duringMedia', 'A media object representing the circumstances while performing this direction.'),
(6455, 1, 22, 'valueMinLength', 'valueMinLength', 'Specifies the minimum allowed range for number of characters in a literal value.'),
(6456, 1, 22, 'cvdNumC19HOPats', 'cvdNumC19HOPats', 'numc19hopats - HOSPITAL ONSET: Patients hospitalized in an NHSN inpatient care location with onset of suspected or confirmed COVID-19 14 or more days after hospitalization.'),
(6457, 1, 22, 'citation', 'citation', 'A citation or reference to another creative work, such as another publication, web page, scholarly article, etc.'),
(6458, 1, 22, 'musicGroupMember', 'musicGroupMember', 'A member of a music group&#x2014;for example, John, Paul, George, or Ringo.'),
(6459, 1, 22, 'member', 'member', 'A member of an Organization or a ProgramMembership. Organizations can be members of organizations; ProgramMembership is typically for individuals.'),
(6460, 1, 22, 'cvdNumICUBedsOcc', 'cvdNumICUBedsOcc', 'numicubedsocc - ICU BED OCCUPANCY: Total number of staffed inpatient ICU beds that are occupied.'),
(6461, 1, 22, 'numberOfEmployees', 'numberOfEmployees', 'The number of employees in an organization, e.g. business.'),
(6462, 1, 22, 'subStageSuffix', 'subStageSuffix', 'The substage, e.g. \'a\' for Stage IIIa.'),
(6463, 1, 22, 'coursePrerequisites', 'coursePrerequisites', 'Requirements for taking the Course. May be completion of another [[Course]] or a textual description like \"permission of instructor\". Requirements may be a pre-requisite competency, referenced using [[AlignmentObject]].'),
(6464, 1, 22, 'sharedContent', 'sharedContent', 'A CreativeWork such as an image, video, or audio clip shared as part of this posting.'),
(6465, 1, 22, 'urlTemplate', 'urlTemplate', 'An url template (RFC6570) that will be used to construct the target of the execution of the action.'),
(6466, 1, 22, 'gtin8', 'gtin8', 'The GTIN-8 code of the product, or the product to which the offer refers. This code is also known as EAN/UCC-8 or 8-digit EAN. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.'),
(6467, 1, 22, 'vehicleEngine', 'vehicleEngine', 'Information about the engine or engines of the vehicle.'),
(6468, 1, 22, 'priceRange', 'priceRange', 'The price range of the business, for example ```$$$```.'),
(6469, 1, 22, 'numberOfAvailableAccommodationUnits', 'numberOfAvailableAccommodationUnits', 'Indicates the number of available accommodation units in an [[ApartmentComplex]], or the number of accommodation units for a specific [[FloorPlan]] (within its specific [[ApartmentComplex]]). See also [[numberOfAccommodationUnits]].'),
(6470, 1, 22, 'priceType', 'priceType', 'Defines the type of a price specified for an offered product, for example a list price, a (temporary) sale price or a manufacturer suggested retail price. If multiple prices are specified for an offer the [[priceType]] property can be used to identify the type of each such specified price. The value of priceType can be specified as a value from enumeration PriceTypeEnumeration or as a free form text string for price types that are not already predefined in PriceTypeEnumeration.'),
(6471, 1, 22, 'verificationFactCheckingPolicy', 'verificationFactCheckingPolicy', 'Disclosure about verification and fact-checking processes for a [[NewsMediaOrganization]] or other fact-checking [[Organization]].'),
(6472, 1, 22, 'negativeNotes', 'negativeNotes', 'Provides negative considerations regarding something, most typically in pro/con lists for reviews (alongside [[positiveNotes]]). For symmetry \n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described. Since product descriptions \ntend to emphasise positive claims, it may be relatively unusual to find [[negativeNotes]] used in this way. Nevertheless for the sake of symmetry, [[negativeNotes]] can be used on [[Product]].\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most negative is at the beginning of the list).'),
(6473, 1, 22, 'startOffset', 'startOffset', 'The start time of the clip expressed as the number of seconds from the beginning of the work.'),
(6474, 1, 22, 'codeRepository', 'codeRepository', 'Link to the repository where the un-compiled, human readable code and related code is located (SVN, GitHub, CodePlex).'),
(6475, 1, 22, 'differentialDiagnosis', 'differentialDiagnosis', 'One of a set of differential diagnoses for the condition. Specifically, a closely-related or competing diagnosis typically considered later in the cognitive process whereby this medical condition is distinguished from others most likely responsible for a similar collection of signs and symptoms to reach the most parsimonious diagnosis or diagnoses in a patient.'),
(6476, 1, 22, 'free', 'free', 'A flag to signal that the item, event, or place is accessible for free.'),
(6477, 1, 22, 'isAccessibleForFree', 'isAccessibleForFree', 'A flag to signal that the item, event, or place is accessible for free.'),
(6478, 1, 22, 'subEvents', 'subEvents', 'Events that are a part of this event. For example, a conference event includes many presentations, each subEvents of the conference.'),
(6479, 1, 22, 'subEvent', 'subEvent', 'An Event that is part of this event. For example, a conference event includes many presentations, each of which is a subEvent of the conference.'),
(6480, 1, 22, 'amountOfThisGood', 'amountOfThisGood', 'The quantity of the goods included in the offer.'),
(6481, 1, 22, 'geoEquals', 'geoEquals', 'Represents spatial relations in which two geometries (or the places they represent) are topologically equal, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM). \"Two geometries are topologically equal if their interiors intersect and no part of the interior or boundary of one geometry intersects the exterior of the other\" (a symmetric relationship).'),
(6482, 1, 22, 'geoMidpoint', 'geoMidpoint', 'Indicates the GeoCoordinates at the centre of a GeoShape, e.g. GeoCircle.'),
(6483, 1, 22, 'backstory', 'backstory', 'For an [[Article]], typically a [[NewsArticle]], the backstory property provides a textual summary giving a brief explanation of why and how an article was created. In a journalistic setting this could include information about reporting process, methods, interviews, data sources, etc.'),
(6484, 1, 22, 'acceptedAnswer', 'acceptedAnswer', 'The answer(s) that has been accepted as best, typically on a Question/Answer site. Sites vary in their selection mechanisms, e.g. drawing on community opinion and/or the view of the Question author.'),
(6485, 1, 22, 'suggestedAnswer', 'suggestedAnswer', 'An answer (possibly one of several, possibly incorrect) to a Question, e.g. on a Question/Answer site.'),
(6486, 1, 22, 'cvdNumTotBeds', 'cvdNumTotBeds', 'numtotbeds - ALL HOSPITAL BEDS: Total number of all inpatient and outpatient beds, including all staffed, ICU, licensed, and overflow (surge) beds used for inpatients or outpatients.'),
(6487, 1, 22, 'educationRequirements', 'educationRequirements', 'Educational background needed for the position or Occupation.'),
(6488, 1, 22, 'programmingModel', 'programmingModel', 'Indicates whether API is managed or unmanaged.'),
(6489, 1, 22, 'blogPosts', 'blogPosts', 'Indicates a post that is part of a [[Blog]]. Note that historically, what we term a \"Blog\" was once known as a \"weblog\", and that what we term a \"BlogPosting\" is now often colloquially referred to as a \"blog\".'),
(6490, 1, 22, 'blogPost', 'blogPost', 'A posting that is part of this blog.'),
(6491, 1, 22, 'validFor', 'validFor', 'The duration of validity of a permit or similar thing.'),
(6492, 1, 22, 'biomechnicalClass', 'biomechnicalClass', 'The biomechanical properties of the bone.'),
(6493, 1, 22, 'codeValue', 'codeValue', 'A short textual code that uniquely identifies the value.'),
(6494, 1, 22, 'termCode', 'termCode', 'A code that identifies this [[DefinedTerm]] within a [[DefinedTermSet]]'),
(6495, 1, 22, 'biologicalRole', 'biologicalRole', 'A role played by the BioChemEntity within a biological context.'),
(6496, 1, 22, 'occupationalCredentialAwarded', 'occupationalCredentialAwarded', 'A description of the qualification, award, certificate, diploma or other occupational credential awarded as a consequence of successful completion of this course or program.'),
(6497, 1, 22, 'greater', 'greater', 'This ordering relation for qualitative values indicates that the subject is greater than the object.'),
(6498, 1, 22, 'unnamedSourcesPolicy', 'unnamedSourcesPolicy', 'For an [[Organization]] (typically a [[NewsMediaOrganization]]), a statement about policy on use of unnamed sources and the decision process required.'),
(6499, 1, 22, 'naturalProgression', 'naturalProgression', 'The expected progression of the condition if it is not treated and allowed to progress naturally.'),
(6500, 1, 22, 'geoContains', 'geoContains', 'Represents a relationship between two geometries (or the places they represent), relating a containing geometry to a contained geometry. \"a contains b iff no points of b lie in the exterior of a, and at least one point of the interior of b lies in the interior of a\". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(6501, 1, 22, 'announcementLocation', 'announcementLocation', 'Indicates a specific [[CivicStructure]] or [[LocalBusiness]] associated with the SpecialAnnouncement. For example, a specific testing facility or business with special opening hours. For a larger geographic region like a quarantine of an entire region, use [[spatialCoverage]].'),
(6502, 1, 22, 'runtime', 'runtime', 'Runtime platform or script interpreter dependencies (example: Java v1, Python 2.3, .NET Framework 3.0).'),
(6503, 1, 22, 'runtimePlatform', 'runtimePlatform', 'Runtime platform or script interpreter dependencies (example: Java v1, Python 2.3, .NET Framework 3.0).'),
(6504, 1, 22, 'currenciesAccepted', 'currenciesAccepted', 'The currency accepted.\\n\\nUse standard formats: [ISO 4217 currency format](http://en.wikipedia.org/wiki/ISO_4217), e.g. \"USD\"; [Ticker symbol](https://en.wikipedia.org/wiki/List_of_cryptocurrencies) for cryptocurrencies, e.g. \"BTC\"; well known names for [Local Exchange Trading Systems](https://en.wikipedia.org/wiki/Local_exchange_trading_system) (LETS) and other currency types, e.g. \"Ithaca HOUR\".'),
(6505, 1, 22, 'touristType', 'touristType', 'Attraction suitable for type(s) of tourist. E.g. children, visitors from a particular country, etc. '),
(6506, 1, 22, 'printPage', 'printPage', 'If this NewsArticle appears in print, this field indicates the name of the page on which the article is found. Please note that this field is intended for the exact page name (e.g. A5, B18).'),
(6507, 1, 22, 'typicalAgeRange', 'typicalAgeRange', 'The typical expected age range, e.g. \'7-9\', \'11-\'.'),
(6508, 1, 22, 'suitableForDiet', 'suitableForDiet', 'Indicates a dietary restriction or guideline for which this recipe or menu item is suitable, e.g. diabetic, halal etc.'),
(6509, 1, 22, 'shippingRate', 'shippingRate', 'The shipping rate is the cost of shipping to the specified destination. Typically, the maxValue and currency values (of the [[MonetaryAmount]]) are most appropriate.'),
(6510, 1, 22, 'assemblyVersion', 'assemblyVersion', 'Associated product/technology version. E.g., .NET Framework 4.5.'),
(6511, 1, 22, 'publicAccess', 'publicAccess', 'A flag to signal that the [[Place]] is open to public visitors.  If this property is omitted there is no assumed default boolean value'),
(6512, 1, 22, 'occupationLocation', 'occupationLocation', ' The region/country for which this occupational description is appropriate. Note that educational requirements and qualifications can vary between jurisdictions.'),
(6513, 1, 22, 'benefitsSummaryUrl', 'benefitsSummaryUrl', 'The URL that goes directly to the summary of benefits and coverage for the specific standard plan or plan variation.'),
(6514, 1, 22, 'targetProduct', 'targetProduct', 'Target Operating System / Product to which the code applies.  If applies to several versions, just the product name can be used.'),
(6515, 1, 22, 'workPresented', 'workPresented', 'The movie presented during this event.'),
(6516, 1, 22, 'carrierRequirements', 'carrierRequirements', 'Specifies specific carrier(s) requirements for the application (e.g. an application may only work on a specific carrier network).'),
(6517, 1, 22, 'dateReceived', 'dateReceived', 'The date/time the message was received if a single recipient exists.'),
(6518, 1, 22, 'handlingTime', 'handlingTime', 'The typical delay between the receipt of the order and the goods either leaving the warehouse or being prepared for pickup, in case the delivery method is on site pickup. Typical properties: minValue, maxValue, unitCode (d for DAY).  This is by common convention assumed to mean business days (if a unitCode is used, coded as \"d\"), i.e. only counting days when the business normally operates.'),
(6519, 1, 22, 'educationalAlignment', 'educationalAlignment', 'An alignment to an established educational framework.\n\nThis property should not be used where the nature of the alignment can be described using a simple property, for example to express that a resource [[teaches]] or [[assesses]] a competency.'),
(6520, 1, 22, 'deliveryTime', 'deliveryTime', 'The total delay between the receipt of the order and the goods reaching the final customer.'),
(6521, 1, 22, 'iupacName', 'iupacName', 'Systematic method of naming chemical compounds as recommended by the International Union of Pure and Applied Chemistry (IUPAC).'),
(6522, 1, 22, 'trailerWeight', 'trailerWeight', 'The permitted weight of a trailer attached to the vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(6523, 1, 22, 'shippingLabel', 'shippingLabel', 'Label to match an [[OfferShippingDetails]] with a [[ShippingRateSettings]] (within the context of a [[shippingSettingsLink]] cross-reference).'),
(6524, 1, 22, 'partySize', 'partySize', 'Number of people the reservation should accommodate.'),
(6525, 1, 22, 'publication', 'publication', 'A publication event associated with the item.'),
(6526, 1, 22, 'payload', 'payload', 'The permitted weight of passengers and cargo, EXCLUDING the weight of the empty vehicle.\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: Many databases specify the permitted TOTAL weight instead, which is the sum of [[weight]] and [[payload]]\\n* Note 2: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 3: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 4: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(6527, 1, 22, 'termDuration', 'termDuration', 'The amount of time in a term as defined by the institution. A term is a length of time where students take one or more classes. Semesters and quarters are common units for term.'),
(6528, 1, 22, 'itemReviewed', 'itemReviewed', 'The item that is being reviewed/rated.'),
(6529, 1, 22, 'recipe', 'recipe', 'A sub property of instrument. The recipe/instructions used to perform the action.'),
(6530, 1, 22, 'telephone', 'telephone', 'The telephone number.'),
(6531, 1, 22, 'exchangeRateSpread', 'exchangeRateSpread', 'The difference between the price at which a broker or other intermediary buys and sells foreign currency.'),
(6532, 1, 22, 'itemDefectReturnShippingFeesAmount', 'itemDefectReturnShippingFeesAmount', 'Amount of shipping costs for defect product returns. Applicable when property [[itemDefectReturnFees]] equals [[ReturnShippingFees]].'),
(6533, 1, 22, 'addressRegion', 'addressRegion', 'The region in which the locality is, and which is in the country. For example, California or another appropriate first-level [Administrative division](https://en.wikipedia.org/wiki/List_of_administrative_divisions_by_country).'),
(6534, 1, 22, 'spatial', 'spatial', 'The \"spatial\" property can be used in cases when more specific properties\n(e.g. [[locationCreated]], [[spatialCoverage]], [[contentLocation]]) are not known to be appropriate.'),
(6535, 1, 22, 'estimatedCost', 'estimatedCost', 'The estimated cost of the supply or supplies consumed when performing instructions.'),
(6536, 1, 22, 'financialAidEligible', 'financialAidEligible', 'A financial aid type or program which students may use to pay for tuition or fees associated with the program.'),
(6537, 1, 22, 'sensoryUnit', 'sensoryUnit', 'The neurological pathway extension that inputs and sends information to the brain or spinal cord.'),
(6538, 1, 22, 'awayTeam', 'awayTeam', 'The away team in a sports event.'),
(6539, 1, 22, 'antagonist', 'antagonist', 'The muscle whose action counteracts the specified muscle.'),
(6540, 1, 22, 'orderDelivery', 'orderDelivery', 'The delivery of the parcel related to this order or order item.'),
(6541, 1, 22, 'supplyTo', 'supplyTo', 'The area to which the artery supplies blood.'),
(6542, 1, 22, 'bookingTime', 'bookingTime', 'The date and time the reservation was booked.'),
(6543, 1, 22, 'circle', 'circle', 'A circle is the circular region of a specified radius centered at a specified latitude and longitude. A circle is expressed as a pair followed by a radius in meters.'),
(6544, 1, 22, 'beforeMedia', 'beforeMedia', 'A media object representing the circumstances before performing this direction.'),
(6545, 1, 22, 'episodeNumber', 'episodeNumber', 'Position of the episode within an ordered group of episodes.'),
(6546, 1, 22, 'gracePeriod', 'gracePeriod', 'The period of time after any due date that the borrower has to fulfil its obligations before a default (failure to pay) is deemed to have occurred.'),
(6547, 1, 22, 'addressLocality', 'addressLocality', 'The locality in which the street address is, and which is in the region. For example, Mountain View.'),
(6548, 1, 22, 'learningResourceType', 'learningResourceType', 'The predominant type or kind characterizing the learning resource. For example, \'presentation\', \'handout\'.'),
(6549, 1, 22, 'fuelType', 'fuelType', 'The type of fuel suitable for the engine or engines of the vehicle. If the vehicle has only one engine, this property can be attached directly to the vehicle.'),
(6550, 1, 22, 'accessibilityAPI', 'accessibilityAPI', 'Indicates that the resource is compatible with the referenced accessibility API. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityAPI-vocabulary).'),
(6551, 1, 22, 'masthead', 'masthead', 'For a [[NewsMediaOrganization]], a link to the masthead page or a page listing top editorial management.'),
(6552, 1, 22, 'ticketToken', 'ticketToken', 'Reference to an asset (e.g., Barcode, QR code image or PDF) usable for entrance.'),
(6553, 1, 22, 'eligibleRegion', 'eligibleRegion', 'The ISO 3166-1 (ISO 3166-1 alpha-2) or ISO 3166-2 code, the place, or the GeoShape for the geo-political region(s) for which the offer or delivery charge specification is valid.\\n\\nSee also [[ineligibleRegion]].\n    '),
(6554, 1, 22, 'areaServed', 'areaServed', 'The geographic area where a service or offered item is provided.'),
(6555, 1, 22, 'disambiguatingDescription', 'disambiguatingDescription', 'A sub property of description. A short description of the item used to disambiguate from other, similar items. Information from other properties (in particular, name) may be necessary for the description to be useful for disambiguation.'),
(6556, 1, 22, 'description', 'description', 'A description of the item.'),
(6557, 1, 22, 'suggestedMaxAge', 'suggestedMaxAge', 'Maximum recommended age in years for the audience or user.'),
(6558, 1, 22, 'quest', 'quest', 'The task that a player-controlled character, or group of characters may complete in order to gain a reward.'),
(6559, 1, 22, 'containedIn', 'containedIn', 'The basic containment relation between a place and one that contains it.'),
(6560, 1, 22, 'containedInPlace', 'containedInPlace', 'The basic containment relation between a place and one that contains it.'),
(6561, 1, 22, 'contraindication', 'contraindication', 'A contraindication for this therapy.'),
(6562, 1, 22, 'recipeYield', 'recipeYield', 'The quantity produced by the recipe (for example, number of people served, number of servings, etc).'),
(6563, 1, 22, 'yield', 'yield', 'The quantity that results by performing instructions. For example, a paper airplane, 10 personalized candles.'),
(6564, 1, 22, 'cvdCollectionDate', 'cvdCollectionDate', 'collectiondate - Date for which patient counts are reported.'),
(6565, 1, 22, 'requiredMinAge', 'requiredMinAge', 'Audiences defined by a person\'s minimum age.'),
(6566, 1, 22, 'referencesOrder', 'referencesOrder', 'The Order(s) related to this Invoice. One or more Orders may be combined into a single Invoice.'),
(6567, 1, 22, 'identifyingTest', 'identifyingTest', 'A diagnostic test that can identify this sign.'),
(6568, 1, 22, 'inker', 'inker', 'The individual who traces over the pencil drawings in ink after pencils are complete.'),
(6569, 1, 22, 'operatingSystem', 'operatingSystem', 'Operating systems supported (Windows 7, OS X 10.6, Android 1.6).'),
(6570, 1, 22, 'byMonth', 'byMonth', 'Defines the month(s) of the year on which a recurring [[Event]] takes place. Specified as an [[Integer]] between 1-12. January is 1.'),
(6571, 1, 22, 'steeringPosition', 'steeringPosition', 'The position of the steering wheel or similar device (mostly for cars).'),
(6572, 1, 22, 'branch', 'branch', 'The branches that delineate from the nerve bundle. Not to be confused with [[branchOf]].'),
(6573, 1, 22, 'arterialBranch', 'arterialBranch', 'The branches that comprise the arterial structure.'),
(6574, 1, 22, 'taxID', 'taxID', 'The Tax / Fiscal ID of the organization or person, e.g. the TIN in the US or the CIF/NIF in Spain.'),
(6575, 1, 22, 'stage', 'stage', 'The stage of the condition, if applicable.'),
(6576, 1, 22, 'engineType', 'engineType', 'The type of engine or engines powering the vehicle.'),
(6577, 1, 22, 'acceptedPaymentMethod', 'acceptedPaymentMethod', 'The payment method(s) accepted by seller for this offer.'),
(6578, 1, 22, 'representativeOfPage', 'representativeOfPage', 'Indicates whether this image is representative of the content of the page.'),
(6579, 1, 22, 'partOfOrder', 'partOfOrder', 'The overall order the items in this delivery were included in.'),
(6580, 1, 22, 'purchaseDate', 'purchaseDate', 'The date the item, e.g. vehicle, was purchased by the current owner.'),
(6581, 1, 22, 'loser', 'loser', 'A sub property of participant. The loser of the action.'),
(6582, 1, 22, 'issn', 'issn', 'The International Standard Serial Number (ISSN) that identifies this serial publication. You can repeat this property to identify different formats of, or the linking ISSN (ISSN-L) for, this serial publication.'),
(6583, 1, 22, 'landlord', 'landlord', 'A sub property of participant. The owner of the real estate property.'),
(6584, 1, 22, 'language', 'language', 'A sub property of instrument. The language used on this action.'),
(6585, 1, 22, 'inLanguage', 'inLanguage', 'The language of the content or performance or used in an action. Please use one of the language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47). See also [[availableLanguage]].'),
(6586, 1, 22, 'legislationDateVersion', 'legislationDateVersion', 'The point-in-time at which the provided description of the legislation is valid (e.g.: when looking at the law on the 2016-04-07 (= dateVersion), I get the consolidation of 2015-04-12 of the \"National Insurance Contributions Act 2015\")'),
(6587, 1, 22, 'originAddress', 'originAddress', 'Shipper\'s address.'),
(6588, 1, 22, 'healthPlanDrugTier', 'healthPlanDrugTier', 'The tier(s) of drugs offered by this formulary or insurance plan.'),
(6589, 1, 22, 'eduQuestionType', 'eduQuestionType', 'For questions that are part of learning resources (e.g. Quiz), eduQuestionType indicates the format of question being given. Example: \"Multiple choice\", \"Open ended\", \"Flashcard\".'),
(6590, 1, 22, 'keywords', 'keywords', 'Keywords or tags used to describe some item. Multiple textual entries in a keywords list are typically delimited by commas, or by repeating the property.'),
(6591, 1, 22, 'recognizingAuthority', 'recognizingAuthority', 'If applicable, the organization that officially recognizes this entity as part of its endorsed system of medicine.'),
(6592, 1, 22, 'transitTime', 'transitTime', 'The typical delay the order has been sent for delivery and the goods reach the final customer. Typical properties: minValue, maxValue, unitCode (d for DAY).'),
(6593, 1, 22, 'availableTest', 'availableTest', 'A diagnostic test or procedure offered by this lab.'),
(6594, 1, 22, 'isFamilyFriendly', 'isFamilyFriendly', 'Indicates whether this content is family friendly.'),
(6595, 1, 22, 'knowsLanguage', 'knowsLanguage', 'Of a [[Person]], and less typically of an [[Organization]], to indicate a known language. We do not distinguish skill levels or reading/writing/speaking/signing here. Use language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47).'),
(6596, 1, 22, 'constrainingProperty', 'constrainingProperty', 'Indicates a property used as a constraint to define a [[StatisticalPopulation]] with respect to the set of entities\n  corresponding to an indicated type (via [[populationType]]).'),
(6597, 1, 22, 'geoCovers', 'geoCovers', 'Represents a relationship between two geometries (or the places they represent), relating a covering geometry to a covered geometry. \"Every point of b is a point of (the interior or boundary of) a\". As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(6598, 1, 22, 'penciler', 'penciler', 'The individual who draws the primary narrative artwork.'),
(6599, 1, 22, 'availableAtOrFrom', 'availableAtOrFrom', 'The place(s) from which the offer can be obtained (e.g. store locations).'),
(6600, 1, 22, 'requiredGender', 'requiredGender', 'Audiences defined by a person\'s gender.'),
(6601, 1, 22, 'educationalCredentialAwarded', 'educationalCredentialAwarded', 'A description of the qualification, award, certificate, diploma or other educational credential awarded as a consequence of successful completion of this course or program.'),
(6602, 1, 22, 'medicalSpecialty', 'medicalSpecialty', 'A medical specialty of the provider.'),
(6603, 1, 22, 'startDate', 'startDate', 'The start date and time of the item (in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601)).'),
(6604, 1, 22, 'pregnancyCategory', 'pregnancyCategory', 'Pregnancy category of this drug.'),
(6605, 1, 22, 'line', 'line', 'A line is a point-to-point path consisting of two or more points. A line is expressed as a series of two or more point objects separated by space.'),
(6606, 1, 22, 'numTracks', 'numTracks', 'The number of tracks in this album or playlist.'),
(6607, 1, 22, 'numberOfForwardGears', 'numberOfForwardGears', 'The total number of forward gears available for the transmission system of the vehicle.\\n\\nTypical unit code(s): C62'),
(6608, 1, 22, 'recourseLoan', 'recourseLoan', 'The only way you get the money back in the event of default is the security. Recourse is where you still have the opportunity to go back to the borrower for the rest of the money.'),
(6609, 1, 22, 'manufacturer', 'manufacturer', 'The manufacturer of the product.'),
(6610, 1, 22, 'minValue', 'minValue', 'The lower value of some characteristic or property.'),
(6611, 1, 22, 'dropoffLocation', 'dropoffLocation', 'Where a rental car can be dropped off.'),
(6612, 1, 22, 'isAcceptingNewPatients', 'isAcceptingNewPatients', 'Whether the provider is accepting new patients.'),
(6613, 1, 22, 'permissionType', 'permissionType', 'The type of permission granted the person, organization, or audience.'),
(6614, 1, 22, 'realEstateAgent', 'realEstateAgent', 'A sub property of participant. The real estate agent involved in the action.'),
(6615, 1, 22, 'bookFormat', 'bookFormat', 'The format of the book.'),
(6616, 1, 22, 'numAdults', 'numAdults', 'The number of adults staying in the unit.'),
(6617, 1, 22, 'partOfSeason', 'partOfSeason', 'The season to which this episode belongs.'),
(6618, 1, 22, 'isPartOf', 'isPartOf', 'Indicates an item or CreativeWork that this item, or CreativeWork (in some sense), is part of.'),
(6619, 1, 22, 'produces', 'produces', 'The tangible thing generated by the service, e.g. a passport, permit, etc.'),
(6620, 1, 22, 'serviceOutput', 'serviceOutput', 'The tangible thing generated by the service, e.g. a passport, permit, etc.'),
(6621, 1, 22, 'functionalClass', 'functionalClass', 'The degree of mobility the joint allows.'),
(6622, 1, 22, 'populationType', 'populationType', 'Indicates the populationType common to all members of a [[StatisticalPopulation]].'),
(6623, 1, 22, 'inCodeSet', 'inCodeSet', 'A [[CategoryCodeSet]] that contains this category code.'),
(6624, 1, 22, 'inDefinedTermSet', 'inDefinedTermSet', 'A [[DefinedTermSet]] that contains this term.'),
(6625, 1, 22, 'additionalVariable', 'additionalVariable', 'Any additional component of the exercise prescription that may need to be articulated to the patient. This may include the order of exercises, the number of repetitions of movement, quantitative distance, progressions over time, etc.'),
(6626, 1, 22, 'servicePhone', 'servicePhone', 'The phone number to use to access the service.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(6627, 1, 22, 'readonlyValue', 'readonlyValue', 'Whether or not a property is mutable.  Default is false. Specifying this for a property that also has a value makes it act similar to a \"hidden\" input in an HTML form.'),
(6628, 1, 22, 'addressCountry', 'addressCountry', 'The country. For example, USA. You can also provide the two-letter [ISO 3166-1 alpha-2 country code](http://en.wikipedia.org/wiki/ISO_3166-1).'),
(6629, 1, 22, 'calories', 'calories', 'The number of calories.'),
(6630, 1, 22, 'lesser', 'lesser', 'This ordering relation for qualitative values indicates that the subject is lesser than the object.'),
