(6715, 1, 22, 'molecularWeight', 'molecularWeight', 'This is the molecular weight of the entity being described, not of the parent. Units should be included in the form \'&lt;Number&gt; &lt;unit&gt;\', for example \'12 amu\' or as \'&lt;QuantitativeValue&gt;.'),
(6716, 1, 22, 'carbohydrateContent', 'carbohydrateContent', 'The number of grams of carbohydrates.'),
