(6798, 1, 22, 'mediaAuthenticityCategory', 'mediaAuthenticityCategory', 'Indicates a MediaManipulationRatingEnumeration classification of a media object (in the context of how it was published or shared).'),
(6799, 1, 22, 'healthPlanCoinsuranceRate', 'healthPlanCoinsuranceRate', 'The rate of coinsurance expressed as a number between 0.0 and 1.0.'),
(6800, 1, 22, 'branchOf', 'branchOf', 'The larger organization that this local business is a branch of, if any. Not to be confused with (anatomical) [[branch]].'),
(6801, 1, 22, 'parentOrganization', 'parentOrganization', 'The larger organization that this organization is a [[subOrganization]] of, if any.'),
(6802, 1, 22, 'attendees', 'attendees', 'A person attending the event.'),
(6803, 1, 22, 'attendee', 'attendee', 'A person or organization attending the event.'),
(6804, 1, 22, 'maximumPhysicalAttendeeCapacity', 'maximumPhysicalAttendeeCapacity', 'The maximum physical attendee capacity of an [[Event]] whose [[eventAttendanceMode]] is [[OfflineEventAttendanceMode]] (or the offline aspects, in the case of a [[MixedEventAttendanceMode]]). '),
(6805, 1, 22, 'applicableLocation', 'applicableLocation', 'The location in which the status applies.'),
(6806, 1, 22, 'membershipNumber', 'membershipNumber', 'A unique identifier for the membership.'),
(6807, 1, 22, 'courseCode', 'courseCode', 'The identifier for the [[Course]] used by the course [[provider]] (e.g. CS101 or 6.001).'),
(6808, 1, 22, 'termsOfService', 'termsOfService', 'Human-readable terms of service documentation.'),
(6809, 1, 22, 'originalMediaContextDescription', 'originalMediaContextDescription', 'Describes, in a [[MediaReview]] when dealing with [[DecontextualizedContent]], background information that can contribute to better interpretation of the [[MediaObject]].'),
(6810, 1, 22, 'countryOfOrigin', 'countryOfOrigin', 'The country of origin of something, including products as well as creative  works such as movie and TV content.\n\nIn the case of TV and movie, this would be the country of the principle offices of the production company or individual responsible for the movie. For other kinds of [[CreativeWork]] it is difficult to provide fully general guidance, and properties such as [[contentLocation]] and [[locationCreated]] may be more applicable.\n\nIn the case of products, the country of origin of the product. The exact interpretation of this may vary by context and product type, and cannot be fully enumerated here.'),
(6811, 1, 22, 'countryOfAssembly', 'countryOfAssembly', 'The place where the product was assembled.'),
(6812, 1, 22, 'gettingTestedInfo', 'gettingTestedInfo', 'Information about getting tested (for a [[MedicalCondition]]), e.g. in the context of a pandemic.'),
(6813, 1, 22, 'question', 'question', 'A sub property of object. A question.'),
(6814, 1, 22, 'totalTime', 'totalTime', 'The total time required to perform instructions or a direction (including time to prepare the supplies), in [ISO 8601 duration format](http://en.wikipedia.org/wiki/ISO_8601).'),
(6815, 1, 22, 'serverStatus', 'serverStatus', 'Status of a game server.'),
(6816, 1, 22, 'acceptsReservations', 'acceptsReservations', 'Indicates whether a FoodEstablishment accepts reservations. Values can be Boolean, an URL at which reservations can be made or (for backwards compatibility) the strings ```Yes``` or ```No```.'),
(6817, 1, 22, 'starRating', 'starRating', 'An official rating for a lodging business or food establishment, e.g. from national associations or standards bodies. Use the author property to indicate the rating organization, e.g. as an Organization with name such as (e.g. HOTREC, DEHOGA, WHR, or Hotelstars).'),
(6818, 1, 22, 'agent', 'agent', 'The direct performer or driver of the action (animate or inanimate). E.g. *John* wrote a book.'),
(6819, 1, 22, 'email', 'email', 'Email address.'),
(6820, 1, 22, 'numberOfItems', 'numberOfItems', 'The number of items in an ItemList. Note that some descriptions might not fully describe all items in a list (e.g., multi-page pagination); in such cases, the numberOfItems would be for the entire list.'),
(6821, 1, 22, 'chemicalRole', 'chemicalRole', 'A role played by the BioChemEntity within a chemical context.'),
(6822, 1, 22, 'item', 'item', 'An entity represented by an entry in a list or data feed (e.g. an \'artist\' in a list of \'artists\').'),
(6823, 1, 22, 'validFrom', 'validFrom', 'The date when the item becomes valid.'),
(6824, 1, 22, 'taxonRank', 'taxonRank', 'The taxonomic rank of this taxon given preferably as a URI from a controlled vocabulary – typically the ranks from TDWG TaxonRank ontology or equivalent Wikidata URIs.'),
(6825, 1, 22, 'hasCategoryCode', 'hasCategoryCode', 'A Category code contained in this code set.'),
(6826, 1, 22, 'hasDefinedTerm', 'hasDefinedTerm', 'A Defined Term contained in this term set.'),
(6827, 1, 22, 'healthPlanCostSharing', 'healthPlanCostSharing', 'The costs to the patient for services under this network or formulary.'),
(6828, 1, 22, 'actionPlatform', 'actionPlatform', 'The high level platform(s) where the Action can be performed for the given URL. To specify a specific application or operating system instance, use actionApplication.'),
(6829, 1, 22, 'observationDate', 'observationDate', 'The observationDate of an [[Observation]].'),
(6830, 1, 22, 'cssSelector', 'cssSelector', 'A CSS selector, e.g. of a [[SpeakableSpecification]] or [[WebPageElement]]. In the latter case, multiple matches within a page can constitute a single conceptual \"Web page element\".'),
(6831, 1, 22, 'bccRecipient', 'bccRecipient', 'A sub property of recipient. The recipient blind copied on a message.'),
(6832, 1, 22, 'gameEdition', 'gameEdition', 'The edition of a video game.'),
(6833, 1, 22, 'evidenceLevel', 'evidenceLevel', 'Strength of evidence of the data used to formulate the guideline (enumerated).'),
(6834, 1, 22, 'headline', 'headline', 'Headline of the article.'),
(6835, 1, 22, 'interactionType', 'interactionType', 'The Action representing the type of interaction. For up votes, +1s, etc. use [[LikeAction]]. For down votes use [[DislikeAction]]. Otherwise, use the most specific Action.'),
(6836, 1, 22, 'structuralClass', 'structuralClass', 'The name given to how bone physically connects to each other.'),
(6837, 1, 22, 'workload', 'workload', 'Quantitative measure of the physiologic output of the exercise; also referred to as energy expenditure.'),
(6838, 1, 22, 'repeatCount', 'repeatCount', 'Defines the number of times a recurring [[Event]] will take place.'),
(6839, 1, 22, 'adverseOutcome', 'adverseOutcome', 'A possible complication and/or side effect of this therapy. If it is known that an adverse outcome is serious (resulting in death, disability, or permanent damage; requiring hospitalization; or otherwise life-threatening or requiring immediate medical attention), tag it as a seriousAdverseOutcome instead.'),
(6840, 1, 22, 'departureStation', 'departureStation', 'The station from which the train departs.'),
(6841, 1, 22, 'proteinContent', 'proteinContent', 'The number of grams of protein.'),
(6842, 1, 22, 'accessibilityHazard', 'accessibilityHazard', 'A characteristic of the described resource that is physiologically dangerous to some users. Related to WCAG 2.0 guideline 2.3. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessibilityHazard-vocabulary).'),
(6843, 1, 22, 'regionDrained', 'regionDrained', 'The anatomical or organ system drained by this vessel; generally refers to a specific part of an organ.'),
(6844, 1, 22, 'commentTime', 'commentTime', 'The time at which the UserComment was made.'),
(6845, 1, 22, 'boardingPolicy', 'boardingPolicy', 'The type of boarding policy used by the airline (e.g. zone-based or group-based).'),
(6846, 1, 22, 'vehicleConfiguration', 'vehicleConfiguration', 'A short text indicating the configuration of the vehicle, e.g. \'5dr hatchback ST 2.5 MT 225 hp\' or \'limited edition\'.'),
(6847, 1, 22, 'billingIncrement', 'billingIncrement', 'This property specifies the minimal quantity and rounding increment that will be the basis for the billing. The unit of measurement is specified by the unitCode property.'),
(6848, 1, 22, 'securityClearanceRequirement', 'securityClearanceRequirement', 'A description of any security clearance requirements of the job.'),
(6849, 1, 22, 'drugClass', 'drugClass', 'The class of drug this belongs to (e.g., statins).'),
(6850, 1, 22, 'regionsAllowed', 'regionsAllowed', 'The regions where the media is allowed. If not specified, then it\'s assumed to be allowed everywhere. Specify the countries in [ISO 3166 format](http://en.wikipedia.org/wiki/ISO_3166).'),
(6851, 1, 22, 'screenshot', 'screenshot', 'A link to a screenshot image of the app.'),
(6852, 1, 22, 'appearance', 'appearance', 'Indicates an occurrence of a [[Claim]] in some [[CreativeWork]].'),
(6853, 1, 22, 'toRecipient', 'toRecipient', 'A sub property of recipient. The recipient who was directly sent the message.'),
(6854, 1, 22, 'numberOfPartialBathrooms', 'numberOfPartialBathrooms', 'Number of partial bathrooms - The total number of half and ¼ bathrooms in an [[Accommodation]]. This corresponds to the [BathroomsPartial field in RESO](https://ddwiki.reso.org/display/DDW17/BathroomsPartial+Field). '),
(6855, 1, 22, 'arrivalTerminal', 'arrivalTerminal', 'Identifier of the flight\'s arrival terminal.'),
(6856, 1, 22, 'hasCourse', 'hasCourse', 'A course or class that is one of the learning opportunities that constitute an educational / occupational program. No information is implied about whether the course is mandatory or optional; no guarantee is implied about whether the course will be available to everyone on the program.'),
(6857, 1, 22, 'includedInHealthInsurancePlan', 'includedInHealthInsurancePlan', 'The insurance plans that cover this drug.'),
(6858, 1, 22, 'valueRequired', 'valueRequired', 'Whether the property must be filled in to complete the action.  Default is false.'),
(6859, 1, 22, 'processorRequirements', 'processorRequirements', 'Processor architecture required to run the application (e.g. IA64).'),
(6860, 1, 22, 'minPrice', 'minPrice', 'The lowest price if the price is a range.'),
(6861, 1, 22, 'diseaseSpreadStatistics', 'diseaseSpreadStatistics', 'Statistical information about the spread of a disease, either as [[WebContent]], or\n  described directly as a [[Dataset]], or the specific [[Observation]]s in the dataset. When a [[WebContent]] URL is\n  provided, the page indicated might also contain more such markup.'),
(6862, 1, 22, 'cutoffTime', 'cutoffTime', 'Order cutoff time allows merchants to describe the time after which they will no longer process orders received on that day. For orders processed after cutoff time, one day gets added to the delivery time estimate. This property is expected to be most typically used via the [[ShippingRateSettings]] publication pattern. The time is indicated using the ISO-8601 Time format, e.g. \"23:30:00-05:00\" would represent 6:30 pm Eastern Standard Time (EST) which is 5 hours behind Coordinated Universal Time (UTC).'),
(6863, 1, 22, 'legislationChanges', 'legislationChanges', 'Another legislation that this legislation changes. This encompasses the notions of amendment, replacement, correction, repeal, or other types of change. This may be a direct change (textual or non-textual amendment) or a consequential or indirect change. The property is to be used to express the existence of a change relationship between two acts rather than the existence of a consolidated version of the text that shows the result of the change. For consolidation relationships, use the <a href=\"/legislationConsolidates\">legislationConsolidates</a> property.'),
(6864, 1, 22, 'episodes', 'episodes', 'An episode of a TV/radio series or season.'),
(6865, 1, 22, 'episode', 'episode', 'An episode of a TV, radio or game media within a series or season.'),
(6866, 1, 22, 'permissions', 'permissions', 'Permission(s) required to run the app (for example, a mobile app may require full internet access or may run only on wifi).'),
(6867, 1, 22, 'strengthUnit', 'strengthUnit', 'The units of an active ingredient\'s strength, e.g. mg.'),
(6868, 1, 22, 'endDate', 'endDate', 'The end date and time of the item (in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601)).'),
(6869, 1, 22, 'shippingDestination', 'shippingDestination', 'indicates (possibly multiple) shipping destinations. These can be defined in several ways, e.g. postalCode ranges.'),
(6870, 1, 22, 'accessCode', 'accessCode', 'Password, PIN, or access code needed for delivery (e.g. from a locker).'),
(6871, 1, 22, 'smiles', 'smiles', 'A specification in form of a line notation for describing the structure of chemical species using short ASCII strings.  Double bond stereochemistry \\ indicators may need to be escaped in the string in formats where the backslash is an escape character.'),
(6872, 1, 22, 'afterMedia', 'afterMedia', 'A media object representing the circumstances after performing this direction.'),
(6873, 1, 22, 'gameTip', 'gameTip', 'Links to tips, tactics, etc.'),
(6874, 1, 22, 'yearsInOperation', 'yearsInOperation', 'The age of the business.'),
(6875, 1, 22, 'speakable', 'speakable', 'Indicates sections of a Web page that are particularly \'speakable\' in the sense of being highlighted as being especially appropriate for text-to-speech conversion. Other sections of a page may also be usefully spoken in particular circumstances; the \'speakable\' property serves to indicate the parts most likely to be generally useful for speech.\n\nThe *speakable* property can be repeated an arbitrary number of times, with three kinds of possible \'content-locator\' values:\n\n1.) *id-value* URL references - uses *id-value* of an element in the page being annotated. The simplest use of *speakable* has (potentially relative) URL values, referencing identified sections of the document concerned.\n\n2.) CSS Selectors - addresses content in the annotated page, e.g. via class attribute. Use the [[cssSelector]] property.\n\n3.)  XPaths - addresses content via XPaths (assuming an XML view of the content). Use the [[xpath]] property.\n\n\nFor more sophisticated markup of speakable sections beyond simple ID references, either CSS selectors or XPath expressions to pick out document section(s) as speakable. For this\nwe define a supporting type, [[SpeakableSpecification]]  which is defined to be a possible value of the *speakable* property.\n         '),
(6876, 1, 22, 'accessMode', 'accessMode', 'The human sensory perceptual system or cognitive faculty through which a person may process or perceive information. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessMode-vocabulary).'),
(6877, 1, 22, 'orderNumber', 'orderNumber', 'The identifier of the transaction.'),
(6878, 1, 22, 'foundingDate', 'foundingDate', 'The date that this organization was founded.'),
(6879, 1, 22, 'fuelEfficiency', 'fuelEfficiency', 'The distance traveled per unit of fuel used; most commonly miles per gallon (mpg) or kilometers per liter (km/L).\\n\\n* Note 1: There are unfortunately no standard unit codes for miles per gallon or kilometers per liter. Use [[unitText]] to indicate the unit of measurement, e.g. mpg or km/L.\\n* Note 2: There are two ways of indicating the fuel consumption, [[fuelConsumption]] (e.g. 8 liters per 100 km) and [[fuelEfficiency]] (e.g. 30 miles per gallon). They are reciprocal.\\n* Note 3: Often, the absolute value is useful only when related to driving speed (\"at 80 km/h\") or usage pattern (\"city traffic\"). You can use [[valueReference]] to link the value for the fuel economy to another value.'),
(6880, 1, 22, 'hasOccupation', 'hasOccupation', 'The Person\'s occupation. For past professions, use Role for expressing dates.'),
(6881, 1, 22, 'inAlbum', 'inAlbum', 'The album to which this recording belongs.'),
(6882, 1, 22, 'knownVehicleDamages', 'knownVehicleDamages', 'A textual description of known damages, both repaired and unrepaired.'),
(6883, 1, 22, 'dataFeedElement', 'dataFeedElement', 'An item within a data feed. Data feeds may have many elements.'),
(6884, 1, 22, 'expressedIn', 'expressedIn', 'Tissue, organ, biological sample, etc in which activity of this gene has been observed experimentally. For example brain, digestive system.'),
(6885, 1, 22, 'size', 'size', 'A standardized size of a product or creative work, specified either through a simple textual string (for example \'XL\', \'32Wx34L\'), a  QuantitativeValue with a unitCode, or a comprehensive and structured [[SizeSpecification]]; in other cases, the [[width]], [[height]], [[depth]] and [[weight]] properties may be more applicable. '),
(6886, 1, 22, 'customer', 'customer', 'Party placing the order or paying the invoice.'),
(6887, 1, 22, 'employees', 'employees', 'People working for this organization.'),
(6888, 1, 22, 'employee', 'employee', 'Someone working for this organization.'),
(6889, 1, 22, 'providesService', 'providesService', 'The service provided by this channel.'),
(6890, 1, 22, 'printSection', 'printSection', 'If this NewsArticle appears in print, this field indicates the print section in which the article appeared.'),
(6891, 1, 22, 'text', 'text', 'The textual content of this CreativeWork.'),
(6892, 1, 22, 'legislationLegalValue', 'legislationLegalValue', 'The legal value of this legislation file. The same legislation can be written in multiple files with different legal values. Typically a digitally signed PDF have a \"stronger\" legal value than the HTML file of the same act.'),
(6893, 1, 22, 'earlyPrepaymentPenalty', 'earlyPrepaymentPenalty', 'The amount to be paid as a penalty in the event of early payment of the loan.'),
(6894, 1, 22, 'returnMethod', 'returnMethod', 'The type of return method offered, specified from an enumeration.'),
(6895, 1, 22, 'commentText', 'commentText', 'The text of the UserComment.'),
(6896, 1, 22, 'geoTouches', 'geoTouches', 'Represents spatial relations in which two geometries (or the places they represent) touch: \"they have at least one boundary point in common, but no interior points.\" (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)'),
(6897, 1, 22, 'labelDetails', 'labelDetails', 'Link to the drug\'s label details.'),
(6898, 1, 22, 'answerCount', 'answerCount', 'The number of answers this question has received.'),
(6899, 1, 22, 'archivedAt', 'archivedAt', 'Indicates a page or other link involved in archival of a [[CreativeWork]]. In the case of [[MediaReview]], the items in a [[MediaReviewItem]] may often become inaccessible, but be archived by archival, journalistic, activist, or law enforcement organizations. In such cases, the referenced page may not directly publish the content.'),
(6900, 1, 22, 'relatedAnatomy', 'relatedAnatomy', 'Anatomical systems or structures that relate to the superficial anatomy.'),
(6901, 1, 22, 'accountMinimumInflow', 'accountMinimumInflow', 'A minimum amount that has to be paid in every month.'),
(6902, 1, 22, 'photos', 'photos', 'Photographs of this place.'),
(6903, 1, 22, 'photo', 'photo', 'A photograph of this place.'),
(6904, 1, 22, 'interactionService', 'interactionService', 'The WebSite or SoftwareApplication where the interactions took place.'),
(6905, 1, 22, 'physiologicalBenefits', 'physiologicalBenefits', 'Specific physiologic benefits associated to the plan.'),
(6906, 1, 22, 'previousItem', 'previousItem', 'A link to the ListItem that precedes the current one.'),
(6907, 1, 22, 'duplicateTherapy', 'duplicateTherapy', 'A therapy that duplicates or overlaps this one.'),
(6908, 1, 22, 'busNumber', 'busNumber', 'The unique identifier for the bus.'),
(6909, 1, 22, 'artEdition', 'artEdition', 'The number of copies when multiple copies of a piece of artwork are produced - e.g. for a limited edition of 20 prints, \'artEdition\' refers to the total number of copies (in this example \"20\").'),
(6910, 1, 22, 'foodEvent', 'foodEvent', 'A sub property of location. The specific food event where the action occurred.'),
(6911, 1, 22, 'gender', 'gender', 'Gender of something, typically a [[Person]], but possibly also fictional characters, animals, etc. While https://schema.org/Male and https://schema.org/Female may be used, text strings are also acceptable for people who do not identify as a binary gender. The [[gender]] property can also be used in an extended sense to cover e.g. the gender of sports teams. As with the gender of individuals, we do not try to enumerate all possibilities. A mixed-gender [[SportsTeam]] can be indicated with a text value of \"Mixed\".'),
(6912, 1, 22, 'deliveryAddress', 'deliveryAddress', 'Destination address.'),
(6913, 1, 22, 'valueName', 'valueName', 'Indicates the name of the PropertyValueSpecification to be used in URL templates and form encoding in a manner analogous to HTML\'s input@name.'),
(6914, 1, 22, 'saturatedFatContent', 'saturatedFatContent', 'The number of grams of saturated fat.'),
(6915, 1, 22, 'articleSection', 'articleSection', 'Articles may belong to one or more \'sections\' in a magazine or newspaper, such as Sports, Lifestyle, etc.'),
(6916, 1, 22, 'byMonthWeek', 'byMonthWeek', 'Defines the week(s) of the month on which a recurring Event takes place. Specified as an Integer between 1-5. For clarity, byMonthWeek is best used in conjunction with byDay to indicate concepts like the first and third Mondays of a month.'),
(6917, 1, 22, 'assembly', 'assembly', 'Library file name, e.g., mscorlib.dll, system.web.dll.'),
(6918, 1, 22, 'executableLibraryName', 'executableLibraryName', 'Library file name, e.g., mscorlib.dll, system.web.dll.'),
(6919, 1, 22, 'closes', 'closes', 'The closing hour of the place or service on the given day(s) of the week.'),
(6920, 1, 22, 'activityDuration', 'activityDuration', 'Length of time to engage in the activity.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(6921, 1, 22, 'bitrate', 'bitrate', 'The bitrate of the media object.'),
(6922, 1, 22, 'amount', 'amount', 'The amount of money.'),
(6923, 1, 22, 'rxcui', 'rxcui', 'The RxCUI drug identifier from RXNORM.'),
(6924, 1, 22, 'percentile90', 'percentile90', 'The 90th percentile value.'),
(6925, 1, 22, 'diagram', 'diagram', 'An image containing a diagram that illustrates the structure and/or its component substructures and/or connections with other structures.'),
(6926, 1, 22, 'loanPaymentAmount', 'loanPaymentAmount', 'The amount of money to pay in a single payment.'),
(6927, 1, 22, 'paymentDue', 'paymentDue', 'The date that payment is due.'),
(6928, 1, 22, 'paymentDueDate', 'paymentDueDate', 'The date that payment is due.'),
(6929, 1, 22, 'maxValue', 'maxValue', 'The upper value of some characteristic or property.'),
(6930, 1, 22, 'numberOfAccommodationUnits', 'numberOfAccommodationUnits', 'Indicates the total (available plus unavailable) number of accommodation units in an [[ApartmentComplex]], or the number of accommodation units for a specific [[FloorPlan]] (within its specific [[ApartmentComplex]]). See also [[numberOfAvailableAccommodationUnits]].'),
(6931, 1, 22, 'restockingFee', 'restockingFee', 'Use [[MonetaryAmount]] to specify a fixed restocking fee for product returns, or use [[Number]] to specify a percentage of the product price paid by the customer.'),
(6932, 1, 22, 'colleagues', 'colleagues', 'A colleague of the person.'),
(6933, 1, 22, 'colleague', 'colleague', 'A colleague of the person.'),
(6934, 1, 22, 'mobileUrl', 'mobileUrl', 'The [[mobileUrl]] property is provided for specific situations in which data consumers need to determine whether one of several provided URLs is a dedicated \'mobile site\'.\n\nTo discourage over-use, and reflecting intial usecases, the property is expected only on [[Product]] and [[Offer]], rather than [[Thing]]. The general trend in web technology is towards [responsive design](https://en.wikipedia.org/wiki/Responsive_web_design) in which content can be flexibly adapted to a wide range of browsing environments. Pages and sites referenced with the long-established [[url]] property should ideally also be usable on a wide variety of devices, including mobile phones. In most cases, it would be pointless and counter productive to attempt to update all [[url]] markup to use [[mobileUrl]] for more mobile-oriented pages. The property is intended for the case when items (primarily [[Product]] and [[Offer]]) have extra URLs hosted on an additional \"mobile site\" alongside the main one. It should not be taken as an endorsement of this publication style.\n    '),
(6935, 1, 22, 'suggestedGender', 'suggestedGender', 'The suggested gender of the intended person or audience, for example \"male\", \"female\", or \"unisex\".'),
(6936, 1, 22, 'eventStatus', 'eventStatus', 'An eventStatus of an event represents its status; particularly useful when an event is cancelled or rescheduled.'),
(6937, 1, 22, 'discusses', 'discusses', 'Specifies the CreativeWork associated with the UserComment.'),
(6938, 1, 22, 'borrower', 'borrower', 'A sub property of participant. The person that borrows the object being lent.'),
(6939, 1, 22, 'inBroadcastLineup', 'inBroadcastLineup', 'The CableOrSatelliteService offering the channel.'),
(6940, 1, 22, 'intensity', 'intensity', 'Quantitative measure gauging the degree of force involved in the exercise, for example, heartbeats per minute. May include the velocity of the movement.'),
(6941, 1, 22, 'textValue', 'textValue', 'Text value being annotated.'),
(6942, 1, 22, 'isAccessoryOrSparePartFor', 'isAccessoryOrSparePartFor', 'A pointer to another product (or multiple products) for which this product is an accessory or spare part.'),
(6943, 1, 22, 'previousStartDate', 'previousStartDate', 'Used in conjunction with eventStatus for rescheduled or cancelled events. This property contains the previously scheduled start date. For rescheduled events, the startDate property should be used for the newly scheduled start date. In the (rare) case of an event that has been postponed and rescheduled multiple times, this field may be repeated.'),
(6944, 1, 22, 'maintainer', 'maintainer', 'A maintainer of a [[Dataset]], software package ([[SoftwareApplication]]), or other [[Project]]. A maintainer is a [[Person]] or [[Organization]] that manages contributions to, and/or publication of, some (typically complex) artifact. It is common for distributions of software and data to be based on \"upstream\" sources. When [[maintainer]] is applied to a specific version of something e.g. a particular version or packaging of a [[Dataset]], it is always  possible that the upstream source has a different maintainer. The [[isBasedOn]] property can be used to indicate such relationships between datasets to make the different maintenance roles clear. Similarly in the case of software, a package may have dedicated maintainers working on integration into software distributions such as Ubuntu, as well as upstream maintainers of the underlying work.\n      '),
(6945, 1, 22, 'primaryPrevention', 'primaryPrevention', 'A preventative therapy used to prevent an initial occurrence of the medical condition, such as vaccination.'),
(6946, 1, 22, 'buyer', 'buyer', 'A sub property of participant. The participant/person/organization that bought the object.'),
(6947, 1, 22, 'suggestedAge', 'suggestedAge', 'The age or age range for the intended audience or person, for example 3-12 months for infants, 1-5 years for toddlers.'),
(6948, 1, 22, 'httpMethod', 'httpMethod', 'An HTTP method that specifies the appropriate HTTP method for a request to an HTTP EntryPoint. Values are capitalized strings as used in HTTP.'),
(6949, 1, 22, 'originalMediaLink', 'originalMediaLink', 'Link to the page containing an original version of the content, or directly to an online copy of the original [[MediaObject]] content, e.g. video file.'),
(6950, 1, 22, 'sameAs', 'sameAs', 'URL of a reference Web page that unambiguously indicates the item\'s identity. E.g. the URL of the item\'s Wikipedia page, Wikidata entry, or official website.'),
(6951, 1, 22, 'broadcaster', 'broadcaster', 'The organization owning or operating the broadcast service.'),
(6952, 1, 22, 'jobLocationType', 'jobLocationType', 'A description of the job location (e.g. TELECOMMUTE for telecommute jobs).'),
(6953, 1, 22, 'arrivalBusStop', 'arrivalBusStop', 'The stop or station from which the bus arrives.'),
(6954, 1, 22, 'relevantSpecialty', 'relevantSpecialty', 'If applicable, a medical specialty in which this entity is relevant.'),
(6955, 1, 22, 'permitAudience', 'permitAudience', 'The target audience for this permit.'),
(6956, 1, 22, 'seatingCapacity', 'seatingCapacity', 'The number of persons that can be seated (e.g. in a vehicle), both in terms of the physical space available, and in terms of limitations set by law.\\n\\nTypical unit code(s): C62 for persons '),
(6957, 1, 22, 'reviewBody', 'reviewBody', 'The actual body of the review.'),
(6958, 1, 22, 'serviceType', 'serviceType', 'The type of service being offered, e.g. veterans\' benefits, emergency relief, etc.'),
(6959, 1, 22, 'jobTitle', 'jobTitle', 'The job title of the person (for example, Financial Manager).'),
