(7137, 1, 22, 'webFeed', 'webFeed', 'The URL for a feed, e.g. associated with a podcast series, blog, or series of date-stamped updates. This is usually RSS or Atom.'),
(7138, 1, 22, 'creditText', 'creditText', 'Text that can be used to credit person(s) and/or organization(s) associated with a published Creative Work.'),
(7139, 1, 22, 'reservationStatus', 'reservationStatus', 'The current status of the reservation.'),
(7140, 1, 22, 'insertion', 'insertion', 'The place of attachment of a muscle, or what the muscle moves.'),
(7141, 1, 22, 'fileFormat', 'fileFormat', 'Media type, typically MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml)) of the content, e.g. application/zip of a SoftwareApplication binary. In cases where a CreativeWork has several media type representations, \'encoding\' can be used to indicate each MediaObject alongside particular fileFormat information. Unregistered or niche file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia entry.'),
(7142, 1, 22, 'encodingFormat', 'encodingFormat', 'Media type typically expressed using a MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml) and [MDN reference](https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/MIME_types)), e.g. application/zip for a SoftwareApplication binary, audio/mpeg for .mp3 etc.\n\nIn cases where a [[CreativeWork]] has several media type representations, [[encoding]] can be used to indicate each [[MediaObject]] alongside particular [[encodingFormat]] information.\n\nUnregistered or niche encoding and file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia/Wikidata entry.'),
(7143, 1, 22, 'scheduledTime', 'scheduledTime', 'The time the object is scheduled to.'),
(7144, 1, 22, 'availabilityEnds', 'availabilityEnds', 'The end of the availability of the product or service included in the offer.'),
(7145, 1, 22, 'video', 'video', 'An embedded video object.'),
(7146, 1, 22, 'fuelConsumption', 'fuelConsumption', 'The amount of fuel consumed for traveling a particular distance or temporal duration with the given vehicle (e.g. liters per 100 km).\\n\\n* Note 1: There are unfortunately no standard unit codes for liters per 100 km.  Use [[unitText]] to indicate the unit of measurement, e.g. L/100 km.\\n* Note 2: There are two ways of indicating the fuel consumption, [[fuelConsumption]] (e.g. 8 liters per 100 km) and [[fuelEfficiency]] (e.g. 30 miles per gallon). They are reciprocal.\\n* Note 3: Often, the absolute value is useful only when related to driving speed (\"at 80 km/h\") or usage pattern (\"city traffic\"). You can use [[valueReference]] to link the value for the fuel consumption to another value.'),
(7147, 1, 22, 'greaterOrEqual', 'greaterOrEqual', 'This ordering relation for qualitative values indicates that the subject is greater than or equal to the object.'),
(7148, 1, 22, 'layoutImage', 'layoutImage', 'A schematic image showing the floorplan layout.'),
(7149, 1, 22, 'broadcastAffiliateOf', 'broadcastAffiliateOf', 'The media network(s) whose content is broadcast on this station.'),
(7150, 1, 22, 'siblings', 'siblings', 'A sibling of the person.'),
(7151, 1, 22, 'sibling', 'sibling', 'A sibling of the person.'),
(7152, 1, 22, 'returnFees', 'returnFees', 'The type of return fees for purchased products (for any return reason).'),
(7153, 1, 22, 'defaultValue', 'defaultValue', 'The default value of the input.  For properties that expect a literal, the default is a literal value, for properties that expect an object, it\'s an ID reference to one of the current values.'),
(7154, 1, 22, 'foundingLocation', 'foundingLocation', 'The place where the Organization was founded.'),
(7155, 1, 22, 'childMinAge', 'childMinAge', 'Minimal age of the child.'),
(7156, 1, 22, 'followee', 'followee', 'A sub property of object. The person or organization being followed.'),
(7157, 1, 22, 'claimInterpreter', 'claimInterpreter', 'For a [[Claim]] interpreted from [[MediaObject]] content\n    sed to indicate a claim contained, implied or refined from the content of a [[MediaObject]].'),
(7158, 1, 22, 'dietFeatures', 'dietFeatures', 'Nutritional information specific to the dietary plan. May include dietary recommendations on what foods to avoid, what foods to consume, and specific alterations/deviations from the USDA or other regulatory body\'s approved dietary guidelines.'),
(7159, 1, 22, 'bookingAgent', 'bookingAgent', '\'bookingAgent\' is an out-dated term indicating a \'broker\' that serves as a booking agent.'),
(7160, 1, 22, 'broker', 'broker', 'An entity that arranges for an exchange between a buyer and a seller.  In most cases a broker never acquires or releases ownership of a product or service involved in an exchange.  If it is not clear whether an entity is a broker, seller, or buyer, the latter two terms are preferred.'),
(7161, 1, 22, 'bodyType', 'bodyType', 'Indicates the design and body style of the vehicle (e.g. station wagon, hatchback, etc.).'),
(7162, 1, 22, 'geo', 'geo', 'The geo coordinates of the place.'),
(7163, 1, 22, 'skills', 'skills', 'A statement of knowledge, skill, ability, task or any other assertion expressing a competency that is desired or required to fulfill this role or to work in this occupation.'),
(7164, 1, 22, 'hasMenuItem', 'hasMenuItem', 'A food or drink item contained in a menu or menu section.'),
(7165, 1, 22, 'cargoVolume', 'cargoVolume', 'The available volume for cargo or luggage. For automobiles, this is usually the trunk volume.\\n\\nTypical unit code(s): LTR for liters, FTQ for cubic foot/feet\\n\\nNote: You can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(7166, 1, 22, 'minimumPaymentDue', 'minimumPaymentDue', 'The minimum payment required at this time.'),
(7167, 1, 22, 'hospitalAffiliation', 'hospitalAffiliation', 'A hospital with which the physician or office is affiliated.'),
(7168, 1, 22, 'scheduledPaymentDate', 'scheduledPaymentDate', 'The date the invoice is scheduled to be paid.'),
(7169, 1, 22, 'targetUrl', 'targetUrl', 'The URL of a node in an established educational framework.'),
(7170, 1, 22, 'overdosage', 'overdosage', 'Any information related to overdose on a drug, including signs or symptoms, treatments, contact information for emergency response.'),
(7171, 1, 22, 'legislationResponsible', 'legislationResponsible', 'An individual or organization that has some kind of responsibility for the legislation. Typically the ministry who is/was in charge of elaborating the legislation, or the adressee for potential questions about the legislation once it is published.'),
(7172, 1, 22, 'safetyConsideration', 'safetyConsideration', 'Any potential safety concern associated with the supplement. May include interactions with other drugs and foods, pregnancy, breastfeeding, known adverse reactions, and documented efficacy of the supplement.'),
(7173, 1, 22, 'hasMeasurement', 'hasMeasurement', 'A product measurement, for example the inseam of pants, the wheel size of a bicycle, or the gauge of a screw. Usually an exact measurement, but can also be a range of measurements for adjustable products, for example belts and ski bindings.'),
(7174, 1, 22, 'smokingAllowed', 'smokingAllowed', 'Indicates whether it is allowed to smoke in the place, e.g. in the restaurant, hotel or hotel room.'),
(7175, 1, 22, 'correction', 'correction', 'Indicates a correction to a [[CreativeWork]], either via a [[CorrectionComment]], textually or in another document.'),
(7176, 1, 22, 'studyDesign', 'studyDesign', 'Specifics about the observational study design (enumerated).'),
(7177, 1, 22, 'artform', 'artform', 'e.g. Painting, Drawing, Sculpture, Print, Photograph, Assemblage, Collage, etc.'),
(7178, 1, 22, 'fatContent', 'fatContent', 'The number of grams of fat.'),
(7179, 1, 22, 'costOrigin', 'costOrigin', 'Additional details to capture the origin of the cost data. For example, \'Medicare Part B\'.'),
(7180, 1, 22, 'aspect', 'aspect', 'An aspect of medical practice that is considered on the page, such as \'diagnosis\', \'treatment\', \'causes\', \'prognosis\', \'etiology\', \'epidemiology\', etc.'),
(7181, 1, 22, 'mainContentOfPage', 'mainContentOfPage', 'Indicates if this web page element is the main subject of the page.'),
(7182, 1, 22, 'transitTimeLabel', 'transitTimeLabel', 'Label to match an [[OfferShippingDetails]] with a [[DeliveryTimeSettings]] (within the context of a [[shippingSettingsLink]] cross-reference).'),
(7183, 1, 22, 'nerveMotor', 'nerveMotor', 'The neurological pathway extension that involves muscle control.'),
(7184, 1, 22, 'alignmentType', 'alignmentType', 'A category of alignment between the learning resource and the framework node. Recommended values include: \'requires\', \'textComplexity\', \'readingLevel\', and \'educationalSubject\'.'),
(7185, 1, 22, 'tongueWeight', 'tongueWeight', 'The permitted vertical load (TWR) of a trailer attached to the vehicle. Also referred to as Tongue Load Rating (TLR) or Vertical Load Rating (VLR).\\n\\nTypical unit code(s): KGM for kilogram, LBR for pound\\n\\n* Note 1: You can indicate additional information in the [[name]] of the [[QuantitativeValue]] node.\\n* Note 2: You may also link to a [[QualitativeValue]] node that provides additional information using [[valueReference]].\\n* Note 3: Note that you can use [[minValue]] and [[maxValue]] to indicate ranges.'),
(7186, 1, 22, 'predecessorOf', 'predecessorOf', 'A pointer from a previous, often discontinued variant of the product to its newer variant.'),
(7187, 1, 22, 'paymentAccepted', 'paymentAccepted', 'Cash, Credit Card, Cryptocurrency, Local Exchange Tradings System, etc.'),
(7188, 1, 22, 'sportsTeam', 'sportsTeam', 'A sub property of participant. The sports team that participated on this action.'),
(7189, 1, 22, 'wordCount', 'wordCount', 'The number of words in the text of the Article.'),
(7190, 1, 22, 'vendor', 'vendor', '\'vendor\' is an earlier term for \'seller\'.'),
(7191, 1, 22, 'seatingType', 'seatingType', 'The type/class of the seat.'),
(7192, 1, 22, 'driveWheelConfiguration', 'driveWheelConfiguration', 'The drive wheel configuration, i.e. which roadwheels will receive torque from the vehicle\'s engine via the drivetrain.'),
(7193, 1, 22, 'expires', 'expires', 'Date the content expires and is no longer useful or available. For example a [[VideoObject]] or [[NewsArticle]] whose availability or relevance is time-limited, or a [[ClaimReview]] fact check whose publisher wants to indicate that it may no longer be relevant (or helpful to highlight) after some date.'),
(7194, 1, 22, 'yearlyRevenue', 'yearlyRevenue', 'The size of the business in annual revenue.'),
(7195, 1, 22, 'replacee', 'replacee', 'A sub property of object. The object that is being replaced.'),
(7196, 1, 22, 'departureAirport', 'departureAirport', 'The airport where the flight originates.'),
(7197, 1, 22, 'availableFrom', 'availableFrom', 'When the item is available for pickup from the store, locker, etc.'),
(7198, 1, 22, 'follows', 'follows', 'The most generic uni-directional social relation.'),
(7199, 1, 22, 'workHours', 'workHours', 'The typical working hours for this job (e.g. 1st shift, night shift, 8am-5pm).'),
(7200, 1, 22, 'sampleType', 'sampleType', 'What type of code sample: full (compile ready) solution, code snippet, inline code, scripts, template.'),
(7201, 1, 22, 'codeSampleType', 'codeSampleType', 'What type of code sample: full (compile ready) solution, code snippet, inline code, scripts, template.'),
(7202, 1, 22, 'confirmationNumber', 'confirmationNumber', 'A number that confirms the given order or payment has been received.'),
(7203, 1, 22, 'isBasedOnUrl', 'isBasedOnUrl', 'A resource that was used in the creation of this resource. This term can be repeated for multiple sources. For example, http://example.com/great-multiplication-intro.html.'),
(7204, 1, 22, 'isBasedOn', 'isBasedOn', 'A resource from which this work is derived or from which it is a modification or adaption.'),
(7205, 1, 22, 'travelBans', 'travelBans', 'Information about travel bans, e.g. in the context of a pandemic.'),
(7206, 1, 22, 'value', 'value', 'The value of the quantitative value or property value node.\\n\\n* For [[QuantitativeValue]] and [[MonetaryAmount]], the recommended type for values is \'Number\'.\\n* For [[PropertyValue]], it can be \'Text\', \'Number\', \'Boolean\', or \'StructuredValue\'.\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(7207, 1, 22, 'proprietaryName', 'proprietaryName', 'Proprietary name given to the diet plan, typically by its originator or creator.'),
(7208, 1, 22, 'hoursAvailable', 'hoursAvailable', 'The hours during which this service or contact is available.'),
(7209, 1, 22, 'vehicleTransmission', 'vehicleTransmission', 'The type of component used for transmitting the power from a rotating power source to the wheels or other relevant component(s) (\"gearbox\" for cars).'),
(7210, 1, 22, 'ratingExplanation', 'ratingExplanation', 'A short explanation (e.g. one to two sentences) providing background context and other information that led to the conclusion expressed in the rating. This is particularly applicable to ratings associated with \"fact check\" markup using [[ClaimReview]].'),
(7211, 1, 22, 'artist', 'artist', 'The primary artist for a work\n    	in a medium other than pencils or digital line art--for example, if the\n    	primary artwork is done in watercolors or digital paints.'),
(7212, 1, 22, 'itemLocation', 'itemLocation', 'Current location of the item.'),
(7213, 1, 22, 'cvdFacilityId', 'cvdFacilityId', 'Identifier of the NHSN facility that this data record applies to. Use [[cvdFacilityCounty]] to indicate the county. To provide other details, [[healthcareReportingData]] can be used on a [[Hospital]] entry.'),
(7214, 1, 22, 'translator', 'translator', 'Organization or person who adapts a creative work to different languages, regional differences and technical requirements of a target market, or that translates during some event.'),
(7215, 1, 22, 'eligibilityToWorkRequirement', 'eligibilityToWorkRequirement', 'The legal requirements such as citizenship, visa and other documentation required for an applicant to this job.'),
(7216, 1, 22, 'rangeIncludes', 'rangeIncludes', 'Relates a property to a class that constitutes (one of) the expected type(s) for values of the property.'),
(7217, 1, 22, 'lowPrice', 'lowPrice', 'The lowest price of all offers available.\\n\\nUsage guidelines:\\n\\n* Use values from 0123456789 (Unicode \'DIGIT ZERO\' (U+0030) to \'DIGIT NINE\' (U+0039)) rather than superficially similar Unicode symbols.\\n* Use \'.\' (Unicode \'FULL STOP\' (U+002E)) rather than \',\' to indicate a decimal point. Avoid using these symbols as a readability separator.'),
(7218, 1, 22, 'loanTerm', 'loanTerm', 'The duration of the loan or credit agreement.'),
(7219, 1, 22, 'duration', 'duration', 'The duration of the item (movie, audio recording, event, etc.) in [ISO 8601 date format](http://en.wikipedia.org/wiki/ISO_8601).'),
(7220, 1, 22, 'percentile75', 'percentile75', 'The 75th percentile value.'),
(7221, 1, 22, 'tocEntry', 'tocEntry', 'Indicates a [[HyperTocEntry]] in a [[HyperToc]].'),
(7222, 1, 22, 'hasPart', 'hasPart', 'Indicates an item or CreativeWork that is part of this item, or CreativeWork (in some sense).'),
(7223, 1, 22, 'busName', 'busName', 'The name of the bus (e.g. Bolt Express).'),
(7224, 1, 22, 'interestRate', 'interestRate', 'The interest rate, charged or paid, applicable to the financial product. Note: This is different from the calculated annualPercentageRate.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(7225, 1, 22, 'hasEnergyEfficiencyCategory', 'hasEnergyEfficiencyCategory', 'Defines the energy efficiency Category (which could be either a rating out of range of values or a yes/no certification) for a product according to an international energy efficiency standard.'),
(7226, 1, 22, 'illustrator', 'illustrator', 'The illustrator of the book.'),
(7227, 1, 22, 'eligibleTransactionVolume', 'eligibleTransactionVolume', 'The transaction volume, in a monetary unit, for which the offer or price specification is valid, e.g. for indicating a minimal purchasing volume, to express free shipping above a certain order volume, or to limit the acceptance of credit cards to purchases to a certain minimal amount.'),
(7228, 1, 22, 'additionalType', 'additionalType', 'An additional type for the item, typically used for adding more specific types from external vocabularies in microdata syntax. This is a relationship between something and a class that the thing is in. In RDFa syntax, it is better to use the native RDFa syntax - the \'typeof\' attribute - for multiple types. Schema.org tools may have only weaker understanding of extra types, in particular those defined externally.'),
(7229, 1, 22, 'exifData', 'exifData', 'exif data for this object.'),
(7230, 1, 22, 'imagingTechnique', 'imagingTechnique', 'Imaging technique used.'),
(7231, 1, 22, 'ownedThrough', 'ownedThrough', 'The date and time of giving up ownership on the product.'),
(7232, 1, 22, 'targetPopulation', 'targetPopulation', 'Characteristics of the population for which this is intended, or which typically uses it, e.g. \'adults\'.'),
(7233, 1, 22, 'referenceQuantity', 'referenceQuantity', 'The reference quantity for which a certain price applies, e.g. 1 EUR per 4 kWh of electricity. This property is a replacement for unitOfMeasurement for the advanced cases where the price does not relate to a standard unit.'),
(7234, 1, 22, 'howPerformed', 'howPerformed', 'How the procedure is performed.'),
(7235, 1, 22, 'signOrSymptom', 'signOrSymptom', 'A sign or symptom of this condition. Signs are objective or physically observable manifestations of the medical condition while symptoms are the subjective experience of the medical condition.'),
(7236, 1, 22, 'isInvolvedInBiologicalProcess', 'isInvolvedInBiologicalProcess', 'Biological process this BioChemEntity is involved in; please use PropertyValue if you want to include any evidence.'),
(7237, 1, 22, 'preparation', 'preparation', 'Typical preparation that a patient must undergo before having the procedure performed.'),
(7238, 1, 22, 'winner', 'winner', 'A sub property of participant. The winner of the action.'),
(7239, 1, 22, 'muscleAction', 'muscleAction', 'The movement the muscle generates.'),
(7240, 1, 22, 'numberOfAirbags', 'numberOfAirbags', 'The number or type of airbags in the vehicle.'),
(7241, 1, 22, 'expectsAcceptanceOf', 'expectsAcceptanceOf', 'An Offer which must be accepted before the user can perform the Action. For example, the user may need to buy a movie before being able to watch it.'),
(7242, 1, 22, 'courseWorkload', 'courseWorkload', 'The amount of work expected of students taking the course, often provided as a figure per week or per month, and may be broken down by type. For example, \"2 hours of lectures, 1 hour of lab work and 3 hours of independent study per week\".'),
(7243, 1, 22, 'issuedThrough', 'issuedThrough', 'The service through which the permit was granted.'),
(7244, 1, 22, 'depth', 'depth', 'The depth of the item.'),
(7245, 1, 22, 'transmissionMethod', 'transmissionMethod', 'How the disease spreads, either as a route or vector, for example \'direct contact\', \'Aedes aegypti\', etc.'),
(7246, 1, 22, 'petsAllowed', 'petsAllowed', 'Indicates whether pets are allowed to enter the accommodation or lodging business. More detailed information can be put in a text value.'),
(7247, 1, 22, 'fromLocation', 'fromLocation', 'A sub property of location. The original location of the object or the agent before the action.'),
(7248, 1, 22, 'editor', 'editor', 'Specifies the Person who edited the CreativeWork.'),
(7249, 1, 22, 'ineligibleRegion', 'ineligibleRegion', 'The ISO 3166-1 (ISO 3166-1 alpha-2) or ISO 3166-2 code, the place, or the GeoShape for the geo-political region(s) for which the offer or delivery charge specification is not valid, e.g. a region where the transaction is not allowed.\\n\\nSee also [[eligibleRegion]].\n      '),
(7250, 1, 22, 'events', 'events', 'Upcoming or past events associated with this place or organization.'),
(7251, 1, 22, 'event', 'event', 'Upcoming or past event associated with this place, organization, or action.'),
(7252, 1, 22, 'modifiedTime', 'modifiedTime', 'The date and time the reservation was modified.'),
(7253, 1, 22, 'nerve', 'nerve', 'The underlying innervation associated with the muscle.'),
(7254, 1, 22, 'customerRemorseReturnFees', 'customerRemorseReturnFees', 'The type of return fees if the product is returned due to customer remorse.'),
(7255, 1, 22, 'associatedMedia', 'associatedMedia', 'A media object that encodes this CreativeWork. This property is a synonym for encoding.'),
(7256, 1, 22, 'educationalUse', 'educationalUse', 'The purpose of a work in the context of education; for example, \'assignment\', \'group work\'.'),
(7257, 1, 22, 'numberOfPlayers', 'numberOfPlayers', 'Indicate how many people can play this game (minimum, maximum, or range).'),
(7258, 1, 22, 'width', 'width', 'The width of the item.'),
(7259, 1, 22, 'conditionsOfAccess', 'conditionsOfAccess', 'Conditions that affect the availability of, or method(s) of access to, an item. Typically used for real world items such as an [[ArchiveComponent]] held by an [[ArchiveOrganization]]. This property is not suitable for use as a general Web access control mechanism. It is expressed only in natural language.\\n\\nFor example \"Available by appointment from the Reading Room\" or \"Accessible only from logged-in accounts \". '),
(7260, 1, 22, 'bodyLocation', 'bodyLocation', 'Location in the body of the anatomical structure.'),
(7261, 1, 22, 'nutrition', 'nutrition', 'Nutrition information about the recipe or menu item.'),
(7262, 1, 22, 'eligibleQuantity', 'eligibleQuantity', 'The interval and unit of measurement of ordering quantities for which the offer or price specification is valid. This allows e.g. specifying that a certain freight charge is valid only for a certain quantity.'),
(7263, 1, 22, 'owns', 'owns', 'Products owned by the organization or person.'),
(7264, 1, 22, 'breadcrumb', 'breadcrumb', 'A set of links that can help a user understand and navigate a website hierarchy.'),
(7265, 1, 22, 'percentile10', 'percentile10', 'The 10th percentile value.'),
(7266, 1, 22, 'dateSent', 'dateSent', 'The date/time at which the message was sent.'),
(7267, 1, 22, 'healthPlanCopayOption', 'healthPlanCopayOption', 'Whether the copay is before or after deductible, etc. TODO: Is this a closed set?'),
(7268, 1, 22, 'birthPlace', 'birthPlace', 'The place where the person was born.'),
(7269, 1, 22, 'name', 'name', 'The name of the item.'),
(7270, 1, 22, 'permittedUsage', 'permittedUsage', 'Indications regarding the permitted usage of the accommodation.'),
(7271, 1, 22, 'includedDataCatalog', 'includedDataCatalog', 'A data catalog which contains this dataset (this property was previously \'catalog\', preferred name is now \'includedInDataCatalog\').'),
(7272, 1, 22, 'dependencies', 'dependencies', 'Prerequisites needed to fulfill steps in article.'),
(7273, 1, 22, 'actionAccessibilityRequirement', 'actionAccessibilityRequirement', 'A set of requirements that must be fulfilled in order to perform an Action. If more than one value is specified, fulfilling one set of requirements will allow the Action to be performed.'),
(7274, 1, 22, 'inPlaylist', 'inPlaylist', 'The playlist to which this recording belongs.'),
(7275, 1, 22, 'geoIntersects', 'geoIntersects', 'Represents spatial relations in which two geometries (or the places they represent) have at least one point in common. As defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).'),
(7276, 1, 22, 'openingHours', 'openingHours', 'The general opening hours for a business. Opening hours can be specified as a weekly time range, starting with days, then times per day. Multiple days can be listed with commas \',\' separating each day. Day or time ranges are specified using a hyphen \'-\'.\\n\\n* Days are specified using the following two-letter combinations: ```Mo```, ```Tu```, ```We```, ```Th```, ```Fr```, ```Sa```, ```Su```.\\n* Times are specified using 24:00 format. For example, 3pm is specified as ```15:00```, 10am as ```10:00```. \\n* Here is an example: <code>&lt;time itemprop=\"openingHours\" datetime=&quot;Tu,Th 16:00-20:00&quot;&gt;Tuesdays and Thursdays 4-8pm&lt;/time&gt;</code>.\\n* If a business is open 7 days a week, then it can be specified as <code>&lt;time itemprop=&quot;openingHours&quot; datetime=&quot;Mo-Su&quot;&gt;Monday through Sunday, all day&lt;/time&gt;</code>.'),
(7277, 1, 22, 'familyName', 'familyName', 'Family name. In the U.S., the last name of a Person.'),
(7278, 1, 22, 'nextItem', 'nextItem', 'A link to the ListItem that follows the current one.'),
(7279, 1, 22, 'maps', 'maps', 'A URL to a map of the place.'),
(7280, 1, 22, 'fuelCapacity', 'fuelCapacity', 'The capacity of the fuel tank or in the case of electric cars, the battery. If there are multiple components for storage, this should indicate the total of all storage of the same type.\\n\\nTypical unit code(s): LTR for liters, GLL of US gallons, GLI for UK / imperial gallons, AMH for ampere-hours (for electrical vehicles).'),
(7281, 1, 22, 'maximumVirtualAttendeeCapacity', 'maximumVirtualAttendeeCapacity', 'The maximum physical attendee capacity of an [[Event]] whose [[eventAttendanceMode]] is [[OnlineEventAttendanceMode]] (or the online aspects, in the case of a [[MixedEventAttendanceMode]]). '),
(7282, 1, 22, 'itemCondition', 'itemCondition', 'A predefined value from OfferItemCondition specifying the condition of the product or service, or the products or services included in the offer. Also used for product return policies to specify the condition of products accepted for returns.'),
(7283, 1, 22, 'cvdNumVentUse', 'cvdNumVentUse', 'numventuse - MECHANICAL VENTILATORS IN USE: Total number of ventilators in use.'),
(7284, 1, 22, 'modelDate', 'modelDate', 'The release date of a vehicle model (often used to differentiate versions of the same make and model).'),
(7285, 1, 22, 'monoisotopicMolecularWeight', 'monoisotopicMolecularWeight', 'The monoisotopic mass is the sum of the masses of the atoms in a molecule using the unbound, ground-state, rest mass of the principal (most abundant) isotope for each element instead of the isotopic average mass. Please include the units in the form \'&lt;Number&gt; &lt;unit&gt;\', for example \'770.230488 g/mol\' or as \'&lt;QuantitativeValue&gt;.'),
(7286, 1, 22, 'polygon', 'polygon', 'A polygon is the area enclosed by a point-to-point path for which the starting and ending points are the same. A polygon is expressed as a series of four or more space delimited points where the first and final points are identical.'),
(7287, 1, 22, 'legalStatus', 'legalStatus', 'The drug or supplement\'s legal status, including any controlled substance schedules that apply.'),
(7288, 1, 22, 'servesCuisine', 'servesCuisine', 'The cuisine of the restaurant.'),
(7289, 1, 22, 'answerExplanation', 'answerExplanation', 'A step-by-step or full explanation about Answer. Can outline how this Answer was achieved or contain more broad clarification or statement about it. '),
(7290, 1, 22, 'childMaxAge', 'childMaxAge', 'Maximal age of the child.'),
(7291, 1, 22, 'lender', 'lender', 'A sub property of participant. The person that lends the object being borrowed.'),
(7292, 1, 22, 'significance', 'significance', 'The significance associated with the superficial anatomy; as an example, how characteristics of the superficial anatomy can suggest underlying medical conditions or courses of treatment.'),
(7293, 1, 22, 'relatedTo', 'relatedTo', 'The most generic familial relation.'),
(7294, 1, 22, 'shippingSettingsLink', 'shippingSettingsLink', 'Link to a page containing [[ShippingRateSettings]] and [[DeliveryTimeSettings]] details.'),
(7295, 1, 22, 'hasMerchantReturnPolicy', 'hasMerchantReturnPolicy', 'Specifies a MerchantReturnPolicy that may be applicable.'),
(7296, 1, 22, 'variableMeasured', 'variableMeasured', 'The variableMeasured property can indicate (repeated as necessary) the  variables that are measured in some dataset, either described as text or as pairs of identifier and description using PropertyValue.'),
(7297, 1, 22, 'acquireLicensePage', 'acquireLicensePage', 'Indicates a page documenting how licenses can be purchased or otherwise acquired, for the current item.'),
(7298, 1, 22, 'usageInfo', 'usageInfo', 'The schema.org [[usageInfo]] property indicates further information about a [[CreativeWork]]. This property is applicable both to works that are freely available and to those that require payment or other transactions. It can reference additional information, e.g. community expectations on preferred linking and citation conventions, as well as purchasing details. For something that can be commercially licensed, usageInfo can provide detailed, resource-specific information about licensing options.\n\nThis property can be used alongside the license property which indicates license(s) applicable to some piece of content. The usageInfo property can provide information about other licensing options, e.g. acquiring commercial usage rights for an image that is also available under non-commercial creative commons licenses.'),
(7299, 1, 22, 'reviewedBy', 'reviewedBy', 'People or organizations that have reviewed the content on this web page for accuracy and/or completeness.'),
(7300, 1, 22, 'availableDeliveryMethod', 'availableDeliveryMethod', 'The delivery method(s) available for this offer.'),
(7301, 1, 22, 'embedUrl', 'embedUrl', 'A URL pointing to a player for a specific video. In general, this is the information in the ```src``` element of an ```embed``` tag and should not be the same as the content of the ```loc``` tag.'),
(7302, 1, 22, 'option', 'option', 'A sub property of object. The options subject to this action.'),
(7303, 1, 22, 'actionOption', 'actionOption', 'A sub property of object. The options subject to this action.'),
(7304, 1, 22, 'collection', 'collection', 'A sub property of object. The collection target of the action.'),
(7305, 1, 22, 'targetCollection', 'targetCollection', 'A sub property of object. The collection target of the action.'),
(7306, 1, 22, 'encodingType', 'encodingType', 'The supported encoding type(s) for an EntryPoint request.'),
(7307, 1, 22, 'musicReleaseFormat', 'musicReleaseFormat', 'Format of this release (the type of recording media used, i.e. compact disc, digital media, LP, etc.).'),
(7308, 1, 22, 'interactionCount', 'interactionCount', 'This property is deprecated, alongside the UserInteraction types on which it depended.'),
(7309, 1, 22, 'interactionStatistic', 'interactionStatistic', 'The number of interactions for the CreativeWork using the WebSite or SoftwareApplication. The most specific child type of InteractionCounter should be used.'),
(7310, 1, 22, 'worstRating', 'worstRating', 'The lowest value allowed in this rating system. If worstRating is omitted, 1 is assumed.'),
(7311, 1, 22, 'providerMobility', 'providerMobility', 'Indicates the mobility of a provided service (e.g. \'static\', \'dynamic\').'),
(7312, 1, 22, 'trackingUrl', 'trackingUrl', 'Tracking url for the parcel delivery.'),
(7313, 1, 22, 'departureGate', 'departureGate', 'Identifier of the flight\'s departure gate.'),
(7314, 1, 22, 'paymentStatus', 'paymentStatus', 'The status of payment; whether the invoice has been paid or not.'),
(7315, 1, 22, 'valueAddedTaxIncluded', 'valueAddedTaxIncluded', 'Specifies whether the applicable value-added tax (VAT) is included in the price specification or not.'),
(7316, 1, 22, 'carrier', 'carrier', '\'carrier\' is an out-dated term indicating the \'provider\' for parcel delivery and flights.'),
(7317, 1, 22, 'provider', 'provider', 'The service provider, service operator, or service performer; the goods producer. Another party (a seller) may offer those services or goods on behalf of the provider. A provider may also serve as the seller.'),
(7318, 1, 22, 'geoDisjoint', 'geoDisjoint', 'Represents spatial relations in which two geometries (or the places they represent) are topologically disjoint: \"they have no point in common. They form a set of disconnected geometries.\" (A symmetric relationship, as defined in [DE-9IM](https://en.wikipedia.org/wiki/DE-9IM).)'),
(7319, 1, 22, 'unsaturatedFatContent', 'unsaturatedFatContent', 'The number of grams of unsaturated fat.'),
(7320, 1, 22, 'schemaVersion', 'schemaVersion', 'Indicates (by URL or string) a particular version of a schema used in some CreativeWork. This property was created primarily to\n    indicate the use of a specific schema.org release, e.g. ```10.0``` as a simple string, or more explicitly via URL, ```https://schema.org/docs/releases.html#v10.0```. There may be situations in which other schemas might usefully be referenced this way, e.g. ```http://dublincore.org/specifications/dublin-core/dces/1999-07-02/``` but this has not been carefully explored in the community.'),
(7321, 1, 22, 'speechToTextMarkup', 'speechToTextMarkup', 'Form of markup used. eg. [SSML](https://www.w3.org/TR/speech-synthesis11) or [IPA](https://www.wikidata.org/wiki/Property:P898).'),
(7322, 1, 22, 'reviewCount', 'reviewCount', 'The count of total number of reviews.'),
(7323, 1, 22, 'sourcedFrom', 'sourcedFrom', 'The neurological pathway that originates the neurons.'),
(7324, 1, 22, 'videoFrameSize', 'videoFrameSize', 'The frame size of the video.'),
(7325, 1, 22, 'inProductGroupWithID', 'inProductGroupWithID', 'Indicates the [[productGroupID]] for a [[ProductGroup]] that this product [[isVariantOf]]. '),
(7326, 1, 22, 'numberOfDoors', 'numberOfDoors', 'The number of doors.\\n\\nTypical unit code(s): C62'),
(7327, 1, 22, 'issuedBy', 'issuedBy', 'The organization issuing the ticket or permit.'),
(7328, 1, 22, 'orderItemStatus', 'orderItemStatus', 'The current status of the order item.'),
(7329, 1, 22, 'healthPlanNetworkTier', 'healthPlanNetworkTier', 'The tier(s) for this network.'),
(7330, 1, 22, 'copyrightHolder', 'copyrightHolder', 'The party holding the legal copyright to the CreativeWork.'),
(7331, 1, 22, 'accessibilitySummary', 'accessibilitySummary', 'A human-readable summary of specific accessibility features or deficiencies, consistent with the other accessibility metadata but expressing subtleties such as \"short descriptions are present but long descriptions will be needed for non-visual users\" or \"short descriptions are present and no long descriptions are needed.\"'),
(7332, 1, 22, 'monthsOfExperience', 'monthsOfExperience', 'Indicates the minimal number of months of experience required for a position.'),
(7333, 1, 22, 'primaryImageOfPage', 'primaryImageOfPage', 'Indicates the main image on the page.'),
(7334, 1, 22, 'transcript', 'transcript', 'If this MediaObject is an AudioObject or VideoObject, the transcript of that object.'),
(7335, 1, 22, 'accountOverdraftLimit', 'accountOverdraftLimit', 'An overdraft is an extension of credit from a lending institution when an account reaches zero. An overdraft allows the individual to continue withdrawing money even if the account has no funds in it. Basically the bank allows people to borrow a set amount of money.'),
(7336, 1, 22, 'cvdNumICUBeds', 'cvdNumICUBeds', 'numicubeds - ICU BEDS: Total number of staffed inpatient intensive care unit (ICU) beds.'),
(7337, 1, 22, 'contactType', 'contactType', 'A person or organization can have different contact points, for different purposes. For example, a sales contact point, a PR contact point and so on. This property is used to specify the kind of contact point.'),
(7338, 1, 22, 'timeRequired', 'timeRequired', 'Approximate or typical time it takes to work with or through this learning resource for the typical intended target audience, e.g. \'PT30M\', \'PT1H25M\'.'),
(7339, 1, 22, 'endorsee', 'endorsee', 'A sub property of participant. The person/organization being supported.'),
(7340, 1, 22, 'relatedLink', 'relatedLink', 'A link related to this web page, for example to other related web pages.'),
(7341, 1, 22, 'tickerSymbol', 'tickerSymbol', 'The exchange traded instrument associated with a Corporation object. The tickerSymbol is expressed as an exchange and an instrument name separated by a space character. For the exchange component of the tickerSymbol attribute, we recommend using the controlled vocabulary of Market Identifier Codes (MIC) specified in ISO 15022.'),
(7342, 1, 22, 'url', 'url', 'URL of the item.'),
(7343, 1, 22, 'associatedArticle', 'associatedArticle', 'A NewsArticle associated with the Media Object.'),
(7344, 1, 22, 'coverageEndTime', 'coverageEndTime', 'The time when the live blog will stop covering the Event. Note that coverage may continue after the Event concludes.'),
(7345, 1, 22, 'publisher', 'publisher', 'The publisher of the creative work.'),
(7346, 1, 22, 'interactivityType', 'interactivityType', 'The predominant mode of learning supported by the learning resource. Acceptable values are \'active\', \'expositive\', or \'mixed\'.'),
(7347, 1, 22, 'studySubject', 'studySubject', 'A subject of the study, i.e. one of the medical conditions, therapies, devices, drugs, etc. investigated by the study.'),
(7348, 1, 22, 'mechanismOfAction', 'mechanismOfAction', 'The specific biochemical interaction through which this drug or supplement produces its pharmacological effect.'),
(7349, 1, 22, 'educationalFramework', 'educationalFramework', 'The framework to which the resource being described is aligned.'),
(7350, 1, 22, 'accessModeSufficient', 'accessModeSufficient', 'A list of single or combined accessModes that are sufficient to understand all the intellectual content of a resource. Values should be drawn from the [approved vocabulary](https://www.w3.org/2021/a11y-discov-vocab/latest/#accessModeSufficient-vocabulary).'),
(7351, 1, 22, 'cookingMethod', 'cookingMethod', 'The method of cooking, such as Frying, Steaming, ...'),
(7352, 1, 22, 'xpath', 'xpath', 'An XPath, e.g. of a [[SpeakableSpecification]] or [[WebPageElement]]. In the latter case, multiple matches within a page can constitute a single conceptual \"Web page element\".'),
(7353, 1, 22, 'printColumn', 'printColumn', 'The number of the column in which the NewsArticle appears in the print edition.'),
(7354, 1, 22, 'surface', 'surface', 'A material used as a surface in some artwork, e.g. Canvas, Paper, Wood, Board, etc.'),
(7355, 1, 22, 'artworkSurface', 'artworkSurface', 'The supporting materials for the artwork, e.g. Canvas, Paper, Wood, Board, etc.'),
(7356, 1, 22, 'trainName', 'trainName', 'The name of the train (e.g. The Orient Express).'),
(7357, 1, 22, 'broadcastFrequencyValue', 'broadcastFrequencyValue', 'The frequency in MHz for a particular broadcast.'),
(7358, 1, 22, 'distance', 'distance', 'The distance travelled, e.g. exercising or travelling.'),
(7359, 1, 22, 'totalJobOpenings', 'totalJobOpenings', 'The number of positions open for this job posting. Use a positive integer. Do not use if the number of positions is unclear or not known.'),
(7360, 1, 22, 'opens', 'opens', 'The opening hour of the place or service on the given day(s) of the week.'),
(7361, 1, 22, 'availableThrough', 'availableThrough', 'After this date, the item will no longer be available for pickup.'),
(7362, 1, 22, 'cheatCode', 'cheatCode', 'Cheat codes to the game.'),
(7363, 1, 22, 'cholesterolContent', 'cholesterolContent', 'The number of milligrams of cholesterol.'),
(7364, 1, 22, 'departurePlatform', 'departurePlatform', 'The platform from which the train departs.'),
(7365, 1, 22, 'upvoteCount', 'upvoteCount', 'The number of upvotes this question, answer or comment has received from the community.'),
(7366, 1, 22, 'termsPerYear', 'termsPerYear', 'The number of times terms of study are offered per year. Semesters and quarters are common units for term. For example, if the student can only take 2 semesters for the program in one year, then termsPerYear should be 2.'),
(7367, 1, 22, 'deliveryStatus', 'deliveryStatus', 'New entry added as the package passes through each leg of its journey (from shipment to final delivery).'),
(7368, 1, 22, 'releaseNotes', 'releaseNotes', 'Description of what changed in this version.'),
(7369, 1, 22, 'warning', 'warning', 'Any FDA or other warnings about the drug (text or URL).'),
(7370, 1, 22, 'businessFunction', 'businessFunction', 'The business function (e.g. sell, lease, repair, dispose) of the offer or component of a bundle (TypeAndQuantityNode). The default is http://purl.org/goodrelations/v1#Sell.'),
(7371, 1, 22, 'hasEnergyConsumptionDetails', 'hasEnergyConsumptionDetails', 'Defines the energy efficiency Category (also known as \"class\" or \"rating\") for a product according to an international energy efficiency standard.'),
(7372, 1, 22, 'device', 'device', 'Device required to run the application. Used in cases where a specific make/model is required to run the application.'),
