(7380, 1, 22, 'securityScreening', 'securityScreening', 'The type of security screening the passenger is subject to.'),
(7381, 1, 22, 'downloadUrl', 'downloadUrl', 'If the file can be downloaded, URL to download the binary.'),
(7382, 1, 22, 'incentives', 'incentives', 'Description of bonus and commission compensation aspects of the job.'),
