(7387, 1, 22, 'accommodationFloorPlan', 'accommodationFloorPlan', 'A floorplan of some [[Accommodation]].'),
(7388, 1, 22, 'jobStartDate', 'jobStartDate', 'The date on which a successful applicant for this job would be expected to start work. Choose a specific date in the future or use the jobImmediateStart property to indicate the position is to be filled as soon as possible.'),
(7389, 1, 22, 'hasDeliveryMethod', 'hasDeliveryMethod', 'Method used for delivery or shipping.'),
(7390, 1, 22, 'procedureType', 'procedureType', 'The type of procedure, for example Surgical, Noninvasive, or Percutaneous.'),
(7391, 1, 22, 'liveBlogUpdate', 'liveBlogUpdate', 'An update to the LiveBlog.'),
(7392, 1, 22, 'license', 'license', 'A license document that applies to this content, typically indicated by URL.'),
(7393, 1, 22, 'iso6523Code', 'iso6523Code', 'An organization identifier as defined in ISO 6523(-1). Note that many existing organization identifiers such as [leiCode](https://schema.org/leiCode), [duns](https://schema.org/duns) and [vatID](https://schema.org/vatID) can be expressed as an ISO 6523 identifier by setting the ICD part of the ISO 6523 identifier accordingly. '),
(7394, 1, 22, 'expectedPrognosis', 'expectedPrognosis', 'The likely outcome in either the short term or long term of the medical condition.'),
(7395, 1, 22, 'programmingLanguage', 'programmingLanguage', 'The computer programming language.'),
(7396, 1, 22, 'contentSize', 'contentSize', 'File size in (mega/kilo)bytes.'),
(7397, 1, 22, 'tocContinuation', 'tocContinuation', 'A [[HyperTocEntry]] can have a [[tocContinuation]] indicated, which is another [[HyperTocEntry]] that would be the default next item to play or render.'),
(7398, 1, 22, 'contentRating', 'contentRating', 'Official rating of a piece of content&#x2014;for example, \'MPAA PG-13\'.'),
(7399, 1, 22, 'albumProductionType', 'albumProductionType', 'Classification of the album by its type of content: soundtrack, live album, studio album, etc.'),
(7400, 1, 22, 'articleBody', 'articleBody', 'The actual body of the article.'),
(7401, 1, 22, 'accountId', 'accountId', 'The identifier for the account the payment will be applied to.'),
(7402, 1, 22, 'paymentMethodId', 'paymentMethodId', 'An identifier for the method of payment used (e.g. the last 4 digits of the credit card).'),
(7403, 1, 22, 'weight', 'weight', 'The weight of the product or person.'),
(7404, 1, 22, 'potentialAction', 'potentialAction', 'Indicates a potential Action, which describes an idealized action in which this thing would play an \'object\' role.'),
(7405, 1, 22, 'suggestedMeasurement', 'suggestedMeasurement', 'A suggested range of body measurements for the intended audience or person, for example inseam between 32 and 34 inches or height between 170 and 190 cm. Typically found on a size chart for wearable products.'),
(7406, 1, 22, 'softwareVersion', 'softwareVersion', 'Version of the software instance.'),
(7407, 1, 22, 'streetAddress', 'streetAddress', 'The street address. For example, 1600 Amphitheatre Pkwy.'),
(7408, 1, 22, 'serviceSmsNumber', 'serviceSmsNumber', 'The number to access the service by text message.'),
(7409, 1, 22, 'webCheckinTime', 'webCheckinTime', 'The time when a passenger can check into the flight online.'),
(7410, 1, 22, 'tributary', 'tributary', 'The anatomical or organ system that the vein flows into; a larger structure that the vein connects to.'),
(7411, 1, 22, 'discussionUrl', 'discussionUrl', 'A link to the page containing the comments of the CreativeWork.'),
(7412, 1, 22, 'parentTaxon', 'parentTaxon', 'Closest parent taxon of the taxon in question.'),
(7413, 1, 22, 'childTaxon', 'childTaxon', 'Closest child taxa of the taxon in question.'),
(7414, 1, 22, 'subjectOf', 'subjectOf', 'A CreativeWork or Event about this Thing.'),
(7415, 1, 22, 'about', 'about', 'The subject matter of the content.'),
(7416, 1, 22, 'holdingArchive', 'holdingArchive', '[[ArchiveOrganization]] that holds, keeps or maintains the [[ArchiveComponent]].'),
(7417, 1, 22, 'archiveHeld', 'archiveHeld', 'Collection, [fonds](https://en.wikipedia.org/wiki/Fonds), or item held, kept or maintained by an [[ArchiveOrganization]].'),
(7418, 1, 22, 'dataset', 'dataset', 'A dataset contained in this catalog.'),
(7419, 1, 22, 'offeredBy', 'offeredBy', 'A pointer to the organization or person making the offer.'),
(7420, 1, 22, 'makesOffer', 'makesOffer', 'A pointer to products or services offered by the organization or person.'),
(7421, 1, 22, 'offers', 'offers', 'An offer to provide this item&#x2014;for example, an offer to sell a product, rent the DVD of a movie, perform a service, or give away tickets to an event. Use [[businessFunction]] to indicate the kind of transaction offered, i.e. sell, lease, etc. This property can also be used to describe a [[Demand]]. While this property is listed as expected on a number of common types, it can be used in others. In that case, using a second type, such as Product or a subtype of Product, can clarify the nature of the offer.\n      '),
(7422, 1, 22, 'itemOffered', 'itemOffered', 'An item being offered (or demanded). The transactional nature of the offer or demand is documented using [[businessFunction]], e.g. sell, lease etc. While several common expected types are listed explicitly in this definition, others can be used. Using a second type, such as Product or a subtype of Product, can clarify the nature of the offer.'),
(7423, 1, 22, 'mainEntityOfPage', 'mainEntityOfPage', 'Indicates a page (or other CreativeWork) for which this thing is the main entity being described. See [background notes](/docs/datamodel.html#mainEntityBackground) for details.'),
(7424, 1, 22, 'mainEntity', 'mainEntity', 'Indicates the primary entity described in some page or other CreativeWork.'),
(7425, 1, 22, 'hasBioChemEntityPart', 'hasBioChemEntityPart', 'Indicates a BioChemEntity that (in some sense) has this BioChemEntity as a part. '),
(7426, 1, 22, 'isPartOfBioChemEntity', 'isPartOfBioChemEntity', 'Indicates a BioChemEntity that is (in some sense) a part of this BioChemEntity. '),
(7427, 1, 22, 'funding', 'funding', 'A [[Grant]] that directly or indirectly provide funding or sponsorship for this item. See also [[ownershipFundingInfo]].'),
(7428, 1, 22, 'fundedItem', 'fundedItem', 'Indicates something directly or indirectly funded or sponsored through a [[Grant]]. See also [[ownershipFundingInfo]].'),
(7429, 1, 22, 'isEncodedByBioChemEntity', 'isEncodedByBioChemEntity', 'Another BioChemEntity encoding by this one.'),
(7430, 1, 22, 'encodesBioChemEntity', 'encodesBioChemEntity', 'Another BioChemEntity encoded by this one. '),
(7431, 1, 22, 'providesBroadcastService', 'providesBroadcastService', 'The BroadcastService offered on this channel.'),
(7432, 1, 22, 'hasBroadcastChannel', 'hasBroadcastChannel', 'A broadcast channel of a broadcast service.'),
(7433, 1, 22, 'recordedAs', 'recordedAs', 'An audio recording of the work.'),
(7434, 1, 22, 'recordingOf', 'recordingOf', 'The composition this track is a recording of.'),
(7435, 1, 22, 'releaseOf', 'releaseOf', 'The album this is a release of.'),
(7436, 1, 22, 'albumRelease', 'albumRelease', 'A release of this album.'),
(7437, 1, 22, 'partOfTrip', 'partOfTrip', 'Identifies that this [[Trip]] is a subTrip of another Trip.  For example Day 1, Day 2, etc. of a multi-day trip.'),
(7438, 1, 22, 'subTrip', 'subTrip', 'Identifies a [[Trip]] that is a subTrip of this Trip.  For example Day 1, Day 2, etc. of a multi-day trip.'),
(7439, 1, 22, 'encodesCreativeWork', 'encodesCreativeWork', 'The CreativeWork encoded by this media object.'),
(7440, 1, 22, 'subOrganization', 'subOrganization', 'A relationship between two organizations where the first includes the second, e.g., as a subsidiary. See also: the more specific \'department\' property.'),
(7441, 1, 22, 'isVariantOf', 'isVariantOf', 'Indicates the kind of product that this is a variant of. In the case of [[ProductModel]], this is a pointer (from a ProductModel) to a base product from which this product is a variant. It is safe to infer that the variant inherits all product features from the base model, unless defined locally. This is not transitive. In the case of a [[ProductGroup]], the group description also serves as a template, representing a set of Products that vary on explicitly defined, specific dimensions only (so it defines both a set of variants, as well as which values distinguish amongst those variants). When used with [[ProductGroup]], this property can apply to any [[Product]] included in the group.'),
(7442, 1, 22, 'hasVariant', 'hasVariant', 'Indicates a [[Product]] that is a member of this [[ProductGroup]] (or [[ProductModel]]).'),
(7443, 1, 22, 'gameServer', 'gameServer', 'The server on which  it is possible to play the game.'),
(7444, 1, 22, 'game', 'game', 'Video game which is played on this server.'),
(7445, 1, 22, 'containsSeason', 'containsSeason', 'A season that is part of the media series.'),
(7446, 1, 22, 'workTranslation', 'workTranslation', 'A work that is a translation of the content of this work. E.g. 西遊記 has an English workTranslation “Journey to the West”, a German workTranslation “Monkeys Pilgerfahrt” and a Vietnamese  translation Tây du ký bình khảo.'),
(7447, 1, 22, 'translationOfWork', 'translationOfWork', 'The work that this work has been translated from. E.g. 物种起源 is a translationOf “On the Origin of Species”.'),
(7448, 1, 22, 'alumniOf', 'alumniOf', 'An organization that the person is an alumni of.'),
(7449, 1, 22, 'alumni', 'alumni', 'Alumni of an organization.'),
(7450, 1, 22, 'recordedAt', 'recordedAt', 'The Event where the CreativeWork was recorded. The CreativeWork may capture all or part of the event.'),
(7451, 1, 22, 'recordedIn', 'recordedIn', 'The CreativeWork that captured all or part of this Event.'),
(7452, 1, 22, 'containsPlace', 'containsPlace', 'The basic containment relation between a place and another that it contains.'),
(7453, 1, 22, 'exampleOfWork', 'exampleOfWork', 'A creative work that this work is an example/instance/realization/derivation of.'),
(7454, 1, 22, 'contentLocation', 'contentLocation', 'The location depicted or described in the content. For example, the location in a photograph or painting.'),
(7455, 1, 22, 'superEvent', 'superEvent', 'An event that this event is a part of. For example, a collection of individual music performances might each have a music festival as their superEvent.'),
(7473, 1, 24, 'bc', 'Definition of the period in time (BC=True or AC).', 'This property informs if the date in the bound of the timeline is before christ (true) or After christ (false).'),
(7474, 1, 24, 'hasGPSCoordinates', 'Location - has GPS Coordinates', 'This property points to an instance of the GPS coordinates of the central point of the excavation\'s location (in degrees).'),
(7475, 1, 24, 'hasPersonInCharge', 'Excavation - has a person in charge -> Archaeologist', 'This property points to the person in charge of the excavation (an Archaeologist).'),
(7476, 1, 24, 'hasContext', 'Excavation - hasContext', 'This property points to the context of an excavation.'),
(7477, 1, 24, 'hasSVU', 'This property points to the to the  StratigraphicVolumeUNit', 'This property points to the StratigraphicVolumeUNit (CIDOC CRM A1).'),
(7478, 1, 24, 'foundInSVU', 'Encounter Event - an item found in a specific StratigraphicVolumeUnit', 'Points to the StratigraphicVolumeUnitwhere the item was found finding.'),
(7479, 1, 24, 'foundInAContext', 'The Encounter Event - an item found in a specific Context', 'Points to the Context where the item was found.'),
(7480, 1, 24, 'foundInAExcavation', 'The Encounter Event - an item found in a specific Excavation', 'Points to the Excavation where the item was found.'),
(7481, 1, 25, 'actsFor', 'acts for', 'The relation holding between any Agent, and a SocialAgent. In principle, a SocialAgent requires at least one PhysicalAgent in order to act, but this dependency can be \'delegated\'; e.g. a university can be acted for by a department, which on its turm is acted for by physical agents.'),
(7482, 1, 25, 'actsThrough', 'acts through', 'The relation holding between a PhysicalAgent and a SocialAgent. In principle, a SocialAgent requires at least one PhysicalAgent in order to act, but this dependency can be \'delegated\', e.g. a university can be acted for by a department, which is acted for by physical agents. AKA isActedBy'),
(7483, 1, 25, 'associatedWith', 'associatedWith', 'A catch-all object property, useful for alignment and querying purposes.\nIt is declared as both transitive and symmetric, in order to reason an a maximal closure of associations between individuals.'),
(7484, 1, 25, 'characterizes', 'caratterizza', 'A relation between concepts and collections, where a Concept is said to characterize a Collection; it corresponds to a link between the (reified) intensional and extensional interpretations of a _proper subset of_ a (reified) class. This is different from covers, because it refers to an interpretation the entire reified class.\nE.g. the collection of vintage saxophones is characterized by the Concept \'manufactured by hand\', while it gets covered by the Concept \'Saxophone\' with the Parameter \'Vintage\'.'),
(7485, 1, 25, 'classifies', 'classifica', 'A relation between a Concept and an Entity, e.g. the Role \'student\' classifies a Person \'John\'.'),
(7486, 1, 25, 'conceptualizes', 'conceptualizes', 'A relation stating that an Agent is internally representing a SocialObject: situations, descriptions, concepts, etc. E.g., \'John believes in the conspiracy theory\'; \'Niels Bohr created the solar-system metaphor for the atomic theory\'; \'Jacques assumes all swans are white\'; \'the task force members share the attack plan\'.\nConceptualizations can be distinguished into different forms, primarily based on the type of SocialObject that is conceptualized. Descriptions and concepts can be \'assumed\', situations can be \'believed\' or \'known\', plans can be \'adopted\', etc. (see ontology: http://www.ontologydesignpatterns.org/ont/dul/Conceptualization.owl.'),
(7487, 1, 25, 'concretelyExpresses', 'concretely expresses', 'A relation between an InformationRealization and a Description, e.g. \'the printout of the Italian Constitution concretelyExpresses the Italian Constitution\'. It should be supplied also with a rule stating that the InformationRealization realizes an InformationObject that expresses the Description'),
(7488, 1, 25, 'coparticipatesWith', 'co-participates with', 'A relation between two objects participating in a same Event; e.g., \'Vitas and Jimmy are playing tennis\'.'),
(7489, 1, 25, 'covers', 'covers', 'A relation between concepts and collections, where a Concept is said to cover a Collection; it corresponds to a link between the (reified) intensional and extensional interpretations of a (reified) class.\nE.g. the collection of vintage saxophones is covered by the Concept \'Saxophone\' with the Parameter \'Vintage\'.'),
(7490, 1, 25, 'defines', 'defines', 'A relation between a Description and a Concept, e.g. a Workflow for a governmental Organization defines the Role \'officer\', or \'the Italian Traffic Law defines the role Vehicle\'.'),
(7491, 1, 25, 'definesRole', 'defines role', 'A relation between a description and a role, e.g. the recipe for a cake defines the role \'ingredient\'.'),
(7492, 1, 25, 'definesTask', 'defines task', 'A relation between a description and a task, e.g. the recipe for a cake defines the task \'boil\'.'),
(7493, 1, 25, 'describes', 'describes', 'The relation between a Description and an Entity : a Description gives a unity to a Collection of parts (the components), or constituents, by assigning a Role to each of them in the context of a whole Object (the system).\nA same Entity can be given different descriptions, for example, an old cradle can be given a unifying Description based on the original aesthetic design, the functionality it was built for, or a new aesthetic functionality in which it can be used as a flower pot.'),
(7494, 1, 25, 'directlyFollows', 'directly follows', 'The intransitive follows relation. For example, Wednesday directly precedes Thursday. Directness of precedence depends on the designer conceptualization.'),
(7495, 1, 25, 'directlyPrecedes', 'directly precedes', 'The intransitive precedes relation. For example, Monday directly precedes Tuesday. Directness of precedence depends on the designer conceptualization.'),
(7496, 1, 25, 'executesTask', 'esegue il task', 'A relation between an action and a task, e.g. \'putting some water in a pot and putting the pot on a fire until the water starts bubbling\' executes the task \'boiling\'.'),
(7497, 1, 25, 'expands', 'espande', 'A partial order relation that holds between descriptions. It represents the proper part relation between a description and another description featuring the same properties as the former, with at least one additional one.\nDescriptions can be expanded either by adding other descriptions as parts, or by refining concepts that are used by them. \nAn \'intention\' to expand must be present (unless purely formal theories are considered, but even in this case a criterion of relevance is usually active).'),
(7498, 1, 25, 'expresses', 'esprime', 'A relation between an InformationObject and a \'meaning\', generalized here as a \'SocialObject\'. For example: \'A Beehive is a structure in which bees are kept, typically in the form of a dome or box.\' (Oxford dictionary)\'; \'the term Beehive expresses the concept Beehive in my apiculture ontology\'.\nThe intuition for \'meaning\' is intended to be very broad. A separate, large comment is included for those who want to investigate more on what kind of meaning can be represented in what form.'),
(7499, 1, 25, 'expressesConcept', 'esprime il concetto', 'A relation between an InformationObject and a Concept , e.g. the term \"dog\" expresses the Concept \"dog\". For expressing a relational meaning, see the more general object property: expresses'),
(7500, 1, 25, 'farFrom', 'far from', 'Generic distance relation between any Entity(s). E.g. Rome is far from Beijing, astronomy is far from necromancy.'),
(7501, 1, 25, 'follows', 'follows', 'A relation between entities, expressing a \'sequence\' schema. \nE.g. \'year 2000 follows 1999\', \'preparing coffee\' follows \'deciding what coffee to use\', \'II World War follows I World War\', etc. \nIt can be used between tasks, processes or time intervals, and subproperties would fit best in order to distinguish the different uses.'),
(7502, 1, 25, 'hasCommonBoundary', 'has common boundary', 'A relation to encode either formal or informal characterizations of \'boundaries\' common to two different entities: an Event that ends when another begins, two abstract regions that have a common topological boundary, two objects that are said to be \'in contact\' from a commonsense perspective, etc.'),
(7503, 1, 25, 'hasComponent', 'ha componente', 'The hasProperPart relation without transitivity, holding between an Object (the system) and another (the component), and assuming a Design that structures the Object.'),
(7504, 1, 25, 'hasConstituent', 'ha costituente', '\'Constituency\' depends on some layering of  the world described by the ontology. For example, scientific granularities (e.g. body-organ-tissue-cell) or ontological \'strata\' (e.g. social-mental-biological-physical) are  typical layerings. \nIntuitively, a constituent is a part belonging to a lower layer. Since layering is actually a partition of the world described by the ontology, constituents are not properly classified as parts, although this kinship can be intuitive for common sense.\nA desirable advantage of this distinction is that we are able to talk e.g. of physical constituents of non-physical objects (e.g. systems), while this is not possible in terms of parts.\nExample of are the persons constituting a social system, the molecules constituting a person, the atoms constituting a river, etc. \nIn all these examples, we notice a typical discontinuity between the constituted and the constituent object: e.g. a social system is conceptualized at a different layer from the persons that constitute it, a person is conceptualized at a different layer from the molecules that constitute them, and a river is conceptualized at a different layer from the atoms that constitute it.'),
(7505, 1, 25, 'hasConstraint', 'ha vincolo', 'A relation between parameters and entities. It allows to assert generic constraints (encoded as parameters), e.g. MinimumAgeForDriving isConstraintFor John (where John is a legal subject under the TrafficLaw).\nThe intended semantics (not expressible in OWL) is that a Parameter isParameterFor a Concept that classifies an Entity; moreover, it entails that a Parameter parametrizes a Region that isRegionFor that Entity.'),
(7506, 1, 25, 'hasInScope', 'hasInScope', NULL),
(7507, 1, 25, 'hasLocation', 'ha localizzazione', 'A generic, relative spatial location, holding between any entities. E.g. \'the cat is on the mat\', \'Omar is in Samarcanda\', \'the wound is close to the femural artery\'.\nFor \'absolute\' locations, see SpaceRegion'),
(7508, 1, 25, 'hasMember', 'ha membro', 'A relation between collections and entities, e.g. \'my collection of saxophones includes an old Adolphe Sax original alto\' (i.e. my collection has member an Adolphe Sax alto).'),
(7509, 1, 25, 'hasParameter', 'ha parametro', 'A Concept can have a Parameter that constrains the attributes that a classified Entity can have in a certain Situation, e.g. a 4WheelDriver Role definedIn the ItalianTrafficLaw has a MinimumAge parameter on the Amount 16.'),
(7510, 1, 25, 'hasPart', 'ha parte', 'A schematic relation between any entities, e.g. \'the human body has a brain as part\', \'20th century contains year 1923\', \'World War II includes the Pearl Harbour event\'.\n\nParthood should assume the basic properties of mereology: transitivity, antisymmetry, and reflexivity (propert Parthood of course misses reflexivity). \nHowever, antisymmetry is not supported in OWL2 explicitly, therefore DUL has to adopt one of two patterns:\n1) dropping asymmetry axioms, while granting reflexivity: this means that symmetry is not enforced, but permitted for the case of reflexivity. Of course, in this way we cannot prevent symmetric usages of hasPart;\n2) dropping the reflexivity axiom, and enforce asymmetry: in this case, we would prevent all symmetric usages, but we loose the possibility of enforcing reflexivity, which is commonsensical in parthood.\nIn DUL, we adopt pattern #1 for partOf, and pattern #2 for properPartOf, which seems a good approximation: due to the lack of inheritance of property characteristics, each asymmetric hasPropertPart assertion would also be a reflexive hasPart assertion (reflexive reduction design pattern).\n\nSubproperties and restrictions can be used to specialize hasPart for objects, events, etc.'),
(7511, 1, 25, 'hasParticipant', 'ha come partecipante', 'A relation between an object and a process, e.g. \'John took part in the discussion\', \'a large mass of snow fell during the avalanche\', or \'a cook, some sugar, flour, etc. are all present in the cooking of a cake\'.');
INSERT INTO `property` (`id`, `owner_id`, `vocabulary_id`, `local_name`, `label`, `comment`) VALUES
(7512, 1, 25, 'hasPostcondition', 'ha postcondizione', 'Direct succession applied to situations. \nE.g., \'A postcondition of our Plan is to have things settled\'.'),
(7513, 1, 25, 'hasPrecondition', 'ha precondizione', 'Direct precedence applied to situations. \nE.g., \'A precondition to declare war against a foreign country is claiming to find nuclear weapons in it\'.'),
(7514, 1, 25, 'hasProperPart', 'has proper part', 'Asymmetric (so including irreflexive) parthood.'),
(7515, 1, 25, 'hasQuality', 'ha qualità', 'A relation between entities and qualities, e.g. \'Dmitri\'s skin is yellowish\'.'),
(7516, 1, 25, 'hasRegion', 'ha attributo', 'A relation between entities and regions, e.g. \'the number of wheels of that truck is 12\', \'the time of the experiment is August 9th, 2004\', \'the whale has been localized at 34 degrees E, 20 degrees S\'.'),
(7517, 1, 25, 'hasRole', 'ha ruolo', 'A relation between an object and a role, e.g. the person \'John\' has role \'student\'.'),
(7518, 1, 25, 'hasSetting', 'has setting', 'A relation between entities and situations, e.g. \'this morning I\'ve prepared my coffee with a new fantastic Arabica\', i.e.: (an amount of) a new fantastic Arabica hasSetting the preparation of my coffee this morning.'),
(7519, 1, 25, 'hasTask', 'ha come obiettivo', 'A relation between roles and tasks, e.g. \'students have the duty of giving exams\' (i.e. the Role \'student\' hasTask the Task \'giving exams\').'),
(7520, 1, 25, 'hasTimeInterval', 'ha intervallo temporale', 'The generic relation between events and time intervals.'),
(7521, 1, 25, 'includesAction', 'include azione', 'A relation between situations and actions, e.g. \'this morning I\'ve prepared my coffee and had my fingers burnt\' (i.e.: the preparation of my coffee this morning included a burning of my fingers).'),
(7522, 1, 25, 'includesAgent', 'include l\'agente', 'A relation between situations and persons, e.g. \'this morning I\'ve prepared my coffee and had my fingers burnt\' (i.e.: the preparation of my coffee this morning included me).'),
(7523, 1, 25, 'includesEvent', 'include l\'evento', 'A relation between situations and events, e.g. \'this morning I\'ve prepared my coffee and had my fingers burnt\' (i.e.: the preparation of my coffee this morning included a burning of my fingers).'),
(7524, 1, 25, 'includesObject', 'include l\'oggetto', 'A relation between situations and objects, e.g. \'this morning I\'ve prepared my coffee and had my fingers burnt\' (i.e.: the preparation of my coffee this morning included me).'),
(7525, 1, 25, 'includesPart', 'includesPart', NULL),
(7526, 1, 25, 'includesTime', 'include tempo', 'A relation between situations and time intervals, e.g. \'this morning I\'ve prepared my coffee and had my fingers burnt\' (i.e.: preparing my coffee was held this morning). A data value attached to the time interval typically complements this modelling pattern.'),
(7527, 1, 25, 'includesWhole', 'includesWhole', NULL),
(7528, 1, 25, 'introduces', 'introduce', 'A relation between a Description and a SocialAgent, e.g. a Constitutional Charter introduces the SocialAgent \'PresidentOfRepublic\'.'),
(7529, 1, 25, 'involvesAgent', 'coinvolge agente', 'Agent participation.'),
(7530, 1, 25, 'isAbout', 'is about', 'A relation between an information object and an Entity (including information objects). It can be used to talk about entities that are references of proper nouns: the proper noun \'Leonardo da Vinci\' isAbout the Person Leonardo da Vinci; as well as to talk about sets of entities that can be described by a common noun: the common noun \'person\' isAbout the set of all persons in a domain of discourse, which can be represented in DOLCE-Ultralite as an individual of the class: dul:Collection.\nA specific sentence may use common nouns with either a singular or plural reference, or it can even refer to all possible references (e.g. in a lexicographic definition): all those uses are kinds of aboutness.\n\nThe isAbout relation is sometimes considered as reflexive, however this is semiotically inaccurate, because information can be about itself (\'de dicto\' usage, as in \'John is four character long\'), but it is typically about something else (\'de re\' usage, as in \'John loves Mary\').\nIf a reflexivity exists in general, it rather concerns its realisation, which is always associated with an event, e.g. an utterance, which makes the information denoting itself, besides its aboutness. This is implemented in DUL with the dul:realizesSelfInformation property, which is used with local reflexivity in the dul:InformationRealization class.'),
(7531, 1, 25, 'isActionIncludedIn', 'is action included in', NULL),
(7532, 1, 25, 'isAgentIncludedIn', 'is agent included in', NULL),
(7533, 1, 25, 'isAgentInvolvedIn', 'is agent involved in', 'Agent participation.'),
(7534, 1, 25, 'isCharacterizedBy', 'is characterized by', NULL),
(7535, 1, 25, 'isClassifiedBy', 'is classified by', 'A relation between a Concept and an Entity, e.g. \'John is considered a typical rude man\'; your last concert constitutes the achievement of a lifetime; \'20-year-old means she\'s mature enough\'.'),
(7536, 1, 25, 'isComponentOf', 'is component of', 'The asymmetric isProperPartOf relation without transitivity, holding between an Object (the system) and another (the component), and assuming a Design that structures the Object.'),
(7537, 1, 25, 'isConceptExpressedBy', 'is concept expressed by', 'A relation between an InformationObject and a Concept , e.g. the term \"dog\" expresses the Concept \"dog\". For expressing a relational meaning, see the more general object property: expresses'),
(7538, 1, 25, 'isConceptUsedIn', 'is concept used in', 'A more generic relation holding between a Description and a Concept. In order to be used, a Concept must be previously definedIn another Description'),
(7539, 1, 25, 'isConceptualizedBy', 'is conceptualized by', 'A relation stating that an Agent is internally representing a Description . E.g., \'John believes in the conspiracy theory\'; \'Niels Bohr created a solar-system metaphor for his atomic theory\'; \'Jacques assumes all swans are white\'; \'the task force shares the attack plan\'.'),
(7540, 1, 25, 'isConcretelyExpressedBy', 'is concretely expressed by', 'A relation between an InformationRealization and a Description, e.g. \'the printout of the Italian Constitution concretelyExpresses the Italian Constitution\'. It should be supplied also with a rule stating that the InformationRealization realizes an InformationObject that expresses the Description'),
(7541, 1, 25, 'isConstituentOf', 'is constituent of', '\'Constituency\' depends on some layering of  the world described by the ontology. For example, scientific granularities (e.g. body-organ-tissue-cell) or ontological \'strata\' (e.g. social-mental-biological-physical) are  typical layerings. \nIntuitively, a constituent is a part belonging to a lower layer. Since layering is actually a partition of the world described by the ontology, constituents are not properly classified as parts, although this kinship can be intuitive for common sense.\nA desirable advantage of this distinction is that we are able to talk e.g. of physical constituents of non-physical objects (e.g. systems), while this is not possible in terms of parts.\nExample of are the persons constituting a social system, the molecules constituting a person, the atoms constituting a river, etc. \nIn all these examples, we notice a typical discontinuity between the constituted and the constituent object: e.g. a social system is conceptualized at a different layer from the persons that constitute it, a person is conceptualized at a different layer from the molecules that constitute them, and a river is conceptualized at a different layer from the atoms that constitute it.'),
(7542, 1, 25, 'isConstraintFor', 'is constraint for', 'A relation between parameters and entities. It allows to assert generic constraints (encoded as parameters), e.g. MinimumAgeForDriving isConstraintFor John (where John is a legal subject under the TrafficLaw).\nThe intended semantics (not expressible in OWL) is that a Parameter isConstraintFor and Entity if the Parameter isParameterFor a Concept that classifies that Entity; moreover, it entails that a Parameter parametrizes a Region that isRegionFor that Entity. The use in OWL is therefore a shortcut to annotate what Parameter constrains what Entity'),
(7543, 1, 25, 'isCoveredBy', 'is covered by', 'A relation between concepts and collections, where a Concept is said to cover a Collection; it corresponds to a link between the (reified) intensional and extensional interpretations of a (reified) class.\nE.g. the collection of vintage saxophones is covered by the Concept \'Saxophone\' with the Parameter \'Vintage\'.'),
(7544, 1, 25, 'isDefinedIn', 'is defined in', 'A relation between a Description and a Concept, e.g. a Workflow for a governmental Organization defines the Role \'officer\', or \'the Italian Traffic Law defines the role Vehicle\'.'),
(7545, 1, 25, 'isDescribedBy', 'is described by', 'The relation between an Entity and a Description: a Description gives a unity to a Collection of parts (the components), or constituents, by assigning a Role to each of them in the context of a whole Object (the system).\nA same Entity can be given different descriptions, for example, an old cradle can be given a unifying Description based on the original aesthetic design, the functionality it was built for, or a new aesthetic functionality in which it can be used as a flower pot.'),
(7546, 1, 25, 'isEventIncludedIn', 'is event included in', NULL),
(7547, 1, 25, 'isExecutedIn', 'is executed in', 'A relation between an action and a task, e.g. \'putting some water in a pot and putting the pot on a fire until the water starts bubbling\' executes the task \'boiling\'.'),
(7548, 1, 25, 'isExpandedIn', 'is expanded in', 'A partial order relation that holds between descriptions. It represents the proper part relation between a description and another description featuring the same properties as the former, with at least one additional one.\nDescriptions can be expanded either by adding other descriptions as parts, or by refining concepts that are used by them. \nAn \'intention\' to expand must be present (unless purely formal theories are considered, but even in this case a criterion of relevance is usually active).'),
(7549, 1, 25, 'isExpressedBy', 'is expressed by', 'A relation between a dul:SocialObject (the \'meaning\') and a dul:InformationObject (the \'expression\'). \nFor example: \'A Beehive is a structure in which bees are kept, typically in the form of a dome or box.\' (Oxford dictionary)\'; \'the term Beehive expresses the concept Beehive in my apiculture ontology\'.\nThe intuition for \'meaning\' is intended to be very broad. A separate, large comment is included in the encoding of \'expresses\', for those who want to investigate more on what kind of meaning can be represented in what form.'),
(7550, 1, 25, 'isIntroducedBy', 'is introduced by', 'A relation between a Description and a SocialAgent, e.g. a Constitutional Charter introduces the SocialAgent \'PresidentOfRepublic\'.'),
(7551, 1, 25, 'isLocationOf', 'is location of', 'A generic, relative localization, holding between any entities. E.g. \'Rome is the seat of the Pope\', \'the liver is the location of the tumor\'.\nFor \'absolute\' locations, see SpaceRegion'),
(7552, 1, 25, 'isMemberOf', 'is member of', 'A relation between collections and entities, e.g. \'the Night Watch by Rembrandt is in the Rijksmuseum collection\'; \'Davide is member of the Pen Club\', \'Igor is one the subjects chosen for the experiment\'.'),
(7553, 1, 25, 'isObjectIncludedIn', 'is object included in', NULL),
(7554, 1, 25, 'isObservableAt', 'is observable at', 'A relation to represent a (past, present or future) TimeInterval at which an Entity is observable.\nIn order to encode a specific time, a data value should be related to the TimeInterval. \nAn alternative way of representing time is the datatype property: hasIntervalDate'),
(7555, 1, 25, 'isParameterFor', 'is parameter for', 'A Concept can have a Parameter that constrains the attributes that a classified Entity can have in a certain Situation, e.g. a 4WheelDriver Role definedIn the ItalianTrafficLaw has a MinimumAge parameter on the Amount 16.'),
(7556, 1, 25, 'isParametrizedBy', 'is parametrized by', 'The relation between a Parameter, e.g. \'MajorAge\', and a Region, e.g. \'>17 year\'.'),
(7557, 1, 25, 'isPartOf', 'is part of', 'A relation between any entities, e.g. \'brain is a part of the human body\'. See dul:hasPart for additional documentation.'),
(7558, 1, 25, 'isParticipantIn', 'is participant in', 'A relation between an object and a process, e.g. \'John took part in the discussion\', \'a large mass of snow fell during the avalanche\', or \'a cook, some sugar, flour, etc. are all present in the cooking of a cake\'.'),
(7559, 1, 25, 'isPostconditionOf', 'is postcondition of', 'Direct succession applied to situations. \nE.g., \'Taking some rest is a postcondition of my search for a hotel\'.'),
(7560, 1, 25, 'isPreconditionOf', 'is precondition of', 'Direct precedence applied to situations. \nE.g., \'claiming to find nuclear weapons in a foreign country is a precondition to declare war against it\'.'),
(7561, 1, 25, 'isPropertPartOf', 'is propert part of', 'See dul:hasProperPart for additional documentation.'),
(7562, 1, 25, 'isQualityOf', 'is quality of', 'A relation between entities and qualities, e.g. \'Dmitri\'s skin is yellowish\'.'),
(7563, 1, 25, 'isRealizedBy', 'is realized by', 'A relation between an information realization and an information object, e.g. the paper copy of the Italian Constitution realizes the text of the Constitution.'),
(7564, 1, 25, 'isReferenceOf', 'is reference of', 'A relation between information objects and any Entity (including information objects). It can be used to talk about e.g. entities are references of proper nouns: the proper noun \'Leonardo da Vinci\' isAbout the Person Leonardo da Vinci; as well as to talk about sets of entities that can be described by a common noun: the common noun \'person\' isAbout the set of all persons in a domain of discourse, which can be represented in DOLCE-Ultralite as an individual of the class: Collection .\nThe isReferenceOf relation is irreflexive, differently from its inverse isAbout.'),
(7565, 1, 25, 'isReferenceOfInformationRealizedBy', 'is reference of information realized by', 'The relation between entities and information realizations, e.g. between Italy and a paper copy of the text of the Italian Constitution.'),
(7566, 1, 25, 'isRegionFor', 'is region for', 'A relation between entities and regions, e.g. \'the color of my car is red\'.'),
(7567, 1, 25, 'isRelatedToConcept', 'is related to concept', 'Any relation between concepts, e.g. superordinated, conceptual parthood, having a parameter, having a task, superordination, etc.'),
(7568, 1, 25, 'isRelatedToDescription', 'is related to description', 'Any relation between descriptions.'),
(7569, 1, 25, 'isRoleDefinedIn', 'is role defined in', 'A relation between a description and a role, e.g. the role \'Ingredient\' is defined in the recipe for a cake.'),
(7570, 1, 25, 'isRoleOf', 'is role of', 'A relation between an object and a role, e.g. \'student\' is the role of \'John\'.'),
(7571, 1, 25, 'isSatisfiedBy', 'is satisfied by', 'A relation between a Situation and a Description, e.g. the execution of a Plan satisfies that plan.'),
(7572, 1, 25, 'isSettingFor', 'include', 'A relation between situations and entities, e.g. \'this morning I\'ve prepared my coffee with a new fantastic Arabica\', i.e.: the preparation of my coffee this morning is the setting for (an amount of) a new fantastic Arabica.'),
(7573, 1, 25, 'isSpecializedBy', 'is specialized by', 'A partial order relation that holds between social objects. It represents the subsumption relation between e.g. a Concept and another Concept that is broader in extensional interpretation, but narrowe in intensional interpretation.\nE.g. PhDStudent Role specializes Student Role'),
(7574, 1, 25, 'isSubordinatedTo', 'is subordinated to', 'Direct succession applied to concepts. E.g. the role \'Officer\' is subordinated to \'Director\'.'),
(7575, 1, 25, 'isSuperordinatedTo', 'is superordinated to', 'Direct precedence applied to concepts. E.g. the role \'Executive\' is superordinated to \'DepartmentManager\'.'),
(7576, 1, 25, 'isTaskDefinedIn', 'is task defined in', 'A relation between a description and a task, e.g. the task \'boil\' is defined in a recipe for a cake.'),
(7577, 1, 25, 'isTaskOf', 'is task of', 'A relation between roles and tasks, e.g. \'students have the duty of giving exams\' (i.e. the Role \'student\' hasTask the Task \'giving exams\').'),
(7578, 1, 25, 'isTimeIncludedIn', 'is time included in', NULL),
(7579, 1, 25, 'isTimeIntervalOf', 'intervallo temporale di', 'The generic relation between time intervals and events.'),
(7580, 1, 25, 'isTimeOfObservationOf', 'is time of observation of', 'A relation to represent a (past, present or future) TimeInterval at which an Entity is observable.\nIn order to encode a specific time, a data value should be related to the TimeInterval. \nAn alternative way of representing time is the datatype property: hasIntervalDate'),
(7581, 1, 25, 'isUnifiedBy', 'is unified by', 'A Collection has a unification criterion, provided by a Description; for example, a community of practice can be unified by a shared theory or interest, e.g. the community that makes research on mirror neurons shares some core knowledge about mirror neurons, which can be represented as a Description MirrorNeuronTheory that unifies the community. There can be several unifying descriptions.'),
(7582, 1, 25, 'nearTo', 'near to', 'Generic distance relation between any Entity(s). E.g. Rome is near to Florence, astronomy is near to physics.'),
(7583, 1, 25, 'overlaps', 'overlaps', 'A schematic relation between any entities, e.g. \'the chest region overlaps with the abdomen region\', \'my spoken words overlap with hers\', \'the time of my leave overlaps with the time of your arrival\', \'fibromyalgia overlaps with other conditions\'.\nSubproperties and restrictions can be used to specialize overlaps for objects, events, time intervals, etc.'),
(7584, 1, 25, 'parametrizes', 'parametrizes', 'The relation between a Parameter, e.g. \'MajorAgeLimit\', and a Region, e.g. \'18_year\'.\nFor a more data-oriented relation, see hasDataValue'),
(7585, 1, 25, 'precedes', 'precede', 'A relation between entities, expressing a \'sequence\' schema. \nE.g. \'year 1999 precedes 2000\', \'deciding what coffee to use\' precedes \'preparing coffee\', \'World War II follows World War I\', \'in the Milan to Rome autoroute, Bologna precedes Florence\', etc.\nIt can then be used between tasks, processes, time intervals, spatially locate objects, situations, etc. \nSubproperties can be defined in order to distinguish the different uses.'),
(7586, 1, 25, 'realizes', 'realizes', 'A relation between an information realization and an information object, e.g. the paper copy of the Italian Constitution realizes the text of the Constitution.'),
(7587, 1, 25, 'realizesInformationAbout', 'realizes information about', 'The relation between entities and information realizations, e.g. between Italy and a paper copy of the text of the Italian Constitution.'),
(7588, 1, 25, 'realizesSelfInformation', 'realizesSelfInformation', 'This relation is a workaround to enable local reflexivity axioms (Self) working with non-simple properties; in this case, dul:realizesInformation About.'),
(7589, 1, 25, 'sameSettingAs', 'is in the same setting as', 'A relation between two entities participating in a same Situation; e.g., \'Our company provides an antivenom service\' (the situation is the service, the two entities are the company and the antivenom).'),
(7590, 1, 25, 'satisfies', 'satisfies', 'A relation between a Situation and a Description, e.g. the execution of a Plan satisfies that plan.'),
(7591, 1, 25, 'specializes', 'specializes', 'A partial order relation that holds between social objects. \nIt mainly represents the subsumption relation between e.g. a Concept or Description and another Concept (resp. Description) that is broader in extensional interpretation, but narrower in intensional interpretation. For example, the role PhDStudent specializes the role Student.\nAnother possible use is between a Collection that isCoveredBy a Concept A, and another Collection that isCoveredBy a Concept B that on its turm specializes A. For example, the 70,000 series Selmer Mark VI saxophone Collection specializes the Selmer Mark VI saxophone Collection.'),
(7592, 1, 25, 'unifies', 'unifica', 'A Collection has a unification criterion, provided by a Description; for example, a community of practice can be unified by a shared theory or interest, e.g. the community that makes research on mirror neurons shares some core knowledge about mirror neurons, which can be represented as a Description MirrorNeuronTheory that unifies the community. There can be several unifying descriptions.'),
(7593, 1, 25, 'usesConcept', 'usa il concetto', 'A generic relation holding between a Description and a Concept. In order to be used, a Concept must be previously definedIn another Description. This last condition cannot be encoded for object properties in OWL.'),
(7594, 1, 25, 'hasDataValue', 'ha valore', 'A datatype property that encodes values from a datatype for an Entity. \nThere are several ways to encode values in DOLCE (Ultralite):\n\n1) Directly assert an xsd:_ value to an Entity by using hasDataValue\n2) Assert a Region for an Entity by using hasRegion, and then assert an xsd:_ value to that Region, by using hasRegionDataValue\n3) Assert a Quality for an Entity by using hasQuality, then assert a Region for that Quality, and assert an xsd:_ value to that Region, by using hasRegionDataValue\n4) When the value is required, but not directly observed, assert a Parameter for an xsd:_ value by using hasParameterDataValue, and then associate the Parameter to an Entity by using isConstraintFor\n5) When the value is required, but not directly observed, you can also assert a Parameter for a Region by using parametrizes, and then assert an xsd:_ value to that Region, by using hasRegionDataValue\n\nThe five approaches obey different requirements. \nFor example, a simple value can be easily asserted by using pattern (1), but if one needs to assert an interval between two values, a Region should be introduced to materialize that interval, as pattern (2) suggests. \nFurthermore, if one needs to distinguish the individual Quality of a value, e.g. the particular nature of the density of a substance, pattern (3) can be used. \nPatterns (4) and (5) should be used instead when a constraint or a selection is modeled, independently from the actual observation of values in the real world.'),
(7595, 1, 25, 'hasEventDate', 'evento ha data', 'A datatype property that encodes values from xsd:dateTime for an Event; a same Event can have more than one xsd:dateTime value: begin date, end date, date at which the interval holds, etc.'),
(7596, 1, 25, 'hasIntervalDate', 'has interval date', 'A datatype property that encodes values from xsd:dateTime for a TimeInterval; a same TimeInterval can have more than one xsd:dateTime value: begin date, end date, date at which the interval holds, etc.'),
(7597, 1, 25, 'hasParameterDataValue', 'ha valore', 'Parametrizes values from a datatype. For example, a Parameter MinimumAgeForDriving hasParameterDataValue 18 on datatype xsd:int, in the Italian traffic code. In this example, MinimumAgeForDriving isDefinedIn the Norm ItalianTrafficCodeAgeDriving.\nMore complex parametrization requires workarounds. E.g. AgeRangeForDrugUsage could parametrize data value: 14 to 50 on the datatype: xsd:int. Since complex datatypes are not allowed in OWL1.0, a solution to this can only work by creating two \'sub-parameters\': MinimumAgeForDrugUsage (that hasParameterDataValue 14) and MaximumAgeForDrugUsage (that hasParameterDataValue 50), which are components of (cf. hasComponent) the main Parameter AgeRangeForDrugUsage.\nOrdering on subparameters can be created by using or specializing the object property \'precedes\'.'),
(7598, 1, 25, 'hasRegionDataValue', 'has region data value', 'A datatype property that encodes values for a Region, e.g. a float for the Region Height.'),
(7647, 1, 29, 'hasMorphology', 'ArrowHead - morphology', 'This property points to an instance of the definition of the morphology of the arrowhead.'),
(7648, 1, 29, 'hasChipping', 'ArrowHead - has chipping', 'This Property points to an instance of the definition of the chipping of the arrowhead.'),
(7649, 1, 29, 'bodyLength', 'ArrowHead - bodyLength', 'This property points to an instance that presents the length of the body of the arrowhead.'),
(7650, 1, 29, 'baseLength', 'ArrowHead - baseLength', 'This property points to an instance that presents the length of the base of the arrowhead.'),
(7651, 1, 29, 'shape', 'ArrowHead - shape', 'This property records the shape of the arrowhead. A good practice is to use the controlled vocabulary  AH-Shape.'),
(7652, 1, 29, 'variant', 'ArrowHead - Variant', 'This property records the variant of the arrowhead. A good practice is to use the controlled vocabulary  AH-Variant.'),
(7653, 1, 29, 'point', 'Arrowhead-point - point. Sharp=True;Fractured=False', 'Definition of the tip of the arrowhead. Sharp=True;Fractured=False.'),
(7654, 1, 29, 'body', 'Arrowhead-Morphology - body. Symmetrical=True; Non-symmetrical=False. ', 'THis property is used to define the simmetry of the body of the arrowhead. Symmetrical=True; Non-symmetrical=False'),
(7655, 1, 29, 'base', 'ArrowHead - Morphology - Base. A good pratice is to use the Controlled Vocabulary AH-Base. ', 'This properties defines the base of the arrowhead. A good pratice is to use the controlled vocabulary AH-Base.'),
(7656, 1, 29, 'chippingMode', 'Arrowhead-Chipping-mode', 'Type of retouching incidence, defines the angle formed by the retouching line and the chipping surface. A good pratice is to use the Controlled Vocabulary AH-ChippingMode.'),
(7657, 1, 29, 'chippingAmplitude', 'Arrowhead-Chipping-amplitude', 'Retouching extension, Marginal=True;Deep=False.'),
(7658, 1, 29, 'chippingDirection', 'Arrowhead-Chipping-direction', 'It results from the position in which the chip or blade is placed to be retouched. A good pratice is to use the Controlled Vocabulary AH-ChippingDirection.'),
(7659, 1, 29, 'chippingOrientation', 'Arrowhead-Chipping-Orientation', 'Angle between the original axis of the part and the line formed by the retouching, Lateral=True;Transverse=False.'),
(7660, 1, 29, 'chippingDelineation', 'Arrowhead-Chipping-delineation', 'The retouching gives the margins a shape.. A good pratice is to use the Controlled Vocabulary AH-ChippingDelineation.'),
(7661, 1, 29, 'chippingShape', 'Arrowhead-Chipping-shape', 'Line defined by the edge. A good pratice is to use the Controlled Vocabulary AH-ChippingShape.'),
(7662, 1, 29, 'chippingLocationSide', 'Arrowhead-Chipping Location-lateral', 'The retouching can occupy a position to the left or right of the axis of symmetry and, depending on the axis perpendicular to it, the retouching can be distal, medial or proximal. . A good pratice is to use the COntrolled Vocabulary AH-ChippingLocation.'),
(7663, 1, 29, 'chippingLocationTransversal', 'Arrowhead-Chipping Location-Transversal', 'The retouching can be distal or proximal and, depending on the edge where it is located, it can occupy a left, right or median position. A good pratice is to use the COntrolled Vocabulary AH-ChippingLocation.'),
(7664, 1, 30, 'hasGPSCoordinates', 'Location - has GPS Coordinates', 'The GPS coordinates of the central point of the excavation\'s location (in degrees).'),
(7665, 1, 30, 'hasPersonInCharge', 'The Excavation has a person in charge -> Archaeologist', 'The person in charge of the excavation (an Archaeologist).'),
(7666, 1, 30, 'hasContext', 'Excavation - hasContext', 'The contexts of the excavation.'),
(7667, 1, 30, 'hasSVU', 'The  StratigraphicVolumeUnit', 'The StratigraphicVolumeUnit (CIDOC CRM A2).'),
(7668, 1, 30, 'hasSquare', 'The Square ', 'A Square within an excavation.'),
(7669, 1, 30, 'hasTimeline', 'The Stratigraphic unit has a timeline', 'The specific timeline of the the layer .'),
(7670, 1, 30, 'foundInCoordinates', 'Coordinates of the Item found', 'Points to the Coordinates where the item was found.'),
(7671, 1, 30, 'foundInSVU', 'Encounter Event - an item found in a specific Stratigraphic Unit', 'Points to the Stratigraphic Unit where the item was found.'),
(7672, 1, 30, 'foundInContext', 'The Encounter Event - an item found in a specific Context', 'Points to the Context where the item was found.'),
(7673, 1, 30, 'foundInExcavation', 'The Encounter Event - an item found in an Excavation', 'Points to the Excavation where the item was found.'),
(7674, 1, 30, 'hasCoordinatesInSquare', 'Item found in the Coordinates (within the square)', 'Item found in the Coordinates (within the square).'),
(7675, 1, 30, 'bcac', 'Definition of the period in time .', 'This property informs if the date in the bounds of the timeline is before Christ (bc) or after Christ (AD). Use a URI of the term in the controlled vocabulary MegaLOD-BCAC'),
(7676, 1, 30, 'elongationIndex', 'Elongation Index.', 'The elongation index of the item. Use a URI of the term in the controlled vocabulary MegaLOD-IndexElongation'),
(7677, 1, 30, 'thicknessIndex', 'Thickness Index.', 'The thickness index of the item. Use a URI of the term in the controlled vocabulary MegaLOD-IndexThicknessn'),
(7678, NULL, 29, 'hasBodyLength', 'ArrowHead - bodyLength', 'Points to a class that gives the length of the body of the arrowhead.'),
(7679, NULL, 29, 'hasBaseLength', 'ArrowHead - baseLength', 'Points to a class that presents the length of the base of the arrowhead.');
